                    end
                    
                    if cheat_client.proximity_cleanup then
                        cheat_client.proximity_cleanup();
                    end
                    
                    watched_guis = nil
                end)
                for _, v in pairs(Services.CoreGui:GetChildren()) do
                    task.defer(function()
                        if FindFirstChild(v, "Toggle") and FindFirstChild(v, 'SaveInstance') then
                            v.Enabled = false
                        end
