                    end

                    local data = httpService:JSONDecode(response.Body)
                    if data and data.data then
                        for _, server in ipairs(data.data) do
                            if server.id and server.id ~= currentJobId and not is_server_recent(server.id, history) then
                                return server.id
                            end
                        end
                    end

                    return nil
