                -- region-1 inns + live inn keepers in the current world (Khei etc.)
                local function scan_inns_exploits()
                    local found, seen = {}, {}
                    for _, n in ipairs(inn_locations) do if not seen[n] then seen[n] = true; found[#found + 1] = n end end
                    local npcs = FindFirstChild(ws, "NPCs")
                    if npcs then
                        for _, npc in ipairs(npcs:GetChildren()) do
                            if npc.Name:gsub("%s", ""):lower() == "innkeeper" and FindFirstChild(npc, "Location") then
                                local loc = (npc.Location.Value:gsub("^%s*(.-)%s*$", "%1"))
                                if loc and loc ~= "" and not seen[loc] then seen[loc] = true; found[#found + 1] = loc end
                            end
                        end
                        if FindFirstChild(npcs, "Ria") and not seen["Flowerlight Town"] then seen["Flowerlight Town"] = true; found[#found + 1] = "Flowerlight Town" end
                        if FindFirstChild(npcs, "Fungkeeper") and not seen["Scroomville"] then seen["Scroomville"] = true; found[#found + 1] = "Scroomville" end
                    end
                    return found
                end

