            if not (pcall(function()
                local group_23 = Tabs.TwentyThree:AddLeftGroupbox("Inn Teleports")
                group_23:AddLabel("Lit = a player is within 50 studs of that inn's keeper right now")

                local INN_TARGETS_23 = {
                    "Southern Sanctuary",
                    "Central Sanctuary",
