                })

                group_23watch:AddToggle("auto_join_23", {
                    Text = "Auto Join (Play/Rejoin) While Menued",
                    Default = false,
                    Callback = function(v) auto_join_active = v end
                })

                local function do_menu_23(reason)
                    if menu_debounce_23 then return end
                    menu_debounce_23 = true
                    library:Notify("23 Tab: " .. reason .. " - menuing.")

                    local requests = rps:FindFirstChild("Requests")
                    local return_to_menu = requests and requests:FindFirstChild("ReturnToMenu")
                    local to_menu = rps:FindFirstChild("toMenu")

                    if return_to_menu and return_to_menu:IsA("RemoteFunction") then
                        pcall(function() return_to_menu:InvokeServer() end)
                    elseif to_menu and to_menu:IsA("RemoteEvent") then
                        pcall(function() to_menu:FireServer() end)
                    end
                end

                plrs.PlayerRemoving:Connect(function(leaving)
                    if not menu_watch_active then return end
                    if not watched_players[leaving.Name] then return end
                    do_menu_23(leaving.Name .. " left")
                end)

                plr.CharacterAdded:Connect(function()
                    menu_debounce_23 = false
                end)

                -- Auto Join: while there's no character (sitting at whatever
                -- menu screen, first-load OR after ReturnToMenu), periodically
                -- look for any visible Play/Rejoin/Continue/Join button and
                -- press it. Searches broadly instead of one hardcoded path,
                -- since the first-load menu and the post-ReturnToMenu menu are
                -- different GUIs with different structures.
                local AUTOJOIN_KEYWORDS = { "play", "rejoin", "continue", "join", "resume" }

                local function find_join_button_23()
                    local gui_root = plr:FindFirstChild("PlayerGui")
                    if not gui_root then return nil end
                    local found = nil
                    pcall(function()
                        for _, v in next, gui_root:GetDescendants() do
                            if found then break end
                            if (v:IsA("TextButton") or v:IsA("ImageButton")) and v.Visible then
                                local text = (v:IsA("TextButton") and v.Text or ""):lower()
                                local name = v.Name:lower()
                                for _, kw in next, AUTOJOIN_KEYWORDS do
                                    if text:find(kw, 1, true) or name:find(kw, 1, true) then
                                        found = v
                                        break
                                    end
                                end
                            end
                        end
                    end)
                    return found
                end

                task.spawn(function()
                    while shared and not shared.is_unloading do
                        task.wait(2)
                        if auto_join_active and not plr.Character then
                            local btn = find_join_button_23()
                            if btn then
                                pcall(function()
                                    pcall(replicatesignal, btn.MouseButton1Click)
                                    firesignal(btn.MouseButton1Click)
                                end)
                            end
                        end
                    end
                end)
            end)) then
                pcall(function() library:Notify("23 TAB (Menu Watch) UI FAILED - see console", 20) end)
            end

            -- Saved Teleports (your own tp_store points) shown here too, one
            -- light+button per point, so you can see at a glance which of
            -- YOUR spots are empty vs. occupied - not just the fixed inn
            -- list above. This block reads the same
            -- HYDROXIDE/teleport_points.json file the Teleport tab writes
            -- to (own pcall closure, same 200-local-safety reasoning as
            -- every other block on this tab).
            local ok_23tp, err_23tp = pcall(function()
                local group_23tp = Tabs.TwentyThree:AddLeftGroupbox("Saved Teleports")
                group_23tp:AddLabel("Lit = a player is within 50 studs of that saved spot right now")

                local tp23_points = {}
                local function tp23_load()
                    tp23_points = {}
                    if readfile and isfile and isfile("HYDROXIDE/teleport_points.json") then
                        local ok, data = pcall(function() return Services.HttpService:JSONDecode(readfile("HYDROXIDE/teleport_points.json")) end)
                        if ok and type(data) == "table" then tp23_points = data end
                    end
                end
                tp23_load()

                local function tp23_hrp()
                    return plr.Character and FindFirstChild(plr.Character, "HumanoidRootPart")
                end

                local function teleport_to_point_23(point)
                    if shared and shared.is_unloading then return end
                    local target_pos = Vector3.new(point.x, point.y, point.z)
                    local root = tp23_hrp()
                    if not root then library:Notify("Teleport: character not found"); return end
                    local char = plr.Character
                    local humanoid = char and FindFirstChildOfClass(char, "Humanoid")
                    if humanoid then pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end) end
                    root.CFrame = root.CFrame + Vector3.new(0, 50, 0)
                    task.wait(0.25)

                    root = tp23_hrp()
                    if not root then return end
                    root.CFrame = CFrame.new(target_pos)
                    pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
                    pcall(function() root.AssemblyAngularVelocity = Vector3.new(0, 0, 0) end)

                    local spam_t0 = os.clock()
                    local fired_ok = false
                    while (os.clock() - spam_t0) < 1 do
                        local ok = pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)
                        if ok then fired_ok = true end
                        task.wait(0.05)
                    end
                    library:Notify("Teleport: " .. (fired_ok and "menu fired" or "menu FAILED"), 3)
                    if not fired_ok then return end

                    pcall(function() plr.PlayerGui:WaitForChild("StartMenu", 30) end)
                    if plr.PlayerGui:FindFirstChild("StartMenu") then
                        pcall(function()
                            if plr.PlayerGui.StartMenu:FindFirstChild("Choices") and
                               plr.PlayerGui.StartMenu.Choices:FindFirstChild("Play") then
                                firesignal(plr.PlayerGui.StartMenu.Choices.Play.MouseButton1Click)
                            end
                        end)
                    end
                end

                local function tp23_toggle_id(pname)
                    return "tp23_" .. pname:gsub("%s", "_"):gsub("[^%w_]", "")
                end

                local function tp23_rebuild_list()
                    tp23_load()
                    for _, point in ipairs(tp23_points) do
                        local toggle_id = tp23_toggle_id(point.name)
                        if not Toggles[toggle_id] then
                            group_23tp:AddToggle(toggle_id, {
                                Text = point.name,
                                Default = false,
                                Callback = function() end -- read-only status light, not user-driven
                            })
                            group_23tp:AddButton(toggle_id .. "_btn", {
                                Text = "Teleport to " .. point.name,
                                Func = function()
                                    task.spawn(function() teleport_to_point_23(point) end)
                                end
                            })
                        end
                    end
                end
                tp23_rebuild_list()

                group_23tp:AddButton("tp23_refresh", {
                    Text = "Refresh List (new/renamed points)",
                    Tooltip = "Reloads from teleport_points.json and adds lights for any points saved after this loaded",
                    Func = function() tp23_rebuild_list() end
                })

                task.spawn(function()
                    while shared and not shared.is_unloading do
                        for _, point in ipairs(tp23_points) do
                            local toggle_id = tp23_toggle_id(point.name)
                            local toggle = Toggles[toggle_id]
                            if toggle then
                                local target_pos = Vector3.new(point.x, point.y, point.z)
                                local near = false
                                for _, other in next, plrs:GetPlayers() do
                                    if other ~= plr and other.Character and FindFirstChild(other.Character, "HumanoidRootPart") then
                                        if (other.Character.HumanoidRootPart.Position - target_pos).Magnitude <= 50 then
                                            near = true
                                            break
                                        end
                                    end
                                end
                                if toggle.Value ~= near then
                                    pcall(function() toggle:SetValue(near) end)
                                end
                            end
                        end
                        task.wait(2)
                    end
                end)
            end)
            if not ok_23tp then
                warn("[23TAB-SAVEDTP] " .. tostring(err_23tp))
                pcall(function() library:Notify("23 TAB (Saved Teleports) FAILED: " .. tostring(err_23tp), 20) end)
            end

            group_exploits:AddDivider()

            group_exploits:AddButton("enable_aa_bypass", {
                Text = "AA Bypass",
                Tooltip = "EXPERIMENTAL FEATURE",
                Func = function()
                    if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then
                        library:Notify("character not found")
                        return
                    end

                    local hrp = plr.Character.HumanoidRootPart
                    local huma = FindFirstChildOfClass(plr.Character, "Humanoid")
                    local eagle = FindFirstChild(ws.NPCs, "The Eagle")

                    if not eagle or not FindFirstChild(eagle, "HumanoidRootPart") or not FindFirstChild(eagle, "ClickDetector") then
                        library:Notify("didn't find eagle npc")
                        return
                    end

                    task.defer(function()
                        local noclip_con = utility:Connection(rs.RenderStepped, function()
                            if not plr.Character or not hrp or not hrp.Parent then return end

                            for i, v in next, plr.Character:GetDescendants() do
                                if v:IsA("BasePart") then
                                    v.CanCollide = false

                                    if v ~= hrp then
                                        v.RotVelocity = Vector3.new(0, 0, 0)
                                    end
                                end
                            end

                            if huma then
                                huma:SetStateEnabled(5, false)
                                huma:ChangeState(3)
                            end

                            if hrp then
                                local camCFrame = ws.CurrentCamera.CFrame
                                local lookVector = camCFrame.LookVector
                                local flatLook = Vector3.new(lookVector.X, 0, lookVector.Z).Unit

                                if flatLook.Magnitude > 0.01 then
                                    hrp.CFrame = CFrame.new(hrp.Position, hrp.Position + flatLook)
                                end
                            end
                        end)

                        for i = 1, 10 do
                            if not hrp or not hrp.Parent then break end
                            hrp.CFrame = eagle.HumanoidRootPart.CFrame
                            fireclickdetector(eagle.ClickDetector)
                            task.wait(0.1)
                        end

                        if noclip_con then
                            noclip_con:Disconnect()
                        end

                        if plr.Character then
                            for _, part in ipairs(plr.Character:GetDescendants()) do
                                if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                                    if part.Name == "Head" or part.Name == "Torso" then
                                        part.CanCollide = true
                                    else
                                        part.CanCollide = false
                                    end
                                end
                            end

                            if huma then
                                huma:SetStateEnabled(5, true)
                                huma:ChangeState(5)
                            end
                        end
                    end)

                    library:Notify("AA Bypass active, deactivates when forcefield disappears")
                end
            })

