            group_spoofing:AddToggle("spoof_days_enabled", {
                Text = "Enable Day Spoof",
                Default = cheat_client.config.spoof_days_enabled,
                Callback = function(state)
                    cheat_client.config.spoof_days_enabled = state
                    if state then
