                end
            })

            local stop_button = group_trinket_config:AddButton("stop_bot", {
                Text = "Stop Bot",
                Tooltip = "Stop the currently running bot",
                Func = function()
                    if trinket_bot.path_running then
                        trinket_bot.path_running = false
                        mem:RemoveItem("botstarted")
                        mem:RemoveItem("serverhop_count")

                        kick_after_path = false
                        kick_debounce = false
                        kick_trinket_name = ""

                        current_gate_section = 0
                        player_encounters = {}
                        emergency_gate_requested = nil
                        proximity_warnings = {}
                        proximity_repeat_players = {}
                        mana_initialized = false
                        trinket_bot.pending_artifact_logs = {}

                        if cpu and cpu.status and cpu.status.active then
                            cpu.status.active = false
                            setfpscap(240)
                            settings().Rendering.QualityLevel = cpu.services.ql
                            cpu.services.rs:Set3dRenderingEnabled(true)
                        end

                        for _, connection in next, getconnections(plr.Idled) do
                            connection:Enable()
                        end

                        if loot_tracking_connection then
                            pcall(function() loot_tracking_connection:Disconnect() end)
                            loot_tracking_connection = nil
                        end
                        for _, conn in ipairs(quantity_connections) do
                            if conn then
                                pcall(function() conn:Disconnect() end)
                            end
                        end
                        quantity_connections = {}
                        droppedTools = {}
                        usedTools = {}

                        visited_positions = {}

                        if shared.playerAddedConnection then
                            shared.playerAddedConnection:Disconnect()
                            shared.playerAddedConnection = nil
                        end
                        if shared.day_farm_player_connections then
                            for player, conn in pairs(shared.day_farm_player_connections) do
                                if conn and conn.Disconnect then
                                    conn:Disconnect()
                                end
                            end
                            shared.day_farm_player_connections = {}
                        end
                        if shared.deathConnection then
                            shared.deathConnection:Disconnect()
                            shared.deathConnection = nil
                        end
                        if shared.characterAddedConnection then
                            shared.characterAddedConnection:Disconnect()
                            shared.characterAddedConnection = nil
                        end

                        for _, part in ipairs(trinket_bot.point_visualizations) do
                            if part and part.Parent then
                                part:Destroy()
                            end
                        end
                        trinket_bot.point_visualizations = {}

                        if trinket_bot.connections then
                            for name, conn in pairs(trinket_bot.connections) do
                                if conn then
                                    pcall(function() conn:Disconnect() end)
                                end
                            end
                            trinket_bot.connections = {}
                        end

                        if trinket_bot.illu_connections then
                            for _, conn in ipairs(trinket_bot.illu_connections) do
                                if conn then
                                    pcall(function() conn:Disconnect() end)
                                end
                            end
                            trinket_bot.illu_connections = {}
                        end

                        if trinket_bot.gnav_connections then
                            for _, conn in ipairs(trinket_bot.gnav_connections) do
                                if conn then
                                    pcall(function() conn:Disconnect() end)
                                end
                            end
                            trinket_bot.gnav_connections = {}
                        end

                        if active_tween_data then
                            if active_tween_data.tween then
                                pcall(function() active_tween_data.tween:Cancel() end)
                                active_tween_data.tween = nil
                            end
                            if active_tween_data.connection then
                                pcall(function() active_tween_data.connection:Disconnect() end)
                                active_tween_data.connection = nil
                            end
                        end

                        restore_bot_state()

                        if trinket_bot.visualize_enabled then
                            update_visualizations()
                        end

                        library:Notify("Bot manually stopped")
                    else
                        local was_botstarted = mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true"
                        trinket_bot.path_running = false
                        mem:RemoveItem("botstarted")
                        mem:RemoveItem("serverhop_count")

                        if was_botstarted then
                            library:Notify("Bot state reset (was in inconsistent state)")
                        else
                            library:Notify("Bot is not running")
                        end
                    end
                end
            })

            stop_button:SetVisible(false)

            task.spawn(function()
                while shared and not shared.is_unloading and task.wait(0.5) do
                    local is_running = trinket_bot.path_running or (mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true")
                    stop_button:SetVisible(is_running)
                end
            end)

            local group_trinket_looping = Tabs.Botting:AddRightGroupbox("Looping Settings")

            group_trinket_looping:AddToggle("StayInServer", {
                Text = "Stay in Server",
                Default = false,
                Tooltip = "Loops the path in the same server instead of serverhopping"
            })

            group_trinket_looping:AddToggle("ReequipGateInLoop", {
                Text = "Re-equip Gate in Loop",
                Default = cheat_client.config.reequip_gate_in_loop,
                Tooltip = "Automatically re-equip gate tool if it gets unequipped during botting"
            })

            group_trinket_looping:AddSlider("TimeBetweenLooting", {
                Text = "Time Between Looting",
                Default = 5,
                Min = 0,
                Max = 30,
                Rounding = 0,
                Suffix = "m",
                Tooltip = "Wait time before respawning and restarting path (in minutes)"
            })

            if game.PlaceId == 3541987450 or game.PlaceId == 5208655184 then
                local lives_table = {
                    ["Azael"] = 2,
                    ["Kasparan"] = 4,
                    ["Cameo"] = 9
                }

                local function can_pop_pd()
                    if not (mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true") then
                        return false
                    end

                    if not (Toggles.AutoPopPDs and Toggles.AutoPopPDs.Value) then
                        return false
                    end

                    local lives = Get("Lives")
                    if not lives then return false end

                    local race = Get("Race")
                    if not race then return false end

                    local days_survived = Get("DaysSurvived")
                    if not days_survived then return false end

                    local max_lives = lives_table[race] or 3

                    if lives >= max_lives then
                        return false
                    end

                    local last_pd_key = "last_pd_day_" .. plr.UserId
                    if mem:HasItem(last_pd_key) then
                        local last_pd_day = tonumber(mem:GetItem(last_pd_key))
                        if last_pd_day == days_survived then
                            return false
                        end
                    end

                    return true, days_survived
                end

                local function try_pop_pd()
                    local can_pop, current_day = can_pop_pd()
                    if not can_pop then return end

                    local old_lives = Get("Lives")
                    if not old_lives then return end

                    if not plr.Backpack then return end
                    local pd = FindFirstChild(plr.Backpack, "Phoenix Down")
                    if pd and pd:IsA("Tool") then
                        local character = plr.Character
                        if character and FindFirstChild(character, "Humanoid") then
                            character.Humanoid:EquipTool(pd)

                            task.spawn(function()
                                local timeout = tick() + 5
                                while pd.Parent ~= character and tick() < timeout do
                                    task.wait()
                                end

                                if pd.Parent == character then
                                    pd:Activate()
                                    local last_pd_key = "last_pd_day_" .. plr.UserId
                                    mem:SetItem(last_pd_key, tostring(current_day))

                                    task.wait(1)
                                    local new_lives = Get("Lives")
                                    if new_lives then
                                        local msg = string.format("Auto Popped Phoenix Down: %d → %d lives", old_lives, new_lives)
                                        library:Notify(msg)
                                        local server_name, server_region = get_server_info()

                                        local player_count = #plrs:GetPlayers()
                                        local footer_text
                                        if cheat_client.config.webhook_show_username ~= false then
                                            footer_text = string.format("Players: %d/23 | %s | Job: %s", player_count, plr.Name, game.JobId)
                                        else
                                            footer_text = string.format("Players: %d/23 | Job: %s", player_count, game.JobId)
                                        end

                                        local embed = {
                                            title = "Auto Popped Phoenix Down",
                                            description = string.format(
                                                "**Server:** `%s (%s)`\n**Lives:** `%d → %d`",
                                                server_name ~= "" and server_name or "Unknown",
                                                server_region ~= "" and server_region or "Unknown",
                                                old_lives,
                                                new_lives
                                            ),
                                            color = 0xFFAE00,
                                            footer = {
                                                text = footer_text
                                            },
                                            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ")
                                        }

                                        if cheat_client.config.webhook and cheat_client.config.webhook ~= "" then
                                            task.spawn(function()
                                                pcall(function()
                                                    HXD_SEND_WEBHOOK(cheat_client.config.webhook, {
                                                        username = cheat_client.config.webhook_username or "bladee",
                                                        embeds = {embed}
                                                    })
                                                end)
                                            end)
                                        end
                                    else
                                        library:Notify("Used Phoenix Down!")
                                    end
                                end
                            end)
                        end
                    end
                end

                pd_char_connection = utility:Connection(plr.CharacterAdded, function(character)
                    character:WaitForChild("Humanoid", 10)
                    task.wait(1)
                    try_pop_pd()
                end)

                task.spawn(function()
                    while shared and not shared.is_unloading do
                        try_pop_pd()
                        task.wait(15)
                    end
                end)
            end

            local function drop_item(item)
                if not (mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true") then
                    return
                end

                if not plr.Character or not plr.Character:FindFirstChild("Humanoid") then
                    return
                end

                while currently_dropping do
                    task.wait(0.1)
                end
                currently_dropping = true

                if not (Options.AutoDropItems and Options.AutoDropItems.Value) then
                    currently_dropping = false
                    return
                end

                if droppedTools[item.Name] then
                    currently_dropping = false
                    return
                end
                local selected_items = Options.AutoDropItems.Value
                local should_drop = false

                for dropdown_name, enabled in pairs(selected_items) do
                    if enabled and item.Name:gsub(" ", "") == dropdown_name:gsub(" ", "") then
                        should_drop = true
                        break
                    end
                end

                if not should_drop then
                    currently_dropping = false
                    return
                end

                if should_drop then
                    droppedTools[item.Name] = true

                    local character = plr.Character
                    if character and character:FindFirstChild("Humanoid") then
                        local is_scroll = item.Name:lower():find("scroll of") ~= nil
                        local is_ice_essence = item.Name == "Ice Essence"
                        local should_try_use = is_scroll or is_ice_essence

                        local equip_success = pcall(function()
                            character.Humanoid:EquipTool(item)
                        end)

                        if not equip_success then
                            print("[DEBUG] Failed to equip item for dropping")
                            droppedTools[item.Name] = nil
                            currently_dropping = false
                            return
                        end

                        local start_time = tick()
                        local timeout = 3
                        while item.Parent ~= character and (tick() - start_time) < timeout do
                            task.wait(0.1)
                        end

                        if item.Parent ~= character then
                            print(string.format("[DEBUG] Timeout waiting for %s to equip", item.Name))
                            droppedTools[item.Name] = nil
                            currently_dropping = false
                            return
                        end

                        if should_try_use then
                            library:Notify(string.format("Attempting to use %s before dropping...", item.Name))
                            task.wait(0.1)

                            task.spawn(function()
                                if vim then
                                    vim:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                                    task.wait(math.random(1, 15) / 1000)
                                    vim:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                                end
                            end)

                            if utility and utility.LeftClick then
                                utility:LeftClick()
                            end

                            task.wait(0.5)

                            if not item or not item.Parent or (item.Parent ~= character and item.Parent ~= plr.Backpack) then
                                library:Notify(string.format("Used %s successfully!", item.Name))
                                droppedTools[item.Name] = nil
                                currently_dropping = false
                                return
                            end

                            library:Notify(string.format("Could not use %s, dropping instead...", item.Name))

                            if item.Parent == plr.Backpack then
                                pcall(function()
                                    character.Humanoid:EquipTool(item)
                                end)
                                task.wait(0.3)
                            end
                        end

                        task.wait(0.075)
                        vim:SendKeyEvent(true, Enum.KeyCode.Backspace, false, game)
                        task.wait()
                        vim:SendKeyEvent(false, Enum.KeyCode.Backspace, false, game)
                        library:Notify(string.format("Dropped %s", item.Name))

                        local item_name = item.Name
                        task.delay(2, function()
                            droppedTools[item_name] = nil
                        end)

                        task.wait(0.3)
                    end

                    currently_dropping = false
                end
            end

            -- Auto Use: actually consumes selected scrolls when picked up, instead of
            -- dropping them. Separate from drop_item's own should_try_use fallback
            -- (which only tries a use as a nicety before dropping regardless of
            -- outcome) - this never drops the item, so a failed/on-cooldown use just
            -- leaves it sitting in the Backpack for the next pickup event to retry.
            local function use_item(item)
                if not (mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true") then
                    return
                end

                if not plr.Character or not plr.Character:FindFirstChild("Humanoid") then
                    return
                end

                while currently_dropping do
                    task.wait(0.1)
                end
                currently_dropping = true

                if usedTools[item.Name] then
                    currently_dropping = false
                    return
                end
                usedTools[item.Name] = true

                local character = plr.Character
                if character and character:FindFirstChild("Humanoid") then
                    local equip_success = pcall(function()
                        character.Humanoid:EquipTool(item)
                    end)

                    if not equip_success then
                        usedTools[item.Name] = nil
                        currently_dropping = false
                        return
                    end

                    local start_time = tick()
                    local timeout = 3
                    while item.Parent ~= character and (tick() - start_time) < timeout do
                        task.wait(0.1)
                    end

                    if item.Parent ~= character then
                        usedTools[item.Name] = nil
                        currently_dropping = false
                        return
                    end

                    library:Notify(string.format("Auto-using %s...", item.Name))
                    -- give the equip time to actually land server-side first - clicking
                    -- immediately after EquipTool can fire before the server has
                    -- processed the equip, so the click gets silently ignored even
                    -- though the tool is already visibly held client-side.
                    task.wait(0.3)

                    local used = false
                    for attempt = 1, 3 do
                        if not item or not item.Parent or (item.Parent ~= character and item.Parent ~= plr.Backpack) then
                            used = true
                            break
                        end

                        pcall(function()
                            if item.Activate then item:Activate() end
                        end)

                        task.spawn(function()
                            if vim then
                                vim:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                                task.wait(math.random(1, 15) / 1000)
                                vim:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                            end
                        end)

                        if utility and utility.LeftClick then
                            utility:LeftClick()
                        end

                        task.wait(0.4)

                        if not item or not item.Parent or (item.Parent ~= character and item.Parent ~= plr.Backpack) then
                            used = true
                            break
                        end
                    end

                    if used then
                        library:Notify(string.format("Used %s successfully!", item.Name))
                    else
                        library:Notify(string.format("Couldn't use %s after 3 tries (on cooldown?) - left in Backpack, will retry next pickup", item.Name))
                    end

                    local item_name = item.Name
                    task.delay(2, function()
                        usedTools[item_name] = nil
                    end)
                end

                currently_dropping = false
            end

            local function setup_backpack_monitoring()
                if auto_drop_backpack_connection then
                    auto_drop_backpack_connection:Disconnect()
                    auto_drop_backpack_connection = nil
                end

                local backpack = plr:WaitForChild("Backpack", 55)
                if not backpack then
                    warn("[DEBUG] Failed to find backpack after 55 seconds")
                    return
                end

                if not utility then
                    return
                end

                auto_drop_backpack_connection = utility:Connection(backpack.ChildAdded, function(obj)
                    if not obj then return end

                    local bot_started = mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true"
                    if not bot_started then return end

                    if not obj:IsA("Tool") then return end

                    task.wait(0.05)

                    if not kick_debounce and Toggles.KickOnTrinket and Toggles.KickOnTrinket.Value and Options.KickTrinketList and Options.KickTrinketList.Value then
                        local selected_trinkets = Options.KickTrinketList.Value
                        for trinket_name, _ in next, selected_trinkets do
                            if obj.Name:gsub(" ", "") == trinket_name:gsub(" ", "") then
                                kick_debounce = true
                                kick_after_path = true
                                kick_trinket_name = trinket_name
                                print(string.format("[Kick on Trinket] MATCH FOUND: %s - will kick after reaching last point", obj.Name))
                                utility:plain_webhook(string.format("@here %s found! Going to last point then kicking.", trinket_name))
                                library:Notify(string.format("%s found! Going to last point...", trinket_name))
                                return
                            end
                        end
                    end

                    task.wait(0.67)

                    for _, item in ipairs(backpack:GetChildren()) do
                        if item then
                            local success, is_tool = pcall(function() return item:IsA("Tool") end)
                            if success and is_tool then
                                local use_selected = Options.AutoUseItems and Options.AutoUseItems.Value or {}
                                local should_use = false
                                for dropdown_name, enabled in pairs(use_selected) do
                                    if enabled and item.Name:gsub(" ", "") == dropdown_name:gsub(" ", "") then
                                        should_use = true
                                        break
                                    end
                                end
                                if should_use then
                                    if not usedTools[item.Name] then
                                        task.spawn(use_item, item)
                                    end
                                elseif not droppedTools[item.Name] then
                                    task.spawn(drop_item, item)
                                end
                            end
                        end
                    end
                end)
            end

            task.spawn(setup_backpack_monitoring)
            auto_drop_char_connection = utility:Connection(plr.CharacterAdded, function()
                task.wait(2.5)
                setup_backpack_monitoring()
            end)
        end

        do
            local macro_system = {
                current_actions = {},
                loaded_macros = {},
                is_running = {},
                stopping = false,
            }
            cheat_client.macro_system = macro_system

            local last_m1 = 0
            utility:Connection(uis.InputBegan, function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 then
                    if plr.Character and FindFirstChild(plr.Character, "Dagger") then
                        last_m1 = tick()
                    end
                end
            end)

            local function left_click()
                if macro_system.stopping then return end
                
                last_m1 = tick()
                task.spawn(function()
                    if vim then
                        vim:SendMouseButtonEvent(0,0,0, true, game, 1)
                        task.wait(math.random(1, 15) / 1000)
                        vim:SendMouseButtonEvent(0,0,0, false, game, 1)
                    end
                end)

                if utility and utility.LeftClick then
                    utility:LeftClick()
                end
            end

            local function right_click()
                if macro_system.stopping then return end
                if utility and utility.RightClick then
                    utility:RightClick()
                end
            end

            local function is_stunned()
                local char = plr.Character
                if not char then return false end
                for _, obj in ipairs(char:GetChildren()) do
                    if cheat_client.im_lazy_stuns[obj.Name] then
                        return true
                    end
                end
                return false
            end

            local function buffer_action()
                if tick() - last_m1 < 0.05 then
                    repeat task.wait() until tick() - last_m1 > 0.05
                end
            end

            local vk_code_map = {
                A = 0x41, B = 0x42, C = 0x43, D = 0x44, E = 0x45, F = 0x46, G = 0x47,
                H = 0x48, I = 0x49, J = 0x4A, K = 0x4B, L = 0x4C, M = 0x4D, N = 0x4E,
                O = 0x4F, P = 0x50, Q = 0x51, R = 0x52, S = 0x53, T = 0x54, U = 0x55,
                V = 0x56, W = 0x57, X = 0x58, Y = 0x59, Z = 0x5A,
                Zero = 0x30, One = 0x31, Two = 0x32, Three = 0x33, Four = 0x34,
                Five = 0x35, Six = 0x36, Seven = 0x37, Eight = 0x38, Nine = 0x39,
                F1 = 0x70, F2 = 0x71, F3 = 0x72, F4 = 0x73, F5 = 0x74, F6 = 0x75,
                F7 = 0x76, F8 = 0x77, F9 = 0x78, F10 = 0x79, F11 = 0x7A, F12 = 0x7B,
                Space = 0x20, Return = 0x0D, Tab = 0x09, Escape = 0x1B, Backspace = 0x08,
                LeftShift = 0xA0, RightShift = 0xA1, LeftControl = 0xA2, RightControl = 0xA3,
                LeftAlt = 0xA4, RightAlt = 0xA5, CapsLock = 0x14,
                Up = 0x26, Down = 0x28, Left = 0x25, Right = 0x27,
                Insert = 0x2D, Delete = 0x2E, Home = 0x24, End = 0x23,
                PageUp = 0x21, PageDown = 0x22,
                NumLock = 0x90, KeypadZero = 0x60, KeypadOne = 0x61, KeypadTwo = 0x62,
                KeypadThree = 0x63, KeypadFour = 0x64, KeypadFive = 0x65, KeypadSix = 0x66,
                KeypadSeven = 0x67, KeypadEight = 0x68, KeypadNine = 0x69,
                KeypadMultiply = 0x6A, KeypadPlus = 0x6B, KeypadMinus = 0x6D,
                KeypadPeriod = 0x6E, KeypadDivide = 0x6F,
            }

            local vk_name_map = {}
            for name, code in pairs(vk_code_map) do
                vk_name_map[code] = name
            end

            local function find_tool(name)
                local lower = name:lower()
                for _, t in ipairs(plr.Backpack:GetChildren()) do
                    if t:IsA("Tool") and t.Name:lower() == lower then return t end
                end
                if plr.Character then
                    for _, t in ipairs(plr.Character:GetChildren()) do
                        if t:IsA("Tool") and t.Name:lower() == lower then return t end
                    end
                end
            end

            local active_nostun_conns = {}
            local function run_action(action)
                if macro_system.stopping then return end
                local char = plr.Character
                if action.type == "equip" then
                    local tool = find_tool(action.tool)
                    if tool and char then
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        if hum then hum:EquipTool(tool) end
                    end
                elseif action.type == "unequip" then
                    if char then
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        if hum then hum:UnequipTools() end
                    end
                    task.wait(0.005)
                elseif action.type == "wait" then
                    task.wait(action.duration or 0.1)
                elseif action.type == "bufferaction" then
                    buffer_action()
                elseif action.type == "waitstun" then
                    if is_stunned() then
                        repeat task.wait() until not is_stunned() or macro_system.stopping
                    end
                elseif action.type == "loopclick" then
                    local duration = action.duration or 1
                    local start_time = tick()
                    while tick() - start_time < duration and macro_system.is_running and not macro_system.stopping do
                        left_click()
                        task.wait()
                    end
                elseif action.type == "leftclick" then
                    left_click()
                    task.wait()
                elseif action.type == "rightclick" then
                    right_click()
                    task.wait()
                elseif action.type == "activate" then
                    if char then
                        local tool = char:FindFirstChildOfClass("Tool")
                        if tool then tool:Activate() end
                    end
                elseif action.type == "charge" then
                    if utility and utility.charge_mana then
                        utility:charge_mana()
                    end
                elseif action.type == "stopcharge" then
                    if utility and utility.decharge_mana then
                        utility:decharge_mana()
                    end
                elseif action.type == "chargeuntil" then
                    if utility and utility.charge_mana_until then utility:charge_mana_until(action.amount or 50) end
                elseif action.type == "nostun" then
                    local dur = action.duration or 0.2
                    local char = plr.Character
                    if not char or not utility or not utility.Connection then return end
                    local conn
                    conn = utility:Connection(char.ChildAdded, function(obj)
                        if cheat_client and cheat_client.stuns and cheat_client.stuns[obj.Name] then
                            task.defer(obj.Destroy, obj)
                        end
                    end)
                    table.insert(active_nostun_conns, conn)
                    task.delay(dur, function()
                        if conn then
                            conn:Disconnect()
                            local idx = table.find(active_nostun_conns, conn)
                            if idx then table.remove(active_nostun_conns, idx) end
                        end
                    end)
                elseif action.type == "punch" then
                    if char and utility and utility.Connection then
                        local punched = false
                        local conn

                        conn = utility:Connection(char.ChildAdded, function(obj)
                            if obj:IsA("Accessory") and obj.Name == "LightAttack" then
                                punched = true
                                if conn then conn:Disconnect() end
                            end
                        end)

                        local hum = char:FindFirstChildOfClass("Humanoid")

                        local hasDagger = FindFirstChild(char, "Dagger")
                        local hasSword = FindFirstChild(char, "Sword")

                        if hasDagger or hasSword then
                            local bypass
                            if hasDagger then
                                bypass = find_tool("Agility")
                            elseif hasSword then
                                bypass = find_tool("Action Surge")
                            end

                            if bypass and hum then
                                hum:EquipTool(bypass)
                                task.wait(0.04)
                            end
                        end

                        if hum then hum:UnequipTools() end
                        task.wait(0.01)

                        while not punched and not macro_system.stopping do
                            left_click()
                            task.wait(0.01)
                        end

                        if conn then conn:Disconnect() end
                    end
                elseif action.type == "heavypunch" then
                    if char and utility and utility.Connection then
                        local punched = false
                        local conn

                        conn = utility:Connection(char.ChildAdded, function(obj)
                            if obj:IsA("Accessory") and obj.Name == "HeavyAttack" then
                                punched = true
                                if conn then conn:Disconnect() end
                            end
                        end)

                        local hum = char:FindFirstChildOfClass("Humanoid")

                        local hasDagger = FindFirstChild(char, "Dagger")
                        local hasSword = FindFirstChild(char, "Sword")

                        if hasDagger or hasSword then
                            local bypass
                            if hasDagger then
                                bypass = find_tool("Agility")
                            elseif hasSword then
                                bypass = find_tool("Action Surge")
                            end

                            if bypass and hum then
                                hum:EquipTool(bypass)
                                task.wait(0.04)
                            end
                        end

                        if hum then hum:UnequipTools() end
                        task.wait(0.01)

                        while not punched and not macro_system.stopping do
                            right_click()
                            task.wait(0.01)
                        end

                        if conn then conn:Disconnect() end
                    end
                elseif action.type == "keyclick" then
                    local vk = tonumber(action.keycode)
                    if vk then
                        if not cheat_client.window_active then return end
                        keypress(vk)
                        task.wait(0.05)
                        keyrelease(vk)
                    end
                elseif action.type == "keypress" then
                    local vk = tonumber(action.keycode)
                    if vk then
                        if not cheat_client.window_active then return end
                        keypress(vk)
                    end
                elseif action.type == "keyrelease" then
                    local vk = tonumber(action.keycode)
                    if vk then
                        keyrelease(vk)
                    end
                elseif action.type == "executecode" then
                    if action.file and action.file ~= "" then
                        local file_path = "HYDROXIDE/macros/" .. action.file
                        if isfile(file_path) then
                            local success, err = pcall(function()
                                loadstring(readfile(file_path))()
                            end)
                            if not success then
                                warn("ExecuteCode error: " .. tostring(err))
                            end
                        else
                            warn("ExecuteCode: File not found - " .. action.file)
                        end
                    end
                end
            end

            local function run_macro(actions, macro_name)
                if not plr.Character then return end

                local name = macro_name or "unnamed"
                macro_system.is_running[name] = true

                for _, action in ipairs(actions) do
                    if action.type == "loopclick" or action.type == "chargeuntil" then
                        task.spawn(run_action, action)
                    else
                        run_action(action)
                    end
                end

                task.wait(0.5)
                macro_system.is_running[name] = nil
            end

            local function format_list(actions)
                if #actions == 0 then return "No actions added" end

                local regular_actions = {}
                local keybind_actions = {}

                for i, a in ipairs(actions) do
                    if a.type == "keybind" then
                        table.insert(keybind_actions, a)
                    else
                        table.insert(regular_actions, a)
                    end
                end

                local lines = {}
                local max_show = 8

                for i, a in ipairs(regular_actions) do
                    if i > max_show then
                        table.insert(lines, "... +" .. (#regular_actions - max_show) .. " more")
                        break
                    end
                    local text
                    if a.type == "equip" then text = i .. ". Equip: " .. a.tool
                    elseif a.type == "unequip" then text = i .. ". Unequip"
                    elseif a.type == "wait" then text = string.format("%d. Wait: %.2fs", i, a.duration)
                    elseif a.type == "click" then text = i .. ". Click"
                    elseif a.type == "activate" then text = i .. ". Activate"
                    elseif a.type == "charge" then text = i .. ". Charge Mana"
                    elseif a.type == "stopcharge" then text = i .. ". Stop Charge"
                    elseif a.type == "chargeuntil" then text = i .. ". Charge Until: " .. (a.amount or 50)
                    elseif a.type == "nostun" then text = string.format("%d. No Stun: %.2fs", i, a.duration or 0.2)
                    elseif a.type == "punch" then text = i .. ". Punch"
                    elseif a.type == "heavypunch" then text = i .. ". Heavy Punch"
                    elseif a.type == "leftclick" then text = i .. ". Left Click"
                    elseif a.type == "rightclick" then text = i .. ". Right Click"
                    elseif a.type == "loopclick" then text = string.format("%d. Loop Click: %.2fs", i, a.duration or 1)
                    elseif a.type == "bufferaction" then text = i .. ". Buffer Action"
                    elseif a.type == "waitstun" then text = i .. ". Wait Stun"
                    elseif a.type == "keyclick" then text = i .. ". Key Click: " .. (vk_name_map[a.keycode] or string.format("0x%02X", a.keycode or 0))
                    elseif a.type == "keypress" then text = i .. ". Key Press: " .. (vk_name_map[a.keycode] or string.format("0x%02X", a.keycode or 0))
                    elseif a.type == "keyrelease" then text = i .. ". Key Release: " .. (vk_name_map[a.keycode] or string.format("0x%02X", a.keycode or 0))
                    elseif a.type == "executecode" then text = i .. ". Execute: " .. (a.file or "?")
                    end
                    if text then table.insert(lines, text) end
                end

                if #keybind_actions > 0 then
                    table.insert(lines, "")
                    table.insert(lines, "")
                    table.insert(lines, "- Keybinds")

                    for i, a in ipairs(keybind_actions) do
                        local text = string.format("%d. %s -> %s", i, a.key or "?", a.tool or "?")
                        table.insert(lines, text)
                    end
                end

                if #lines == 0 then return "No actions added" end
                return table.concat(lines, "\n")
            end

            local function get_macros()
                local folder = "HYDROXIDE/macros"
                if not isfolder then return {} end
                if not isfolder(folder) then
                    if makefolder then makefolder(folder) end
                    return {}
                end
                local names = {}
                for _, path in ipairs(listfiles(folder)) do
                    local name = path:match("([^/\\]+)%.json$")
                    if name then table.insert(names, name) end
                end
                return names
            end

            local function get_lua_scripts()
                local folder = "HYDROXIDE/macros"
                if not isfolder then return {} end
                if not isfolder(folder) then
                    if makefolder then makefolder(folder) end
                    return {}
                end
                local scripts = {}
                for _, path in ipairs(listfiles(folder)) do
                    local name = path:match("([^/\\]+)%.lua$")
                    if name then table.insert(scripts, name .. ".lua") end
                end
                return scripts
            end

            local function encode_value(val)
                local t = typeof(val)
                if t == "string" then
                    return "\"" .. val:gsub("\\", "\\\\"):gsub("\"", "\\\""):gsub("\n", "\\n") .. "\""
                elseif t == "number" or t == "boolean" then
                    return tostring(val)
                elseif t == "table" then
                    local parts = {}
                    for k, v in pairs(val) do
                        table.insert(parts, "\"" .. tostring(k) .. "\": " .. encode_value(v))
                    end
                    return "{ " .. table.concat(parts, ", ") .. " }"
                else
                    return "null"
                end
            end

            local function pretty_json(data)
                local lines = {"{"}
                table.insert(lines, "  \"name\": " .. encode_value(data.name) .. ",")
                table.insert(lines, "  \"keybind\": " .. encode_value(data.keybind) .. ",")
                table.insert(lines, "  \"actions\": [")
                for i, action in ipairs(data.actions) do
                    local comma = i < #data.actions and "," or ""
                    table.insert(lines, "    " .. encode_value(action) .. comma)
                end

                local actions_closing = "  ]"
                if data.keybinds and #data.keybinds > 0 then
                    actions_closing = actions_closing .. ","
                end
                table.insert(lines, actions_closing)

                if data.keybinds and #data.keybinds > 0 then
                    table.insert(lines, "  \"keybinds\": [")
                    for i, kb in ipairs(data.keybinds) do
                        local comma = i < #data.keybinds and "," or ""
                        table.insert(lines, "    " .. encode_value(kb) .. comma)
                    end
                    table.insert(lines, "  ]")
                end

                table.insert(lines, "}")
                return table.concat(lines, "\n")
            end

            local function save_macro(name, actions, keybind)
                if not name or name == "" then
                    library:Notify("Enter a macro name!")
                    return false
                end
                if #actions == 0 then
                    library:Notify("Add at least one action!")
                    return false
                end
                local folder = "HYDROXIDE/macros"
                if not isfolder(folder) then makefolder(folder) end
                local path = folder .. "/" .. name .. ".json"
                local exists = isfile(path)

                local regular_actions = {}
                local keybinds_array = {}
                for _, action in ipairs(actions) do
                    if action.type == "keybind" then
                        table.insert(keybinds_array, {key = action.key, tool = action.tool})
                    else
                        table.insert(regular_actions, action)
                    end
                end

                local data = {
                    name = name,
                    keybind = keybind or "None",
                    actions = regular_actions,
                    keybinds = #keybinds_array > 0 and keybinds_array or nil
                }
                local ok = pcall(function()
                    writefile(path, pretty_json(data))
                end)
                if ok then
                    library:Notify(exists and "Overwrote: " .. name or "Saved: " .. name)
                else
                    library:Notify("Failed to save macro!")
                end
                return ok
            end

            local function load_macro(name)
                local path = "HYDROXIDE/macros/" .. name .. ".json"
                if not isfile(path) then
                    library:Notify("Macro not found!")
                    return nil
                end
                local ok, data = pcall(function()
                    return game:GetService("HttpService"):JSONDecode(readfile(path))
                end)
                return ok and data or nil
            end

            local function delete_macro(name)
                local path = "HYDROXIDE/macros/" .. name .. ".json"
                if isfile(path) then
                    delfile(path)
                    library:Notify("Deleted macro: " .. name)
                    return true
                end
                return false
            end

            local function setup_macro_keybind(name, macro_data)
                if not macro_data or macro_data.keybind == "None" then return end
                local key = Enum.KeyCode[macro_data.keybind]
                if not key then return end

                local running = false
                local conn = utility:Connection(uis.InputBegan, function(input, gpe)
                    if gpe or running then return end
                    if input.KeyCode == key then
                        running = true
                        task.spawn(function()
                            run_macro(macro_data.actions, name)
                            running = false
                        end)
                    end
                end)

                return conn
            end

            local function setup_keybinds_array(keybinds_data)
                local connections = {}

                if keybinds_data then
                    for _, kb in ipairs(keybinds_data) do
                        if kb.key and kb.tool then
                            local key = Enum.KeyCode[kb.key]
                            if key then
                                local conn = utility:Connection(uis.InputBegan, function(input, gpe)
                                    if gpe then return end
                                    if input.KeyCode == key then
                                        local character = plr.Character
                                        if not character then return end

                                        local hum = character:FindFirstChildOfClass("Humanoid")
                                        if not hum then return end

                                        local equipped_tool = character:FindFirstChild(kb.tool)

                                        if equipped_tool and equipped_tool:IsA("Tool") then
                                            hum:UnequipTools()
                                        else
                                            local tool = find_tool(kb.tool)
                                            if tool then
                                                hum:EquipTool(tool)
                                            end
                                        end
                                    end
                                end)
                                table.insert(connections, conn)
                            end
                        end
                    end
                end

                return connections
            end

