                                end
                                print(string.format("  Hidden Connections: %d", hidden_count))
                            end

                            if shared.drawing_containers then
                                print("\n[Drawing Containers]")
                                local total_drawings = 0
                                for container_name, drawings in pairs(shared.drawing_containers) do
