                Button.Text = ""
                Button.Size = UDim2.new(1, 0, 1, 0)
                Button.Position = UDim2.new(0, 0, 0, 0)

                utility:Connection(Button.MouseButton2Click, function()
                    if shared == nil or shared.SPRLS ~= THIS_SCRIPT then
                        if script ~= THIS_SCRIPT then
