                                end) then
                                    Labels = Value
                                    for i, v in pairs(Value) do
                                        pcall(NameRightClick, i, v)
                                    end
                                end

                                if shared == nil then
                                    shared = {}
                                end
                                
                                if shared.SPROC == nil then
                                    shared.SPROC = {}
