                                local Index = (shared.SPROC[v] and shared.SPROC[v].Index) or Index
                                local Original = (shared.SPROC[v] and shared.SPROC[v].Function) or debug.getupvalues(v)[Index]
                                
                                if shared.SPROC then
                                    shared.SPROC[v] = {Index = Index, Function = Original}
                                end

                                debug.setupvalue(v, Index, function(Player, ...)
                                    local Label = Original(Player, ...)
                                    local DummyConstant = "HouseRank"
                                    local DummyTable = Labels

                                    if Player and Label and shared.labelsNeedingButtons then
                                        if #shared.labelsNeedingButtons < 100 then
                                            table.insert(shared.labelsNeedingButtons, {label = Label, player = Player})
                                        end
                                    end

                                    return Label
                                end)
                            end
                        end
                    end
                end))
            end

            InitSpectator()

            utility:Connection(plr.PlayerGui.ChildAdded, function(child)
                if child.Name == "LeaderboardGui" then
                    task.wait(1)
                    InitSpectator()
                end
            end)

            task.spawn(function()
                while shared and not shared.is_unloading do
                    task.wait(1)
                end

                if player_monitor_connections then
                    for player, connections in pairs(player_monitor_connections) do
                        for _, conn in pairs(connections) do
                            if conn and conn.Connected then
                                conn:Disconnect()
                            end
                        end
                    end
                    table.clear(player_monitor_connections)
                end

                if playerLabels then
                    for label, player in pairs(playerLabels) do
                        pcall(function()
                            local spbButton = FindFirstChild(label, "SPB")
                            if spbButton then
                                spbButton:Destroy()
                            end

                            if player then
                                local hasMaxEdict = player:GetAttribute("MaxEdict") == true
                                local hasLeaderstat = is_khei and FindFirstChild(player, "leaderstats") and FindFirstChild(player.leaderstats, "MaxEdict") and player.leaderstats.MaxEdict.Value == true

                                label.TextColor3 = (hasMaxEdict or hasLeaderstat) and Color3.fromRGB(255, 214, 81) or Color3.new(1, 1, 1)
                            end
                        end)
                    end
                    table.clear(playerLabels)
                end

                pcall(function() collectgarbage("collect") end)
            end)
        end
    
        do
            utility:Connection(uis.WindowFocused, function() 
                cheat_client.window_active = true
            end)
        
            utility:Connection(uis.WindowFocusReleased, function() 
                cheat_client.window_active = false
            end)
        end
    
        do
            local notification_connection = nil
            local last_check = 0
            local check_interval = 1

            local function start_notification_updater()
                if notification_connection then return end

                notification_connection = utility:Connection(rs.RenderStepped, LPH_NO_VIRTUALIZE(function()
                    if #shared.notifications == 0 then
                        if notification_connection then
                            notification_connection:Disconnect()
                            notification_connection = nil
                        end
                        return
                    end

                    local count = #shared.notifications
                    local removed_first = false

                    for i = 1, count do
                        local current_tick = tick()
                        local notification = shared.notifications[i]
                        if notification then
                            if current_tick - notification.start_tick > notification.lifetime then
                                task.spawn(notification.destruct, notification)
                                table.remove(shared.notifications, i)
                            elseif count > 35 and not removed_first then
                                removed_first = true
                                local first = table.remove(shared.notifications, 1)
                                task.spawn(first.destruct, first)
                            else
                                local previous_notification = shared.notifications[i - 1]
                                local basePosition
                                if previous_notification then
                                    basePosition = Vector2.new(16, previous_notification.drawings.main_text.Position.y + previous_notification.drawings.main_text.TextBounds.y + 1)
                                else
                                    basePosition = Vector2.new(16, 40)
                                end

                                notification.drawings.shadow_text.Position = basePosition + Vector2.new(1, 1)
                                notification.drawings.main_text.Position = basePosition
                                notification.drawings.shadow_text.Visible = true
                                notification.drawings.main_text.Visible = true
                            end
                        end
                    end
                end))
            end

            utility:Connection(rs.Heartbeat, LPH_NO_VIRTUALIZE(function()
                local current_time = tick()
                if current_time - last_check >= check_interval then
                    last_check = current_time
                    if shared.notifications and #shared.notifications > 0 and not notification_connection then
                        start_notification_updater()
                    end
                end
            end))

            if shared.notifications and #shared.notifications > 0 then
                start_notification_updater()
            end
        end
    
        do
            local function is_moderator_check(player)
                if cheat_client and cheat_client.mod_list and table.find(cheat_client.mod_list, player.UserId) then
                    return true
                end

                local success, isInGroup = pcall(function()
                    return player:IsInGroup(4556484)
                end)

                if success and isInGroup then
                    return true
                end

                return false
            end

            utility:Connection(plrs.PlayerAdded, function(player)
                if is_moderator_check(player) then
                    if Toggles and Toggles.auto_panic and Toggles.auto_panic.Value and
                       Options and Options.auto_panic_options and Options.auto_panic_options.Value and
                       Options.auto_panic_options.Value["Unload on mod join"] then
                        utility:plain_webhook(string.format("**AUTO PANIC** Unloading because a moderator joined - %s (%s)", player.Name, player.UserId))
                        task.wait(0.05)
                        utility:Unload()
                    end
                end
            end)
        end

        do
            local detected_illusionists = {}

            local function handle_illusionist(player)
                if detected_illusionists[player.UserId] then return end
                detected_illusionists[player.UserId] = true

                if (library ~= nil and library.Notify) then
                    utility:sound("rbxassetid://2865227039",2)
                    library:Notify({
                        Title = "⚠️ ILLUSIONIST DETECTED",
                        Description = cheat_client:get_name(player).." ["..player.Name.."] is an illusionist",
                        Time = 10
                    })
                end

                if Toggles and Toggles.auto_panic and Toggles.auto_panic.Value and
                   Options and Options.auto_panic_options and Options.auto_panic_options.Value and
                   Options.auto_panic_options.Value["Unload on Illusionist join"] then
                    utility:plain_webhook(string.format("**AUTO PANIC** Unloading because an Illusionist joined - %s (%s)", player.Name, player.UserId))
                    task.wait(0.05)
                    utility:Unload()
                end
            end

            local function setup_illu_player(player)
                if player == plr then return end

                local function check_and_handle(character)
                    local backpack = FindFirstChild(player, "Backpack")
                    if not backpack then return false end
                    local observe_tool = FindFirstChild(backpack, "Observe") or (character and FindFirstChild(character, "Observe"))
                    if observe_tool then
                        handle_illusionist(player)
                        return true
                    end
                    return false
                end

                local function setup_backpack_listener()
                    local backpack = FindFirstChild(player, "Backpack")
                    if not backpack then return end
                    if detected_illusionists[player.UserId] then return end

                    local waiting_connection
                    waiting_connection = utility:Connection(backpack.ChildAdded, function(child)
                        if child.Name == "Observe" then
                            handle_illusionist(player)
                            if waiting_connection then
                                waiting_connection:Disconnect()
                                waiting_connection = nil
                            end
                        end
                    end)
                end

                task.spawn(function()
                    local backpack = FindFirstChild(player, "Backpack")
                    if not backpack then
                        backpack = player:WaitForChild("Backpack", 10)
                    end
                    if not backpack then return end

                    if player.Character then
                        if not check_and_handle(player.Character) then
                            setup_backpack_listener()
                        end
                    else
                        setup_backpack_listener()
                    end
                end)

                utility:Connection(player.CharacterAdded, function(character)
                    task.wait(0.5)
                    detected_illusionists[player.UserId] = nil
                    if not check_and_handle(character) then
                        setup_backpack_listener()
                    end
                end)
            end

            for _, player in next, plrs:GetPlayers() do
                setup_illu_player(player)
            end

            utility:Connection(plrs.PlayerAdded, setup_illu_player)

            utility:Connection(plrs.PlayerRemoving, function(player)
                detected_illusionists[player.UserId] = nil
            end)
        end
        
        do
            utility:Connection(plrs.PlayerRemoving, function(player)
                if player.Character and cs:HasTag(player.Character,'Danger') then
                    if (library ~= nil and library.Notify) then
                        library:Notify(cheat_client:get_name(player).." ["..player.Name.."] combat logged, what a retard LOL", Color3.fromRGB(5,139,252))
                    end
                end
            end)
        end
        

        do
            utility:Connection(plrs.PlayerAdded, function(player)
                task.spawn(cheat_client.detect_mod, cheat_client, player)

                if player.Character then
                    task.spawn(cheat_client.detect_specs, cheat_client, player)
                end

                utility:Connection(player.CharacterAdded, function(character)
                    task.wait(1)
                    task.spawn(cheat_client.detect_specs, cheat_client, player)
                end)
            end)
        end

        do
            local function readCSG(union)
                local result = gethiddenproperty(union, "PhysicalConfigData")
                local unionData
                
                if type(result) == "table" and #result >= 2 then
                    unionData = result[2]
                else
                    unionData = select(2, pcall(function() return gethiddenproperty(union, "PhysicalConfigData") end))
                    
                    if type(unionData) ~= "string" then
                        warn("DEBUG - PhysicalConfigData type:", type(result))
                        
                        for _, prop in pairs({"BinaryData", "MeshData", "RawData", "ConfigData"}) do
                            local success, data = pcall(function() return gethiddenproperty(union, prop) end)
                            if success and type(data) == "string" and #data > 100 then
                                warn("Found usable data in property:", prop)
                                unionData = data
                                break
                            end
                        end
                        
                        if type(unionData) ~= "string" then
                            warn("WARNING: Could not get valid CSG data. Captcha bypass may fail.")
                            return {}
                        end
                    end
                end
                
                local unionDataStream = tostring(unionData)
                if type(unionDataStream) ~= "string" then
                    warn("ERROR: Failed to convert union data to string")
                    return {}
                end

                local function readByte(n)
                    if #unionDataStream < n then
                        return ""
                    end
                    local returnData = unionDataStream:sub(1, n)
                    unionDataStream = unionDataStream:sub(n+1, #unionDataStream)
                    return returnData
                end;

                readByte(51);

                local points = {};

                while #unionDataStream > 0 do
                    readByte(20)
                    readByte(20)

                    local vertSizeRaw = readByte(8)
                    if #vertSizeRaw < 8 then break end
                    local vertSize = string.unpack('ii', vertSizeRaw);

                    for i = 1, (vertSize/3) do
                        local vertRaw = readByte(12)
                        if #vertRaw < 12 then break end
                        local x, y, z = string.unpack('fff', vertRaw)
                        points[#points + 1] = union.CFrame:ToWorldSpace(CFrame.new(x, y, z)).Position;
                    end;

                    local faceSizeRaw = readByte(4)
                    if #faceSizeRaw < 4 then break end
                    local faceSize = string.unpack('I', faceSizeRaw);
                    readByte(faceSize * 4);
                end;

                return points;
            end;

            function solveCaptcha(union)
                local worldModel = Instance.new('WorldModel');
                worldModel.Parent = cg;

                local newUnion = union:Clone()
                newUnion.Parent = worldModel;

                local cameraCFrame = gethiddenproperty(union.Parent, "CameraCFrame");
                local points = readCSG(union);

                local rangePart = Instance.new('Part');
                rangePart.Parent = worldModel;
                rangePart.CFrame = cameraCFrame:ToWorldSpace(CFrame.new(-8, 0, 0))
                rangePart.Size = Vector3.new(1, 100, 100);

                local model = Instance.new('Model', worldModel);
                local baseModel = Instance.new('Model', worldModel);

                baseModel.Name = 'Base';
                model.Name = 'Final';

                for i, v in next, points do
                    local part = Instance.new('Part', baseModel);
                    part.CFrame = CFrame.new(v);
                    part.Size = Vector3.new(0.1, 0.1, 0.1);
                end;

                local seen = false;
                for i = 0, 100 do
                    rangePart.CFrame = rangePart.CFrame * CFrame.new(1, 0, 0)

                    local overlapParams = OverlapParams.new();
                    overlapParams.FilterType = Enum.RaycastFilterType.Whitelist;
                    overlapParams.FilterDescendantsInstances = {baseModel};

                    local bob = worldModel:GetPartsInPart(rangePart, overlapParams);
                    if(seen and #bob <= 0) then break end;

                    for i, v in next, bob do
                        seen = true;

                        local new = v:Clone();

                        new.Parent = model;
                        new.CFrame = CFrame.new(new.Position);
                    end;
                end;

                for i, v in next, model:GetChildren() do
                    v.CFrame = v.CFrame * CFrame.Angles(0, math.rad(union.Orientation.Y), 0);
                end;

                local shorter, found = math.huge, '';
                local result = model:GetExtentsSize();

                local values = {
                    ['Arocknid'] = Vector3.new(11.963972091675, 6.2284870147705, 12.341609954834),
                    ['Howler'] = Vector3.new(2.904595375061, 7.5143890380859, 6.4855442047119),
                    ['Evil Eye'] = Vector3.new(6.7253036499023, 6.2872190475464, 11.757738113403),
                    ['Zombie Scroom'] = Vector3.new(4.71413230896, 4.400146484375, 4.7931442260742),
                    ['Golem'] = Vector3.new(17.123439788818, 21.224365234375, 6.9429664611816),
                };

                for i, v in next, values do
                    if((result - v).Magnitude < shorter) then
                        found = i;
                        shorter = (result - v).Magnitude;
                    end;
                end;

                worldModel:Destroy();
                worldModel = nil;

                return found;
            end

            local time_elapsed = 0
            local playerDays = 0
            local gacha_cooldown_until = 0 -- os.clock() timestamp; failing the captcha locks Xenyari out for ~5min

            local function no_kick()
                if Toggles and Toggles.no_kick and Toggles.no_kick.Value then
                    return true
                end
                return false
            end
            
            local function kickPlayer(message)
                if cs:HasTag(plr.Character, "Danger") then
                    repeat task.wait() until not cs:HasTag(plr.Character, "Danger")
                end

                utility:plain_webhook(message)
                rps.Requests.ReturnToMenu:InvokeServer()
                plr:Kick(message)
                utility:Unload()
            end

            local function Get(value)
                local success, result = pcall(function()
                    return rps.Requests.Get:InvokeServer(utf8.char(65532) .. "\240\159\152\131", value)[value]
                end)
                return success and result or nil
            end

            local function check_silver()
                local silver = Get("Silver")

                if not silver then
                    return true, nil
                end

                return silver >= 250, silver
            end

            local function is_gacha_moderator(player)
                if cheat_client and cheat_client.mod_list and table.find(cheat_client.mod_list, player.UserId) then
                    return true
                end

                local success, isInGroup = pcall(function()
                    return player:IsInGroup(4556484)
                end)
                if success and isInGroup then
                    local role = player:GetRoleInGroup(4556484)
                    if role ~= "Guest" then
                        return true
                    end
                end

                return false
            end

            local function has_gacha_illusionist()
                for _, other_player in next, plrs:GetPlayers() do
                    if other_player ~= plr then
                        local backpack = FindFirstChild(other_player, "Backpack")
                        local observed = backpack and FindFirstChild(backpack, "Observe")
                        if not observed and other_player.Character then
                            observed = FindFirstChild(other_player.Character, "Observe")
                        end
                        if observed then
                            return true
                        end
                    end
                end
                return false
            end

            local function has_player_near_gacha(range)
                if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then return false end
                local my_pos = plr.Character.HumanoidRootPart.Position

                for _, other_player in next, plrs:GetPlayers() do
                    if other_player ~= plr and other_player.Character then
                        local their_hrp = FindFirstChild(other_player.Character, "HumanoidRootPart")
                        if their_hrp and (their_hrp.Position - my_pos).Magnitude <= range then
                            return true
                        end
                    end
                end
                return false
            end

            local function gacha()
                if not (Toggles and Toggles.gacha_farm and Toggles.gacha_farm.Value) then return false end
                if not plr.Character then return end
                if os.clock() < gacha_cooldown_until then return false end

                -- Dialogue Only: don't walk up or click Xenyari at all - a
                -- separate script drives that (and solves the captcha). We
                -- only watch dialogue_remote (see the standalone watcher
                -- below) and click through Bye/pay whenever a dialogue shows
                -- up, however it got triggered.
                if Toggles and Toggles.gacha_dialogue_only and Toggles.gacha_dialogue_only.Value then
                    return false
                end

                -- A captcha (or the post-solve "I'll pay" dialogue) is
                -- already up on screen - don't re-fire the click detector or
                -- open a second dialogue_remote listener on top of the one
                -- already watching it, whether we're solving it ourselves or
                -- leaving it for a separate solver script.
                if FindFirstChild(plr.PlayerGui, 'Captcha') then return true end

                if Toggles and Toggles.gacha_skip_illusionist and Toggles.gacha_skip_illusionist.Value and has_gacha_illusionist() then
                    return false
                end

                if Toggles and Toggles.gacha_skip_mods and Toggles.gacha_skip_mods.Value then
                    for _, other_player in next, plrs:GetPlayers() do
                        if other_player ~= plr and is_gacha_moderator(other_player) then
                            return false
                        end
                    end
                end

                local npc = FindFirstChild(workspace.NPCs, "Xenyari")
                local npcHead = FindFirstChild(npc, "Head")
                local clickDetector = FindFirstChildWhichIsA(npc, "ClickDetector")

                if not workspace.NPCs or not FindFirstChild(workspace.NPCs, "Xenyari") or
                not FindFirstChild(workspace.NPCs.Xenyari, "Head") or
                not FindFirstChildWhichIsA(workspace.NPCs.Xenyari, "ClickDetector") then
                    return false
                end

                local distanceFromNPC = plr:DistanceFromCharacter(npcHead.Position)
                if distanceFromNPC > 20 then
                    return false
                end

                local gacha_player_range = (Options and Options.GachaDistance and Options.GachaDistance.Value) or 20
                if gacha_player_range > 0 and has_player_near_gacha(gacha_player_range) then
                    if plr.Character and cs:HasTag(plr.Character, "Danger") then
                        repeat task.wait(0.1) until not plr.Character or not cs:HasTag(plr.Character, "Danger")
                    end

                    utility:plain_webhook(string.format("%s (%s) had a player come too close during gacha - serverhopping", plr.Name, plr.UserId))

                    if rps.Requests and FindFirstChild(rps.Requests, "ReturnToMenu") and plr.Character then
                        pcall(function()
                            rps.Requests.ReturnToMenu:InvokeServer()
                        end)
                    end

                    utility:Serverhop()
                    return false
                end

                local has_enough_silver, silver_amount = check_silver()
                if not has_enough_silver then
                    if Toggles and Toggles.gacha_low_silver_kick and Toggles.gacha_low_silver_kick.Value then
                        kickPlayer(string.format("%s (%s) has low silver for gacha (%d < 250)", plr.Name, plr.UserId, silver_amount or 0))
                    end
                    return false
                end

                if not playerDays then
                    playerDays = utility:getPlayerDays() or 0
                    if not playerDays then
                        repeat
                            playerDays = utility:getPlayerDays()
                            task.wait(0.1)
                        until playerDays
                    end
                end
                
                local dialogue_settled = false

                if dialogue_remote then
                    local dialogConnection
                    dialogConnection = utility:Connection(dialogue_remote.OnClientEvent, function(dialogData)
                        task.wait(1)

                        pcall(function()
                            local choice_strs = {}
                            if dialogData.choices then
                                for _, c in next, dialogData.choices do table.insert(choice_strs, tostring(c)) end
                            end
                            warn(string.format("[GACHA DIALOGUE] speaker=%s msg=%s choices=%s",
                                tostring(dialogData.speaker), tostring(dialogData.msg),
                                #choice_strs > 0 and table.concat(choice_strs, " | ") or "(none)"))
                        end)

                        if not dialogData.choices then
                            dialogue_remote:FireServer({exit = true})
                            task.wait(1)
                            dialogConnection:Disconnect()
                            dialogue_settled = true
                        else
                            -- Three cases share this same event:
                            --  1. Captcha wrong -> Xenyari locks you out for
                            --     ~5min and the only/first useful choice is
                            --     "Bye" - prefer that, and start the cooldown
                            --     so gacha() stops hammering the NPC for
                            --     those 5 minutes.
                            --  2. Captcha right (solved by us OR, in Dialogue
                            --     Only mode, by a separate solver script) ->
                            --     the follow-up choice to actually claim the
                            --     scroll is "I'll pay" - prefer that so the
                            --     reward doesn't get missed.
                            --  3. Neither matches -> fall back to choices[1]
                            --     like before.
                            local pick = dialogData.choices[1]
                            local matched_bye = false
                            for _, choice_entry in next, dialogData.choices do
                                -- a choice can be a plain string OR a table with a
                                -- Text/text field (same as talk_to_nearest_npc's
                                -- pickChoice elsewhere) - stringifying the table
                                -- itself instead of reading its text silently never
                                -- matched "bye", which is why this went undetected.
                                local ctext = type(choice_entry) == "table" and (choice_entry.Text or choice_entry.text) or choice_entry
                                local lower_choice = tostring(ctext):lower()
                                if lower_choice:find("bye", 1, true) then
                                    pick = choice_entry
                                    matched_bye = true
                                    gacha_cooldown_until = os.clock() + 300
                                    break
                                elseif lower_choice:find("pay", 1, true) then
                                    pick = choice_entry
                                end
                            end
                            dialogue_remote:FireServer({choice = pick})
                            if matched_bye then
                                dialogConnection:Disconnect()
                                dialogue_settled = true
                            end
                        end
                    end)
                end

                -- fireclickdetector is an exploit-only call with no real
                -- mouse input behind it at all - suspected to be part of why
                -- gacha attempts were getting flagged. Click Xenyari with a
                -- real simulated mouse event (VirtualInputManager) at his
                -- on-screen position instead, same as the captcha answer
                -- clicks below and the mine-swing pattern elsewhere in this
                -- file - this doesn't need the Roblox window focused, and
                -- looks like a genuine player click. Falls back to
                -- fireclickdetector only if he's not currently on-screen.
                local function real_click_xenyari()
                    local camera = workspace.CurrentCamera
                    if camera and npcHead then
                        local ok, screenPos, onScreen = pcall(function()
                            return camera:WorldToScreenPoint(npcHead.Position)
                        end)
                        if ok and onScreen then
                            vim:SendMouseButtonEvent(screenPos.X, screenPos.Y, 0, true, game, 0)
                            task.wait(0.05)
                            vim:SendMouseButtonEvent(screenPos.X, screenPos.Y, 0, false, game, 0)
                            return
                        end
                    end
                    fireclickdetector(clickDetector)
                end

                -- If we're still on the ~5min cooldown from a prior failed
                -- captcha, clicking Xenyari does NOT bring up a new Captcha -
                -- it immediately brings up a "you failed, wait 5 min" dialogue
                -- message (with a "Bye" choice) instead. The old exit
                -- condition here only recognized CaptchaLoad/Captcha showing
                -- up, so on cooldown it never triggered and this just spammed
                -- clicks every 0.25s forever, re-triggering that same gate
                -- message nonstop and never giving the dialogConnection above
                -- a clean moment to actually land the Bye click. Also exit as
                -- soon as we're in ANY dialogue (InDialogue tag), so we stop
                -- clicking and let that connection handle it.
                repeat
                    real_click_xenyari()
                task.wait(0.25);
                until FindFirstChild(plr.PlayerGui, 'CaptchaLoad') or FindFirstChild(plr.PlayerGui, 'Captcha')
                   or (plr.Character and FindFirstChild(plr.Character, "InDialogue"));

                if not (FindFirstChild(plr.PlayerGui, 'CaptchaLoad') or FindFirstChild(plr.PlayerGui, 'Captcha')) then
                    -- Got a dialogue instead of a captcha (cooldown gate, most
                    -- likely) - stop clicking and just wait for dialogConnection
                    -- to pick "Bye" and settle it, instead of hammering again.
                    local settle_start = os.clock()
                    repeat task.wait(0.2) until dialogue_settled or (os.clock() - settle_start) > 15
                    return true
                end

                repeat task.wait(0.05) until FindFirstChild(plr.PlayerGui, 'Captcha');

                repeat
                    local captchaGUI = FindFirstChild(plr.PlayerGui, 'Captcha');
                    local choices = captchaGUI and captchaGUI.MainFrame.Options:GetChildren();
                    local union = captchaGUI and captchaGUI.MainFrame.Viewport.Union;

                    utility:random_wait(true);

                    if(choices and union) then
                        local captchaAnswer = solveCaptcha(union);

                        for i, v in next, choices do
                            if(v.Name == captchaAnswer) then
                                local objVector = v.AbsolutePosition;
                                vim:SendMouseButtonEvent(objVector.X + 65, objVector.Y + 65, 0, true, game, 0);
                                utility:random_wait(true);
                                vim:SendMouseButtonEvent(objVector.X + 65, objVector.Y + 65, 0, false, game, 0);
                                break
                            end
                        end
                    end

                    task.wait(1);
                until not FindFirstChild(plr.PlayerGui, 'Captcha');

                -- Captcha closed - if we got it wrong, the "wait 5 min" +
                -- Bye dialogue is about to arrive via dialogConnection above.
                -- Give it a moment to land before returning, so the outer
                -- gacha loop doesn't immediately re-click Xenyari on top of it.
                local settle_start2 = os.clock()
                repeat task.wait(0.2) until dialogue_settled or (os.clock() - settle_start2) > 15

                return true
            end

            -- Dialogue Only watcher: while Gacha: Dialogue Only is on, this
            -- never clicks Xenyari itself (a separate script does that and
            -- solves the captcha) - it just watches dialogue_remote and
            -- clicks through whatever dialogue results: "I'll pay" on a
            -- success (that's how the scroll actually gets handed over after
            -- the captcha, so it's preferred over any other choice first),
            -- "Bye" if it failed, otherwise falls back to the first choice.
            task.spawn(function()
                while shared and not shared.is_unloading and not dialogue_remote do task.wait(0.5) end
                if not dialogue_remote then return end
                utility:Connection(dialogue_remote.OnClientEvent, function(dialogData)
                    if not (Toggles and Toggles.gacha_dialogue_only and Toggles.gacha_dialogue_only.Value) then return end
                    task.wait(1)
                    if not dialogData.choices then
                        pcall(function() dialogue_remote:FireServer({exit = true}) end)
                        return
                    end
                    local pick = dialogData.choices[1]
                    for _, choice_entry in next, dialogData.choices do
                        local ctext = type(choice_entry) == "table" and (choice_entry.Text or choice_entry.text) or choice_entry
                        local lc = tostring(ctext):lower()
                        if lc:find("pay", 1, true) then
                            pick = choice_entry
                            break
                        elseif lc:find("bye", 1, true) then
                            pick = choice_entry
                        end
                    end
                    pcall(function() dialogue_remote:FireServer({choice = pick}) end)
                end)
            end)

            do
                local rare_scrolls = {
                    ["Scroll of Snarvindur"] = true,
                    ["Scroll of Percutiens"] = true,
                    ["Scroll of Hoppa"] = true,
                }

                if plr.Backpack then
                    utility:Connection(plr.Backpack.ChildAdded, function(item)
                        if not (Toggles and Toggles.gacha_kick_rare_scroll and Toggles.gacha_kick_rare_scroll.Value) then return end
                        if not item:IsA("Tool") or not rare_scrolls[item.Name] then return end

                        kickPlayer(string.format("%s (%s) picked up rare scroll: %s", plr.Name, plr.UserId, item.Name))
                    end)
                end
            end

            local function day_goal()
                local day_goal_value = (Options and Options.day_goal and Options.day_goal.Value) or "1"
                local day_goal = tonumber(day_goal_value) or 1

                if playerDays >= day_goal then
                    if Toggles and Toggles.day_goal_kick and Toggles.day_goal_kick.Value then
                        if no_kick() then
                            utility:plain_webhook(string.format("@here %s (%s) reached day goal: %d (no_kick enabled, not kicking)", plr.Name, plr.UserId, playerDays))
                        else
                            kickPlayer(string.format("%s reached day goal: %d", plr.Name, plr.UserId, playerDays))
                        end
                    end
                    return true
                end
                return false
            end

            utility:Connection(rps.Requests.DaysSurvivedChanged.OnClientEvent, function(days)
                local day_farm_active = Toggles and Toggles.day_farm and Toggles.day_farm.Value
                local gacha_farm_active = Toggles and Toggles.gacha_farm and Toggles.gacha_farm.Value
                if not day_farm_active and not gacha_farm_active then return end

                playerDays = days
                utility:sound("rbxassetid://6729922069",4)
                utility:plain_webhook(plr.Name .. " is now at " .. playerDays .. " days")

                if day_goal() then
                    return
                end
                
                if gacha() then
                    warn("Successfully interacted with Xenyari!")
                else
                    warn("Not near Xenyari, continuing with normal day farm")
                end
            end)

            -- Gacha's real trigger was ONLY the DaysSurvivedChanged server
            -- event above, which is a Day Farm side effect (fires when your
            -- day counter ticks over) - not something the Gacha Farm toggle
            -- controls on its own. With Day Farm off, that event basically
            -- never fires, so Gacha Farm did nothing even when enabled. This
            -- loop drives it independently, on its own timer.
            task.spawn(function()
                while shared and not shared.is_unloading do
                    if Toggles and Toggles.gacha_farm and Toggles.gacha_farm.Value then
                        local ok, result = pcall(gacha)
                        if not ok then
                            warn("[GACHA LOOP] error: " .. tostring(result))
                        end
                    end
                    task.wait(1)
                end
            end)
        end
    
