        do
            local trinkets = {}
            local auto_trinket_enabled = false

            local artifact_batch = {}
            local batch_timer = nil
            local BATCH_DELAY = 0.25

            utility:Connection(ws.ChildAdded, function(object)
                if object.Name == "Part" and FindFirstChild(object, "ID") then
                    if auto_trinket_enabled then
                        trinkets[#trinkets + 1] = object
                    end

                    local trinket_name, trinket_color, trinket_zindex = cheat_client:identify_trinket(object)
                    if trinket_color == cheat_client.trinket_colors.artifact.Color or trinket_color == cheat_client.trinket_colors.mythic.Color then
                        table.insert(artifact_batch, {
                            name = trinket_name,
                            object = object
                        })

                        if not batch_timer then
                            utility:sound("rbxassetid://6432593850", 2)
                        end

                        if batch_timer then
                            task.cancel(batch_timer)
                        end

                        batch_timer = task.delay(BATCH_DELAY, function()
                            if #artifact_batch == 0 then return end

                            local valid_artifacts = {}
                            for _, artifact in ipairs(artifact_batch) do
                                if artifact.object and artifact.object.Parent then
                                    table.insert(valid_artifacts, artifact)
                                end
                            end

                            artifact_batch = {}
                            if #valid_artifacts == 0 then return end

                            local artifact_names = {}
                            local artifact_objects = {}
                            local artifact_ids = {}
                            for _, artifact in ipairs(valid_artifacts) do
                                table.insert(artifact_names, artifact.name)
                                table.insert(artifact_objects, artifact.object)
                                local id_value = FindFirstChild(artifact.object, "ID")
                                table.insert(artifact_ids, id_value and id_value.Value or "")
                            end

                            local unpicked_artifact_names = {}
                            local unpicked_artifact_ids = {}
                            for idx, artifact_obj in ipairs(artifact_objects) do
                                if artifact_obj and artifact_obj.Parent then
                                    table.insert(unpicked_artifact_names, artifact_names[idx])
                                    table.insert(unpicked_artifact_ids, artifact_ids[idx])
                                end
                            end

                            local first_object = artifact_objects[1]
                            local function detectArtifactArea()
                                if not FindFirstChild(ws, "AreaMarkers") then return "None" end

                                local LocationName = "None"
                                local LocationNumSq = math.huge
                                local Area = ws.AreaMarkers
                                local artifactPos = first_object.Position

                                for i,v in pairs(Area:GetChildren()) do
                                    local diff = artifactPos - v.Position
                                    local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                    if distSq < LocationNumSq then
                                        LocationName = v.Name
                                        LocationNumSq = distSq
                                    end
                                end

                                return LocationName
                            end

                            local area = detectArtifactArea()
                            local area_text = area ~= "None" and " ("..area..")" or ""

                            local artifact_list = table.concat(artifact_names, ", ")
                            local msg = string.format("✨ Artifact%s Spawned: %s%s",
                                #artifact_names > 1 and "s" or "",
                                artifact_list,
                                area_text
                            )
                            library:Notify(msg, 10)

                            local bot_running = (cheat_client.trinket_bot and cheat_client.trinket_bot.path_running) or (mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true")
                            local path_name = cheat_client.trinket_bot and cheat_client.trinket_bot.current_path_name or "None"
                            local nearest_point_index = nil
                            local nearest_point_distance = math.huge

                            if bot_running and cheat_client.trinket_bot.path_points and #cheat_client.trinket_bot.path_points > 0 then
                                local artifact_pos = first_object.Position
                                for i, point in ipairs(cheat_client.trinket_bot.path_points) do
                                    local distance = (point.position - artifact_pos).Magnitude
                                    if distance < nearest_point_distance then
                                        nearest_point_distance = distance
                                        nearest_point_index = i
                                    end
                                end
                            end

                            local function get_last_looted(where)
                                if game.PlaceId ~= 5208655184 then return "N/A" end
                                local success, result = pcall(function()
                                    if where == "cr" then
                                        return math.floor((os.time() - workspace.MonsterSpawns.Triggers.CastleRockSnake.LastSpawned.Value) / 60) .. "m"
                                    elseif where == "deepsunken" then
                                        return math.floor((os.time() - workspace.MonsterSpawns.Triggers.evileye2.LastSpawned.Value) / 60) .. "m"
                                    elseif where == "temple" then
                                        return math.floor((os.time() - workspace.MonsterSpawns.Triggers.MazeSnakes.LastSpawned.Value) / 60) .. "m"
                                    end
                                end)
                                return success and result or "N/A"
                            end

                            local player_count = #plrs:GetPlayers()

                            local server_name, server_region = get_server_info()
                            local webhook_msg = string.format("@here")

                            local fields = {
                                { name = string.format("🎯 Artifact%s", #artifact_names > 1 and "s" or ""), value = artifact_list .. (area ~= "None" and string.format(" (%s)", area) or ""), inline = false }
                            }

                            if bot_running and nearest_point_index then
                                table.insert(fields, { name = "🗺️ Path", value = path_name, inline = true })
                                table.insert(fields, { name = "📍 Nearest Point", value = string.format("#%d (%.0f studs)", nearest_point_index, nearest_point_distance), inline = true })
                            end

                            table.insert(fields, { name = "🌐 Server", value = string.format("%s (%s)", server_name ~= "" and server_name or "Unknown", server_region ~= "" and server_region or "Unknown"), inline = true })

                            table.insert(fields, {
                                name = "⏳ Last Looted",
                                value = string.format("• Castle Rock: %s\n• Sunken: %s\n• Temple of Fire: %s",
                                    get_last_looted("cr"), get_last_looted("deepsunken"), get_last_looted("temple")),
                                inline = false
                            })

                            local footer_text
                            if cheat_client.config.webhook_show_username ~= false then
                                footer_text = string.format("Carbine • %s • %d/23 players • Job %s", plr.Name, player_count, game.JobId)
                            else
                                footer_text = string.format("Carbine • %d/23 players • Job %s", player_count, game.JobId)
                            end

                            local embed = {
                                title = "✨ Artifact Found",
                                color = 0xff3679,
                                fields = fields,
                                thumbnail = {
                                    url = "https://static.wikia.nocookie.net/rogue-lineage/images/d/d8/PhiloRender.png/revision/latest?cb=20251012003300"
                                },
                                footer = {
                                    text = footer_text
                                },
                                timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ")
                            }

                            if cheat_client.config.webhook and cheat_client.config.webhook ~= "" then
                                pcall(function()
                                    HXD_SEND_WEBHOOK(cheat_client.config.webhook, {
                                        username = cheat_client.config.webhook_username or "bladee",
                                        content = webhook_msg,
                                        embeds = {embed}
                                    })
                                end)
                            end

                            -- [Carbine] REMOVED - this used to queue/send the player's
                            -- artifact finds (with name/UserId) to a hardcoded devs'
                            -- Discord webhook ("artifact stream"). No outbound telemetry now.

                            batch_timer = nil
                        end)
                    end
                end
            end)

            local function start_auto_trinket_rendering()
                if cheat_client.feature_connections.auto_trinket then return end

                auto_trinket_enabled = true

                trinkets = {}
                for _,object in next, ws:GetChildren() do
                    if object.Name == "Part" and FindFirstChild(object, "ID") then
                        trinkets[#trinkets + 1] = object
                    end
                end

                cheat_client.feature_connections.auto_trinket = utility:Connection(rs.Heartbeat, LPH_NO_VIRTUALIZE(function(delta_time)
                    if not plr.Character then return end

                    for i = #trinkets, 1, -1 do
                        if not trinkets[i] or not trinkets[i].Parent then
                            table.remove(trinkets, i)
                        end
                    end

                    for _, object in next, trinkets do
                        local trinket_name = cheat_client:identify_trinket(object)
                        if trinket_name == "Azael Horn" then
                            continue
                        end

                        local click_detector = FindFirstChild(object, "ClickDetector", true)
                        local distance = plr:DistanceFromCharacter(object.CFrame.Position)
                        local dist = 9e9

                        if click_detector then
                            dist = click_detector.MaxActivationDistance
                        end

                        if click_detector and distance > 0 and distance < dist then
                            local trinket_id = FindFirstChild(object, "ID")
                            if trinket_id and trinket_id:IsA("StringValue") and cheat_client.trinket_bot and cheat_client.trinket_bot.pending_pickup_ids then
                                table.insert(cheat_client.trinket_bot.pending_pickup_ids, trinket_id.Value)
                                while #cheat_client.trinket_bot.pending_pickup_ids > 100 do
                                    table.remove(cheat_client.trinket_bot.pending_pickup_ids, 1)
                                end
                            end
                            fireclickdetector(click_detector)
                        end
                    end
                end), true)
            end

            local function stop_auto_trinket_rendering()
                if cheat_client.feature_connections.auto_trinket then
                    cheat_client.feature_connections.auto_trinket:Disconnect()
                    cheat_client.feature_connections.auto_trinket = nil
                end

                auto_trinket_enabled = false
                trinkets = {}
            end

            cheat_client.start_auto_trinket_rendering = start_auto_trinket_rendering
            cheat_client.stop_auto_trinket_rendering = stop_auto_trinket_rendering

            if Toggles and Toggles.auto_trinket and Toggles.auto_trinket.Value then
                start_auto_trinket_rendering()
            end
        end

        -- =====================================================================
        -- Monster XP Farm (added module)
        -- Auto-attack (M1), monster proximity detection, silver looting, inn
        -- travel + custom pathing (with inn stops), idle serverhop, and a
        -- weapon-XP / class readiness check. Fully self-contained: it does NOT
        -- modify the Trinket Bot above, it only reuses existing helpers.
        -- =====================================================================
        do
            -- LOAD SIGNAL: if you do NOT see this popup when the script loads,
            -- you are running the GitHub copy, not this edited local file.
            pcall(function()
                if library and library.Notify then
                    library:Notify("CARBINE | XP Farm BUILD 343 loaded - Instant points now get a quick 0.2s settle instead of skipping it entirely, still fixes clipping without visibly stopping", 20)
                end
            end)
            print("[XP FARM] Monster XP Farm module loaded - look on the Botting tab")

            local INN_LIST = {
                "Southern Sanctuary", "Central Sanctuary", "Castle Sanctuary",
                "Wayside Inn", "Flowerlight Town", "Renova", "Oresfall",
                "Santorini", "Scroomville", "Sleeping Snail",
                "Kiki Village", "Frostfall Town", "Morokh Reservoir"
            }

            -- Target class is informational only. Rogue Lineage's per-weapon
            -- mastery requirements aren't exposed to this script, so the actual
            -- gate is the "Required Weapon XP" slider below.
            local CLASS_LIST = {
                "Knight", "Duelist", "Adept", "Mercenary", "Warden",
                "Paladin", "Assassin", "Monk", "Warrior", "Custom"
            }

            -- Heuristic markers for world silver/loot drops. The SilverValue
            -- child is what the game itself tags silver with; the keywords are a
            -- fallback and can be edited if drops are named differently.
            local SILVER_WORDS = { "silver", "satchel", "pouch", "coin", "money" }
            local XP_CHILD_NAMES = { "Exp", "EXP", "XP", "Experience", "Mastery", "Proficiency", "Prof", "Level", "Skill", "WeaponXP" }

            local selected_inn = INN_LIST[1]
            local selected_action = "Move + Wait"
            local selected_weapon = ""

            -- shared between the loops below
            local burst_until = 0                  -- os.clock() deadline for "attack for a duration"
            local last_monster_seen = os.clock()   -- drives idle serverhop
            local cached_count, cached_nearest, cached_dist = 0, nil, math.huge

            local function local_hrp()
                local c = plr.Character
                return (c and FindFirstChild(c, "HumanoidRootPart")) or nil
            end

            -- names of every Tool in the backpack / held, for the weapon picker
            local function get_backpack_tools()
                local names, seen = {}, {}
                for _, container in ipairs({ FindFirstChild(plr, "Backpack"), plr.Character }) do
                    if container then
                        for _, t in ipairs(container:GetChildren()) do
                            if t:IsA("Tool") and not seen[t.Name] then
                                seen[t.Name] = true
                                names[#names + 1] = t.Name
                            end
                        end
                    end
                end
                return names
            end

            -- Make sure a weapon is held before swinging (RL M1 needs one).
            -- Auto by default: keep whatever's already equipped, otherwise pull
            -- the first real weapon from the bag (skips potions/silver/spells/
            -- skills). If a weapon is picked in the dropdown, that one is forced.
            local function ensure_weapon()
                local char = plr.Character
                if not char then return end
                local hum = FindFirstChildOfClass(char, "Humanoid")
                if not hum then return end
                local held = FindFirstChildOfClass(char, "Tool")

                if selected_weapon ~= "" then
                    if held and held.Name == selected_weapon then return end
                    local bp = FindFirstChild(plr, "Backpack")
                    local tool = bp and FindFirstChild(bp, selected_weapon)
                    if tool then pcall(function() hum:EquipTool(tool) end) end
                    return
                end

                -- auto-detect: already holding a tool? use it. else equip a weapon.
                if held then return end
                local bp = FindFirstChild(plr, "Backpack")
                if not bp then return end
                for _, t in ipairs(bp:GetChildren()) do
                    if t:IsA("Tool")
                        and not FindFirstChild(t, "Quantity")
                        and not FindFirstChild(t, "SilverValue")
                        and not FindFirstChild(t, "Spell")
                        and not FindFirstChild(t, "Skill")
                        and not FindFirstChild(t, "SkillSpell")
                    then
                        pcall(function() hum:EquipTool(t) end)
                        return
                    end
                end
            end

            -- equip an actual sword/melee weapon (preferred over ensure_weapon when knocking
            -- down Evil Eyes and shriekers - they need the blade out, not a skill/consumable)
            local function equip_sword()
                local char = plr.Character
                local hum = char and FindFirstChildOfClass(char, "Humanoid")
                if not hum then return end
                local held = FindFirstChildOfClass(char, "Tool")
                if held and (held.Name == selected_weapon or held.Name:lower():find("sword")) then return end
                local bp = FindFirstChild(plr, "Backpack")
                local want
                if bp and selected_weapon ~= "" then want = FindFirstChild(bp, selected_weapon) end
                if not want and bp then
                    for _, t in ipairs(bp:GetChildren()) do
                        if t:IsA("Tool") and t.Name:lower():find("sword") then want = t; break end
                    end
                end
                if want then pcall(function() hum:EquipTool(want) end) else ensure_weapon() end
            end

            local hold_cf = nil    -- saved "hold spot" position for ledge farming
            local resting = false  -- pauses attacks while recovering HP
            local set_full_farm    -- master on/off switch, defined after the UI below

            -- custom path: { {kind="point", cf=CFrame}, {kind="inn", inn=name}, ... }
            local xp_path = {}
            local path_idx = 0
            local shrieker_done = 0   -- shriekers grabbed this run (for the pickup notify)
            local shrk_countable = false   -- the carried shrieker is a fresh grab (counts as a turn-in)
            local test_once = false   -- "Test Run Once": one pass with repeats skipped, then stop
            local path_resume_from = nil   -- set by the resume task to start a pass mid-path after a serverhop.
                                            -- NEGATIVE means a manual "Run Path From #" test start (sign bit
                                            -- doubles as the manual-start flag so it doesn't cost its own
                                            -- register - stay under the 200-local cap)
            local classbot_catchup_to = nil  -- after a hop: fast-walk the route to this EXACT step (the spot we hopped at), skipping actions, then resume normally

            -- add a waypoint: insert at the "Insert At #" index if set, else append.
            local function add_step(step)
                local at = tonumber(Options.xpfarm_insert_idx and Options.xpfarm_insert_idx.Value)
                if at then
                    at = math.clamp(math.floor(at), 1, #xp_path + 1)
                    table.insert(xp_path, at, step)
                    return at
                end
                table.insert(xp_path, step)
                return #xp_path
            end

            local function cf_to_string(cf)
                local p, l = cf.Position, cf.LookVector
                return string.format("%.2f,%.2f,%.2f,%.4f,%.4f,%.4f", p.X, p.Y, p.Z, l.X, l.Y, l.Z)
            end

            local function cf_from_string(s)
                local n = {}
                for num in string.gmatch(s or "", "[^,]+") do n[#n + 1] = tonumber(num) end
                if #n < 6 then return nil end
                local pos = Vector3.new(n[1], n[2], n[3])
                local ok, cf = pcall(function() return CFrame.lookAt(pos, pos + Vector3.new(n[4], n[5], n[6])) end)
                return ok and cf or CFrame.new(pos)
            end

            -- Everything Full Auto needs to survive a serverhop lives in mem,
            -- mirroring how the Trinket Bot persists itself via "botstarted".
            local function save_farm_state()
                pcall(function()
                    mem:SetItem("xpfarm_state", Services.HttpService:JSONEncode({
                        hold = hold_cf and cf_to_string(hold_cf) or nil,
                        inn = selected_inn,
                        cps = Options.xpfarm_cps and Options.xpfarm_cps.Value or nil,
                        speed = Options.xpfarm_speed and Options.xpfarm_speed.Value or nil,
                        range = Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value or nil,
                        silver_range = Options.xpfarm_silver_range and Options.xpfarm_silver_range.Value or nil,
                        inn_hp = Options.xpfarm_inn_hp and Options.xpfarm_inn_hp.Value or nil,
                        hop_after = Options.xpfarm_hop_after and Options.xpfarm_hop_after.Value or nil,
                        per_class = Options.xpfarm_per_class and Options.xpfarm_per_class.Value or nil,
                        class = Options.xpfarm_target_class and Options.xpfarm_target_class.Value or nil,
                        weapon = selected_weapon,
                        path = (function()
                            local parts = {}
                            for _, step in ipairs(xp_path) do
                                if step.kind == "inn" then
                                    parts[#parts + 1] = "i:" .. tostring(step.inn)
                                elseif step.cf then
                                    local p = step.cf.Position
                                    parts[#parts + 1] = string.format("p:%.1f,%.1f,%.1f", p.X, p.Y, p.Z)
                                end
                            end
                            return table.concat(parts, "|")
                        end)(),
                        stop_done = (Toggles.xpfarm_stop_done and Toggles.xpfarm_stop_done.Value) and true or false,
                    }))
                    mem:SetItem("xpfarm_running", "true")
                end)
            end

            -- Move exactly like the Trinket Bot does (its SmoothTeleport):
            -- tween the HumanoidRootPart at a fixed studs/sec speed, zeroing
            -- velocity and disabling collision during the move, with the same
            -- 1500-stud sanity cap. Self-contained copy - the Trinket Bot's own
            -- function is untouched.
            local move_active = false
            local function bot_move_to(target_pos)
                if move_active then return false end
                local root = local_hrp()
                if not root then return false end

                local distance = (target_pos - root.Position).Magnitude
                if distance <= 3 then return true end
                if distance > 1500 then
                    library:Notify(string.format("!! Attempted move of %.0f studs - refusing", distance))
                    return false
                end

                move_active = true

                local vel_connection
                local ok, err = pcall(function()
                    local character = plr.Character
                    local humanoid = character and FindFirstChildOfClass(character, "Humanoid")
                    if humanoid then
                        humanoid:SetStateEnabled(5, false)
                        humanoid:ChangeState(3)
                    end

                    vel_connection = utility:Connection(rs.RenderStepped, function()
                        if shared and shared.is_unloading then
                            if vel_connection then vel_connection:Disconnect(); vel_connection = nil end
                            return
                        end
                        if plr.Character then
                            for _, v in pairs(plr.Character:GetDescendants()) do
                                if v:IsA("BasePart") then
                                    v.Velocity = Vector3.new()
                                    v.CanCollide = false
                                end
                            end
                        end
                    end)

                    local speed = (Options.xpfarm_speed and Options.xpfarm_speed.Value) or 100
                    local move_time = distance / speed
                    local tween = ts:Create(root, TweenInfo.new(move_time, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut), { CFrame = CFrame.new(target_pos) })

                    local completed = false
                    local done_connection
                    done_connection = utility:Connection(tween.Completed, function()
                        completed = true
                        if done_connection then done_connection:Disconnect() end
                    end)

                    tween:Play()

                    local t0 = os.clock()
                    while not completed and not (shared and shared.is_unloading) and os.clock() - t0 < move_time + 10 do
                        task.wait()
                    end
                    if not completed then pcall(function() tween:Cancel() end) end
                end)

                if vel_connection then pcall(function() vel_connection:Disconnect() end) end

                pcall(function()
                    local humanoid = plr.Character and FindFirstChildOfClass(plr.Character, "Humanoid")
                    if humanoid then
                        humanoid:SetStateEnabled(5, true)
                        humanoid:ChangeState(5)
                    end
                end)

                move_active = false

                if not ok then
                    library:Notify("Move error: " .. tostring(err), 6)
                    return false
                end

                local hrp_after = local_hrp()
                return hrp_after ~= nil and (hrp_after.Position - target_pos).Magnitude <= 10
            end

            -- Hard stop: death or an unrecoverable position. We never teleport
            -- to recover - we kick out of the game instead (same flow as the
            -- Trinket Bot: webhook, ReturnToMenu, Kick) and disarm the farm so
            -- it can't death-loop a permadeath character.
            local farm_kicking = false
            local function farm_kick(reason)
                if farm_kicking then return end
                farm_kicking = true
                reason = tostring(reason or "XP Farm stopped")
                pcall(function() mem:SetItem("xpfarm_running", "false") end)
                pcall(function() utility:plain_webhook("XP Farm: " .. reason .. " - kicking out of the game") end)
                pcall(function() library:Notify("XP Farm: " .. reason .. " - kicking", 8) end)
                task.wait(0.5)
                pcall(function()
                    -- never kick while in Danger (combat-log = lost life): wait until it fully clears
                    while plr.Character and cs:HasTag(plr.Character, "Danger") and shared and not shared.is_unloading do
                        task.wait(0.2)
                    end
                end)
                pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)
                pcall(function() plr:Kick(reason) end)
            end

            local function monster_root(m)
                if not m then return nil end
                local ok, pp = pcall(function() return m.PrimaryPart end)
                if ok and pp then return pp end
                return FindFirstChild(m, "HumanoidRootPart")
                    or FindFirstChild(m, "Torso")
                    or FindFirstChild(m, "UpperTorso")
                    or FindFirstChildWhichIsA(m, "BasePart")
            end

            -- Monsters live in workspace.Live. Most carry a "MonsterInfo" child,
            -- but some (e.g. Evil Eyes) may not, so we also accept any non-player
            -- model in Live that has a Humanoid as a monster.
            local function is_monster(m)
                if m == plr.Character then return false end
                if plrs:GetPlayerFromCharacter(m) then return false end
                return FindFirstChild(m, "MonsterInfo") ~= nil
                    or FindFirstChildOfClass(m, "Humanoid") ~= nil
            end

            local function scan_monsters(range)
                local hrp = local_hrp()
                local live = FindFirstChild(ws, "Live")
                if not hrp or not live then return 0, nil, math.huge end

                local count, nearest, ndist = 0, nil, math.huge
                local origin = hrp.Position
                for _, m in ipairs(live:GetChildren()) do
                    if is_monster(m) then
                        local hum = FindFirstChildOfClass(m, "Humanoid")
                        if (not hum) or hum.Health > 0 then
                            local root = monster_root(m)
                            if root then
                                local d = (root.Position - origin).Magnitude
                                if d <= range then
                                    count = count + 1
                                    if d < ndist then ndist = d; nearest = m end
                                end
                            end
                        end
                    end
                end
                return count, nearest, ndist
            end

            -- Shriekers (necromancer summons, Orderly turn-ins): Models in
            -- workspace.Live named *Shrieker* with a MonsterInfo.
            local function is_shrieker(m)
                return m:IsA("Model")
                    and FindFirstChild(m, "MonsterInfo") ~= nil
                    and string.find(m.Name, "Shrieker", 1, true) ~= nil
                    and string.find(m.Name, "Sealed", 1, true) == nil   -- NOT a Sealed Shrieker (its own waypoint)
            end
            -- Sealed Shrieker = a shrieker subtype you GRIP (B) instead of carry (V).
            local function is_sealed_shrieker(m)
                return m:IsA("Model")
                    and FindFirstChild(m, "MonsterInfo") ~= nil
                    and string.find(m.Name, "Sealed Shrieker", 1, true) ~= nil
            end

            -- true if another player in this server is an Illusionist (holds Observe)
            local function server_has_illusionist()
                for _, p in ipairs(plrs:GetPlayers()) do
                    if p ~= plr then
                        local bp = p:FindFirstChildOfClass("Backpack")
                        if (bp and FindFirstChild(bp, "Observe")) or (p.Character and FindFirstChild(p.Character, "Observe")) then
                            return p
                        end
                    end
                end
                return nil
            end

            -- a Rogue Lineage moderator in the server (cheat mod list or staff group)
            local function server_has_moderator()
                for _, p in ipairs(plrs:GetPlayers()) do
                    if p ~= plr then
                        if cheat_client and cheat_client.mod_list and table.find(cheat_client.mod_list, p.UserId) then
                            return p
                        end
                        local ok, in_group = pcall(function() return p:IsInGroup(4556484) end)
                        if ok and in_group then
                            local ok2, role = pcall(function() return p:GetRoleInGroup(4556484) end)
                            if ok2 and role and role ~= "Guest" then return p end
                        end
                    end
                end
                return nil
            end

            -- Ores: workspace.Ores children are BaseParts whose Name is the ore type
            -- (Tin/Copper/Iron/Mythril/...). Tin is ignored everywhere per request.
            local function ore_pos(ore)
                if ore:IsA("BasePart") then return ore.Position end
                local ok, p = pcall(function() return ore:GetPivot().Position end)
                return ok and p or nil
            end
            local function ores_exist()
                local folder = FindFirstChild(ws, "Ores")
                if not folder then return false end
                for _, ore in ipairs(folder:GetChildren()) do
                    if ore.Name ~= "Tin" then return true end
                end
                return false
            end
            local function nearest_ore(range)
                local hrp = local_hrp()
                local folder = FindFirstChild(ws, "Ores")
                if not hrp or not folder then return nil, nil end
                local best, bestpos, bestd
                for _, ore in ipairs(folder:GetChildren()) do
                    if ore.Name ~= "Tin" then
                        local p = ore_pos(ore)
                        if p then
                            local d = (p - hrp.Position).Magnitude
                            if d <= (range or 120) and (not bestd or d < bestd) then bestd = d; best = ore; bestpos = p end
                        end
                    end
                end
                return best, bestpos
            end
            -- equip the Pickaxe and swing it (same as the instant-mine pattern)
            local function mine_swing()
                local char = plr.Character
                local hum = char and FindFirstChildOfClass(char, "Humanoid")
                if not hum then return false end
                local pick = FindFirstChild(char, "Pickaxe")
                if not pick then
                    local bp = FindFirstChild(plr, "Backpack")
                    pick = bp and FindFirstChild(bp, "Pickaxe")
                end
                if not pick then return false end
                pcall(function()
                    hum:UnequipTools()
                    hum:EquipTool(pick)
                    task.wait(0.05)
                    -- fire REAL simulated mouse clicks (not pick:Activate()) so this
                    -- swing goes through the exact same path a genuine player click
                    -- does - which is what the Instant Mine hook listens for
                    -- (uis.InputBegan MouseButton1). Activate() alone never triggered
                    -- that hook, so Instant Mine silently did nothing during Mine Here.
                    local x, y = mouse and mouse.X or 0, mouse and mouse.Y or 0
                    for _ = 1, 8 do
                        if vim then
                            vim:SendMouseButtonEvent(x, y, 0, true, game, 1)
                            task.wait(0.03)
                            vim:SendMouseButtonEvent(x, y, 0, false, game, 1)
                        else
                            pick:Activate()
                        end
                        task.wait(0.05)
                    end
                    hum:EquipTool(pick)
                end)
                return true
            end

            -- returns: nearest ALIVE shrieker, nearest DOWNED (<=0 HP) shrieker, downed distance
            local function scan_shriekers(range)
                local hrp = local_hrp()
                local live = FindFirstChild(ws, "Live")
                if not hrp or not live then return nil, nil, math.huge end
                local origin = hrp.Position
                local alive, alive_d, downed, downed_d
                for _, m in ipairs(live:GetChildren()) do
                    if m ~= plr.Character and is_shrieker(m) then
                        local root = monster_root(m)
                        if root then
                            local d = (root.Position - origin).Magnitude
                            if d <= range then
                                local hum = FindFirstChildOfClass(m, "Humanoid")
                                if hum and hum.Health <= 0 then
                                    if not downed_d or d < downed_d then downed_d = d; downed = m end
                                else
                                    if not alive_d or d < alive_d then alive_d = d; alive = m end
                                end
                            end
                        end
                    end
                end
                return alive, downed, downed_d or math.huge
            end

            local function scan_sealed(range)
                local hrp = local_hrp()
                local live = FindFirstChild(ws, "Live")
                if not hrp or not live then return nil, nil end
                local origin = hrp.Position
                local alive, alive_d, downed, downed_d
                for _, m in ipairs(live:GetChildren()) do
                    if m ~= plr.Character and is_sealed_shrieker(m) then
                        local root = monster_root(m)
                        if root then
                            local d = (root.Position - origin).Magnitude
                            if d <= range then
                                local hum = FindFirstChildOfClass(m, "Humanoid")
                                if hum and hum.Health <= 0 then
                                    if not downed_d or d < downed_d then downed_d = d; downed = m end
                                else
                                    if not alive_d or d < alive_d then alive_d = d; alive = m end
                                end
                            end
                        end
                    end
                end
                return alive, downed
            end

            local function find_inn_keeper(inn)
                local npcs = FindFirstChild(ws, "NPCs")
                if not npcs then return nil end
                if inn == "Flowerlight Town" then return FindFirstChild(npcs, "Ria") end
                if inn == "Scroomville" then return FindFirstChild(npcs, "Fungkeeper") end
                local want = (tostring(inn):gsub("^%s*(.-)%s*$", "%1")):lower()
                for _, npc in ipairs(npcs:GetChildren()) do
                    if npc.Name:gsub("%s", ""):lower() == "innkeeper" and FindFirstChild(npc, "Location")
                    and (npc.Location.Value:gsub("^%s*(.-)%s*$", "%1")):lower() == want then
                        return npc
                    end
                end
                return nil
            end

            -- region-1 inns + any inn keepers in the current world (so Khei etc. show up)
            local function scan_inns()
                local found, seen = {}, {}
                for _, n in ipairs(INN_LIST) do if not seen[n] then seen[n] = true; found[#found + 1] = n end end
                local npcs = FindFirstChild(ws, "NPCs")
                if npcs then
                    for _, npc in ipairs(npcs:GetChildren()) do
                        if npc.Name:gsub("%s", ""):lower() == "innkeeper" and FindFirstChild(npc, "Location") then
                            local loc = (npc.Location.Value:gsub("^%s*(.-)%s*$", "%1"))
                            if loc and loc ~= "" and not seen[loc] then seen[loc] = true; found[#found + 1] = loc end
                        end
                    end
                    if FindFirstChild(npcs, "Ria") and not seen["Flowerlight Town"] then seen["Flowerlight Town"] = true; found[#found + 1] = "Flowerlight Town" end
                    if FindFirstChild(npcs, "Fungkeeper") and not seen["Scroomville"] then seen["Scroomville"] = true; found[#found + 1] = "Scroomville" end
                end
                return found
            end

            -- Inn teleport, identical to the Exploits-tab "Teleport to Inn"
            -- button: PivotTo the keeper, fire its ClickDetector when within
            -- range and answer the dialogue to rent (sets respawn), then drop.
            local function rent_at_inn_nearby(inn)
                if not inn then return false end
                if not local_hrp() then library:Notify("Character not found"); return false end

                local keeper = find_inn_keeper(inn)
                if not keeper or not FindFirstChild(keeper, "HumanoidRootPart") then
                    library:Notify("Inn keeper not found at " .. tostring(inn))
                    return false
                end

                local response = (inn == "Flowerlight Town") and "A room, please." or "Sure."
                local elapsed = 0
                while elapsed < 1 and not (shared and shared.is_unloading) do
                    if plr.Character then
                        plr.Character:PivotTo(keeper:GetPivot())
                        local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                        if hrp then
                            hrp.Velocity = Vector3.zero
                            if (hrp.Position - keeper.HumanoidRootPart.Position).Magnitude <= 10 then
                                local cd = FindFirstChildWhichIsA(keeper, "ClickDetector", true)
                                if cd then pcall(function() fireclickdetector(cd) end) end
                            end
                        end
                        if dialogue_remote then
                            pcall(function() dialogue_remote:FireServer({ choice = response }) end)
                        end
                    end
                    elapsed = elapsed + task.wait()
                end

                if plr.Character then pcall(function() plr.Character:BreakJoints() end) end
                library:Notify("Teleported to " .. tostring(inn))
                return true
            end

            -- Did we actually END UP at the inn? Renting respawns you at the inn bed,
            -- right by the keeper - so being within a radius of the keeper means the
            -- teleport really landed. Returns true/false, or nil if it can't be checked
            -- (keeper not found in this world), so callers can fall back gracefully.
            local function at_inn(inn, radius)
                radius = radius or 80
                local hrp = local_hrp()
                local keeper = find_inn_keeper(inn)
                if not (hrp and keeper) then return nil end
                local khrp = FindFirstChild(keeper, "HumanoidRootPart")
                if not khrp then return nil end
                return (hrp.Position - khrp.Position).Magnitude <= radius
            end

            -- Talk to the nearest NPC. Moves into ClickDetector range (the inn
            -- works because it gets right next to the keeper), fires the detector
            -- until the character actually enters dialogue (InDialogue tag), then
            -- auto-answers the first choice until the conversation ends.
            local function in_dialogue()
                return plr.Character and FindFirstChild(plr.Character, "InDialogue") ~= nil
            end

            -- Bulk-sell to a merchant: "Can I sell in bulk?" -> category -> "It's a
            -- deal." repeatedly -> "Bye." Same GUI-driven pattern already proven for
            -- Alt Support's trinket/antiquarian selling, duplicated here (not bridged)
            -- since this closure and Alt Support's are separate scopes. Kept as ONE
            -- outer-scope local (with the click/open helpers nested inside it) instead
            -- of three, since every extra top-level local here eats into this
            -- function's 200-register cap.
            local function xpfarm_sell_categories(npc_name, categories)
                local function click(text_substr)
                    local gui = FindFirstChild(plr, "PlayerGui")
                    local dgui = gui and FindFirstChild(gui, "DialogueGui")
                    local frame = dgui and FindFirstChild(dgui, "DialogueFrame")
                    local choices = frame and FindFirstChild(frame, "Choices")
                    if not choices then return false end
                    local want = text_substr:lower()
                    for _, opt in ipairs(choices:GetChildren()) do
                        if opt.Name:lower():find(want, 1, true) then
                            local btn = FindFirstChildOfClass(opt, "TextButton") or FindFirstChild(opt, "TextButton")
                            if btn then
                                pcall(function() firesignal(btn.MouseButton1Click) end)
                                return true
                            end
                        end
                    end
                    return false
                end
                local function open_dlg(name, timeout)
                    local hrp = local_hrp()
                    local npcs_folder = FindFirstChild(ws, "NPCs")
                    if not hrp or not npcs_folder then return false end
                    local want = name and name ~= "" and name:lower() or nil
                    local nearest, nearest_pos, ndist
                    for _, npc in ipairs(npcs_folder:GetChildren()) do
                        local nhrp = FindFirstChild(npc, "HumanoidRootPart")
                        if nhrp and FindFirstChildWhichIsA(npc, "ClickDetector", true) then
                            if not want or npc.Name:lower():find(want, 1, true) then
                                local d = (nhrp.Position - hrp.Position).Magnitude
                                if not ndist or d < ndist then ndist = d; nearest = npc; nearest_pos = nhrp.Position end
                            end
                        end
                    end
                    if not nearest then library:Notify("Path: no matching merchant NPC nearby", 5); return false end
                    if ndist and ndist > 12 then bot_move_to(nearest_pos) end
                    local cd = FindFirstChildWhichIsA(nearest, "ClickDetector", true)
                    local t0 = os.clock()
                    while os.clock() - t0 < (timeout or 5) do
                        if cd then pcall(function() fireclickdetector(cd) end) end
                        if in_dialogue() then return true end
                        task.wait(0.3)
                    end
                    library:Notify("Path: couldn't open dialogue with " .. nearest.Name, 5)
                    return false
                end

                local sold_any = false
                for _, cat in ipairs(categories) do
                    if not open_dlg(npc_name, 6) then break end
                    task.wait(0.5)
                    click("bulk")
                    for _ = 1, 40 do   -- safety cap on rounds, not item count
                        task.wait(0.6)
                        if not click(cat) then break end
                        task.wait(0.6)
                        if not click("deal") then break end
                        sold_any = true
                        task.wait(0.6)
                    end
                    task.wait(0.3)
                    click("Bye")
                    task.wait(0.5)
                end
                return sold_any
            end

            local function talk_to_nearest_npc(duration, target_name, choice_sequence)
                duration = duration or 8
                -- optional: force specific choices in order (e.g. {"may i pick up a
                -- book", "language"}) for NPCs with a menu that isn't just "pick
                -- the first option" - matches each choice's text against the next
                -- keyword in the sequence (case-insensitive substring), then falls
                -- back to auto-picking the first choice once the sequence runs out.
                local seqIdx = 1
                local function pickChoice(choices)
                    -- "@equip:Item Name" entries aren't a dialogue choice to match - they're
                    -- an instruction to equip that item right now, mid-conversation (e.g. an
                    -- NPC hands you an item on one line, then expects it equipped before the
                    -- next line goes through). Run any of these queued up next, in order,
                    -- before falling through to matching a real choice.
                    while choice_sequence and choice_sequence[seqIdx] and choice_sequence[seqIdx]:sub(1, 7) == "@equip:" do
                        local item_name = choice_sequence[seqIdx]:sub(8)
                        local char = plr.Character
                        local tool = (char and FindFirstChild(char, item_name))
                            or (plr.Backpack and FindFirstChild(plr.Backpack, item_name))
                        local hum = char and FindFirstChildOfClass(char, "Humanoid")
                        if hum and tool then
                            pcall(function() hum:EquipTool(tool) end)
                            library:Notify("Path: equipped '" .. item_name .. "' mid-dialogue", 3)
                        else
                            library:Notify("Path: '" .. item_name .. "' not found to equip mid-dialogue", 5)
                        end
                        seqIdx = seqIdx + 1
                    end
                    if choice_sequence and choice_sequence[seqIdx] then
                        local want = choice_sequence[seqIdx]:lower()
                        for _, choice in ipairs(choices) do
                            local text = (type(choice) == "table" and (choice.Text or choice.text)) or choice
                            if type(text) == "string" and text:lower():find(want, 1, true) then
                                seqIdx = seqIdx + 1
                                return choice
                            end
                        end
                    end
                    return choices[1]
                end
                local hrp = local_hrp()
                local npcs_folder = FindFirstChild(ws, "NPCs")
                if not hrp or not npcs_folder then return false end

                -- if a target name was given, only consider NPCs matching it (so a turn-in
                -- can't accidentally talk to whatever else is nearest) - not just the
                -- physically nearest one. Also cap the search range - without this, if
                -- nothing matching was actually nearby it would happily lock onto the
                -- nearest match ANYWHERE on the map and walk cross-map to it.
                local want = target_name and target_name ~= "" and target_name:gsub("^%s*(.-)%s*$", "%1"):lower() or nil
                local search_range = 150
                local nearest, nearest_pos, ndist
                for _, npc in ipairs(npcs_folder:GetChildren()) do
                    local nhrp = FindFirstChild(npc, "HumanoidRootPart")
                    if nhrp and FindFirstChildWhichIsA(npc, "ClickDetector", true) then
                        if not want or npc.Name:lower():find(want, 1, true) then
                            local d = (nhrp.Position - hrp.Position).Magnitude
                            if d <= search_range and (not ndist or d < ndist) then ndist = d; nearest = npc; nearest_pos = nhrp.Position end
                        end
                    end
                end
                if not nearest then
                    library:Notify(want and ("No NPC named '" .. target_name .. "' found within " .. search_range .. " studs") or "No NPC nearby to talk to")
                    return false
                end

                -- get into click range (the recorded spot may be a bit short) - stay tight
                -- (6 studs) since a ClickDetector's real activation range can be smaller than
                -- 12, and this runs fresh on every retry so it re-approaches each time too.
                if not ndist or ndist > 6 then bot_move_to(nearest_pos) end

                -- auto-answer the first choice while we're in dialogue; track the last
                -- time a NEW line came in so we can tell "still actively talking" apart
                -- from "genuinely stuck", and remember the last choice sent so we can
                -- forcefully re-send it if the conversation stalls (some NPCs - the
                -- Alchemist Trainer in particular - can go quiet for a few seconds after
                -- a long crafting session without the client ever getting a new line).
                local conn
                local last_event = os.clock()
                local last_choice = nil
                if dialogue_remote then
                    conn = utility:Connection(dialogue_remote.OnClientEvent, function(data)
                        last_event = os.clock()
                        if type(data) ~= "table" then return end
                        task.wait(0.1)
                        if data.choices and data.choices[1] then
                            local pick = pickChoice(data.choices)
                            last_choice = pick
                            pcall(function() dialogue_remote:FireServer({ choice = pick }) end)
                        else
                            last_choice = nil
                            pcall(function() dialogue_remote:FireServer({ exit = true }) end)
                        end
                    end)
                end

                -- open the dialogue: fire the detector until InDialogue appears
                local cd = FindFirstChildWhichIsA(nearest, "ClickDetector", true)
                local started, t0 = false, os.clock()
                while os.clock() - t0 < 5 and not (shared and shared.is_unloading) do
                    if cd then pcall(function() fireclickdetector(cd) end) end
                    if in_dialogue() then started = true; break end
                    task.wait(0.3)
                end

                if not started then
                    if conn then pcall(function() conn:Disconnect() end) end
                    library:Notify("Couldn't open dialogue with " .. nearest.Name)
                    return false
                end

                -- let it run (the hook answers) until dialogue ends NATURALLY. A multi-step
                -- conversation (e.g. the one that sends the boat to Khei) can take a while,
                -- and cutting it off mid-way with a forced {exit=true} was skipping its LAST
                -- line - which is what actually triggers the stage transition. So: don't
                -- force-exit on a short timer while it's still actively talking. If it goes
                -- quiet, don't just give up either - forcefully re-send the last choice (or
                -- re-click the NPC) a few times to push it through before finally bailing,
                -- with a generous absolute cap as the last-resort safety net.
                last_event = os.clock()
                local t1 = os.clock()
                local hard_cap = math.max(duration, 45)
                local last_poke = os.clock()
                local pokes = 0
                while in_dialogue() and not (shared and shared.is_unloading) do
                    if (os.clock() - t1) > hard_cap then break end
                    if (os.clock() - last_event) > 20 and pokes >= 6 then break end   -- truly stuck
                    if (os.clock() - last_event) > 2 and (os.clock() - last_poke) > 2 then
                        last_poke = os.clock()
                        pokes = pokes + 1
                        if last_choice then
                            pcall(function() dialogue_remote:FireServer({ choice = last_choice }) end)
                        else
                            pcall(function() dialogue_remote:FireServer({ exit = true }) end)
                        end
                        if cd then pcall(function() fireclickdetector(cd) end) end
                    end
                    task.wait(0.2)
                end

                if conn then pcall(function() conn:Disconnect() end) end
                if dialogue_remote and in_dialogue() then
                    pcall(function() dialogue_remote:FireServer({ exit = true }) end)
                end
                library:Notify("Talked to " .. nearest.Name)
                return true
            end

            local function read_stat(value)
                local ok, res = pcall(function()
                    return rps.Requests.Get:InvokeServer(utf8.char(65532) .. "\240\159\152\131", value)[value]
                end)
                return ok and res or nil
            end

            -- Best-effort weapon XP read: the held weapon's numeric children
            -- first, then a few stat-remote keys. Returns weaponName, xp|nil.
            local function read_weapon_xp()
                local char = plr.Character
                if not char then return "None", nil end
                local tool = FindFirstChildOfClass(char, "Tool")
                local wname = tool and tool.Name or "None"
                local xp

                if tool then
                    for _, nm in ipairs(XP_CHILD_NAMES) do
                        local v = FindFirstChild(tool, nm)
                        if v and (v:IsA("IntValue") or v:IsA("NumberValue")) then xp = v.Value; break end
                    end
                end
                if not xp then
                    for _, key in ipairs({ "WeaponXP", "WeaponExp", "WeaponExperience", "Mastery" }) do
                        local v = read_stat(key)
                        if type(v) == "number" then xp = v; break end
                    end
                end
                if not xp and tool then
                    local v = read_stat(wname .. "XP") or read_stat(wname .. "Exp")
                    if type(v) == "number" then xp = v end
                end
                return wname, xp
            end

            local function looks_like_silver(obj)
                if FindFirstChild(obj, "SilverValue") then return true end
                local n = string.lower(obj.Name)
                for _, w in ipairs(SILVER_WORDS) do
                    if string.find(n, w, 1, true) then return true end
                end
                return false
            end

            -- Kill tracking: a more reliable progress gauge than raw weapon XP
            -- (which RL doesn't expose). Count monsters we actually engage and
            -- kill (~12 per super class by default). Persisted in mem so the
            -- total carries across serverhops.
            local kills = 0
            if mem:HasItem("xpfarm_kills") then kills = tonumber(mem:GetItem("xpfarm_kills")) or 0 end
            local kill_counted = setmetatable({}, { __mode = "k" })   -- monster -> already counted
            local engaged = {}            -- monster -> os.clock() we last attacked it
            local KILL_GRACE = 10         -- count a death/removal as ours within this many seconds
            local classbot_kill_phase = nil  -- "evil" while the Blademaster bot is in the Evil-Eye goal loop

            local function register_kill(m)
                if not m or kill_counted[m] then return end
                kill_counted[m] = true
                kills = kills + 1
                pcall(function() mem:SetItem("xpfarm_kills", tostring(kills)) end)
                -- Blademaster bot: also tally Evil-Eye kills while in the kill phase, so the goal
                -- loop runs until 20 ACTUAL kills (not a fixed round count). Generation-keyed so it
                -- resets each Run and survives serverhops.
                if classbot_kill_phase == "evil" then
                    pcall(function()
                        if mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true" then
                            local gk = "classbot_evil_" .. ((mem:HasItem("classbot_gen") and mem:GetItem("classbot_gen")) or "0")
                            mem:SetItem(gk, tostring((tonumber(mem:GetItem(gk)) or 0) + 1))
                        end
                    end)
                end
            end

            -- Mark a monster as "mine" while we're attacking it (refreshed each
            -- frame). No Humanoid required, so it works for Evil Eyes etc.
            local function engage_monster(m)
                if not m or kill_counted[m] then return end
                engaged[m] = os.clock()
            end

            -- An engaged monster counts as a kill when it dies (Humanoid health
            -- hits 0) or leaves the world shortly after we last hit it. This
            -- catches monsters that don't fire a normal Humanoid.Died event.
            local function check_engaged_kills()
                local now = os.clock()
                for m, t in pairs(engaged) do
                    if kill_counted[m] then
                        engaged[m] = nil
                    else
                        local ok, in_world = pcall(function() return m:IsDescendantOf(ws) end)
                        local removed = not (ok and in_world)
                        local hum = (not removed) and FindFirstChildOfClass(m, "Humanoid") or nil
                        local health_dead = (hum ~= nil) and hum.Health <= 0
                        if removed or health_dead then
                            if (now - t) <= KILL_GRACE then register_kill(m) end
                            engaged[m] = nil
                        elseif (now - t) > KILL_GRACE then
                            engaged[m] = nil   -- abandoned: no longer attacking it
                        end
                    end
                end
            end

            local path_label, weapon_label, combat_label

            local function update_path_label()
                if path_label then
                    path_label:SetText(string.format("Waypoints: %d   |   At: %d", #xp_path, path_idx))
                end
            end

            -- In-world waypoint markers: neon orbs + numbered billboards + beams,
            -- same technique the Trinket Bot uses for its path.
            local viz_parts = {}
            local viz_folder

            local function clear_viz()
                for _, p in ipairs(viz_parts) do
                    if p then pcall(function() p:Destroy() end) end
                end
                viz_parts = {}
            end

            local function viz_orb(pos, text, color)
                local sphere = Instance.new("Part")
                sphere.Shape = Enum.PartType.Ball
                sphere.Size = Vector3.new(2, 2, 2)
                sphere.Position = pos
                sphere.Anchored = true
                sphere.CanCollide = false
                sphere.CanQuery = false
                sphere.Material = Enum.Material.Neon
                sphere.Color = color
                sphere.Transparency = 0.3
                sphere.Name = "XPFarmWaypoint"
                sphere.Parent = viz_folder

                local bb = Instance.new("BillboardGui")
                bb.Size = UDim2.new(0, 50, 0, 50)
                bb.AlwaysOnTop = true
                bb.Adornee = sphere
                bb.Parent = sphere

                local label = Instance.new("TextLabel")
                label.Size = UDim2.new(1, 0, 1, 0)
                label.BackgroundTransparency = 1
                label.Text = text
                label.TextColor3 = Color3.new(1, 1, 1)
                label.TextStrokeTransparency = 0.4
                label.TextScaled = true
                label.Font = Enum.Font.SourceSansBold
                label.Parent = bb

                viz_parts[#viz_parts + 1] = sphere
                return sphere
            end

            local function viz_beam(a, b)
                local at0 = Instance.new("Attachment"); at0.Parent = a
                local at1 = Instance.new("Attachment"); at1.Parent = b
                local beam = Instance.new("Beam")
                beam.Attachment0 = at0
                beam.Attachment1 = at1
                beam.FaceCamera = true
                beam.Width0 = 0.3
                beam.Width1 = 0.3
                beam.Color = ColorSequence.new(Color3.fromRGB(0, 200, 255))
                beam.Transparency = NumberSequence.new(0.3)
                beam.Parent = a
                viz_parts[#viz_parts + 1] = beam
            end

            local function update_viz()
                clear_viz()
                if not (Toggles.xpfarm_show_viz and Toggles.xpfarm_show_viz.Value) then return end
                if not viz_folder or not viz_folder.Parent then
                    viz_folder = Instance.new("Folder")
                    viz_folder.Name = "XPFarmViz"
                    viz_folder.Parent = ws
                end

                local prev, prev_ret
                for i, step in ipairs(xp_path) do
                    if step.kind == "return" and step.cf then
                        -- Return Points are a SEPARATE return route (green), only walked on
                        -- loop-back; keep them off the numbered forward chain.
                        local rorb = viz_orb(step.cf.Position, "RTN", Color3.fromRGB(60, 220, 120))
                        if prev_ret then viz_beam(prev_ret, rorb) end
                        prev_ret = rorb
                    elseif step.cf then
                        local color, label
                        if step.kind == "npc" then
                            color = Color3.fromRGB(255, 170, 0); label = string.format("%d NPC", i)
                        elseif step.kind == "npc_captcha" then
                            color = Color3.fromRGB(255, 140, 220); label = string.format("%d CR", i)
                        elseif step.kind == "attack" then
                            color = Color3.fromRGB(255, 80, 80); label = string.format("%d ATK", i)
                        elseif step.kind == "mana_attack" then
                            color = Color3.fromRGB(150, 100, 255); label = string.format("%d MANA-ATK", i)
                        elseif step.kind == "shrieker" then
                            color = Color3.fromRGB(190, 90, 255); label = string.format("%d SHRK", i)
                        elseif step.kind == "sealed" then
                            color = Color3.fromRGB(120, 40, 200); label = string.format("%d SEAL", i)
                        elseif step.kind == "mana" then
                            color = Color3.fromRGB(80, 140, 255); label = string.format("%d MANA (%ds)", i, step.wait_time or 0)
                        else
                            color = Color3.fromRGB(0, 200, 255); label = string.format("%d (%ds)", i, step.wait_time or 0)
                        end
                        local orb = viz_orb(step.cf.Position, label, color)
                        if prev then viz_beam(prev, orb) end
                        prev = orb
                        if (step.kind == "attack" or step.kind == "mana_attack" or step.kind == "shrieker" or step.kind == "sealed") and step.cf2 then
                            local lbl = (step.kind == "attack" or step.kind == "mana_attack") and string.format("%d LURE", i) or string.format("%d TRIG", i)
                            local lure = viz_orb(step.cf2.Position, lbl, Color3.fromRGB(255, 200, 60))
                            viz_beam(orb, lure)
                        end
                    end
                end

                if hold_cf then
                    viz_orb(hold_cf.Position, "HOLD", Color3.fromRGB(60, 255, 120))
                end
            end

            -- remove the orbs when the script unloads
            task.spawn(function()
                while shared and not shared.is_unloading do task.wait(1) end
                pcall(clear_viz)
                if viz_folder then pcall(function() viz_folder:Destroy() end) end
            end)

            -- Saved paths on disk, exactly like the Trinket Bot's path files
            -- (same JSON-in-folder scheme, separate folder so they never mix).
            local XPFARM_PATH_FOLDER = "HYDROXIDE/xpfarm_paths"

            local function get_saved_xpfarm_paths()
                if not listfiles or not isfolder then return {} end
                if not isfolder(XPFARM_PATH_FOLDER) then
                    if makefolder then makefolder(XPFARM_PATH_FOLDER) end
                    return {}
                end
                local names = {}
                for _, file_path in ipairs(listfiles(XPFARM_PATH_FOLDER)) do
                    local name = file_path:match("([^/\\]+)%.json$")
                    if name then table.insert(names, name) end
                end
                return names
            end

            local function save_xpfarm_path(name)
                if not writefile then library:Notify("writefile not supported!"); return false end
                if not isfolder or not isfolder(XPFARM_PATH_FOLDER) then
                    if makefolder then makefolder(XPFARM_PATH_FOLDER) end
                end

                local steps = {}
                for _, step in ipairs(xp_path) do
                    if step.kind == "inn" then
                        table.insert(steps, { kind = "inn", inn = step.inn })
                    elseif step.kind == "offset_on" or step.kind == "offset_off"
                        or step.kind == "autoing_on" or step.kind == "autoing_off"
                        or step.kind == "autobag_on" or step.kind == "autobag_off"
                        or step.kind == "instmine_on" or step.kind == "instmine_off"
                        or step.kind == "skipillus_on" or step.kind == "skipillus_off"
                        or step.kind == "orderly_on" or step.kind == "orderly_off"
                        or step.kind == "equip_pickaxe" or step.kind == "reset_if_safe" then
                        table.insert(steps, { kind = step.kind })
                    elseif step.kind == "repeat_start" then
                        table.insert(steps, { kind = "repeat_start", count = step.count or 1, goal_kind = step.goal_kind, goal = step.goal, ingredient = step.ingredient })
                    elseif step.kind == "repeat_end" then
                        table.insert(steps, { kind = "repeat_end" })
                    elseif step.kind == "end_path" then
                        table.insert(steps, { kind = "end_path" })
                    elseif step.kind == "wait_ores" then
                        table.insert(steps, { kind = "wait_ores" })
                    elseif step.kind == "wait_ingredient" then
                        table.insert(steps, { kind = "wait_ingredient", ingredient = step.ingredient, amount = step.amount })
                    elseif step.kind == "wait_timer" then
                        table.insert(steps, { kind = "wait_timer", minutes = step.minutes })
                    elseif step.kind == "wait_day" then
                        table.insert(steps, { kind = "wait_day", day = step.day })
                    elseif step.kind == "orderly_n" then
                        table.insert(steps, { kind = "orderly_n", count = step.count })
                    elseif step.kind == "equip_item" then
                        table.insert(steps, { kind = "equip_item", item_name = step.item_name })
                    elseif step.kind == "tp_menu" then
                        table.insert(steps, { kind = "tp_menu", x = step.x, y = step.y, z = step.z, label = step.label })
                    elseif step.kind == "skill_gate" then
                        table.insert(steps, { kind = "skill_gate", skill = step.skill, skills = step.skills, redo_from = step.redo_from })
                    elseif step.kind == "smart_skill_skip" then
                        table.insert(steps, { kind = "smart_skill_skip", checks = step.checks, all_done_goto = step.all_done_goto })
                    elseif step.kind == "smart_ingredient_skip" then
                        table.insert(steps, { kind = "smart_ingredient_skip", want_all = step.want_all, target_all = step.target_all, want_any = step.want_any, target_any = step.target_any })
                    elseif step.kind == "return" and not step.cf then
                        table.insert(steps, { kind = "return", serverhop = step.serverhop })
                    elseif step.kind == "serverhop" then
                        table.insert(steps, { kind = "serverhop" })
                    elseif step.cf then
                        local p = step.cf.Position
                        local e = { kind = step.kind or "point", x = p.X, y = p.Y, z = p.Z, wait_time = step.wait_time or 0 }
                        if step.cf2 then local p2 = step.cf2.Position; e.x2, e.y2, e.z2 = p2.X, p2.Y, p2.Z end
                        if step.turnin then e.turnin = true end
                        if step.potion then e.potion = step.potion end
                        if step.weapon then e.weapon = step.weapon end
                        if step.count ~= nil then e.count = step.count end
                        if step.delay ~= nil then e.delay = step.delay end
                        if step.npc_name then e.npc_name = step.npc_name end
                        if step.skip_if_armed then e.skip_if_armed = true end
                        if step.choice_sequence then e.choice_sequence = step.choice_sequence end
                        table.insert(steps, e)
                    end
                end

                local hold
                if hold_cf then
                    local p, l = hold_cf.Position, hold_cf.LookVector
                    hold = { x = p.X, y = p.Y, z = p.Z, lx = l.X, ly = l.Y, lz = l.Z }
                end

                local data = {
                    steps = steps,
                    hold = hold,
                    settings = {
                        speed = Options.xpfarm_speed and Options.xpfarm_speed.Value or 100,
                        dwell = Options.xpfarm_path_wait and Options.xpfarm_path_wait.Value or 4,
                        inn = selected_inn,
                        per_class = Options.xpfarm_per_class and Options.xpfarm_per_class.Value or 12,
                        class = Options.xpfarm_target_class and Options.xpfarm_target_class.Value or nil,
                    }
                }

                local ok, err = pcall(function()
                    writefile(XPFARM_PATH_FOLDER .. "/" .. name .. ".json", Services.HttpService:JSONEncode(data))
                end)
                if not ok then library:Notify("Failed to save path: " .. tostring(err)) end
                return ok
            end

            local function load_xpfarm_path(name)
                if not name or name == "" then return false end
                if not readfile or not isfile then return false end
                local file_path = XPFARM_PATH_FOLDER .. "/" .. name .. ".json"
                if not isfile(file_path) then return false end

                local ok, data = pcall(function()
                    return Services.HttpService:JSONDecode(readfile(file_path))
                end)
                if not ok or type(data) ~= "table" then
                    library:Notify("Failed to load path '" .. tostring(name) .. "'")
                    return false
                end

                xp_path = {}
                for _, step in ipairs(data.steps or {}) do
                    if step.kind == "inn" and step.inn then
                        table.insert(xp_path, { kind = "inn", inn = step.inn })
                    elseif step.kind == "offset_on" or step.kind == "offset_off"
                        or step.kind == "autoing_on" or step.kind == "autoing_off"
                        or step.kind == "autobag_on" or step.kind == "autobag_off"
                        or step.kind == "instmine_on" or step.kind == "instmine_off"
                        or step.kind == "skipillus_on" or step.kind == "skipillus_off"
                        or step.kind == "orderly_on" or step.kind == "orderly_off"
                        or step.kind == "equip_pickaxe" or step.kind == "reset_if_safe" then
                        table.insert(xp_path, { kind = step.kind })
                    elseif step.kind == "repeat_start" then
                        table.insert(xp_path, { kind = "repeat_start", count = step.count or 1, goal_kind = step.goal_kind, goal = step.goal, ingredient = step.ingredient })
                    elseif step.kind == "repeat_end" then
                        table.insert(xp_path, { kind = "repeat_end" })
                    elseif step.kind == "end_path" then
                        table.insert(xp_path, { kind = "end_path" })
                    elseif step.kind == "wait_ores" then
                        table.insert(xp_path, { kind = "wait_ores" })
                    elseif step.kind == "wait_ingredient" then
                        table.insert(xp_path, { kind = "wait_ingredient", ingredient = step.ingredient, amount = step.amount })
                    elseif step.kind == "wait_timer" then
                        table.insert(xp_path, { kind = "wait_timer", minutes = step.minutes })
                    elseif step.kind == "wait_day" then
                        table.insert(xp_path, { kind = "wait_day", day = step.day })
                    elseif step.kind == "orderly_n" then
                        table.insert(xp_path, { kind = "orderly_n", count = step.count })
                    elseif step.kind == "equip_item" then
                        table.insert(xp_path, { kind = "equip_item", item_name = step.item_name })
                    elseif step.kind == "tp_menu" then
                        table.insert(xp_path, { kind = "tp_menu", x = step.x, y = step.y, z = step.z, label = step.label })
                    elseif step.kind == "skill_gate" then
                        table.insert(xp_path, { kind = "skill_gate", skill = step.skill, skills = step.skills, redo_from = step.redo_from })
                    elseif step.kind == "smart_skill_skip" then
                        table.insert(xp_path, { kind = "smart_skill_skip", checks = step.checks, all_done_goto = step.all_done_goto })
                    elseif step.kind == "smart_ingredient_skip" then
                        table.insert(xp_path, { kind = "smart_ingredient_skip", want_all = step.want_all, target_all = step.target_all, want_any = step.want_any, target_any = step.target_any })
                    elseif step.kind == "return" and not step.x then
                        table.insert(xp_path, { kind = "return", serverhop = step.serverhop })
                    elseif step.kind == "serverhop" then
                        table.insert(xp_path, { kind = "serverhop" })
                    elseif step.x then
                        local e = { kind = step.kind or "point", cf = CFrame.new(step.x, step.y, step.z), wait_time = step.wait_time or 0 }
                        if step.x2 then e.cf2 = CFrame.new(step.x2, step.y2, step.z2) end
                        if step.turnin then e.turnin = true end
                        if step.potion then e.potion = step.potion end
                        if step.weapon then e.weapon = step.weapon end
                        if step.count ~= nil then e.count = step.count end
                        if step.delay ~= nil then e.delay = step.delay end
                        if step.npc_name then e.npc_name = step.npc_name end
                        if step.choice_sequence then e.choice_sequence = step.choice_sequence end
                        if step.skip_if_armed then e.skip_if_armed = true end
                        table.insert(xp_path, e)
                    end
                end

                if data.hold and data.hold.x then
                    local pos = Vector3.new(data.hold.x, data.hold.y, data.hold.z)
                    local ok_cf, cf = pcall(function()
                        return CFrame.lookAt(pos, pos + Vector3.new(data.hold.lx or 0, data.hold.ly or 0, data.hold.lz or 1))
                    end)
                    hold_cf = ok_cf and cf or CFrame.new(pos)
                end

                local s = data.settings or {}
                pcall(function()
                    if s.speed and Options.xpfarm_speed then Options.xpfarm_speed:SetValue(s.speed) end
                    if s.dwell and Options.xpfarm_path_wait then Options.xpfarm_path_wait:SetValue(s.dwell) end
                    if s.inn and Options.xpfarm_inn then Options.xpfarm_inn:SetValue(s.inn) end
                    if s.per_class and Options.xpfarm_per_class then Options.xpfarm_per_class:SetValue(s.per_class) end
                    if s.class and Options.xpfarm_target_class then Options.xpfarm_target_class:SetValue(s.class) end
                end)

                path_idx = 0
                update_path_label()
                update_viz()
                return true
            end

