            -- One-shot traversal: start at the nearest waypoint and ride the
            -- path to its end (used by Full Auto startup and the hop resume).
            local function traverse_path_from_nearest()
                if #xp_path == 0 then return end
                local hrp = local_hrp()
                if not hrp then return end

                local best_i, best_d = 1, math.huge
                for i, step in ipairs(xp_path) do
                    if step.cf then
                        local d = (step.cf.Position - hrp.Position).Magnitude
                        if d < best_d then best_d, best_i = d, i end
                    end
                end

                for i = best_i, #xp_path do
                    if shared and shared.is_unloading then return end
                    local step = xp_path[i]
                    path_idx = i
                    update_path_label()
                    if step.cf then
                        bot_move_to(step.cf.Position)
                    end
                end

                path_idx = 0
                update_path_label()
            end

            -- ---- UI -----------------------------------------------------------
            -- Organised into a small "Full Auto" box plus left/right tabboxes
            -- with labelled sub-tabs so it isn't one giant wall of controls.
            -- If creation errors, report it and fall back to stubs.
            local group_master, group_combat, group_target, group_travel, group_path, group_saves, group_class
            local ui_ok, ui_err = pcall(function()
                local win = getgenv().XPFARM_WINDOW
                local tab
                if win and win.AddTab then
                    tab = win:AddTab("XP Farm", "sword")           -- dedicated tab
                elseif library and library.Tabs and library.Tabs.Botting then
                    tab = library.Tabs.Botting                     -- fallback: existing tab
                else
                    error("no window/tab reference reachable")
                end
                group_master = tab:AddLeftGroupbox("Full Auto")
                local left_tb = tab:AddLeftTabbox()
                group_combat = left_tb:AddTab("Attack")
                group_target = left_tb:AddTab("Targeting")
                local right_tb = tab:AddRightTabbox()
                group_travel = right_tb:AddTab("Inn / Safety")
                group_path = right_tb:AddTab("Path")
                group_saves = right_tb:AddTab("Files")
                group_class = right_tb:AddTab("Class")
            end)
            if not ui_ok then
                pcall(function() library:Notify("XP FARM UI FAILED: " .. tostring(ui_err), 20) end)
                pcall(function() warn("[XP FARM] UI creation failed:", ui_err) end)
                local function ui_stub()
                    local s = {}
                    return setmetatable(s, { __index = function() return function() return s end end })
                end
                group_master = group_master or ui_stub()
                group_combat = group_combat or ui_stub()
                group_target = group_target or ui_stub()
                group_travel = group_travel or ui_stub()
                group_path = group_path or ui_stub()
                group_saves = group_saves or ui_stub()
                group_class = group_class or ui_stub()
            end

            -- Saved Teleport Points (name -> position). This whole tab -
            -- window/tab resolution, groupbox, storage, helpers, every
            -- control - lives inside its OWN pcall closure rather than
            -- sharing the outer XP Farm closure's locals. A do-block does
            -- NOT create a new register scope in Luau (peak concurrent
            -- register count is what's checked, not final live count), but
            -- a genuine nested function does - its locals never touch the
            -- outer closure's register budget at all. That closure is
            -- already at Luau's 200-local-register ceiling (see BUILD
            -- 219/229/230/231's compile-failure history).
            if not (pcall(function()
                local win = getgenv().XPFARM_WINDOW
                local tp_tab
                if win and win.AddTab then
                    tp_tab = win:AddTab("Teleport", "map-pin")
                elseif library and library.Tabs and library.Tabs.Botting then
                    tp_tab = library.Tabs.Botting
                else
                    error("no window/tab reference reachable")
                end
                local group_tp = tp_tab:AddLeftGroupbox("Saved Locations")

                local tp_store = { points = {} }
                if readfile and isfile and isfile("HYDROXIDE/teleport_points.json") then
                    local ok, data = pcall(function() return Services.HttpService:JSONDecode(readfile("HYDROXIDE/teleport_points.json")) end)
                    if ok and type(data) == "table" then tp_store.points = data end
                end

                local function tp_save()
                    if not writefile then return end
                    pcall(function()
                        if makefolder and isfolder and not isfolder("HYDROXIDE") then makefolder("HYDROXIDE") end
                        writefile("HYDROXIDE/teleport_points.json", Services.HttpService:JSONEncode(tp_store.points))
