                        local nm = Options.tp_save_name and Options.tp_save_name.Value or ""
                        if nm == "" then library:Notify("Type a name first"); return end
                        local root = local_hrp()
                        if not root then library:Notify("Character not found"); return end
                        local p = root.Position
                        local existing = tp_find(nm)
                        if existing then
                            existing.x, existing.y, existing.z = p.X, p.Y, p.Z
                        else
