                    Func = function()
                        local nm = Options.tp_selected and Options.tp_selected.Value
                        local point = nm and tp_find(nm)
                        if not point then library:Notify("No saved location selected"); return end
                        -- Jump + teleport + menu + rejoin, tuned from live
                        -- in-game testing: an exact 50-stud vertical pop, a
                        -- ~0.25s settle, an instant teleport, a wait, then the
                        -- menu invoke, then auto-click Play to rejoin.
                        task.spawn(function()
                            local target_pos = Vector3.new(point.x, point.y, point.z)
                            local root = local_hrp()
                            if not root then library:Notify("Teleport: character not found"); return end
                            local char = plr.Character
                            local humanoid = char and FindFirstChildOfClass(char, "Humanoid")
                            if humanoid then pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end) end
                            root.CFrame = root.CFrame + Vector3.new(0, 50, 0)
                            task.wait(0.25)

                            root = local_hrp()
                            if not root then return end
                            root.CFrame = CFrame.new(target_pos)
                            pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
                            pcall(function() root.AssemblyAngularVelocity = Vector3.new(0, 0, 0) end)

                            -- spam the menu invoke repeatedly for 1s right after landing
                            -- instead of waiting out a fixed delay then firing once
                            local spam_t0 = os.clock()
                            local fired_ok = false
                            while (os.clock() - spam_t0) < 1 do
                                local ok = pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)
                                if ok then fired_ok = true end
                                task.wait(0.05)
                            end
                            library:Notify("Teleport: " .. (fired_ok and "menu fired" or "menu FAILED"), 3)
                            if not fired_ok then return end

                            pcall(function() plr.PlayerGui:WaitForChild("StartMenu", 30) end)
                            if plr.PlayerGui:FindFirstChild("StartMenu") then
                                pcall(function()
                                    if plr.PlayerGui.StartMenu:FindFirstChild("Choices") and
                                       plr.PlayerGui.StartMenu.Choices:FindFirstChild("Play") then
                                        firesignal(plr.PlayerGui.StartMenu.Choices.Play.MouseButton1Click)
                                    end
                                end)
                            end
                        end)
                    end
                })
                group_tp:AddInput("tp_rename_to", {
                    Text = "Rename Selected To",
                    Default = "",
                    Placeholder = "new name"
                })
                group_tp:AddButton("tp_rename", {
                    Text = "Rename Selected",
                    Func = function()
                        local nm = Options.tp_selected and Options.tp_selected.Value
                        local point = nm and tp_find(nm)
                        local newname = Options.tp_rename_to and Options.tp_rename_to.Value or ""
                        if not point then library:Notify("No saved location selected"); return end
                        if newname == "" then library:Notify("Type a new name first"); return end
                        point.name = newname
                        tp_save()
                        pcall(function() Options.tp_selected:SetValues(tp_names()) end)
                        library:Notify("Renamed to: " .. newname, 3)
                    end
                })
                group_tp:AddButton("tp_delete", {
                    Text = "Delete Selected",
                    Func = function()
                        local nm = Options.tp_selected and Options.tp_selected.Value
                        for i, p in ipairs(tp_store.points) do
                            if p.name == nm then table.remove(tp_store.points, i); break end
                        end
                        tp_save()
                        pcall(function() Options.tp_selected:SetValues(tp_names()) end)
                        library:Notify("Deleted: " .. tostring(nm), 3)
                    end
                })

                group_tp:AddToggle("tp_proximity_light", {
                    Text = "Someone Nearby (50 studs)",
                    Default = false,
                    Callback = function() end -- read-only status light, not user-driven
