                                        end
                                    end
                                end
                            end
                            if toggle.Value ~= near then
                                pcall(function() toggle:SetValue(near) end)
                            end
                        end
                        task.wait(2)
                    end
                end)
            end)) then
                pcall(function() library:Notify("TELEPORT TAB UI FAILED - see console", 20) end)
            end

