            })
            group_travel:AddButton("xpfarm_add_point", {
                Text = "Add Waypoint (here)",
                Tooltip = "Adds a waypoint of the selected Waypoint Action at your current spot",
                Func = function()
                    local wt = tonumber(Options.xpfarm_point_wait and Options.xpfarm_point_wait.Value) or 0
                    if selected_action == "Inn Stop" then
                        local at = add_step({ kind = "inn", inn = selected_inn })
                        update_path_label(); update_viz()
                        library:Notify("Added inn stop #" .. at .. ": " .. tostring(selected_inn))
                        return
                    end
                    if selected_action == "Offset On" or selected_action == "Offset Off" then
                        local at = add_step({ kind = (selected_action == "Offset On") and "offset_on" or "offset_off" })
                        update_path_label(); update_viz()
                        library:Notify("Added action: " .. selected_action .. " (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Auto Ingredient On" or selected_action == "Auto Ingredient Off" then
                        local at = add_step({ kind = (selected_action == "Auto Ingredient On") and "autoing_on" or "autoing_off" })
                        update_path_label(); update_viz()
                        library:Notify("Added action: " .. selected_action .. " (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Auto Bag On" or selected_action == "Auto Bag Off" then
                        local at = add_step({ kind = (selected_action == "Auto Bag On") and "autobag_on" or "autobag_off" })
                        update_path_label(); update_viz()
                        library:Notify("Added action: " .. selected_action .. " (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Instant Mine On" or selected_action == "Instant Mine Off" then
                        local at = add_step({ kind = (selected_action == "Instant Mine On") and "instmine_on" or "instmine_off" })
                        update_path_label(); update_viz()
                        library:Notify("Added action: " .. selected_action .. " (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Skip Illusionist On" or selected_action == "Skip Illusionist Off" then
                        local at = add_step({ kind = (selected_action == "Skip Illusionist On") and "skipillus_on" or "skipillus_off" })
                        update_path_label(); update_viz()
                        library:Notify("Added action: " .. selected_action .. " (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Loop Orderly On" or selected_action == "Loop Orderly Off" then
                        local at = add_step({ kind = (selected_action == "Loop Orderly On") and "orderly_on" or "orderly_off" })
                        update_path_label(); update_viz()
                        library:Notify("Added action: " .. selected_action .. " (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Equip Pickaxe" then
                        local at = add_step({ kind = "equip_pickaxe" })
                        update_path_label(); update_viz()
                        library:Notify("Added action: Equip Pickaxe (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Repeat Start" then
                        local n = math.max(1, math.floor(wt))
                        local at = add_step({ kind = "repeat_start", count = n })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Repeat Start x%d (#%d) - set count via Point Wait Time", n, at))
                        return
                    end
                    if selected_action == "Repeat (Ingredient)" then
                        local ing = (Options.xpfarm_ingredient and Options.xpfarm_ingredient.Value) or "Dire Flower"
                        local amt = math.max(1, math.floor(tonumber(Options.xpfarm_ingredient_amount and Options.xpfarm_ingredient_amount.Value) or 1))
                        local at = add_step({ kind = "repeat_start", count = 1, goal_kind = "ingredient", ingredient = ing, goal = amt })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Repeat (Ingredient): loops until you have %d %s (#%d). Add Return Points after Repeat End to walk back.", amt, ing, at))
                        return
                    end
                    if selected_action == "Repeat (Monster Drop)" then
                        local drop = (Options.xpfarm_drop and Options.xpfarm_drop.Value) or "Evil Eye"
                        local amt = math.max(1, math.floor(tonumber(Options.xpfarm_ingredient_amount and Options.xpfarm_ingredient_amount.Value) or 1))
                        local at = add_step({ kind = "repeat_start", count = 1, goal_kind = "ingredient", ingredient = drop, goal = amt })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Repeat (Monster Drop): kill until you have %d %s (#%d). Put Auto Bag On before it + Attack Here inside, and Return Points after Repeat End.", amt, drop, at))
                        return
                    end
                    if selected_action == "Repeat End" then
                        local at = add_step({ kind = "repeat_end" })
                        update_path_label(); update_viz()
                        library:Notify("Added Repeat End (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Return Serverhop" then
                        local at = add_step({ kind = "return", serverhop = true })
                        update_path_label(); update_viz()
                        library:Notify("Added Return Serverhop - only runs on loop-back to hop for fresh ingredients (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Return Point" then
                        local hrp = local_hrp()
                        if not hrp then library:Notify("Character not found"); return end
                        local at = add_step({ kind = "return", cf = hrp.CFrame, wait_time = wt })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Return Point (#%d) - only walked when the repeat loops back to the start", at))
                        return
                    end
                    if selected_action == "End Path" then
                        local at = add_step({ kind = "end_path" })
                        update_path_label(); update_viz()
                        library:Notify("Added End Path - stops looping here (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Wait For Ores" then
                        local at = add_step({ kind = "wait_ores" })
                        update_path_label(); update_viz()
                        library:Notify("Added Wait For Ores - holds here until ores exist, ignoring Tin (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Wait For Ingredient" then
                        local ing = (Options.xpfarm_ingredient and Options.xpfarm_ingredient.Value) or "Dire Flower"
                        local amt = math.max(1, math.floor(tonumber(Options.xpfarm_ingredient_amount and Options.xpfarm_ingredient_amount.Value) or 1))
                        local at = add_step({ kind = "wait_ingredient", ingredient = ing, amount = amt })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added gate: wait here until you have %d %s (#%d)", amt, ing, at))
                        return
                    end
                    if selected_action == "Serverhop" then
                        local at = add_step({ kind = "serverhop" })
                        update_path_label(); update_viz()
                        library:Notify("Added Serverhop - hops + resumes the path here (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Wait Timer" then
                        local mins = math.max(1, math.floor(tonumber(Options.xpfarm_wait_minutes and Options.xpfarm_wait_minutes.Value) or 15))
                        local at = add_step({ kind = "wait_timer", minutes = mins })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Wait Timer - holds here %d minute(s) (#%d)", mins, at))
                        return
                    end
                    if selected_action == "Reset If Safe" then
                        local at = add_step({ kind = "reset_if_safe" })
                        update_path_label(); update_viz()
                        library:Notify("Added Reset If Safe - resets only when out of Danger (#" .. at .. ")")
                        return
                    end
                    if selected_action == "Wait For Day" then
                        local day = math.max(1, math.floor(tonumber(Options.xpfarm_wait_day and Options.xpfarm_wait_day.Value) or 1))
                        local at = add_step({ kind = "wait_day", day = day })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Wait For Day - holds here until Day %d (#%d)", day, at))
                        return
                    end
                    if selected_action == "Loop Orderly (N times)" then
                        local n = math.max(1, math.floor(tonumber(Options.xpfarm_orderly_count and Options.xpfarm_orderly_count.Value) or 5))
                        local at = add_step({ kind = "orderly_n", count = n })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Loop Orderly x%d - drinks a Tespian Elixir + resets, %d time(s), then continues (#%d)", n, n, at))
                        return
                    end
                    if selected_action == "Equip Item" then
                        local typed = (Options.xpfarm_equip_item_name and Options.xpfarm_equip_item_name.Value) or ""
                        local picked = Options.xpfarm_equip_item_dropdown and Options.xpfarm_equip_item_dropdown.Value
                        local item_name = typed ~= "" and typed or picked
                        if not item_name or item_name == "" or item_name == "(scan your bag first)" or item_name == "(bag is empty)" then
                            library:Notify("Equip Item: type a name, or click Scan My Bag and pick one from the dropdown", 5)
                            return
                        end
                        local at = add_step({ kind = "equip_item", item_name = item_name })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Equip Item: %s (#%d)", item_name, at))
                        return
                    end
                    if selected_action == "Teleport Menu" then
                        local loc = Options.xpfarm_tp_location and Options.xpfarm_tp_location.Value
                        if not loc or loc == "" or loc == "(refresh list)" or loc == "(no saved locations)" then
                            library:Notify("Teleport Menu: click Refresh Locations and pick a saved spot first", 5)
                            return
                        end
                        -- resolve to the actual x/y/z NOW and bake it into the step, rather
                        -- than storing just the saved-location name - a name-only reference
                        -- would break for anyone whose teleport_points.json doesn't have a
                        -- point with that exact name (different save, renamed it, etc).
                        local point = nil
                        if readfile and isfile and isfile("HYDROXIDE/teleport_points.json") then
                            local ok, data = pcall(function() return Services.HttpService:JSONDecode(readfile("HYDROXIDE/teleport_points.json")) end)
                            if ok and type(data) == "table" then
                                for _, p in ipairs(data) do
                                    if p.name == loc then point = p; break end
                                end
                            end
                        end
                        if not point then
                            library:Notify("Teleport Menu: couldn't read '" .. tostring(loc) .. "' from your saved locations", 5)
                            return
                        end
                        local at = add_step({ kind = "tp_menu", x = point.x, y = point.y, z = point.z, label = loc })
                        update_path_label(); update_viz()
                        library:Notify(string.format("Added Teleport Menu: %s @ %.0f,%.0f,%.0f (#%d)", loc, point.x, point.y, point.z, at))
                        return
                    end
                    local hrp = local_hrp()
                    if not hrp then library:Notify("Character not found"); return end
                    local kind = "point"
                    if selected_action == "Talk to NPC" then kind = "npc"
                    elseif selected_action == "CR Captcha" then kind = "npc_captcha"
                    elseif selected_action == "Attack Here" then kind = "attack"
                    elseif selected_action == "Charge Mana + Attack" then kind = "mana_attack"
                    elseif selected_action == "Shrieker Grab" then kind = "shrieker"
                    elseif selected_action == "Sealed Shrieker Grip" then kind = "sealed"
                    elseif selected_action == "Mine Here" then kind = "mine"
                    elseif selected_action == "Smelt Here" then kind = "smelt"
                    elseif selected_action == "Craft Weapon" then kind = "craft"
                    elseif selected_action == "Sell Weapons" then kind = "sell_weapons"
                    elseif selected_action == "Make Potions" then kind = "potion"
                    elseif selected_action == "Hold Point" then kind = "hold"
                    elseif selected_action == "Charge Mana" then kind = "mana" end
                    local step = { kind = kind, cf = hrp.CFrame, wait_time = wt }
                    if kind == "potion" then
                        step.potion = (Options.xpfarm_potion and Options.xpfarm_potion.Value) or "Health Potion"
                        step.count = math.max(0, math.floor(tonumber(Options.xpfarm_potion_count and Options.xpfarm_potion_count.Value) or 0))
                        step.delay = math.max(0, tonumber(Options.xpfarm_potion_delay and Options.xpfarm_potion_delay.Value) or 1)
                    elseif kind == "craft" then
                        step.weapon = (Options.xpfarm_weapon and Options.xpfarm_weapon.Value) or "Mythril Dagger"
                        step.count = math.max(0, math.floor(tonumber(Options.xpfarm_weapon_count and Options.xpfarm_weapon_count.Value) or 0))
                        step.delay = math.max(0, tonumber(Options.xpfarm_weapon_delay and Options.xpfarm_weapon_delay.Value) or 1)
                    elseif kind == "npc" or kind == "sell_weapons" or kind == "npc_captcha" then
                        local nm = Options.xpfarm_npc_name and Options.xpfarm_npc_name.Value or ""
                        if nm ~= "" then step.npc_name = nm end
                        if kind == "npc" and Options.xpfarm_npc_skip_armed and Options.xpfarm_npc_skip_armed.Value then step.skip_if_armed = true end
                        local seq_text = (Options.xpfarm_npc_choice_sequence and Options.xpfarm_npc_choice_sequence.Value) or ""
                        if seq_text ~= "" then
                            local seq = {}
                            for part in seq_text:gmatch("([^,]+)") do
                                local trimmed = part:gsub("^%s*(.-)%s*$", "%1")
                                if trimmed ~= "" then table.insert(seq, trimmed) end
                            end
                            if #seq > 0 then step.choice_sequence = seq end
                        end
                    end
                    local at = add_step(step)
                    update_path_label(); update_viz()
                    local extra = (kind == "potion") and (" - " .. step.potion .. (step.count > 0 and (" x" .. step.count) or " (all)"))
                        or (kind == "craft") and (" - " .. step.weapon .. (step.count > 0 and (" x" .. step.count) or " (all)"))
                        or ""
                    library:Notify(string.format("Added %s waypoint #%d (%ds)%s", selected_action, at, wt, extra))
                end
            })
            group_travel:AddButton("xpfarm_set_lure", {
                Text = "Set Lure/Trigger Spot",
                Tooltip = "Stand where you want the lure/trigger, then click. Sets it on the most recent Attack Here/Charge Mana + Attack (darts here to herd Evil Eyes) or Shrieker Grab (darts here to trigger the spawn / catch the respawn) waypoint.",
                Func = function()
                    local target
                    for j = #xp_path, 1, -1 do
                        local k = xp_path[j].kind
                        if k == "attack" or k == "mana_attack" or k == "shrieker" or k == "sealed" then target = xp_path[j]; break end
                    end
                    if not target then library:Notify("Add an Attack Here, Charge Mana + Attack, Shrieker Grab or Sealed Shrieker Grip waypoint first"); return end
                    local hrp = local_hrp()
                    if not hrp then library:Notify("Character not found"); return end
                    target.cf2 = hrp.CFrame
                    update_viz()
                    library:Notify("Lure/trigger spot set for the last " .. target.kind .. " waypoint")
                end
            })
            group_travel:AddButton("xpfarm_remove_last", {
                Text = "Remove Last Waypoint",
                Func = function()
                    if #xp_path == 0 then library:Notify("Path is empty"); return end
                    table.remove(xp_path)
                    update_path_label()
                    update_viz()
                    library:Notify(string.format("Removed last - %d left", #xp_path))
                end
            })
            group_travel:AddInput("xpfarm_remove_idx", {
                Text = "Remove Waypoint #",
                Default = "",
                Placeholder = "orb number, then click below"
            })
            group_travel:AddButton("xpfarm_remove_at", {
                Text = "Remove That Number",
                Tooltip = "Removes the waypoint whose orb shows this number",
                Func = function()
                    local n = tonumber(Options.xpfarm_remove_idx and Options.xpfarm_remove_idx.Value)
                    if not n then library:Notify("Type a waypoint number first"); return end
                    n = math.floor(n)
                    if n < 1 or n > #xp_path then library:Notify("No waypoint #" .. tostring(n)); return end
                    table.remove(xp_path, n)
                    update_path_label()
                    update_viz()
                    library:Notify(string.format("Removed #%d - %d left", n, #xp_path))
                end
            })
            group_travel:AddInput("xpfarm_edit_idx", {
                Text = "Edit Waypoint #",
                Default = "",
                Placeholder = "orb number to edit"
            })
            group_travel:AddButton("xpfarm_edit_move", {
                Text = "Move That Waypoint Here",
                Tooltip = "Re-records the chosen waypoint's position at your current spot",
                Func = function()
                    local n = tonumber(Options.xpfarm_edit_idx and Options.xpfarm_edit_idx.Value)
                    if not n then library:Notify("Type a waypoint number first"); return end
                    n = math.floor(n)
                    local step = xp_path[n]
                    if not step then library:Notify("No waypoint #" .. tostring(n)); return end
                    if step.kind == "inn" then library:Notify("Inn stops have no position"); return end
                    local hrp = local_hrp()
                    if not hrp then library:Notify("Character not found"); return end
                    step.cf = hrp.CFrame
                    update_viz()
                    library:Notify(string.format("Moved waypoint #%d here", n))
                end
            })
            group_travel:AddButton("xpfarm_edit_apply", {
                Text = "Set That Waypoint Action+Wait",
                Tooltip = "Applies the Waypoint Action + Point Wait Time above to the chosen waypoint",
                Func = function()
                    local n = tonumber(Options.xpfarm_edit_idx and Options.xpfarm_edit_idx.Value)
                    if not n then library:Notify("Type a waypoint number first"); return end
                    n = math.floor(n)
                    local step = xp_path[n]
                    if not step then library:Notify("No waypoint #" .. tostring(n)); return end
                    local wt = tonumber(Options.xpfarm_point_wait and Options.xpfarm_point_wait.Value) or 0
                    if selected_action == "Inn Stop" then
                        xp_path[n] = { kind = "inn", inn = selected_inn }
                    elseif selected_action == "Offset On" then
                        xp_path[n] = { kind = "offset_on" }
                    elseif selected_action == "Offset Off" then
                        xp_path[n] = { kind = "offset_off" }
                    elseif selected_action == "Auto Ingredient On" then
                        xp_path[n] = { kind = "autoing_on" }
                    elseif selected_action == "Auto Ingredient Off" then
                        xp_path[n] = { kind = "autoing_off" }
                    elseif selected_action == "Auto Bag On" then
                        xp_path[n] = { kind = "autobag_on" }
                    elseif selected_action == "Auto Bag Off" then
                        xp_path[n] = { kind = "autobag_off" }
                    elseif selected_action == "Repeat Start" then
                        xp_path[n] = { kind = "repeat_start", count = math.max(1, math.floor(wt)) }
                    elseif selected_action == "Repeat End" then
                        xp_path[n] = { kind = "repeat_end" }
                    elseif selected_action == "End Path" then
                        xp_path[n] = { kind = "end_path" }
                    elseif selected_action == "Serverhop" then
                        xp_path[n] = { kind = "serverhop" }
                    else
                        local kind = "point"
                        if selected_action == "Talk to NPC" then kind = "npc"
                        elseif selected_action == "Attack Here" then kind = "attack"
                        elseif selected_action == "Charge Mana + Attack" then kind = "mana_attack"
                        elseif selected_action == "Shrieker Grab" then kind = "shrieker"
                        elseif selected_action == "Sealed Shrieker Grip" then kind = "sealed"
                        elseif selected_action == "Charge Mana" then kind = "mana" end
                        local cf = step.cf or (local_hrp() and local_hrp().CFrame)
                        if not cf then library:Notify("That waypoint has no spot - use Move first"); return end
                        local ns = { kind = kind, cf = cf, wait_time = wt }
                        if kind == "npc" then
                            local nm = Options.xpfarm_npc_name and Options.xpfarm_npc_name.Value or ""
                            if nm ~= "" then ns.npc_name = nm end
                            if Options.xpfarm_npc_skip_armed and Options.xpfarm_npc_skip_armed.Value then ns.skip_if_armed = true end
                        end
                        xp_path[n] = ns
                    end
                    update_path_label()
                    update_viz()
                    library:Notify(string.format("Set #%d to %s (%ds)", n, selected_action, wt))
                end
            })
            group_travel:AddButton("xpfarm_new_path", {
                Text = "New Path",
                Func = function()
                    xp_path = {}
                    path_idx = 0
                    update_path_label()
                    update_viz()
                    if Options.xpfarm_path_name then Options.xpfarm_path_name:SetValue("") end
                    library:Notify("Started new path - enter a name before saving")
                end
            })
            group_travel:AddToggle("xpfarm_show_viz", {
                Text = "Show Waypoints",
                Default = true,
                Tooltip = "Draw numbered orbs + connecting lines in-world for each waypoint (HOLD = hold spot)",
                Callback = function() update_viz() end
            })
            group_travel = group_saves   -- Files sub-tab
            group_travel:AddInput("xpfarm_path_name", {
                Text = "Path Name",
                Default = "",
                Placeholder = "Enter new path name to save..."
            })
            group_travel:AddButton("xpfarm_save_path", {
                Text = "Save Path",
                Func = function()
                    local name = (Options.xpfarm_path_name and Options.xpfarm_path_name.Value) or ""
                    if name == "" then library:Notify("Please enter a path name!"); return end
                    if #xp_path == 0 then library:Notify("No points to save!"); return end
                    if save_xpfarm_path(name) then
                        library:Notify(string.format("Saved path '%s' (%d steps)", name, #xp_path))
                        if Options.xpfarm_saved_paths then
                            Options.xpfarm_saved_paths:SetValues(get_saved_xpfarm_paths())
                            Options.xpfarm_saved_paths:SetValue(name)
                        end
                    end
                end
            })
            group_travel:AddDropdown("xpfarm_saved_paths", {
                Text = "Saved Paths",
                Values = get_saved_xpfarm_paths(),
                Multi = false,
                Callback = function(value)
                    if value and value ~= "" then
                        if load_xpfarm_path(value) then
                            library:Notify(string.format("Loaded path '%s' (%d steps)", value, #xp_path))
                        end
                    end
                end
            })
            group_travel:AddButton("xpfarm_append_path", {
                Text = "Append Saved Path (Selected)",
                Tooltip = "Adds the selected saved path's steps onto the END of the currently loaded path - build segments separately (druid1, druid2, druid3...) then stitch them together in order, one append at a time",
                Func = function()
                    local name = (Options.xpfarm_saved_paths and Options.xpfarm_saved_paths.Value) or ""
                    if name == "" then library:Notify("Select a saved path from the dropdown first"); return end
                    -- inlined here (not an outer-scope function) - this closure is
                    -- already at Luau's 200-local-register ceiling, see BUILD
                    -- 219/229-236/240's compile-failure history
                    local ok = false
                    local added = 0
                    if readfile and isfile then
                        local file_path = XPFARM_PATH_FOLDER .. "/" .. name .. ".json"
                        if isfile(file_path) then
                            local decOk, data = pcall(function()
                                return Services.HttpService:JSONDecode(readfile(file_path))
                            end)
                            if decOk and type(data) == "table" then
                                ok = true
                                for _, step in ipairs(data.steps or {}) do
                                    if step.kind == "inn" and step.inn then
                                        table.insert(xp_path, { kind = "inn", inn = step.inn })
                                        added = added + 1
                                    elseif step.kind == "offset_on" or step.kind == "offset_off"
                                        or step.kind == "autoing_on" or step.kind == "autoing_off"
                                        or step.kind == "autobag_on" or step.kind == "autobag_off"
                                        or step.kind == "instmine_on" or step.kind == "instmine_off"
                                        or step.kind == "skipillus_on" or step.kind == "skipillus_off"
                                        or step.kind == "orderly_on" or step.kind == "orderly_off"
                                        or step.kind == "equip_pickaxe" or step.kind == "reset_if_safe" then
                                        table.insert(xp_path, { kind = step.kind })
                                        added = added + 1
                                    elseif step.kind == "repeat_start" then
                                        table.insert(xp_path, { kind = "repeat_start", count = step.count or 1, goal_kind = step.goal_kind, goal = step.goal, ingredient = step.ingredient })
                                        added = added + 1
                                    elseif step.kind == "repeat_end" then
                                        table.insert(xp_path, { kind = "repeat_end" })
                                        added = added + 1
                                    elseif step.kind == "end_path" then
                                        table.insert(xp_path, { kind = "end_path" })
                                        added = added + 1
                                    elseif step.kind == "wait_ores" then
                                        table.insert(xp_path, { kind = "wait_ores" })
                                        added = added + 1
                                    elseif step.kind == "wait_ingredient" then
                                        table.insert(xp_path, { kind = "wait_ingredient", ingredient = step.ingredient, amount = step.amount })
                                        added = added + 1
                                    elseif step.kind == "wait_timer" then
                                        table.insert(xp_path, { kind = "wait_timer", minutes = step.minutes })
                                        added = added + 1
                                    elseif step.kind == "wait_day" then
                                        table.insert(xp_path, { kind = "wait_day", day = step.day })
                                        added = added + 1
                                    elseif step.kind == "orderly_n" then
                                        table.insert(xp_path, { kind = "orderly_n", count = step.count })
                                        added = added + 1
                                    elseif step.kind == "equip_item" then
                                        table.insert(xp_path, { kind = "equip_item", item_name = step.item_name })
                                        added = added + 1
                                    elseif step.kind == "tp_menu" then
                                        table.insert(xp_path, { kind = "tp_menu", x = step.x, y = step.y, z = step.z, label = step.label })
                                        added = added + 1
                                    elseif step.kind == "skill_gate" then
                                        table.insert(xp_path, { kind = "skill_gate", skill = step.skill, skills = step.skills, redo_from = step.redo_from })
                                        added = added + 1
                                    elseif step.kind == "smart_skill_skip" then
                                        table.insert(xp_path, { kind = "smart_skill_skip", checks = step.checks, all_done_goto = step.all_done_goto })
                                        added = added + 1
                                    elseif step.kind == "smart_ingredient_skip" then
                                        table.insert(xp_path, { kind = "smart_ingredient_skip", want_all = step.want_all, target_all = step.target_all, want_any = step.want_any, target_any = step.target_any })
                                        added = added + 1
                                    elseif step.kind == "return" and not step.x then
                                        table.insert(xp_path, { kind = "return", serverhop = step.serverhop })
                                        added = added + 1
                                    elseif step.kind == "serverhop" then
                                        table.insert(xp_path, { kind = "serverhop" })
                                        added = added + 1
                                    elseif step.x then
                                        local e = { kind = step.kind or "point", cf = CFrame.new(step.x, step.y, step.z), wait_time = step.wait_time or 0 }
                                        if step.x2 then e.cf2 = CFrame.new(step.x2, step.y2, step.z2) end
                                        if step.turnin then e.turnin = true end
                                        if step.potion then e.potion = step.potion end
                                        if step.weapon then e.weapon = step.weapon end
                                        if step.count ~= nil then e.count = step.count end
                                        if step.delay ~= nil then e.delay = step.delay end
                                        if step.npc_name then e.npc_name = step.npc_name end
                                        if step.choice_sequence then e.choice_sequence = step.choice_sequence end
                                        if step.skip_if_armed then e.skip_if_armed = true end
                                        table.insert(xp_path, e)
                                        added = added + 1
                                    end
                                end
                                path_idx = 0
                                update_path_label()
                                update_viz()
                            end
                        end
                    end
                    if ok then
                        library:Notify(string.format("Appended '%s' (+%d steps, %d total now)", name, added, #xp_path))
                    else
                        library:Notify("Failed to append '" .. name .. "'")
                    end
                end
            })
            group_travel:AddButton("xpfarm_refresh_paths", {
                Text = "Refresh Paths",
                Func = function()
                    local paths = get_saved_xpfarm_paths()
                    if Options.xpfarm_saved_paths then
                        Options.xpfarm_saved_paths:SetValues(paths)
                        library:Notify(string.format("Found %d saved paths", #paths))
                    end
                end
