            group_travel:AddButton("xpfarm_delete_path", {
                Text = "Delete Path",
                Func = function()
                    local name = (Options.xpfarm_saved_paths and Options.xpfarm_saved_paths.Value) or ""
                    if name == "" then library:Notify("Please select a path to delete!"); return end
                    if not delfile or not isfile then library:Notify("delfile/isfile not supported!"); return end
                    local file_path = XPFARM_PATH_FOLDER .. "/" .. name .. ".json"
                    if not isfile(file_path) then library:Notify(string.format("Path '%s' not found!", name)); return end
                    local ok, err = pcall(function() delfile(file_path) end)
                    if ok then
                        library:Notify(string.format("Deleted path '%s'", name))
                        if Options.xpfarm_saved_paths then
                            Options.xpfarm_saved_paths:SetValues(get_saved_xpfarm_paths())
                            Options.xpfarm_saved_paths:SetValue(nil)
                        end
                    else
                        library:Notify("Failed to delete path: " .. tostring(err))
                    end
                end
            })
