            group_travel:AddSlider("xpfarm_speed", {
                Text = "Bot Speed", Default = 100, Min = 20, Max = 300, Rounding = 0, Suffix = " st/s",
                Tooltip = "Movement speed, same style as the Trinket Bot's speed setting"
            })
            group_travel:AddToggle("xpfarm_path_run", {
                Text = "Run Path (loop)",
                Default = false,
                Tooltip = "Move between waypoints with the bot's movement, renting at inn stops, looping forever",
                Callback = function(v) if v then shrieker_done = 0 end end
            })
            group_travel:AddButton("xpfarm_test_run", {
                Text = "Test Run Once (skip repeats)",
                Tooltip = "Run the whole path one time with Repeat blocks doing a single pass - to check the route. Stops after one loop.",
                Func = function()
                    if #xp_path == 0 then library:Notify("Path is empty"); return end
                    test_once = true
                    if Toggles.xpfarm_path_run and not Toggles.xpfarm_path_run.Value then Toggles.xpfarm_path_run:SetValue(true) end
                    library:Notify("Test run: one pass, repeats skipped", 4)
                end
            })
            group_travel:AddInput("xpfarm_start_idx", {
                Text = "Start At Waypoint #",
                Default = "",
                Placeholder = "orb number to start from"
            })
            group_travel:AddButton("xpfarm_run_from", {
                Text = "Run Path From #",
                Tooltip = "Start the path from this waypoint number (handy for testing a later section). It begins there once, then loops normally. If the path is already running, it takes effect on the next loop.",
                Func = function()
                    local n = tonumber(Options.xpfarm_start_idx and Options.xpfarm_start_idx.Value)
                    if not n then library:Notify("Type a waypoint number first"); return end
                    n = math.floor(n)
                    if n < 1 or n > #xp_path then library:Notify("No waypoint #" .. tostring(n)); return end
                    path_resume_from = -n   -- negative = manual test start, skips the serverhop-resume safety checks
                    if Toggles.xpfarm_path_run and not Toggles.xpfarm_path_run.Value then Toggles.xpfarm_path_run:SetValue(true) end
                    library:Notify(string.format("Running path from waypoint %d", n), 4)
                end
            })
            group_travel:AddSlider("xpfarm_path_wait", {
                Text = "Default Dwell", Default = 4, Min = 0, Max = 60, Rounding = 0, Suffix = "s",
                Tooltip = "Fallback wait only for waypoints saved without their own Point Wait Time"
            })
            path_label = group_travel:AddLabel("xpfarm_path_status", { Text = "Waypoints: 0   |   At: 0", DoesWrap = true })
            group_travel = group_class   -- Class sub-tab
            group_travel:AddToggle("xpfarm_auto_hop", {
                Text = "Auto Serverhop When Idle",
                Default = false,
                Tooltip = "Serverhop if no monsters are seen for a while"
            })
            group_travel:AddSlider("xpfarm_hop_after", {
                Text = "Hop After Idle", Default = 90, Min = 1, Max = 600, Rounding = 0, Suffix = "s",
                Tooltip = "Serverhop this many seconds after the last monster is seen. Set to 1 for near-instant hopping."
            })
            group_travel:AddToggle("xpfarm_skip_illus", {
                Text = "Skip Illusionist Servers",
                Default = false,
                Tooltip = "After an XP-farm serverhop, if an Illusionist (a player holding 'Observe') is in the new server, hop again before settling - so the farm never sits in an illus server.",
                Callback = function(v) pcall(function() mem:SetItem("xpfarm_skip_illus", v and "true" or "false") end) end
            })
            pcall(function()
                if mem:HasItem("xpfarm_skip_illus") and mem:GetItem("xpfarm_skip_illus") == "true" and Toggles.xpfarm_skip_illus then
                    Toggles.xpfarm_skip_illus:SetValue(true)
                end
            end)
            group_travel:AddToggle("xpfarm_skip_mod", {
                Text = "Serverhop If Moderator",
                Default = false,
                Tooltip = "If a Rogue Lineage moderator/staff is in the server, hop away (and keep hopping until you land in a mod-free server). Checked on every hop + resume.",
                Callback = function(v) pcall(function() mem:SetItem("xpfarm_skip_mod", v and "true" or "false") end) end
            })
            pcall(function()
                if mem:HasItem("xpfarm_skip_mod") and mem:GetItem("xpfarm_skip_mod") == "true" and Toggles.xpfarm_skip_mod then
                    Toggles.xpfarm_skip_mod:SetValue(true)
                end
            end)
            group_travel:AddSlider("xpfarm_min_player_count", {
                Text = "Min Player Count", Default = 0, Min = 0, Max = 23, Rounding = 0, Compact = true,
                Tooltip = "Only hop into servers with at least this many players (0 = disabled). Restricted/isolated servers are usually only 1-5 players, so setting this to ~8 avoids landing in one.",
                Callback = function(v) pcall(function() mem:SetItem("xpfarm_min_player_count", tostring(v)) end) end
            })
            pcall(function()
                if mem:HasItem("xpfarm_min_player_count") and Options.xpfarm_min_player_count then
                    local saved = tonumber(mem:GetItem("xpfarm_min_player_count"))
                    if saved then Options.xpfarm_min_player_count:SetValue(saved) end
                end
            end)
            group_travel:AddButton("xpfarm_hop_now", {
                Text = "Serverhop Now",
                Func = function()
                    task.spawn(function()
                        if Toggles.xpfarm_master and Toggles.xpfarm_master.Value then save_farm_state() end
                        pcall(function() utility:Serverhop() end)
                    end)
                end
            })
            group_travel:AddDivider()
            group_travel:AddDropdown("xpfarm_target_class", {
                Values = CLASS_LIST, Default = 1, Multi = false, Text = "Target Class",
                Tooltip = "Informational - set Required Weapon XP to its mastery requirement"
            })
            group_travel:AddSlider("xpfarm_required_xp", {
                Text = "Required Weapon XP", Default = 1000, Min = 0, Max = 100000, Rounding = 0,
                Tooltip = "Notified when weapon XP reaches this (only if XP can be read)"
            })
            group_travel:AddSlider("xpfarm_per_class", {
                Text = "Monsters Per Class", Default = 12, Min = 1, Max = 200, Rounding = 0,
                Tooltip = "Kills needed for your target class (~12 for a super class)"
            })
            group_travel:AddToggle("xpfarm_stop_done", {
                Text = "Stop When Goal Reached",
                Default = true,
                Tooltip = "Turn Full Auto Farm off (and stop serverhopping) once the kill goal is hit"
            })
            group_travel:AddButton("xpfarm_reset_kills", {
                Text = "Reset Kill Count",
                Func = function()
                    kills = 0
                    for k in pairs(kill_counted) do kill_counted[k] = nil end
                    pcall(function() mem:SetItem("xpfarm_kills", "0") end)
                    library:Notify("Kill count reset")
                end
            })
            weapon_label = group_travel:AddLabel("xpfarm_weapon_status", { Text = "Weapon: -", DoesWrap = true })

            update_path_label()
            update_viz()

            -- Carbine Extras (Misc tab): native hitbox offset.
            pcall(function()
                local misc = library.Tabs and library.Tabs.Misc
                if not misc then return end
                local g_ext = misc:AddLeftGroupbox("Carbine Extras")

                -- Native hitbox offset (reverse-engineered from the external script):
                -- play a pre-made animation (2986649587) and freeze it on its raised
                -- pose (~+18 studs). The pose displaces the body through the rig, which
                -- REPLICATES to the server, so server-side monster hit detection misses
                -- while the HumanoidRootPart stays grounded (you can still attack, still
                -- walk under walls). Players hit client-side so they can still hit you.
                -- The HRP is kept un-anchored each frame so the frozen pose holds.
                local HITBOX_ANIM = "rbxassetid://2986649587"
                local HITBOX_FREEZE_T = 1.7   -- plateau in the anim where the pose holds ~+18
                local hb_track, hb_char
                local function ensure_hb_track()
                    local c = plr.Character
                    local hum = c and c:FindFirstChildOfClass("Humanoid")
                    local animator = hum and hum:FindFirstChildOfClass("Animator")
                    if not animator then return nil end
                    if not hb_track or hb_char ~= c then
                        local anim = Instance.new("Animation")
                        anim.AnimationId = HITBOX_ANIM
                        local ok, t = pcall(function() return animator:LoadAnimation(anim) end)
                        if not ok then return nil end
                        hb_track, hb_char = t, c
                        hb_track.Looped = true
                        pcall(function() hb_track.Priority = Enum.AnimationPriority.Action4 end)
                    end
                    return hb_track
                end
                local function hb_start()
                    local t = ensure_hb_track()
                    if t then pcall(function() t:Play(0); t.TimePosition = HITBOX_FREEZE_T; t:AdjustSpeed(0) end) end
                end
                local function hb_stop()
                    if hb_track then pcall(function() hb_track:Stop() end) end
                end
                g_ext:AddToggle("xpfarm_hitbox_air", {
                    Text = "Hitbox Offset (Air)",
                    Default = false,
                    Tooltip = "Freezes an offset animation so your hitbox sits ~18 studs up - monsters' server-side hits miss while you can still attack and walk. (Players hit client-side, so they can still hit you.)",
                    Callback = function(v)
                        if v then hb_start() else hb_stop() end
                    end
                })
                cheat_client.feature_connections.xpfarm_hitbox = utility:Connection(rs.RenderStepped, function()
                    if not shared or shared.is_unloading then return end
                    if not (Toggles.xpfarm_hitbox_air and Toggles.xpfarm_hitbox_air.Value) then return end
                    local c = plr.Character
                    if not c then return end
                    local hrp = c:FindFirstChild("HumanoidRootPart")
                    if hrp and hrp.Anchored then pcall(function() hrp.Anchored = false end) end
                    if not hb_track or hb_char ~= c or not hb_track.IsPlaying then
                        hb_start()
                    end
                    local t = hb_track
                    if t and t.IsPlaying then
                        if t.Speed ~= 0 then pcall(function() t:AdjustSpeed(0) end) end
                        if math.abs(t.TimePosition - HITBOX_FREEZE_T) > 0.02 then pcall(function() t.TimePosition = HITBOX_FREEZE_T end) end
                    end
                end)
            end)

            -- ---- Full Auto master switch --------------------------------------
            set_full_farm = function(on)
                if on then
                    if not hold_cf then
                        local hrp = local_hrp()
                        if hrp then
                            hold_cf = hrp.CFrame
                            library:Notify("Hold spot set to current position")
                        end
                    end

                    -- the global OnTeleport handler reloads the script after hops;
                    -- it must stay enabled for the farm to survive serverhops
                    cheat_client.config.execute_on_serverhop = true
                    if Toggles.execute_on_serverhop and not Toggles.execute_on_serverhop.Value then
                        Toggles.execute_on_serverhop:SetValue(true)
                    end

                    for _, name in ipairs({ "xpfarm_autoclick", "xpfarm_only_when_monster", "xpfarm_face_monster", "xpfarm_loot_silver", "xpfarm_auto_inn", "xpfarm_auto_hop" }) do
                        if Toggles[name] and not Toggles[name].Value then Toggles[name]:SetValue(true) end
                    end
                    if Toggles.xpfarm_reach_monster and Toggles.xpfarm_reach_monster.Value then
                        Toggles.xpfarm_reach_monster:SetValue(false)
                    end
                    if hold_cf and Toggles.xpfarm_hold_pos and not Toggles.xpfarm_hold_pos.Value then
                        Toggles.xpfarm_hold_pos:SetValue(true)
                    end

                    save_farm_state()
                    library:Notify("Full Auto Farm: ON - farming until the class goal", 6)

                    -- far from the ledge with a route loaded? ride the path there
                    task.spawn(function()
                        if hold_cf and #xp_path > 0 then
                            local hrp = local_hrp()
                            if hrp and (hrp.Position - hold_cf.Position).Magnitude > 30 then
                                library:Notify("Running path to the hold spot...")
                                traverse_path_from_nearest()
                                if hold_cf then bot_move_to(hold_cf.Position) end
                            end
                        end
                    end)
                else
                    pcall(function() mem:SetItem("xpfarm_running", "false") end)
                    for _, name in ipairs({ "xpfarm_autoclick", "xpfarm_hold_pos", "xpfarm_loot_silver", "xpfarm_auto_inn", "xpfarm_auto_hop" }) do
                        if Toggles[name] and Toggles[name].Value then Toggles[name]:SetValue(false) end
                    end
                    library:Notify("Full Auto Farm: OFF")
                end
            end

            -- ---- combat + monster scan (single Heartbeat) --------------------
            local combat_accum, scan_accum = 0, 0
            local hold_too_far_notified = false
            local shrieker_accum, last_v_press = 0, 0
            local cached_sk_alive, cached_sk_downed, cached_sk_downed_dist = nil, nil, math.huge
            cheat_client.feature_connections.xpfarm_combat = utility:Connection(rs.Heartbeat, function(dt)
                if not shared or shared.is_unloading then return end
                if not plr.Character then combat_accum = 0; return end

                -- Shrieker Mode: attach to the nearest shrieker's back and knock
                -- it to 0 HP. Attaching glues us behind it (zeroes velocity +
                -- no-collide), so its jumping/chasing can't shake us and it faces
                -- away. We do NOT kick on low HP (kicking in Danger costs a life)
                -- - instead we stop so you can retreat.
                if Toggles.xpfarm_shrieker_mode and Toggles.xpfarm_shrieker_mode.Value then
                    local bail = (Options.xpfarm_shrieker_bail_hp and Options.xpfarm_shrieker_bail_hp.Value) or 0
                    if bail > 0 then
                        local hum = FindFirstChildOfClass(plr.Character, "Humanoid")
                        if hum and hum.MaxHealth > 0 and (hum.Health / hum.MaxHealth * 100) <= bail then
                            Toggles.xpfarm_shrieker_mode:SetValue(false)  -- stops + restores collision (see callback)
                            library:Notify("Shrieker farm: HP low - stopped, retreat now (no kick = no lost life)", 7)
                            return
                        end
                    end

                    shrieker_accum = shrieker_accum + dt
                    if shrieker_accum >= 0.1 then
                        shrieker_accum = 0
                        local range = (Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value) or 60
                        cached_sk_alive, cached_sk_downed, cached_sk_downed_dist = scan_shriekers(range)
                        if cached_sk_alive or cached_sk_downed then last_monster_seen = os.clock() end
                    end

                    -- optional: auto-press V to pick up a downed shrieker (off by default;
                    -- while it's on, the attach can fight a second one so it may grab/drop -
                    -- leave it off if you'd rather press V + carry yourself)
                    if Toggles.xpfarm_shrieker_autov and Toggles.xpfarm_shrieker_autov.Value
                        and cached_sk_downed and cached_sk_downed_dist <= 14 and (os.clock() - last_v_press) > 2.5 then
                        last_v_press = os.clock()
                        task.spawn(function()
                            pcall(function()
                                vim:SendKeyEvent(true, Enum.KeyCode.V, false, game)
                                task.wait(0.06)
                                vim:SendKeyEvent(false, Enum.KeyCode.V, false, game)
                            end)
                        end)
                    end

                    -- attach to the nearest alive shrieker's back + knock it down
                    if cached_sk_alive then
                        local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                        local root = monster_root(cached_sk_alive)
                        if hrp and root then
                            hrp.AssemblyLinearVelocity = Vector3.zero
                            local torso = FindFirstChild(plr.Character, "Torso") or FindFirstChild(plr.Character, "UpperTorso")
                            local headp = FindFirstChild(plr.Character, "Head")
                            if torso then torso.CanCollide = false end
                            if headp then headp.CanCollide = false end
                            -- sit 2 studs behind the shrieker, facing it (so M1 connects)
                            pcall(function() hrp.CFrame = CFrame.lookAt(root.Position - (root.CFrame.LookVector * 2), root.Position) end)
                        end
                        ensure_weapon()
                        local cps = math.clamp((Options.xpfarm_cps and Options.xpfarm_cps.Value) or 5, 1, 20)
                        local interval = 1 / cps
                        combat_accum = combat_accum + dt
                        local fired = 0
                        while combat_accum >= interval and fired < 5 do
                            combat_accum = combat_accum - interval
                            fired = fired + 1
                            pcall(function() utility:LeftClick() end)
                        end
                    else
                        combat_accum = 0
                    end
                    return
                end

                local autoclick = Toggles.xpfarm_autoclick and Toggles.xpfarm_autoclick.Value
                local bursting = os.clock() < burst_until
                local want_hop = Toggles.xpfarm_auto_hop and Toggles.xpfarm_auto_hop.Value
                local holding = (Toggles.xpfarm_hold_pos and Toggles.xpfarm_hold_pos.Value and hold_cf) and true or false

                if autoclick or bursting or want_hop or holding then
                    scan_accum = scan_accum + dt
                    if scan_accum >= 0.15 then
                        scan_accum = 0
                        local range = (Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value) or 60
                        cached_count, cached_nearest, cached_dist = scan_monsters(range)
                        if cached_count > 0 then last_monster_seen = os.clock() end
                    end
                end

                -- Hold Spot: if knocked or pushed off the saved spot, move back
                -- with the bot's movement (Trinket Bot style tween). While at
                -- the spot, stand and rotate toward the nearest monster. Yields
                -- to the path runner so the two never fight.
                if holding and not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) then
                    local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                    if hrp then
                        local off = (hrp.Position - hold_cf.Position).Magnitude
                        if off > 1500 then
                            if not hold_too_far_notified then
                                hold_too_far_notified = true
                                if Toggles.xpfarm_master and Toggles.xpfarm_master.Value then
                                    task.spawn(farm_kick, "Displaced too far from the hold spot")
                                else
                                    library:Notify("Too far from hold spot - hold paused")
                                end
                            end
                        elseif off > 4 then
                            if not move_active then
                                task.spawn(function() bot_move_to(hold_cf.Position) end)
                            end
                        else
                            hold_too_far_notified = false
                            if Toggles.xpfarm_face_monster and Toggles.xpfarm_face_monster.Value and cached_nearest then
                                local root = monster_root(cached_nearest)
                                if root then
                                    local flat = Vector3.new(root.Position.X, hrp.Position.Y, root.Position.Z)
                                    pcall(function() hrp.CFrame = CFrame.lookAt(hrp.Position, flat) end)
                                end
                            end
                        end
                    end
                end

                -- don't swing while the bot is moving (attacks root you in RL
                -- and would fight the movement)
                if move_active then combat_accum = 0; return end

                if not autoclick and not bursting then combat_accum = 0; return end

                if Toggles.xpfarm_only_when_monster and Toggles.xpfarm_only_when_monster.Value and cached_count == 0 then
                    combat_accum = 0
                    return
                end

                if resting then combat_accum = 0; return end

                if cached_nearest and not holding then
                    local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                    local root = monster_root(cached_nearest)
                    if hrp and root then
                        if Toggles.xpfarm_reach_monster and Toggles.xpfarm_reach_monster.Value and cached_dist > 12 then
                            if not move_active then
                                local goal = root.Position + (hrp.Position - root.Position).Unit * 7
                                task.spawn(function() bot_move_to(goal) end)
                            end
                        elseif Toggles.xpfarm_face_monster and Toggles.xpfarm_face_monster.Value then
                            local flat = Vector3.new(root.Position.X, hrp.Position.Y, root.Position.Z)
                            pcall(function() hrp.CFrame = CFrame.lookAt(hrp.Position, flat) end)
                        end
                    end
                end

                -- count the monster we're swinging at once it dies (engage range
                -- follows your Monster Range so ledge farming still counts kills)
                if cached_nearest then
                    local eng_range = math.min((Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value) or 60, 90)
                    if cached_dist <= eng_range then
                        engage_monster(cached_nearest)
                    end
                end

                ensure_weapon()

                local cps = math.clamp((Options.xpfarm_cps and Options.xpfarm_cps.Value) or 5, 1, 20)
                local interval = 1 / cps
                combat_accum = combat_accum + dt
                local fired = 0
                while combat_accum >= interval and fired < 5 do
                    combat_accum = combat_accum - interval
                    fired = fired + 1
                    pcall(function() utility:LeftClick() end)
                end
            end)

            -- ---- combat status label + kill detection ------------------------
            task.spawn(function()
                while shared and not shared.is_unloading do
                    task.wait(0.4)
                    check_engaged_kills()
                    if combat_label then
                        local bursting = os.clock() < burst_until
                        combat_label:SetText(string.format(
                            "Monsters near: %d%s",
                            cached_count,
                            bursting and string.format("   |   burst %ds", math.max(0, math.ceil(burst_until - os.clock()))) or ""
                        ))
                    end
                end
            end)

            -- ---- silver looting ----------------------------------------------
            task.spawn(function()
                while shared and not shared.is_unloading do
                    task.wait(0.2)
                    if Toggles.xpfarm_loot_silver and Toggles.xpfarm_loot_silver.Value then
                        local hrp = local_hrp()
                        if hrp then
                            local range = (Options.xpfarm_silver_range and Options.xpfarm_silver_range.Value) or 80
                            local origin = hrp.Position
                            for _, obj in ipairs(ws:GetChildren()) do
                                if obj ~= plr.Character
                                    and (obj:IsA("BasePart") or obj:IsA("Model") or obj:IsA("Tool"))
                                    and looks_like_silver(obj)
                                then
                                    local part = obj:IsA("BasePart") and obj or FindFirstChildWhichIsA(obj, "BasePart")
                                    if part and (part.Position - origin).Magnitude <= range then
                                        local cd = FindFirstChildWhichIsA(obj, "ClickDetector", true)
                                        if cd then
                                            local maxd = cd.MaxActivationDistance
                                            if maxd <= 0 then maxd = range end
                                            if (part.Position - origin).Magnitude <= maxd then
                                                pcall(function() fireclickdetector(cd) end)
                                            end
                                        elseif firetouchinterest then
                                            pcall(function()
                                                firetouchinterest(hrp, part, 0)
                                                firetouchinterest(hrp, part, 1)
                                            end)
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end)

            -- ---- weapon XP / class readiness ---------------------------------
            local xp_notified = false
            local kill_notified = false
            task.spawn(function()
                while shared and not shared.is_unloading do
                    task.wait(1)
                    if weapon_label then
                        local wname, xp = read_weapon_xp()
                        local required = (Options.xpfarm_required_xp and Options.xpfarm_required_xp.Value) or 0
                        local per = (Options.xpfarm_per_class and Options.xpfarm_per_class.Value) or 12
                        local cls = (Options.xpfarm_target_class and Options.xpfarm_target_class.Value) or "?"
                        local xptext = xp and tostring(math.floor(xp)) or "Unknown"

                        local kill_status
                        if kills >= per then
                            kill_status = "ENOUGH for " .. tostring(cls)
                        else
                            kill_status = string.format("Need %d more", per - kills)
                        end

                        weapon_label:SetText(string.format(
                            "Class: %s\nWeapon: %s   (XP: %s / %d)\nKills: %d / %d  ->  %s",
                            tostring(cls), tostring(wname), xptext, required, kills, per, kill_status
                        ))

                        -- kills are the reliable gauge; notify when we hit the target
                        if kills >= per and not kill_notified then
                            kill_notified = true
                            library:Notify(string.format("%d monsters killed - enough for %s!", kills, tostring(cls)), 8)
                            pcall(function()
                                utility:plain_webhook(string.format("XP Farm: %d/%d monsters killed - enough for %s!", kills, per, tostring(cls)))
                            end)
                            if Toggles.xpfarm_stop_done and Toggles.xpfarm_stop_done.Value
                                and Toggles.xpfarm_master and Toggles.xpfarm_master.Value then
                                Toggles.xpfarm_master:SetValue(false)
                                library:Notify("Class goal reached - Full Auto Farm stopped", 8)
                            end
                        elseif kills < per then
                            kill_notified = false
                        end

                        -- secondary: notify on weapon XP too, if it can be read
                        if xp and required > 0 and xp >= required and not xp_notified then
                            xp_notified = true
                            library:Notify(string.format("Weapon XP reached %d - enough for %s!", required, tostring(cls)), 8)
                        elseif xp and xp < required then
                            xp_notified = false
                        end
                    end
                end
            end)

            -- ---- Shrieker grab (used by the "Shrieker Grab" path action) -------
            -- Knock the nearest shrieker to 0 HP, then press V to pick one up. The
            -- path will NOT advance until a pickup is confirmed (a shrieker becomes
            -- a child of our character, or the one we V'd leaves workspace.Live), or
            -- the time budget (the waypoint's wait time, default 60s) runs out.
            local function shrieker_press_v()
                pcall(function()
                    vim:SendKeyEvent(true, Enum.KeyCode.V, false, game)
                    task.wait(0.06)
                    vim:SendKeyEvent(false, Enum.KeyCode.V, false, game)
                end)
            end
            -- A carried shrieker shows up as a "Grabbing" Accessory on our character
            -- (the body itself is reparented to workspace.Thrown, right on top of us).
            local function is_carrying_shrieker()
                local c = plr.Character
                if not c then return false end
                if FindFirstChild(c, "Grabbing") then return true end
                local hrp = FindFirstChild(c, "HumanoidRootPart")
                local thrown = FindFirstChild(ws, "Thrown")
                if hrp and thrown then
                    for _, m in ipairs(thrown:GetChildren()) do
                        if is_shrieker(m) then
                            local root = monster_root(m)
                            if root and (root.Position - hrp.Position).Magnitude <= 8 then return true end
                        end
                    end
                end
                return false
            end
            local function grab_one_shrieker(max_secs, trigger_cf, home_cf)
                -- Two-phase cycle (this is what actually stops the "chased into a
                -- corner and got ganged up on" problem, not just a retarget timer):
                --   PHASE A (HOLD, 15s): stand at the waypoint's home spot and
                --   attack/V whatever's already within melee range - never walks
                --   toward anything far away during this phase.
                --   PHASE B (GRAB ATTEMPT, 15s): actively go for whichever shrieker
                --   currently has the LOWEST health, chasing/attacking it directly.
                --   If it's not grabbed by the end of that window, go back to
                --   PHASE A and repeat the whole cycle until one is actually
                --   grabbed or the overall time budget (max_secs) runs out.
                max_secs = (max_secs and max_secs >= 15) and max_secs or 120
                local HOLD_SECS = 15
                local GRAB_ATTEMPT_SECS = 15
                local t0, last_v, none_since = os.clock(), 0, nil
                local range = (Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value) or 60

                -- nested (not outer-scope) so this doesn't cost the enclosing XP
                -- Farm closure a register - that closure is already right at
                -- Luau's 200-local ceiling (see BUILD 219/229-236's history)
                -- returns whichever nearby shrieker currently has the LOWEST
                -- health (a 0hp one always wins ties since nothing goes lower)
                local function lowest_health_shrieker(rng)
                    local hrp = local_hrp()
                    local live = FindFirstChild(ws, "Live")
                    if not hrp or not live then return nil end
                    local origin = hrp.Position
                    local best, best_hp
                    for _, m in ipairs(live:GetChildren()) do
                        if m ~= plr.Character and is_shrieker(m) then
                            local root = monster_root(m)
                            if root and (root.Position - origin).Magnitude <= rng then
                                local hum = FindFirstChildOfClass(m, "Humanoid")
                                if hum and (not best_hp or hum.Health < best_hp) then
                                    best_hp = hum.Health
                                    best = m
                                end
                            end
                        end
                    end
                    return best
                end

                local function still_running()
                    return not (shared.is_unloading or not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value))
                        and (os.clock() - t0) < max_secs
                end
                local function attack_toward(root, hrp)
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    pcall(function() hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(root.Position.X, hrp.Position.Y, root.Position.Z)) end)
                    equip_sword()
                    local cps = math.clamp((Options.xpfarm_cps and Options.xpfarm_cps.Value) or 5, 1, 20)
                    for _ = 1, math.max(1, math.floor(cps / 5)) do pcall(function() utility:LeftClick() end) end
                    if (os.clock() - last_v) > 0.3 then last_v = os.clock(); shrieker_press_v() end
                end

                while still_running() do
                    if is_carrying_shrieker() then return true end

                    -- PHASE A: hold at home, attack anything already in melee range
                    if home_cf then bot_move_to(home_cf.Position) end
                    local hold_t0 = os.clock()
                    while still_running() and (os.clock() - hold_t0) < HOLD_SECS do
                        if is_carrying_shrieker() then return true end
                        local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                        local nearby = lowest_health_shrieker(range)
                        local root = nearby and monster_root(nearby)
                        if hrp and root and (root.Position - hrp.Position).Magnitude <= 8 then
                            last_monster_seen = os.clock()
                            attack_toward(root, hrp)
                        elseif trigger_cf and not nearby then
                            -- nothing spawned: dart to the trigger spot then back, to
                            -- spawn shriekers / catch the respawn timer
                            none_since = none_since or os.clock()
                            if (os.clock() - none_since) >= 1 then
                                none_since = nil
                                bot_move_to(trigger_cf.Position)
                                if home_cf then bot_move_to(home_cf.Position) end
                            end
                        end
                        task.wait(0.1)
                    end
                    if is_carrying_shrieker() then return true end

                    -- PHASE B: actively go pick up whichever shrieker has the lowest health
                    local target = lowest_health_shrieker(range)
                    local grab_t0 = os.clock()
                    while target and still_running() and (os.clock() - grab_t0) < GRAB_ATTEMPT_SECS do
                        if is_carrying_shrieker() then return true end
                        if not target.Parent then break end
                        local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                        local root = monster_root(target)
                        if not (hrp and root) then break end
                        last_monster_seen = os.clock()
                        local dist = (root.Position - hrp.Position).Magnitude
                        if dist > 8 then
                            bot_move_to(root.Position - (root.Position - hrp.Position).Unit * 3)
                        else
                            attack_toward(root, hrp)
                        end
                        task.wait(0.1)
                    end
                    -- didn't grab it within the attempt window - loop back to PHASE A
                end
                return false
            end

            -- ---- Sealed Shrieker GRIP (the "Sealed Shrieker Grip" path action) ----
            -- Same idea as the shrieker grab but you GRIP (B) a Sealed Shrieker instead
            -- of carrying it (V). Lock one, knock it down (M1) first since it can't be
            -- gripped while still standing, then spam B until it's gripped (removed from
            -- workspace.Live), or the time budget runs out.
            -- B is a TAP, not a hold (confirmed live - holding it does nothing). Tap it
            -- on a cadence the same way shrieker_press_v() taps V for a regular grab.
            local function grip_one_sealed(max_secs, trigger_cf, home_cf)
                local function tap_b()
                    pcall(function()
                        vim:SendKeyEvent(true, Enum.KeyCode.B, false, game)
                        task.wait(0.06)
                        vim:SendKeyEvent(false, Enum.KeyCode.B, false, game)
                    end)
                end
                max_secs = (max_secs and max_secs >= 15) and max_secs or 120
                local t0, target, none_since, engaged, last_b = os.clock(), nil, nil, false, 0
                local no_target_since = os.clock()
                local function valid(m)
                    if not (m and m.Parent and is_sealed_shrieker(m)) then return false end
                    local r, hrp = monster_root(m), local_hrp()
                    if not (r and hrp) then return false end
                    return (r.Position - hrp.Position).Magnitude <= 80
                end
                local function finish(result)
                    return result
                end
                while (os.clock() - t0) < max_secs do
                    if shared.is_unloading or not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) then return finish(false) end
                    -- once we've been point-blank on a sealed shrieker and it's now gone
                    -- from the world (gripped / seal broken), count the grip as done
                    if engaged and target and not (target.Parent and is_sealed_shrieker(target)) then
                        return finish(true)
                    end
                    if not valid(target) then
                        local range = (Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value) or 60
                        local alive, downed = scan_sealed(range)
                        target = downed or alive   -- lock this one until gripped/gone
                        engaged = false
                    end
                    if target then
                        last_monster_seen = os.clock()
                        no_target_since = os.clock()
                        local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                        local root = monster_root(target)
                        if hrp and root then
                            local dist = (root.Position - hrp.Position).Magnitude
                            if dist > 4 then
                                bot_move_to(root.Position - (root.Position - hrp.Position).Unit * 2)
                            else
                                engaged = true
                                -- once a grip attempt actually lands, the character gets an
                                -- "Executing" accessory and the animation takes ~3s to finish
                                -- (confirmed live via capture) - hold off on M1/B entirely while
                                -- that's active, since re-tapping B (or attacking) mid-animation
                                -- was cancelling the grip before it could complete, which is
                                -- exactly "doesn't hold the grip long enough".
                                if FindFirstChild(plr.Character, "Executing") then
                                    -- let the grip animation play out undisturbed
                                else
                                    hrp.AssemblyLinearVelocity = Vector3.zero
                                    pcall(function() hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(root.Position.X, hrp.Position.Y, root.Position.Z)) end)
                                    equip_sword()
                                    -- confirmed live via capture: attacking (M1) and tapping B are
                                    -- NOT sequential phases - the real grip happens while STILL
                                    -- swinging, with successful grip attempts landing at low-but-
                                    -- nonzero health (captured values like 13, 5, 2.5 - never
                                    -- exactly <= 0). Do both every tick once in range.
                                    local cps = math.clamp((Options.xpfarm_cps and Options.xpfarm_cps.Value) or 5, 1, 20)
                                    for _ = 1, math.max(1, math.floor(cps / 5)) do pcall(function() utility:LeftClick() end) end
                                    if (os.clock() - last_b) > 0.3 then last_b = os.clock(); tap_b() end
                                end
                            end
                        end
                    elseif trigger_cf then
                        none_since = none_since or os.clock()
                        if (os.clock() - none_since) >= 1 then
                            none_since = nil
                            bot_move_to(trigger_cf.Position)
                            if home_cf then bot_move_to(home_cf.Position) end
                        end
                    end
                    -- if NOTHING has been detected at all for a while (not just
                    -- struggling to finish a grip on one we found), stop wasting
                    -- the rest of the time budget here - bail out now so the
                    -- enclosing Repeat (Monster Drop) block's own retry kicks in
                    -- sooner: it walks the Return Points route back to the start
                    -- of this section and tries again (which re-triggers/re-scans
                    -- for a fresh spawn), instead of idly darting at an empty
                    -- trigger spot for the full wait time.
                    if not target and (os.clock() - no_target_since) > 20 then
                        library:Notify("Path: no Sealed Shrieker detected for 20s - going back through the return route to respawn", 5)
                        return finish(false)
                    end
                    task.wait(0.1)
                end
                return finish(false)
            end

            -- Auto-Use Idol of War: equip + activate "Idol of War" tools from the bag,
            -- one after another. Does NOT return-to-menu/respawn (that was the patched
            -- exploit) - just uses them. Stops itself if you end up knocked/dead so it
            -- can't death-loop a permadeath character.
            do
                task.spawn(function()
                    while shared and not shared.is_unloading do
                        if Toggles.xpfarm_auto_idol and Toggles.xpfarm_auto_idol.Value and plr.Character then
                            local char = plr.Character
                            local hum = FindFirstChildOfClass(char, "Humanoid")
                            local backpack = plr:FindFirstChildOfClass("Backpack")
                            -- runs even while gate-holding (in Danger) - using an idol
                            -- just grants points, so we only skip while knocked/dead
                            if hum and hum.Health > 0 and backpack and not cs:HasTag(char, "Knocked") then
                                local idol = FindFirstChild(backpack, "Idol of War")
                                if idol then
                                    local prev = FindFirstChildOfClass(char, "Tool")  -- what you're holding (e.g. the Gate)
                                    pcall(function() hum:EquipTool(idol) end)
                                    task.wait(0.35)
                                    local held = plr.Character and FindFirstChild(plr.Character, "Idol of War")
                                    if held then
                                        pcall(function() if held.Activate then held:Activate() end end)
                                        pcall(function()
                                            vim:SendMouseButtonEvent(0, 0, 0, true, game, 1)
                                            task.wait(0.05)
                                            vim:SendMouseButtonEvent(0, 0, 0, false, game, 1)
                                        end)
                                        task.wait(0.5)
                                    end
                                    -- re-equip the Gate/weapon you were holding so the bot keeps gating
                                    if prev and prev.Parent and plr.Character then pcall(function() hum:EquipTool(prev) end) end
                                end
                            end
                        end
                        task.wait(0.5)
                    end
                end)
            end

            -- forward-declared so the Class Bots tab buttons (created below) can call
            -- the full-bot stage machine, which is defined later in this module.
            local classbot_start_full, classbot_stop_full
            local classbot_full_status_label

            -- ---- Class Bots tab ----------------------------------------------
            -- One-click runner for saved class paths (e.g. Uber Sigil / Ultra
            -- Sigil for the Blademaster edict): load the chosen saved path and
            -- start it, with per-run server safety - skip illusionist servers,
            -- skip moderator servers, and a serverhop-if-player-near distance.
            pcall(function()
                local win = getgenv().XPFARM_WINDOW
                if not (win and win.AddTab) then return end
                local cb = win:AddTab("Class Bots", "sword")
                local g = cb:AddLeftGroupbox("Class Bot")

                g:AddDropdown("classbot_path", {
                    Text = "Class Path",
                    Values = get_saved_xpfarm_paths(),
                    Multi = false,
                    Tooltip = "Pick a saved path to run (e.g. your Uber Sigil / Ultra Sigil path)."
                })
                g:AddButton("classbot_refresh", {
                    Text = "Refresh List",
                    Func = function()
                        if Options.classbot_path then
                            pcall(function() Options.classbot_path:SetValues(get_saved_xpfarm_paths()) end)
                            library:Notify("Class path list refreshed")
                        end
                    end
                })
                g:AddDivider()
                local cb_status = g:AddLabel("classbot_status", { Text = "Idle", DoesWrap = true })
                g:AddButton("classbot_run", {
                    Text = "Run Class Bot",
                    Tooltip = "Loads the selected path and starts it with the server-safety options on the right.",
                    Func = function()
                        local name = (Options.classbot_path and Options.classbot_path.Value) or ""
                        if name == "" then library:Notify("Pick a class path first"); return end
                        if not load_xpfarm_path(name) then library:Notify("Couldn't load '" .. name .. "'"); return end
                        if #xp_path == 0 then library:Notify("That path is empty"); return end
                        -- a genuine fresh start (not a mid-session serverhop resume) - clear any
                        -- leftover Make Potions progress/retry counters AND plain Repeat block
                        -- counts from a PREVIOUS run that got manually stopped, or they'd wrongly
                        -- get credited here (potions stop short; a Repeat could skip laps it
                        -- hasn't actually done yet this run).
                        for idx, s in ipairs(xp_path) do
                            if s.kind == "potion" then
                                pcall(function() mem:RemoveItem("xpfarm_potion_progress_" .. idx) end)
                                pcall(function() mem:RemoveItem("xpfarm_potion_retries_" .. idx) end)
                            elseif s.kind == "repeat_start" and not s.goal_kind then
                                pcall(function() mem:RemoveItem("xpfarm_rep_" .. idx) end)
                            end
                        end
                        if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(true) end
                        pcall(function() cb_status:SetText("Running: " .. name .. "  (" .. #xp_path .. " steps)") end)
                        library:Notify(string.format("Class bot running '%s' (%d steps)", name, #xp_path), 6)
                    end
                })
                g:AddButton("classbot_stop", {
                    Text = "Stop",
                    Func = function()
                        if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(false) end
                        pcall(function() cb_status:SetText("Stopped") end)
                        library:Notify("Class bot stopped")
                    end
                })
                g:AddDivider()
                g:AddButton("classbot_run_druid", {
                    Text = "Run Druid Bot",
                    Tooltip = "One-click: loads the 'druid_combined' saved path and starts it immediately - no need to pick it from the dropdown above. Auto-resumes through every serverhop like any other class path.",
                    Func = function()
                        if not load_xpfarm_path("druid_combined") then library:Notify("Class bot: missing 'druid_combined' saved path", 8); return end
                        if #xp_path == 0 then library:Notify("The 'druid_combined' path is empty"); return end
                        -- fresh start - clear any leftover Make Potions progress/retry counters
                        -- and Repeat block counts from a previous run (see classbot_run above).
                        for idx, s in ipairs(xp_path) do
                            if s.kind == "potion" then
                                pcall(function() mem:RemoveItem("xpfarm_potion_progress_" .. idx) end)
                                pcall(function() mem:RemoveItem("xpfarm_potion_retries_" .. idx) end)
                            elseif s.kind == "repeat_start" and not s.goal_kind then
                                pcall(function() mem:RemoveItem("xpfarm_rep_" .. idx) end)
                            end
                        end
                        if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(true) end
                        pcall(function() cb_status:SetText("Running: druid_combined  (" .. #xp_path .. " steps)") end)
                        library:Notify(string.format("Druid Bot running (%d steps)", #xp_path), 6)
                    end
                })
                g:AddButton("classbot_show_druid_first_point", {
                    Text = "Show Druid Path Start",
                    Tooltip = "Reads the 'druid_combined' saved path from disk and drops a temporary glowing marker at its first waypoint, without loading/starting the path - just to see where it begins.",
                    Func = function()
                        if not (readfile and isfile) then library:Notify("This executor doesn't support readfile", 6); return end
                        local file_path = "HYDROXIDE/xpfarm_paths/druid_combined.json"
                        if not isfile(file_path) then library:Notify("No 'druid_combined' saved path found on disk", 6); return end

                        local ok, data = pcall(function()
                            return Services.HttpService:JSONDecode(readfile(file_path))
                        end)
                        if not ok or type(data) ~= "table" or type(data.steps) ~= "table" then
                            library:Notify("Couldn't read 'druid_combined' - file may be corrupt", 6)
                            return
                        end

                        local first
                        for _, step in ipairs(data.steps) do
                            if step.x and step.y and step.z then first = step; break end
                        end
                        if not first then
                            library:Notify("'druid_combined' has no positioned waypoints", 6)
                            return
                        end

                        local pos = Vector3.new(first.x, first.y, first.z)
                        library:Notify(string.format("Druid path starts at %.0f, %.0f, %.0f", pos.X, pos.Y, pos.Z), 8)

                        pcall(function()
                            local marker = Instance.new("Part")
                            marker.Name = "DruidStartMarker"
                            marker.Shape = Enum.PartType.Ball
                            marker.Size = Vector3.new(4, 4, 4)
                            marker.Position = pos
                            marker.Anchored = true
                            marker.CanCollide = false
                            marker.Material = Enum.Material.Neon
                            marker.Color = Color3.fromRGB(60, 255, 120)
                            marker.Transparency = 0.15
                            marker.Parent = ws

                            local beam_part = Instance.new("Part")
                            beam_part.Name = "DruidStartBeam"
                            beam_part.Size = Vector3.new(1, 300, 1)
                            beam_part.CFrame = CFrame.new(pos + Vector3.new(0, 150, 0))
                            beam_part.Anchored = true
                            beam_part.CanCollide = false
                            beam_part.Material = Enum.Material.Neon
                            beam_part.Color = Color3.fromRGB(60, 255, 120)
                            beam_part.Transparency = 0.6
                            beam_part.Parent = ws

                            game.Debris:AddItem(marker, 20)
                            game.Debris:AddItem(beam_part, 20)
                        end)
                    end
                })

                local gf = cb:AddLeftGroupbox("Blademaster Full Bot")
                classbot_full_status_label = gf:AddLabel("classbot_full_status", { Text = "Idle", DoesWrap = true })
                gf:AddButton("classbot_full_run", {
                    Text = "Run Blademaster Full Bot",
                    Tooltip = "Full auto: farm Ultra Sigil in Gaia, take the boat to Khei, make the Uber Sigil, then join your broadcasting account's server to be killed. Start it while you're in Gaia.",
                    Func = function()
                        if classbot_full_status_label then pcall(function() classbot_full_status_label:SetText("Starting...") end) end
                        if classbot_start_full then classbot_start_full() end
                    end
                })
                gf:AddButton("classbot_full_stop", {
                    Text = "Stop Full Bot",
                    Func = function()
                        if classbot_stop_full then classbot_stop_full() end
                        library:Notify("Full bot stopped")
                    end
                })
                gf:AddToggle("classbot_kick_done", {
                    Text = "Kick When Done (don't join)",
                    Default = (mem:HasItem("classbot_kick_done") and mem:GetItem("classbot_kick_done") == "true"),
                    Tooltip = "When the Uber Sigil is finished, kick the account out of the game instead of joining your other account to be killed.",
                    Callback = function(v) pcall(function() mem:SetItem("classbot_kick_done", v and "true" or "false") end) end
                })
                gf:AddDivider()
                -- seed progress: tell the bot how many of the 20 Evil-Eye kills / 20 shrieker
                -- turn-ins you've ALREADY done by hand, so it only does the rest.
                gf:AddInput("classbot_seed_evil", {
                    Text = "Evil Eyes Already Killed",
                    Default = "0",
                    Numeric = true,
                    Finished = false,
                    Tooltip = "How many of the 20 Evil-Eye kills you've already done. Used as the starting count on the next Run (or click 'Apply Counts Now' to set it while it's running).",
                })
                gf:AddInput("classbot_seed_shrk", {
                    Text = "Shriekers Already Done",
                    Default = "0",
                    Numeric = true,
                    Finished = false,
                    Tooltip = "How many of the 20 shrieker turn-ins you've already done. Used as the starting count on the next Run (or click 'Apply Counts Now' to set it while it's running).",
                })
                gf:AddButton("classbot_apply_counts", {
                    Text = "Apply Counts Now",
                    Tooltip = "Set the bot's CURRENT progress to the two numbers above - use this while the bot is already running. (A fresh Run also starts from these numbers automatically.)",
                    Func = function()
                        local gen = (mem:HasItem("classbot_gen") and mem:GetItem("classbot_gen")) or "0"
                        local ev = math.max(0, math.floor(tonumber(Options.classbot_seed_evil and Options.classbot_seed_evil.Value) or 0))
                        local sh = math.max(0, math.floor(tonumber(Options.classbot_seed_shrk and Options.classbot_seed_shrk.Value) or 0))
                        pcall(function() mem:SetItem("classbot_evil_" .. gen, tostring(ev)) end)
                        pcall(function() mem:SetItem("classbot_shrk_" .. gen, tostring(sh)) end)
                        library:Notify(string.format("Bot progress set: %d/20 Evil Eyes, %d/20 shriekers", ev, sh), 6)
                    end
                })
                gf:AddLabel("classbot_full_help", {
                    Text = "Stages: Gaia (Ultra) -> Khei boat -> Uber -> join. Turn on 'Broadcast My Server' (Multi-Account tab) on the account that will kill it.",
                    DoesWrap = true
                })

                local opt = cb:AddRightGroupbox("Server Safety")
                opt:AddToggle("classbot_skip_illus", {
                    Text = "Skip Illusionist Servers",
                    Default = (mem:HasItem("xpfarm_skip_illus") and mem:GetItem("xpfarm_skip_illus") == "true"),
                    Tooltip = "After a hop, if a player holding 'Observe' is in the new server, hop again before settling.",
                    Callback = function(v)
                        pcall(function() mem:SetItem("xpfarm_skip_illus", v and "true" or "false") end)
                        if Toggles.xpfarm_skip_illus and Toggles.xpfarm_skip_illus.Value ~= v then
                            pcall(function() Toggles.xpfarm_skip_illus:SetValue(v) end)
                        end
                    end
                })
                opt:AddToggle("classbot_skip_mod", {
                    Text = "Skip Moderator Servers",
                    Default = (mem:HasItem("xpfarm_skip_mod") and mem:GetItem("xpfarm_skip_mod") == "true"),
                    Tooltip = "After a hop, if a Rogue Lineage moderator (staff group / mod list) is in the server, hop again before settling.",
                    Callback = function(v)
                        pcall(function() mem:SetItem("xpfarm_skip_mod", v and "true" or "false") end)
                    end
                })
                opt:AddToggle("classbot_hop_near", {
                    Text = "Serverhop If Player Near",
                    Default = (Toggles.xpfarm_hop_near and Toggles.xpfarm_hop_near.Value) or false,
                    Tooltip = "Serverhop (and resume the path) when another player comes within the distance below.",
                    Callback = function(v)
                        if Toggles.xpfarm_hop_near then pcall(function() Toggles.xpfarm_hop_near:SetValue(v) end) end
                    end
                })
                opt:AddSlider("classbot_hop_dist", {
                    Text = "Serverhop Distance",
                    Default = (Options.xpfarm_hop_near_dist and Options.xpfarm_hop_near_dist.Value) or 150,
                    Min = 10, Max = 2000, Rounding = 0, Suffix = " studs",
                    Tooltip = "How close a player has to get before the bot serverhops away.",
                    Callback = function(v)
                        if Options.xpfarm_hop_near_dist then pcall(function() Options.xpfarm_hop_near_dist:SetValue(v) end) end
                    end
                })
                opt:AddSlider("classbot_min_players", {
                    Text = "Min Player Count",
                    Default = (Options.xpfarm_min_player_count and Options.xpfarm_min_player_count.Value) or 0,
                    Min = 0, Max = 23, Rounding = 0,
                    Tooltip = "Only hop into servers with at least this many players (0 = disabled). Restricted/isolated servers are usually only 1-5 players, so ~8 keeps every hop out of them.",
                    Callback = function(v)
                        if Options.xpfarm_min_player_count then pcall(function() Options.xpfarm_min_player_count:SetValue(v) end) end
                    end
                })
                opt:AddDropdown("xpfarm_emergency_items", {
                    Text = "Emergency Serverhop Items",
                    Values = { "Perflora", "Pebble", "Celeritas", "Fimbulvetr" },
                    Multi = true,
                    Default = {},
                    Tooltip = "Instantly serverhop if another player is HOLDING any of these items (only while the bot is running). Stays through every hop.",
                    Callback = function(v)
                        pcall(function() mem:SetItem("xpfarm_emergency_items", Services.HttpService:JSONEncode(v or {})) end)
                    end
                })
                pcall(function()
                    if mem:HasItem("xpfarm_emergency_items") and Options.xpfarm_emergency_items then
                        local ok, t = pcall(function() return Services.HttpService:JSONDecode(mem:GetItem("xpfarm_emergency_items")) end)
                        if ok and type(t) == "table" then Options.xpfarm_emergency_items:SetValue(t) end
                    end
                end)
            end)

            -- Carbine Multi-Account: the alt (already in the target server) broadcasts
            -- its PlaceId+JobId to a shared executor file; the bot account reads it and
            -- teleports into that exact server (handles a different world via PlaceId).
            -- Both accounts must run on the same PC / same executor (shared files).
            -- Own dedicated tab (same pattern as "XP Farm" and "Class Bots") instead of
            -- being crammed into Misc, since this section grew a lot (Alt Support Paths,
            -- the auto pipeline, job ID tools, etc.) - falls back to Misc if the window
            -- reference isn't available for some reason.
            pcall(function()
                local win = getgenv().XPFARM_WINDOW
                local tab
                if win and win.AddTab then
                    tab = win:AddTab("Multi-Account", "users")
                elseif library.Tabs and library.Tabs.Misc then
                    tab = library.Tabs.Misc
                else
                    return
                end
                local g_ma = tab:AddLeftGroupbox("Carbine Multi-Account")
                local FEED_FILE = "Carbine/feed_server.txt"
                g_ma:AddToggle("xpfarm_broadcast_server", {
                    Text = "Broadcast My Server (run on alt)",
                    Default = false,
                    Tooltip = "Turn on with the alt that's already in the target server - writes this server's id to a shared file so the bot account can join it."
                })
                task.spawn(function()
                    while shared and not shared.is_unloading do
                        if Toggles.xpfarm_broadcast_server and Toggles.xpfarm_broadcast_server.Value then
                            pcall(function()
                                if writefile then
                                    if makefolder and isfolder and not isfolder("Carbine") then makefolder("Carbine") end
                                    writefile(FEED_FILE, tostring(game.PlaceId) .. "," .. tostring(game.JobId))
                                end
                            end)
                        end
                        task.wait(3)
                    end
                end)
                g_ma:AddButton("xpfarm_join_other", {
                    Text = "Join Other Account's Server",
                    Tooltip = "Run on the BOT account - reads the alt's broadcast and teleports into that exact server.",
                    Func = function()
                        if not (readfile and isfile and isfile(FEED_FILE)) then library:Notify("No broadcast file - turn on Broadcast on the alt first"); return end
                        local ok, data = pcall(function() return readfile(FEED_FILE) end)
                        if not ok or not data or data == "" then library:Notify("Broadcast file empty - is the alt broadcasting?"); return end
                        local pid, jid = data:match("^(%d+),(.+)$")
                        pid = tonumber(pid)
                        if not pid or not jid or jid == "" then library:Notify("Broadcast data invalid"); return end
                        if jid == tostring(game.JobId) then library:Notify("Already in the alt's server"); return end
                        library:Notify("Joining the other account's server...", 6)
                        pcall(function()
                            local jr = rps.Requests and rps.Requests:FindFirstChild("JoinPublicServer")
                            if jr then jr:FireServer(jid) else Services.TeleportService:TeleportToPlaceInstance(pid, jid, plr) end
                        end)
                    end
                })

                -- --- Job ID tools: read this server's Job ID + join a server by Job ID ---
                g_ma:AddDivider()
                g_ma:AddLabel("classbot_jobid_lbl", {
                    Text = "Place: " .. tostring(game.PlaceId) .. "\nJob: " .. tostring(game.JobId),
                    DoesWrap = true
                })
                g_ma:AddButton("classbot_copy_jobid", {
                    Text = "Copy Job ID",
                    Tooltip = "Copies this server's Job ID to your clipboard.",
                    Func = function()
                        if setclipboard then setclipboard(tostring(game.JobId)); library:Notify("Job ID copied") else library:Notify("setclipboard not supported by your executor") end
                    end
                })
                g_ma:AddButton("classbot_copy_placejob", {
                    Text = "Copy Place+Job",
                    Tooltip = "Copies 'placeId,jobId' - paste into the Join By Job ID box below or the join script.",
                    Func = function()
                        if setclipboard then setclipboard(tostring(game.PlaceId) .. "," .. tostring(game.JobId)); library:Notify("Place+Job copied") else library:Notify("setclipboard not supported by your executor") end
                    end
                })
                g_ma:AddInput("classbot_join_jobid", {
                    Text = "Host Place,Job",
                    Default = "",
                    Placeholder = "placeId,jobId  (or just the jobId)"
                })
                g_ma:AddButton("classbot_join_byid", {
                    Text = "Join By Job ID",
                    Tooltip = "Teleport THIS account into the server with the pasted Place,Job (or just a Job ID, using the current world).",
                    Func = function()
                        local v = (Options.classbot_join_jobid and Options.classbot_join_jobid.Value) or ""
                        v = v:gsub("%s", "")
                        if v == "" then library:Notify("Paste a Job ID (or placeId,jobId) first"); return end
                        local pid, jid = v:match("^(%d+),(.+)$")
                        if pid then pid = tonumber(pid) else pid = game.PlaceId; jid = v end
                        if not jid or jid == "" then library:Notify("Invalid Job ID"); return end
                        if jid == tostring(game.JobId) then library:Notify("That's already this server"); return end
                        library:Notify("Joining " .. tostring(pid) .. " / " .. jid, 6)
                        pcall(function()
                            local jr = rps.Requests and rps.Requests:FindFirstChild("JoinPublicServer")
                            if jr then jr:FireServer(jid) else Services.TeleportService:TeleportToPlaceInstance(pid, jid, plr) end
                        end)
                    end
                })

                -- --- Known Servers: list live job ids from ReplicatedStorage.ServerInfo ------
                -- Same registry get_oldest_server/get_newest_server read above - the game
                -- replicates every active server's JobId + player count there. This is the
                -- only place that data exists for non-root places like Gaia (5208655184);
                -- Roblox's public games.roblox.com servers/Public REST API returns an empty
                -- list for them, so an external tool can't discover these job ids at all.
                local known_server_ids = {}
                local known_server_display = {}

                local function refresh_known_servers()
                    known_server_ids = {}
                    known_server_display = {}

                    local serverInfo = FindFirstChild(rps, "ServerInfo")
                    if not serverInfo then
                        library:Notify("ServerInfo not found - are you in a live server?", 4)
                        return
                    end

                    local entries = {}
                    for _, serverFolder in ipairs(serverInfo:GetChildren()) do
                        local jobId = serverFolder.Name
                        if jobId ~= tostring(game.JobId) then
                            local playersValue = FindFirstChild(serverFolder, "Players")
                            local playerCount = 0
                            if playersValue and playersValue:IsA("StringValue") then
                                local ok, playerData = pcall(function()
                                    return Services.HttpService:JSONDecode(playersValue.Value)
                                end)
                                if ok and type(playerData) == "table" then
                                    playerCount = #playerData
                                end
                            end
                            table.insert(entries, {jobId = jobId, players = playerCount})
                        end
                    end

                    table.sort(entries, function(a, b) return a.players < b.players end)

                    for _, entry in ipairs(entries) do
                        local label = string.format("%dp - %s", entry.players, entry.jobId)
                        table.insert(known_server_display, label)
                        known_server_ids[label] = entry.jobId
                    end

                    if Options.classbot_known_servers then
                        Options.classbot_known_servers:SetValues(known_server_display)
                        if #known_server_display > 0 then
                            Options.classbot_known_servers:SetValue(known_server_display[1])
                        end
                    end

                    library:Notify(string.format("Found %d known server(s)", #known_server_display), 3)
                end

                g_ma:AddDivider()
                g_ma:AddButton("classbot_refresh_known", {
                    Text = "Refresh Known Servers",
                    Tooltip = "Scans ReplicatedStorage.ServerInfo for other live servers of THIS place - works for Gaia/Khei even though Roblox's public API won't list them.",
                    Func = refresh_known_servers
                })
                g_ma:AddDropdown("classbot_known_servers", {
                    Text = "Known Servers (lowest pop first)",
                    Values = {},
                    Multi = false,
                    Callback = function() end
                })
                g_ma:AddButton("classbot_copy_known", {
                    Text = "Copy Job ID",
                    Tooltip = "Copies just the raw Job ID of the selected known server.",
                    Func = function()
                        local label = Options.classbot_known_servers and Options.classbot_known_servers.Value
                        local jobId = label and known_server_ids[label]
                        if not jobId then library:Notify("Refresh and pick a server first", 3); return end
                        if setclipboard then setclipboard(jobId); library:Notify("Job ID copied: " .. jobId) else library:Notify("setclipboard not supported by your executor") end
                    end
                })
                g_ma:AddButton("classbot_join_known", {
                    Text = "Join Selected Known Server",
                    DoubleClick = true,
                    Func = function()
                        local label = Options.classbot_known_servers and Options.classbot_known_servers.Value
                        local jobId = label and known_server_ids[label]
                        if not jobId then library:Notify("Refresh and pick a server first", 3); return end
                        library:Notify("Joining " .. jobId, 4)
                        pcall(function()
                            local jr = rps.Requests and rps.Requests:FindFirstChild("JoinPublicServer")
                            if jr then jr:FireServer(jobId) else Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, jobId, plr) end
                        end)
                    end
                })

                -- --- Alt Support: drop silver + sell trinkets (GUI-driven, no remotes) ----
                -- Both confirmed by capturing the actual GUI paths live (not guessed):
                --   Silver drop: click CurrencyGui.Silver -> set DropFrame.MoneyDrop -> click DropFrame.Submit
                --   Merchant sell: DialogueGui.DialogueFrame.Choices has a Frame per choice, named
                --   after its text, holding a TextButton - click "Trinkets." then "It's a deal." to
                --   confirm, repeat until nothing left to sell, then click "Bye".
                -- (Defined here, inside this closure, so they don't add to the outer function's
                -- 200-local cap - they're only used by the two buttons below anyway.)
                local function click_dialogue_choice(text_substr)
                    local gui = FindFirstChild(plr, "PlayerGui")
                    local dgui = gui and FindFirstChild(gui, "DialogueGui")
                    local frame = dgui and FindFirstChild(dgui, "DialogueFrame")
                    local choices = frame and FindFirstChild(frame, "Choices")
                    if not choices then return false end
                    local want = text_substr:lower()
                    for _, opt in ipairs(choices:GetChildren()) do
                        if opt.Name:lower():find(want, 1, true) then
                            local btn = FindFirstChildOfClass(opt, "TextButton") or FindFirstChild(opt, "TextButton")
                            if btn then
                                pcall(function() firesignal(btn.MouseButton1Click) end)
                                return true
                            end
                        end
                    end
                    return false
                end

                local function drop_silver(amount)
                    amount = math.floor(tonumber(amount) or 0)
                    if amount <= 0 then return false end
                    local gui = FindFirstChild(plr, "PlayerGui")
                    local cur = gui and FindFirstChild(gui, "CurrencyGui")
                    local silver_btn = cur and FindFirstChild(cur, "Silver")
                    if not silver_btn then library:Notify("Alt Support: CurrencyGui.Silver not found"); return false end
                    pcall(function() firesignal(silver_btn.MouseButton1Click) end)
                    task.wait(0.4)
                    local frame = cur and FindFirstChild(cur, "DropFrame")
                    local box = frame and FindFirstChild(frame, "MoneyDrop")
                    local submit = frame and FindFirstChild(frame, "Submit")
                    if not (box and submit) then library:Notify("Alt Support: drop frame not found"); return false end
                    pcall(function() box.Text = tostring(amount) end)
                    pcall(function() firesignal(box.FocusLost, true) end)
                    task.wait(0.3)
                    pcall(function() firesignal(submit.MouseButton1Click) end)
                    task.wait(0.4)
                    library:Notify("Alt Support: dropped " .. amount .. " silver", 5)
                    return true
                end

                -- Opens dialogue with the nearest NPC matching `name` WITHOUT the auto-answer
                -- hook (talk_to_nearest_npc always picks choices[1], which would skip past the
                -- Trinkets./deal choices before we can click them) - just gets us into dialogue,
                -- then click_dialogue_choice drives it from there.
                local function open_dialogue_with(name, timeout)
                    local hrp = local_hrp()
                    local npcs_folder = FindFirstChild(ws, "NPCs")
                    if not hrp or not npcs_folder then return false end
                    local want = name and name ~= "" and name:lower() or nil
                    local nearest, nearest_pos, ndist
                    for _, npc in ipairs(npcs_folder:GetChildren()) do
                        local nhrp = FindFirstChild(npc, "HumanoidRootPart")
                        if nhrp and FindFirstChildWhichIsA(npc, "ClickDetector", true) then
                            if not want or npc.Name:lower():find(want, 1, true) then
                                local d = (nhrp.Position - hrp.Position).Magnitude
                                if not ndist or d < ndist then ndist = d; nearest = npc; nearest_pos = nhrp.Position end
                            end
                        end
                    end
                    if not nearest then library:Notify("Alt Support: no matching NPC nearby"); return false end
                    if ndist and ndist > 12 then bot_move_to(nearest_pos) end
                    local cd = FindFirstChildWhichIsA(nearest, "ClickDetector", true)
                    local t0 = os.clock()
                    while os.clock() - t0 < (timeout or 5) do
                        if cd then pcall(function() fireclickdetector(cd) end) end
                        if in_dialogue() then return true end
                        task.wait(0.3)
                    end
                    library:Notify("Alt Support: couldn't open dialogue with " .. nearest.Name)
                    return false
                end

                -- Generic bulk-sell: EACH category gets its own full dialogue cycle - open,
                -- ask "Can I sell in bulk?", click the category -> "It's a deal." repeatedly
                -- until that category's out, then Bye - before moving to the NEXT category
                -- with a fresh open. Merchants with multiple sellable categories (the
                -- Antiquarian: Scrolls, then separately Gemstones) need this rather than
                -- staying in one continuous conversation. Used for both the trinket
                -- merchant (just Trinkets) and the Antiquarian.
                local function sell_categories_to_merchant(npc_name, categories)
                    local sold_any = false
                    for _, cat in ipairs(categories) do
                        if not open_dialogue_with(npc_name, 6) then break end
                        task.wait(0.5)
                        click_dialogue_choice("bulk")
                        for _ = 1, 40 do   -- safety cap on rounds, not item count
                            task.wait(0.6)
                            if not click_dialogue_choice(cat) then break end
                            task.wait(0.6)
                            if not click_dialogue_choice("deal") then break end
                            sold_any = true
                            task.wait(0.6)
                        end
                        task.wait(0.3)
                        click_dialogue_choice("Bye")
                        task.wait(0.5)
                    end
                    library:Notify(sold_any and "Alt Support: items sold" or "Alt Support: nothing to sell", 5)
                    return sold_any
                end

                local function sell_trinkets_to_merchant(npc_name)
                    return sell_categories_to_merchant(npc_name, { "Trinkets" })
                end

                local function sell_to_antiquarian()
                    return sell_categories_to_merchant("Antiquarian", { "Scroll", "Gemstone" })
                end

                -- Best-effort silver reader: try the common leaderstats.Silver pattern first,
                -- fall back to reading the number off the currency GUI itself. Needs live
                -- confirmation like everything else built from a guess rather than a capture.
                local function read_silver()
                    local ls = FindFirstChild(plr, "leaderstats")
                    local sv = ls and FindFirstChild(ls, "Silver")
                    if sv and sv.Value ~= nil then return tonumber(sv.Value) end
                    local gui = FindFirstChild(plr, "PlayerGui")
                    local cur = gui and FindFirstChild(gui, "CurrencyGui")
                    local btn = cur and FindFirstChild(cur, "Silver")
                    if btn then
                        for _, d in ipairs(btn:GetDescendants()) do
                            if d:IsA("TextLabel") then
                                -- gsub returns (string, count) - passing both straight into
                                -- tonumber() makes count look like a "base" argument and
                                -- crashes with "base out of range". Isolate to one value first.
                                local digits = (d.Text or ""):gsub("[^%d]", "")
                                local n = tonumber(digits)
                                if n then return n end
                            end
                        end
                    end
                    return nil
                end

                -- ---- Alt Support Paths: TWO independent waypoint paths (dense Move+Wait
                -- points, walked with bot_move_to like every other path in Carbine - never
                -- one long jump, so no AA-gun risk), each with its own special-action
                -- waypoints:
                --   Blademaster Path: runs on the account that just died and respawned in
                --   Gaia. Typically ends with a separate "Go To Inn" + "Wait For Silver"
                --   tail (their own distinct kinds, so you can drop them anywhere - e.g. at
                --   the very end - without them being confused for ordinary movement points).
                --   Trinket Farmer Path: runs on the account delivering silver, after it
                --   joins the Blademaster's server. Typically ends at "Drop Silver Here".
                local ALTPATH_FILES = {
                    blademaster = "Carbine/altpath_blademaster.json",
                    trinket = "Carbine/altpath_trinket.json",
                }
                local altpaths = { blademaster = {}, trinket = {} }

                local function altpath_key()
                    return (Options.altpath_target and Options.altpath_target.Value == "Trinket Farmer Path") and "trinket" or "blademaster"
                end

                local function altpath_save(key)
                    key = key or altpath_key()
                    if not writefile then library:Notify("writefile not supported"); return end
                    local steps = {}
                    for _, s in ipairs(altpaths[key]) do
                        if s.cf then
                            local p = s.cf.Position
                            table.insert(steps, { kind = s.kind, x = p.X, y = p.Y, z = p.Z, secs = s.secs, inn = s.inn })
                        else
                            table.insert(steps, { kind = s.kind, secs = s.secs, inn = s.inn })
                        end
                    end
                    pcall(function()
                        if makefolder and isfolder and not isfolder("Carbine") then makefolder("Carbine") end
                        writefile(ALTPATH_FILES[key], Services.HttpService:JSONEncode(steps))
                    end)
                    library:Notify(string.format("Alt Support Path (%s): saved (%d waypoints)", key, #altpaths[key]), 5)
                end

                local function altpath_load(key)
                    key = key or altpath_key()
                    if not (readfile and isfile and isfile(ALTPATH_FILES[key])) then
                        library:Notify(string.format("Alt Support Path (%s): no saved path yet", key)); return
                    end
                    local ok, data = pcall(function() return Services.HttpService:JSONDecode(readfile(ALTPATH_FILES[key])) end)
                    if not ok or type(data) ~= "table" then library:Notify("Alt Support Path: failed to load"); return end
                    local loaded = {}
                    for _, s in ipairs(data) do
                        if s.x then
                            table.insert(loaded, { kind = s.kind, cf = CFrame.new(s.x, s.y, s.z), secs = s.secs, inn = s.inn })
                        else
                            table.insert(loaded, { kind = s.kind, secs = s.secs, inn = s.inn })
                        end
                    end
                    altpaths[key] = loaded
                    library:Notify(string.format("Alt Support Path (%s): loaded (%d waypoints)", key, #loaded), 5)
                end

                -- Learned real landing spots per gate destination name, so repeat gates to
                -- the same place can supply a genuinely correct "expected destination" to
                -- the real bot's own backfire check instead of a stale/fake one - fixes the
                -- false BACKFIRE without the nil-position fall-through risk. Named
                -- destinations land at the same spot every time, so this only needs to
                -- "learn" once per destination per session.
                local gate_dest_cache = {}

                -- Walks the given path from an optional start index. drop_silver reads the
                -- amount from whatever help request is currently pending. wait_silver polls
                -- this account's OWN silver until it reaches the target amount, then starts
                -- the Blademaster full bot fresh (classbot_start_full) and stops the path.
                local function run_altpath(key, from_idx)
                    key = key or altpath_key()
                    local path = altpaths[key]
                    if #path == 0 then library:Notify(string.format("Alt Support Path (%s): nothing saved - build it first", key)); return false end
                    library:Notify(string.format("Alt Support Path (%s): running %d waypoints from #%d", key, #path, from_idx or 1), 4)
                    for i = (from_idx or 1), #path do
                        local step = path[i]
                        if shared and shared.is_unloading then return false end
                        local ok, err = pcall(function()
                        -- returning "stop" here ends the WHOLE path (used by wait_silver,
                        -- which is a terminal step) - a bare `return` only exits this
                        -- inner pcall, not run_altpath, so it must be an explicit signal.
                        if step.kind == "point" and step.cf then
                            -- bot_move_to REFUSES anything over 1500 studs and returns false
                            -- instantly (no tween at all) - if we don't check that, the path
                            -- just races through a chain of no-op waypoints in a fraction of
                            -- a second, looking like it "teleported through" everything. Stop
                            -- here instead and say exactly which waypoint and how far.
                            local moved = bot_move_to(step.cf.Position)
                            if not moved then
                                error(string.format("move refused (too far from where you are - add waypoints closer to your actual spawn/current spot)"))
                            end
                        elseif step.kind == "sell_trinkets" then
                            sell_trinkets_to_merchant("")
                        elseif step.kind == "sell_antiquarian" then
                            sell_to_antiquarian()
                        elseif step.kind == "drop_silver" then
                            local amt = tonumber(Options.altsupport_silver_amount and Options.altsupport_silver_amount.Value) or 735
                            local pending = mem:HasItem("altsupport_pending") and mem:GetItem("altsupport_pending")
                            if pending and pending ~= "" then
                                local _, _, _, _, _, _, amt_s = pending:match("^(%d+)|(.-)|(.-)|(.-)|(.-)|(.-)|(.-)|%d+$")
                                if amt_s then amt = tonumber(amt_s) or amt end
                            end
                            drop_silver(amt)
                        elseif step.kind == "autobag_on" then
                            if Toggles.auto_bag then pcall(function() Toggles.auto_bag:SetValue(true) end) end
                        elseif step.kind == "autobag_off" then
                            if Toggles.auto_bag then pcall(function() Toggles.auto_bag:SetValue(false) end) end
                        elseif step.kind == "goto_inn" then
                            -- a flat 1s wait wasn't nearly enough for the actual respawn to
                            -- finish - wait for a genuinely NEW character with a HumanoidRootPart
                            -- to exist (same confirmation pattern the XP Farm's own inn step
                            -- uses), then a little extra settle time before continuing.
                            local old_char = plr.Character
                            pcall(function() rent_at_inn_nearby(step.inn or "Wayside Inn") end)
                            local it0 = os.clock()
                            repeat task.wait(0.25)
                            until (shared and shared.is_unloading)
                                or (plr.Character and plr.Character ~= old_char and FindFirstChild(plr.Character, "HumanoidRootPart"))
                                or (os.clock() - it0 > 25)
                            task.wait(1.5)
                        elseif step.kind == "gate" then
                            -- Calling Gate() standalone never actually clicked, no matter what
                            -- preconditions we satisfied - it only works reliably from INSIDE
                            -- the real Trinket Bot's own path execution (ExecutePath), which is
                            -- proven working for SERVER_LOOT. So instead of calling Gate()
                            -- ourselves, do exactly what "Add Gate" + "Start Path" does for
                            -- real: temporarily swap in a path containing this gate, run it
                            -- through the REAL ExecutePath, then restore your actual path_points.
                            local tb = cheat_client.trinket_bot
                            local ep = cheat_client.Carbine_ExecutePath
                            local dest_key0 = step.inn or "Deepforest 5"
                            local hrp0 = local_hrp()
                            if hrp0 and gate_dest_cache[dest_key0]
                                and (hrp0.Position - gate_dest_cache[dest_key0]).Magnitude < 500 then
                                -- already at (or very near) this destination from a previous
                                -- gate - the real teleport always lands correctly even when
                                -- Gate() falsely reports a backfire, so re-gating here would
                                -- just be wasted mana/time chasing a message, not a real problem.
                                library:Notify("Alt Support: already at " .. tostring(step.inn) .. " - skipping the gate", 4)
                            elseif not (tb and ep) then
                                library:Notify("Alt Support: Trinket Bot not ready - can't gate to " .. tostring(step.inn), 6)
                            else
                                local hrp = local_hrp()
                                local pos = hrp and hrp.Position or Vector3.new(0, 0, 0)
                                local saved_points = tb.path_points
                                local saved_running = tb.path_running
                                tb.path_running = false   -- ExecutePath refuses to start if already "running"
                                -- CRITICAL: the real bot's own gate-retry logic SERVERHOPS after
                                -- 3 failed attempts by default - fine for normal looting (just
                                -- move on), catastrophic here (the trinket farmer would abandon
                                -- the Blademaster's server mid-delivery). Toggles.StayInServer is
                                -- the real, existing toggle that logic already checks to stay and
                                -- retry instead of hopping - force it on for the gate, exactly
                                -- like flipping the real switch, then restore it after.
                                local prev_stay = Toggles.StayInServer and Toggles.StayInServer.Value
                                if Toggles.StayInServer and not prev_stay then
                                    pcall(function() Toggles.StayInServer:SetValue(true) end)
                                end
                                -- a gate point that's the LAST point in path_points gets
                                -- explicitly SKIPPED by the real bot's own logic ("Gate %d is
                                -- the last point - skipping") - a single-point path always hit
                                -- that. Add a trailing no-op point so the gate is never last.
                                -- Its position, in priority order: (1) the NEXT waypoint in
                                -- YOUR OWN path, if you recorded a Move+Wait point there while
                                -- actually standing at the real destination - exactly how the
                                -- real bot's own paths are built (gate point, then the next
                                -- point recorded after arriving) - correct from the very first
                                -- gate, no learning needed; (2) a previously-observed landing
                                -- spot for this destination if we've gated here before this
                                -- session; (3) the pre-gate spot as a last resort (may
                                -- false-backfire once, but never a nil/unsafe position - BUILD
                                -- 146 learned that lesson the hard way, a character fell
                                -- through the floor).
                                local dest_key = step.inn or "Deepforest 5"
                                local next_step = path[i + 1]
                                local dummy_pos = (next_step and next_step.kind == "point" and next_step.cf and next_step.cf.Position)
                                    or gate_dest_cache[dest_key] or pos
                                tb.path_points = {
                                    {
                                        position = pos,
                                        wait_for_trinket = false,
                                        wait_time = 0,
                                        is_gate_point = true,
                                        gate_location = dest_key,
                                    },
                                    {
                                        position = dummy_pos,
                                        wait_for_trinket = false,
                                        wait_time = 0,
                                    }
                                }
                                library:Notify("Alt Support: gating to " .. tostring(step.inn) .. " (via the real Trinket Bot path runner)", 5)
                                pcall(function() ep(true) end)   -- test_mode: no looping - blocks until this pass ends
                                tb.path_points = saved_points
                                tb.path_running = saved_running
                                if Toggles.StayInServer and not prev_stay then
                                    pcall(function() Toggles.StayInServer:SetValue(false) end)
                                end
                                -- a real teleport just happened - confirm the character has
                                -- actually moved (not just that ep() returned) before letting
                                -- the path continue, or the very next waypoint's distance gets
                                -- measured from the OLD pre-gate position and looks thousands
                                -- of studs away even though the gate genuinely worked.
                                local gt0 = os.clock()
                                local moved = false
                                while (os.clock() - gt0) < 15 do
                                    local nhrp = local_hrp()
                                    if nhrp and (nhrp.Position - pos).Magnitude > 100 then
                                        moved = true
                                        gate_dest_cache[dest_key] = nhrp.Position   -- learned for next time
                                        break
                                    end
                                    task.wait(0.25)
                                end
                                task.wait(1)
                                -- basic fall/void safety net: if something put the character
                                -- way below where solid ground normally is, stop this path
                                -- immediately instead of continuing to try to walk more
                                -- waypoints while off the map.
                                local fhrp = local_hrp()
                                if fhrp and fhrp.Position.Y < -200 then
                                    library:Notify("Alt Support: character seems to have fallen (Y=" .. tostring(math.floor(fhrp.Position.Y)) .. ") - stopping this path, please check manually", 10)
                                    error("stopped after gate - character below Y=-200 (fell through the map)")
                                end
                            end
                            task.wait(1)
                        elseif step.kind == "wait_silver" then
                            local target = tonumber(Options.altsupport_silver_amount and Options.altsupport_silver_amount.Value) or 735
                            library:Notify(string.format("Alt Support: waiting for %d silver...", target), 6)
                            local t0 = os.clock()
                            while shared and not shared.is_unloading and (os.clock() - t0) < 1800 do
                                local sv = read_silver()
                                if sv and sv >= target then
                                    pcall(function() mem:SetItem("altsupport_funded", "true") end)   -- one-time fund, never re-check
                                    library:Notify(string.format("Alt Support: %d silver received - starting the Blademaster bot", sv), 8)
                                    classbot_start_full()
                                    return "stop"   -- path ends here; the full bot takes over
                                end
                                task.wait(3)
                            end
                            return "stop"   -- timed out waiting - nothing left to do either way
                        elseif step.kind == "wait" then
                            task.wait(step.secs or 3)
                        end
                        end)   -- end of per-step pcall
                        if not ok then
                            library:Notify(string.format("Alt Support Path (%s): waypoint #%d (%s) errored - %s", key, i, tostring(step.kind), tostring(err)), 8)
                        elseif err == "stop" then
                            return true
                        end
                        task.wait(0.1)
                    end
                    return true
                end

                g_ma:AddDivider()
                g_ma:AddLabel("altpath_lbl", { Text = "Alt Support Paths (two separate paths - Blademaster and Trinket Farmer)", DoesWrap = true })
                g_ma:AddDropdown("altpath_target", {
                    Values = { "Blademaster Path", "Trinket Farmer Path" },
                    Default = 1, Multi = false, Text = "Editing Path"
                })
                g_ma:AddDropdown("altpath_action", {
                    Values = { "Move + Wait", "Sell Trinkets Here", "Sell To Antiquarian", "Drop Silver Here", "Auto Bag On", "Auto Bag Off", "Go To Inn", "Gate", "Wait For Silver", "Wait" },
                    Default = 1, Multi = false, Text = "Waypoint Action"
                })
                g_ma:AddInput("altpath_inn_name", {
                    Text = "Inn Name (for Go To Inn)",
                    Default = "Wayside Inn",
                    Placeholder = "e.g. Wayside Inn"
                })
                g_ma:AddInput("altpath_gate_location", {
                    Text = "Gate Location (for Gate)",
                    Default = "Deepforest 5",
                    Placeholder = "e.g. Deepforest 5, Tundra 7"
                })
                g_ma:AddInput("altpath_wait_secs", {
                    Text = "Wait Seconds (for Wait action)",
                    Default = "3",
                    Numeric = true
                })
                g_ma:AddButton("altpath_add", {
                    Text = "Add Waypoint",
                    Tooltip = "Adds the selected action to the path currently selected in Editing Path, at your current spot for Move + Wait.",
                    Func = function()
                        local key = altpath_key()
                        local path = altpaths[key]
                        local action = Options.altpath_action and Options.altpath_action.Value or "Move + Wait"
                        if action == "Sell Trinkets Here" then
                            table.insert(path, { kind = "sell_trinkets" })
                        elseif action == "Sell To Antiquarian" then
                            table.insert(path, { kind = "sell_antiquarian" })
                        elseif action == "Drop Silver Here" then
                            table.insert(path, { kind = "drop_silver" })
                        elseif action == "Auto Bag On" then
                            table.insert(path, { kind = "autobag_on" })
                        elseif action == "Auto Bag Off" then
                            table.insert(path, { kind = "autobag_off" })
                        elseif action == "Go To Inn" then
                            local inn = (Options.altpath_inn_name and Options.altpath_inn_name.Value) or "Wayside Inn"
                            table.insert(path, { kind = "goto_inn", inn = inn })
                        elseif action == "Gate" then
                            local loc = (Options.altpath_gate_location and Options.altpath_gate_location.Value) or "Deepforest 5"
                            table.insert(path, { kind = "gate", inn = loc })
                        elseif action == "Wait For Silver" then
                            table.insert(path, { kind = "wait_silver" })
                        elseif action == "Wait" then
                            local secs = tonumber(Options.altpath_wait_secs and Options.altpath_wait_secs.Value) or 3
                            table.insert(path, { kind = "wait", secs = secs })
                        else
                            local hrp = local_hrp()
                            if not hrp then library:Notify("Character not found"); return end
                            table.insert(path, { kind = "point", cf = hrp.CFrame })
                        end
                        library:Notify(string.format("Alt Support Path (%s): added %s (#%d)", key, action, #path))
                    end
                })
                g_ma:AddButton("altpath_remove_last", {
                    Text = "Remove Last Waypoint",
                    Func = function()
                        local key = altpath_key()
                        local path = altpaths[key]
                        if #path == 0 then library:Notify("Path is empty"); return end
                        table.remove(path)
                        library:Notify(string.format("Removed last - %d left", #path))
                    end
                })
                g_ma:AddButton("altpath_clear", {
                    Text = "New Path (clear selected)",
                    Func = function()
                        local key = altpath_key()
                        altpaths[key] = {}
                        library:Notify(string.format("Alt Support Path (%s) cleared", key))
                    end
                })
                g_ma:AddButton("altpath_save", { Text = "Save Path", Func = function() altpath_save() end })
                g_ma:AddButton("altpath_load", { Text = "Load Path", Func = function() altpath_load() end })
                g_ma:AddInput("altpath_run_from", {
                    Text = "Run From Waypoint # (blank = start)",
                    Default = "",
                    Placeholder = "e.g. skip straight to the Go To Inn / Wait For Silver tail"
                })
                g_ma:AddButton("altpath_run_now", {
                    Text = "Run Path Now (test)",
                    Tooltip = "Walks the currently selected path immediately, for testing - not tied to any help request. Set 'Run From Waypoint #' to start partway (e.g. the inn+silver tail).",
                    Func = function()
                        local key = altpath_key()
                        local from = tonumber(Options.altpath_run_from and Options.altpath_run_from.Value)
                        task.spawn(function() run_altpath(key, from) end)
                    end
                })
                pcall(function() altpath_load("blademaster"); altpath_load("trinket") end)   -- auto-load both on script start

                -- --- Alt Support: manual test buttons for the sell-trinkets / drop-silver
                -- helpers (GUI-driven, verified against the real UI paths). Test these
                -- individually before trusting an automated pipeline built on top of them.
                g_ma:AddDivider()
                g_ma:AddLabel("altsupport_lbl", { Text = "Alt Support (test manually first)", DoesWrap = true })
                g_ma:AddInput("altsupport_merchant_name", {
                    Text = "Merchant NPC Name (blank = nearest)",
                    Default = "",
                    Placeholder = "leave blank to use whichever NPC is nearest"
                })
                g_ma:AddButton("altsupport_sell", {
                    Text = "Sell Trinkets Now",
                    Tooltip = "Walks to the named/nearest NPC, opens dialogue, clicks Trinkets. -> It's a deal. repeatedly until nothing's left to sell, then Bye.",
                    Func = function()
                        local nm = Options.altsupport_merchant_name and Options.altsupport_merchant_name.Value or ""
                        task.spawn(function() sell_trinkets_to_merchant(nm) end)
                    end
                })
                g_ma:AddButton("altsupport_sell_antiquarian", {
                    Text = "Sell To Antiquarian Now",
                    Tooltip = "Walks to the Antiquarian specifically, sells Scrolls then Gemstones the same bulk-sell way.",
                    Func = function() task.spawn(sell_to_antiquarian) end
                })
                g_ma:AddInput("altsupport_silver_amount", {
                    Text = "Silver Amount",
                    Default = "735",
                    Numeric = true
                })
                g_ma:AddButton("altsupport_drop", {
                    Text = "Drop Silver Now",
                    Tooltip = "Clicks the silver icon, types the amount, clicks Drop - drops it on the ground where you're standing.",
                    Func = function()
                        local amt = tonumber(Options.altsupport_silver_amount and Options.altsupport_silver_amount.Value) or 0
                        task.spawn(function() drop_silver(amt) end)
                    end
                })

                -- ---- Full auto pipeline ------------------------------------------
                -- BLADEMASTER side: the moment it returns to Gaia right after being in
                -- Khei (Uber Sigil done -> joined the killer's server -> died -> back in
                -- Gaia), broadcast a help request with its exact server + position + the
                -- nearest inn/region name, to a SEPARATE file from the "come kill me"
                -- feed (Carbine/feed_server.txt) so the two signals never collide.
                -- TRINKET FARMER side: "Auto-Support Alts" polls for a fresh request,
                -- sells its trinkets, joins that exact server, walks to the reported
                -- position, drops the silver, then Gates to Deepforest 5. It does NOT
                -- restart the original Trinket Bot's own path - that's your own internal
                -- state I was told never to touch - it just notifies you to hit Start.
                local HELP_FILE = "Carbine/help_request.txt"
                local HELP_HANDLED_KEY = "altsupport_last_handled"

                -- ExecutePath (what the real "Start Path" button calls) was declared
                -- LOCAL inside the Trinket Bot's own setup do-block, invisible outside it.
                -- Fixed by forward-declaring "local ExecutePath" before that do-block (same
                -- pattern already used for classbot_start_full/classbot_stop_full) and
                -- dropping "local" from its actual declaration so it assigns to that
                -- forward-declared variable instead of shadowing it - purely an exposure
                -- change, zero behavior difference for the Trinket Bot itself. Kept the
                -- pcall as cheap insurance, not because it's expected to fail now.
                local function try_start_server_loot()
                    -- CRITICAL: the original bot has its OWN dedicated auto-start-on-rejoin
                    -- flow (triggered whenever mem "botstarted" is true) that loads the real
                    -- saved path via load_path_by_name BEFORE calling ExecutePath, with its
                    -- own careful checks. If botstarted is already true, that flow is either
                    -- about to run or already running - calling ExecutePath ourselves in
                    -- parallel races it: our call can fire before the real path has finished
                    -- loading into trinket_bot.path_points, hitting the bot's own "no path
                    -- points loaded" safety - which KICKS the account. So: only start it
                    -- ourselves when nothing else is already handling it.
                    if mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true" then
                        return
                    end
                    local tb = cheat_client.trinket_bot
                    if not (tb and #tb.path_points > 0) then
                        library:Notify("Alt Support: no path loaded yet - click Start Path yourself once a path is loaded", 6)
                        return
                    end
                    local pt = (Options.trinket_ping_threshold and Options.trinket_ping_threshold.Value) or 1000
                    if utility and utility.CheckPingAndHop and utility:CheckPingAndHop("SERVER_LOOT", pt) then return end
                    local ok = pcall(function() task.spawn(cheat_client.Carbine_ExecutePath, false) end)
                    if not ok then
                        library:Notify("Alt Support: couldn't start SERVER_LOOT automatically - click Start Path yourself", 6)
                    end
                end

                g_ma:AddInput("altsupport_ally_name", {
                    Text = "Ally Usernames (your other accounts)",
                    Default = (mem:HasItem("altsupport_ally_name") and mem:GetItem("altsupport_ally_name")) or "",
                    Placeholder = "comma-separated, e.g. MyBlademaster, MyTrinketFarmer",
                    Tooltip = "The real bot's own anti-camping safety serverhops away from any nearby player standing at the last path point - which falsely triggers on YOUR OTHER ACCOUNTS during a delivery (e.g. the Trinket Farmer arriving at the Blademaster). List every other account's exact username here, separated by commas, on ALL of them, to exempt them from that check.",
                    Callback = function(v) pcall(function() mem:SetItem("altsupport_ally_name", v or "") end) end
                })
                g_ma:AddDivider()
                g_ma:AddToggle("altsupport_auto", {
                    Text = "Auto-Support Alts (run on the trinket farmer)",
                    Default = (mem:HasItem("altsupport_auto") and mem:GetItem("altsupport_auto") == "true"),
                    Tooltip = "One button: starts SERVER_LOOT (same as clicking Start Path), watches for a Blademaster's silver help request, pauses looting and runs the Trinket Farmer Path to sell+deliver when one arrives, then resumes SERVER_LOOT after.",
                    Callback = function(v)
                        pcall(function() mem:SetItem("altsupport_auto", v and "true" or "false") end)
                        if v then try_start_server_loot() end
                    end
                })
                g_ma:AddButton("altsupport_reset_funded", {
                    Text = "Reset Funding (this account, run on the Blademaster)",
                    Tooltip = "Silver is a ONE-TIME starting fund - once funded, this account never re-checks/pings again even if it later spends below the target. Click this to make it check/ping again next time (e.g. after permadeath / a new character).",
                    Func = function()
                        pcall(function() mem:RemoveItem("altsupport_funded") end)
                        library:Notify("Alt Support: funding flag reset - will check/ping again next time", 5)
                    end
                })
                -- if the toggle was already on from a previous session/server, make sure
                -- SERVER_LOOT is running on THIS load too (a fresh script load always
                -- starts with path_running = false, even if it was on before the hop).
                if mem:HasItem("altsupport_auto") and mem:GetItem("altsupport_auto") == "true" then
                    task.spawn(function() task.wait(3); try_start_server_loot() end)
                end

                -- Blademaster: check funding, then either start straight away or ping the
                -- trinket farmer and walk the Blademaster Path to the hiding spot to wait.
                -- Shared by the automatic return-to-Gaia watcher below AND the manual
                -- "Start Blademaster" button, so clicking that button gets the exact same
                -- silver-check/detour behaviour as the automatic trigger.
                local function check_silver_and_start_blademaster(wait_for_char)
                    if wait_for_char then
                        local deadline = os.clock() + 60
                        while (not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart")) and os.clock() < deadline do
                            task.wait(0.25)
                        end
                        if not plr.Character then return end
                    end
                    -- don't act (or serverhop/combat-log) while still flagged Danger from the
                    -- kill; wait it out first, capped so this can't hang forever
                    local dt0 = os.clock()
                    while plr.Character and cs:HasTag(plr.Character, "Danger")
                        and shared and not shared.is_unloading and (os.clock() - dt0) < 60 do
                        task.wait(0.25)
                    end
                    task.wait(1)
                    -- silver is a ONE-TIME starting fund, not a recurring balance check -
                    -- once this account has ever been funded (either it already had enough,
                    -- or the trinket farmer delivered), never check/ping again: naturally
                    -- spending silver during normal play would otherwise trigger another
                    -- help request every single cycle.
                    if mem:HasItem("altsupport_funded") and mem:GetItem("altsupport_funded") == "true" then
                        library:Notify("Alt Support: already funded before - starting the Blademaster bot", 6)
                        classbot_start_full()
                        return
                    end
                    local amt = tonumber(Options.altsupport_silver_amount and Options.altsupport_silver_amount.Value) or 735
                    local sv = read_silver()
                    if sv and sv >= amt then
                        -- already funded - no need to bother the trinket farmer at all,
                        -- just start the Blademaster bot again straight away
                        pcall(function() mem:SetItem("altsupport_funded", "true") end)
                        library:Notify(string.format("Alt Support: already have %d silver - starting the Blademaster bot", sv), 8)
                        classbot_start_full()
                    else
                        -- short on silver: broadcast BEFORE walking the path, so the trinket
                        -- farmer can start coming while the Blademaster path (its own separate
                        -- Go To Inn / Wait For Silver tail) runs and blocks at Wait For Silver.
                        local hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                        local pos = hrp and hrp.Position or Vector3.new(0, 0, 0)
                        pcall(function()
                            if makefolder and isfolder and not isfolder("Carbine") then makefolder("Carbine") end
                            writefile(HELP_FILE, table.concat({
                                tostring(game.PlaceId), tostring(game.JobId), "hiding spot",
                                tostring(pos.X), tostring(pos.Y), tostring(pos.Z),
                                tostring(amt), tostring(os.time())
                            }, "|"))
                        end)
                        library:Notify(string.format("Alt Support: only %s silver - help request broadcast, walking the Blademaster Path", tostring(sv or "?")), 8)
                        run_altpath("blademaster")
                    end
                end

                g_ma:AddButton("altsupport_start_blademaster", {
                    Text = "Start Blademaster (check silver first)",
                    Tooltip = "Runs the same funding check the automatic return-to-Gaia trigger does, then either starts the Blademaster bot directly or pings the trinket farmer and walks the Blademaster Path first - use this for a fresh manual start instead of the class bot's own Start button.",
                    Func = function() task.spawn(function() check_silver_and_start_blademaster(false) end) end
                })

                -- broadcast once per return-to-Gaia (not every reload while sitting in
                -- Gaia) - classbot_stage is "khei"/"join" right up until this fires, then
                -- we flip it to "gaia" so it won't re-fire on its own.
                task.spawn(function()
                    local in_khei_now = (game.PlaceId == 3541987450 or game.PlaceId == 14341521240)
                    if in_khei_now then return end
                    local last_stage = mem:HasItem("classbot_stage") and mem:GetItem("classbot_stage")
                    if last_stage ~= "khei" and last_stage ~= "join" then return end
                    pcall(function() mem:SetItem("classbot_stage", "gaia") end)
                    check_silver_and_start_blademaster(true)
                end)

                -- Trinket farmer: watch for a fresh request and start the delivery.
                task.spawn(function()
                    while shared and not shared.is_unloading do
                        task.wait(5)
                        if Toggles.altsupport_auto and Toggles.altsupport_auto.Value
                            and readfile and isfile and isfile(HELP_FILE) then
                            local ok, data = pcall(function() return readfile(HELP_FILE) end)
                            if ok and data and data ~= "" then
                                local pid, jid, region, x, y, z, amt, ts = data:match("^(%d+)|(.-)|(.-)|(.-)|(.-)|(.-)|(.-)|(%d+)$")
                                if pid and jid and ts and (mem:GetItem(HELP_HANDLED_KEY) or "") ~= ts
                                    and (os.time() - tonumber(ts)) < 900 then   -- ignore stale (>15min) requests
                                    pcall(function() mem:SetItem(HELP_HANDLED_KEY, ts) end)
                                    -- stop SERVER_LOOT BEFORE hopping (same graceful pause the
                                    -- "Stop Bot" button's first action does - just the running
                                    -- flag, not a full reset) so it isn't still looting/moving
                                    -- right up to and through the serverhop. It gets picked back
                                    -- up by try_start_server_loot() after delivery finishes.
                                    pcall(function() if cheat_client.trinket_bot then cheat_client.trinket_bot.path_running = false end end)
                                    -- selling now happens as PART of the Trinket Farmer Path itself
                                    -- (add Sell Trinkets Here / Sell To Antiquarian waypoints to it) -
                                    -- one path handles selling AND delivering, not two separate steps.
                                    library:Notify("Alt Support: help request near " .. tostring(region) .. " - stopping loot bot and joining their server", 6)
                                    pcall(function()
                                        mem:SetItem("altsupport_pending", table.concat({pid, jid, region, x, y, z, amt, ts}, "|"))
                                    end)
                                    task.wait(1)
                                    pcall(function()
                                        local jr = rps.Requests and rps.Requests:FindFirstChild("JoinPublicServer")
                                        if jr then jr:FireServer(jid) else Services.TeleportService:TeleportToPlaceInstance(tonumber(pid), jid, plr) end
                                    end)
                                end
                            end
                        end
                    end
                end)

                -- Trinket farmer, after the join above reloads the script in the
                -- Blademaster's server: finish the delivery (walk to them, drop the
                -- silver, Gate home), then clear the pending marker either way so it
                -- can't get stuck retrying forever.
                task.spawn(function()
                    local pending = mem:HasItem("altsupport_pending") and mem:GetItem("altsupport_pending")
                    if not pending or pending == "" then return end
                    if not (Toggles.altsupport_auto and Toggles.altsupport_auto.Value) then return end
                    local pid, jid = pending:match("^(%d+)|(.-)|")
                    if not (pid and jid) then pcall(function() mem:RemoveItem("altsupport_pending") end); return end
                    if jid ~= tostring(game.JobId) then return end   -- not there yet / wrong server
                    local deadline = os.clock() + 60
                    while (not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart")) and os.clock() < deadline do
                        task.wait(0.25)
                    end
                    if not plr.Character then return end
                    task.wait(2)
                    -- pause SERVER_LOOT the same way its own "Stop Bot" button's first
                    -- action does (setting the same flag Gate() itself checks) so it isn't
                    -- fighting the Trinket Farmer Path for control of the character - a
                    -- graceful pause, not the full Stop Bot reset (that resets several
                    -- debounce/tracking locals meant for a fresh future run, not needed
                    -- just to pause movement for a minute).
                    pcall(function() if cheat_client.trinket_bot then cheat_client.trinket_bot.path_running = false end end)
                    library:Notify("Alt Support: walking the Trinket Farmer Path to the Blademaster", 6)
                    run_altpath("trinket")   -- reads the silver amount from this pending record while it runs
                    pcall(function() mem:RemoveItem("altsupport_pending") end)
                    task.wait(1)
                    library:Notify("Alt Support: delivered - resuming SERVER_LOOT", 8)
                    try_start_server_loot()
                end)
            end)

            -- Self Fall Damage: the client-side fall-damage remote is renamed to a
            -- random GUID every rejoin and can't be hardcoded, so this hooks EVERY
            -- remote under CharacterHandler.Remotes and watches for the fall-damage
            -- call signature (exactly 2 args: a {number, number} table + an empty
            -- table). Re-calibrates on EVERY real fall (not just the first) so the
            -- cached reference/last-seen values never go stale after a respawn or a
            -- serverhop swaps the remote out. Own isolated pcall closure - see the
            -- Teleport tab comment above for why (200-local-register ceiling).
            pcall(function()
                local win = getgenv().XPFARM_WINDOW
                local sd_tab
                if win and win.AddTab then
                    sd_tab = win:AddTab("Self Damage", "skull")
                elseif library and library.Tabs and library.Tabs.Misc then
                    sd_tab = library.Tabs.Misc
                else
                    error("no window/tab reference reachable")
                end
                local group_sd = sd_tab:AddLeftGroupbox("Self Fall Damage")

                local sd_last = { 0.10793217244300189, 0.17512923530910326 }

                local function sd_get_remotes()
                    local char = plr.Character
                    local ch = char and char:FindFirstChild("CharacterHandler")
                    return ch and ch:FindFirstChild("Remotes")
                end

                local sd_hooked = {}
                local function sd_hook_remote(r)
                    if sd_hooked[r] or not r:IsA("RemoteEvent") then return end
                    sd_hooked[r] = true
                    local old
                    pcall(function()
                        old = hookfunction(r.FireServer, function(self, ...)
                            if self == r then
                                local args = { ... }
                                if #args == 2 and typeof(args[1]) == "table" and typeof(args[2]) == "table" then
                                    local a1 = args[1]
                                    local n, a2n = 0, 0
                                    for _ in pairs(a1) do n = n + 1 end
                                    for _ in pairs(args[2]) do a2n = a2n + 1 end
                                    if n == 2 and a2n == 0 and typeof(a1[1]) == "number" and typeof(a1[2]) == "number" then
                                        getgenv().Carbine_FallDamageRemote = r
                                        sd_last[1], sd_last[2] = a1[1], a1[2]
                                        library:Notify(string.format("Self Damage: recalibrated (%.4f, %.4f)", a1[1], a1[2]), 3)
                                    end
                                end
                            end
                            return old(self, ...)
                        end)
                    end)
                end
                local function sd_hook_all()
                    local remotes = sd_get_remotes()
                    if not remotes then return end
                    for _, r in ipairs(remotes:GetChildren()) do sd_hook_remote(r) end
                    remotes.ChildAdded:Connect(sd_hook_remote)
                end
                sd_hook_all()
                plr.CharacterAdded:Connect(function() task.wait(1); sd_hook_all() end)

                local function sd_fire(a1, a2)
                    local r = rawget(getgenv(), "Carbine_FallDamageRemote")
                    if not r or not r.Parent then
                        library:Notify("Self Damage: not calibrated yet - take one real fall to calibrate first", 6)
                        return
                    end
                    pcall(function() r:FireServer({ a1, a2 }, {}) end)
                end

                group_sd:AddLabel("sd_lbl", {
                    Text = "Auto-calibrates from your real fall damage (re-syncs on every fall). Take one real fall first if the buttons say 'not calibrated'.",
                    DoesWrap = true
                })
                group_sd:AddButton("sd_knock", {
                    Text = "Knock Yourself",
                    Tooltip = "Fires the fall-damage remote at (0, 1) - knocks you down without meaningful damage.",
                    Func = function() sd_fire(0, 1) end
                })
                group_sd:AddButton("sd_kill", {
                    Text = "Kill Yourself",
                    Tooltip = "Fires the fall-damage remote at a lethal magnitude - this WILL kill you.",
                    Func = function() sd_fire(0.8059, 3.0100) end
                })
            end)

            -- Stella Map Hide: replicates ONLY Stella's self-hide signal (a signed POST
            -- to /api/positions with players={} and me=UserId). It does NOT run Stella's
            -- remote payload and reports ZERO other players - it just tells their backend
            -- to hide your UserId from the live map, using your own token.
            pcall(function()
                local misc = library.Tabs and library.Tabs.Misc
                if not misc then return end
                local g_sh = misc:AddRightGroupbox("Stella Map Hide")
                g_sh:AddInput("stella_hide_token", {
                    Text = "Stella Token",
                    Default = (mem:HasItem("stella_hide_token") and mem:GetItem("stella_hide_token")) or "",
                    Placeholder = "paste your stella_token",
                    Tooltip = "Your Stella token (needed to sign the hide request). Stored locally, not in the build.",
                    Callback = function(v) pcall(function() mem:SetItem("stella_hide_token", v or "") end) end
                })
                g_sh:AddToggle("stella_hide", {
                    Text = "Hide Me From Stella Map",
                    Default = (mem:HasItem("stella_hide") and mem:GetItem("stella_hide") == "true"),
                    Tooltip = "Sends ONLY the Stella self-hide signal (empty player list + your UserId). No Stella payload, no harvesting other players, no chat capture.",
                    Callback = function(v) pcall(function() mem:SetItem("stella_hide", v and "true" or "false") end) end
                })
                g_sh:AddLabel("stella_hide_help", {
                    Text = "Replicates ONLY Stella's self-hide - it does NOT run their script or report any other player.",
                    DoesWrap = true
                })

                local function sha256(s)
                    if crypt and crypt.hash then local ok, h = pcall(crypt.hash, s, "sha256"); if ok then return h end end
                    if syn and syn.crypt and syn.crypt.hash then local ok, h = pcall(syn.crypt.hash, s, "sha256"); if ok then return h end end
                    return nil
                end

                task.spawn(function()
                    local URL = "https://stella.heroinhound.cc/api/positions"
                    while shared and not shared.is_unloading do
                        local on = Toggles.stella_hide and Toggles.stella_hide.Value
                        local token = (Options.stella_hide_token and Options.stella_hide_token.Value) or ""
                        if on and token ~= "" and plr and plr.Character then
                            pcall(function()
                                local req = http_request or request
                                if not req then return end
                                local body = {
                                    job_id = game.JobId,
                                    players = {},
                                    count = #plrs:GetPlayers(),
                                    place = game.PlaceId,
                                    me = plr.UserId,
                                }
                                local json = Services.HttpService:JSONEncode(body)
                                local ts = tostring(os.time())
                                local sender = tostring(plr.UserId)
                                local job = game.JobId
                                local bh = sha256(json)
                                if not bh then return end
                                local sig = sha256(token .. ts .. sender .. job .. string.lower(bh))
                                if not sig then return end
                                req({
                                    Url = URL,
                                    Method = "POST",
                                    Headers = {
                                        ["Content-Type"] = "application/json",
                                        ["Authorization"] = "Bearer " .. token,
                                        ["X-Timestamp"] = ts,
                                        ["X-Sender-ID"] = sender,
                                        ["X-Job-ID"] = job,
                                        ["X-Signature"] = string.lower(sig),
                                    },
                                    Body = json,
                                })
                            end)
                            task.wait(1)
                        else
                            task.wait(1)
                        end
                    end
                end)
            end)

            -- serverhop + resume: save the path to a resume slot, remember where to
            -- continue, make sure the script reloads after the hop, then hop. On
            -- reload the resume task (below) loads it and continues from that index.
            -- snap a resume index back to the start of any repeat block it's inside, so
            -- the loop re-runs cleanly (repeats persist through a serverhop) instead of
            -- resuming mid-loop with a reset counter.
            local function snap_to_repeat_start(idx)
                if not idx or idx < 1 then return idx end
                local open = nil
                for i = 1, math.min(idx, #xp_path) do
                    local k = xp_path[i] and xp_path[i].kind
                    if k == "repeat_start" then open = i
                    elseif k == "repeat_end" then open = nil end
                end
                return open or idx
            end

            -- instant serverhop: join a random non-full public server directly via the
            -- game's JoinPublicServer remote (skips the slow RAMAccount/retry machinery
            -- in utility:Serverhop). Falls back to the full hop if it can't find one.
            local function xpfarm_fast_serverhop()
                local jr = rps.Requests and rps.Requests:FindFirstChild("JoinPublicServer")
                if not jr then
                    -- no JoinPublicServer here (e.g. the Khei place). Do NOT use utility:Serverhop -
                    -- its restricted-place teleport freezes the whole script. Just skip this hop.
                    library:Notify("Hop: no JoinPublicServer in this place - can't hop here, keep farming", 6)
                    return
                end
                local hs = Services.HttpService
                local seen = {}
                -- PRIMARY source: the Roblox games API only lists JOINABLE PUBLIC servers, so it
                -- never hands us the restricted/private servers that froze the client on a teleport.
                -- Use the EXACT request the proven (slow) hop uses: /servers/0 + sortOrder=2 +
                -- Accept header + a StatusCode==200 check. The previous /servers/Public form was
                -- returning nothing on some executors, silently dropping us onto the restricted
                -- in-game ServerInfo list - which is what kept freezing the bot.
                -- restricted/isolated servers (the anti-cheat-bucket kind) are almost always
                -- only ~1-5 players, so requiring a minimum player count filters them out of
                -- the hop candidates entirely - same idea as the Trinket Bot's Min Player Count.
                local min_players = (Options.xpfarm_min_player_count and Options.xpfarm_min_player_count.Value) or 0
                local api_list = {}
                pcall(function()
                    local req = http_request or request or (syn and syn.request)
                    if not req then return end
                    local url = string.format(
                        "https://games.roblox.com/v1/games/%s/servers/0?sortOrder=2&excludeFullGames=false&limit=100",
                        tostring(game.PlaceId))
                    local resp = req({ Url = url, Method = "GET", Headers = { ["Accept"] = "application/json" } })
                    if not (resp and resp.Success and resp.StatusCode == 200 and resp.Body) then return end
                    local ok, data = pcall(function() return hs:JSONDecode(resp.Body) end)
                    if not (ok and data and data.data) then return end
                    for _, srv in ipairs(data.data) do
                        local jid = srv.id
                        if jid and jid ~= game.JobId and not seen[jid]
                            and (srv.playing or 0) < (srv.maxPlayers or 100)
                            and (srv.playing or 0) >= min_players then
                            seen[jid] = true; api_list[#api_list + 1] = jid
                        end
                    end
                end)
                -- FALLBACK source: in-game ServerInfo (instant, but can include the restricted
                -- servers that freeze us) - only used if the API gave us nothing.
                local info_list = {}
                local si = FindFirstChild(rps, "ServerInfo")
                if si then
                    for _, s in ipairs(si:GetChildren()) do
                        if s.Name and s.Name ~= "" and s.Name ~= game.JobId and not seen[s.Name] then
                            local pv = FindFirstChild(s, "Players")
                            local cnt = 0
                            if pv and pv:IsA("StringValue") then
                                local ok, pd = pcall(function() return hs:JSONDecode(pv.Value) end)
                                if ok and type(pd) == "table" then cnt = #pd end
                            end
                            if cnt < 23 and cnt >= min_players then seen[s.Name] = true; info_list[#info_list + 1] = s.Name end
                        end
                    end
                end
                -- prefer the verified-joinable API servers; only touch ServerInfo if the API failed
                local using_api = #api_list > 0
                local candidates = using_api and api_list or info_list
                -- DIAGNOSTIC (so we can see in-game what's actually happening): if this says
                -- "0 API" the executor's HTTP can't reach the games API and we're stuck on the
                -- in-game list, which is the restricted-server source.
                local diag = string.format("Hop: %d API public servers, %d in-game - using %s",
                    #api_list, #info_list, using_api and "API (safe)" or "IN-GAME list")
                library:Notify(diag, 6)
                print("[Carbine] " .. diag)   -- also to console so it shows in the executor log
                if #candidates == 0 then
                    -- no servers found this pass. Do NOT fall to utility:Serverhop (freezes); just
                    -- unpause and let the maintenance loop re-arm the hop shortly.
                    library:Notify("Hop: found no servers this pass - will retry shortly", 5)
                    return
                end

                -- Same "go through the menu" safety Trinket Bot's serverhop uses (lower ban
                -- risk than a raw in-place teleport): wait for the character to actually
                -- settle (grounded, not mid-jump) before menuing out, then invoke
                -- ReturnToMenu. Only done once we know there's actually a candidate to join,
                -- so we don't menu out for nothing.
                pcall(function()
                    local char = plr.Character
                    local hum = char and FindFirstChildOfClass(char, "Humanoid")
                    if hum then
                        local gt0 = os.clock()
                        while hum.Parent and (os.clock() - gt0) < 4
                            and hum:GetState() ~= Enum.HumanoidStateType.Running do
                            task.wait(0.1)
                        end
                    end
                end)
                pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)

                -- A REAL teleport reloads the whole script, so a successful hop simply never
                -- returns from this function. We therefore NEVER "assume success" on a quiet server
                -- (that false positive - the same bug as utility:Serverhop's "no failure in 20s =
                -- success" guess - was leaving the bot sitting in the SAME server doing nothing,
                -- which is the "bot just stops" you saw). Instead we just keep firing servers: a
                -- restricted/full one fires TeleportInitFailed within a second or two, so we move on
                -- fast; a good one teleports us out and this loop never continues.
                local failed = false
                local conn
                pcall(function()
                    conn = Services.TeleportService.TeleportInitFailed:Connect(function(_, _, msg)
                        failed = true
                        library:Notify("Hop: a server refused us (" .. tostring(msg) .. ") - trying another", 3)
                    end)
                end)
                for _ = 1, math.min(16, #candidates) do
                    if shared and shared.is_unloading then break end
                    local idx = math.random(1, #candidates)
                    local jid = candidates[idx]
                    table.remove(candidates, idx)
                    failed = false
                    pcall(function() jr:FireServer(jid) end)
                    -- wait out a possible teleport (a good server reloads us within a few seconds);
                    -- bail to the next one the instant TeleportInitFailed fires
                    local t0 = os.clock()
                    while os.clock() - t0 < 15 and not failed and not (shared and shared.is_unloading) do
                        task.wait(0.2)
                    end
                    -- still running here = that server didn't take us; try the next one
                end
                if conn then pcall(function() conn:Disconnect() end) end
                -- nothing took us this pass. Do NOT fall back to utility:Serverhop - its localhost
                -- RAMAccount probe stalls ~2s and its 20s "success" guess can leave us stuck. Just
                -- unpause; the maintenance loop re-arms the hop and we try again in a moment.
                library:Notify("Hop: no server accepted us this pass - will retry shortly", 5)
            end

            -- Auto-dismiss Roblox's "Teleport Failed" modal (e.g. 773 "place is restricted" / 769
            -- "unexpected error"). That dialog BLOCKS the game and the bot can't click "Ok", so
            -- without this it just sits there stuck. We click its OK button for it - via a REAL
            -- simulated mouse click (works on every executor), plus firesignal as a backup.
            task.spawn(function()
                local VIM = game:GetService("VirtualInputManager")
                local guiinset = 0
                pcall(function() guiinset = game:GetService("GuiService"):GetGuiInset().Y end)
                while shared and not shared.is_unloading do
                    task.wait(0.25)
                    pcall(function()
                        local roots = {}
                        pcall(function() table.insert(roots, game:GetService("CoreGui")) end)
                        pcall(function() if gethui then table.insert(roots, gethui()) end end)
                        for _, cg in ipairs(roots) do
                            for _, sg in ipairs(cg:GetChildren()) do
                                local has_fail, okbtn = false, nil
                                for _, v in ipairs(sg:GetDescendants()) do
                                    if (v:IsA("TextLabel") or v:IsA("TextButton")) then
                                        local txt = string.lower(v.Text or "")
                                        if txt:find("teleport failed") or txt:find("error code")
                                            or txt:find("restricted") or txt:find("cannot be joined")
                                            or txt:find("unexpected error") then
                                            has_fail = true
                                        end
                                    end
                                    if v:IsA("TextButton") and v.Visible then
                                        local bt = string.lower(v.Text or "")
                                        if bt == "ok" or bt == "okay" or bt == "leave" or bt == "leave experience" then
                                            okbtn = v
                                        end
                                    end
                                end
                                if has_fail and okbtn then
                                    print("[Carbine] Dismissing 'Teleport Failed' popup (Ok)")
                                    -- real mouse click at the button's centre. AbsolutePosition is
                                    -- already viewport-relative, so click it DIRECTLY - the old
                                    -- code added GuiInset (~36px) and landed just BELOW the button,
                                    -- missing it. Move the mouse there first, then press+release.
                                    pcall(function()
                                        local p = okbtn.AbsolutePosition
                                        local s = okbtn.AbsoluteSize
                                        local x = p.X + s.X / 2
                                        local y = p.Y + s.Y / 2
                                        VIM:SendMouseMoveEvent(x, y, game)
                                        task.wait(0.03)
                                        VIM:SendMouseButtonEvent(x, y, 0, true, game, 1)
                                        task.wait(0.03)
                                        VIM:SendMouseButtonEvent(x, y, 0, false, game, 1)
                                    end)
                                    -- backup: fire the button's signals directly
                                    pcall(function()
                                        if getconnections then
                                            for _, c in ipairs(getconnections(okbtn.Activated)) do
                                                pcall(function() c:Fire() end)
                                                pcall(function() if c.Function then c.Function() end end)
                                            end
                                            for _, c in ipairs(getconnections(okbtn.MouseButton1Click)) do
                                                pcall(function() c:Fire() end)
                                                pcall(function() if c.Function then c.Function() end end)
                                            end
                                        end
                                        if firesignal then
                                            firesignal(okbtn.Activated)
                                            firesignal(okbtn.MouseButton1Click)
                                        end
                                    end)
                                    library:Notify("Dismissed a 'Teleport Failed' popup - re-hopping", 4)
                                end
                            end
                        end
                    end)
                end
            end)

            local xpfarm_hopping = false   -- pauses the path runner while a hop is in flight
            local function do_path_serverhop(resume_idx)
                xpfarm_hopping = true       -- stop walking the path until we've actually hopped
                -- if we hop while holding a shrieker, flag it so the carry-over isn't counted as a
                -- turn-in after the hop (we'll still take it to the Monster Hunter + back to clear it)
                if is_carrying_shrieker() then
                    pcall(function() mem:SetItem("classbot_crosshop_shrk", "1") end)
                end
                local exact_idx = resume_idx or 1   -- the EXACT step we were on when we hopped
                -- non-classbot paths have no goal counters, so snap to the enclosing repeat start
                -- to keep that loop going; the full bot saves the EXACT spot and walks back to it.
                local snapped_idx = snap_to_repeat_start(exact_idx)
                -- when the Blademaster full bot is active, let its own resume restart the
                -- current stage in the new server - don't also arm the path-resume (avoids
                -- the two fighting over the path after the hop).
                local classbot = mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true"
                if not classbot then
                    pcall(function() save_xpfarm_path("__carbine_resume") end)
                    pcall(function() mem:SetItem("xpfarm_resume_idx", tostring(snapped_idx)) end)
                    pcall(function() mem:SetItem("xpfarm_resume_active", "true") end)
                else
                    -- full bot: remember the EXACT waypoint so it walks back to that precise spot
                    -- in the new server (per stage), instead of restarting the loop.
                    pcall(function() mem:SetItem("classbot_resume_idx", tostring(exact_idx)) end)
                    local kh = (game.PlaceId == 3541987450 or game.PlaceId == 14341521240)
                    pcall(function() mem:SetItem("classbot_resume_stage", kh and "khei" or "gaia") end)
                end
                cheat_client.config.execute_on_serverhop = true
                if Toggles.execute_on_serverhop and not Toggles.execute_on_serverhop.Value then
                    pcall(function() Toggles.execute_on_serverhop:SetValue(true) end)
                end
                library:Notify("Serverhopping - will resume after", 5)
                -- NEVER serverhop while Danger is active (combat-logging risk) - wait for it
                -- to clear no matter how long that takes, rather than capping the wait and
                -- hopping anyway. Only bails if the character/script itself goes away.
                burst_until = 0
                if plr.Character and cs:HasTag(plr.Character, "Danger") then
                    library:Notify("Hop: waiting for Danger to clear before hopping...", 5)
                end
                pcall(function()
                    while plr.Character and cs:HasTag(plr.Character, "Danger")
                        and shared and not shared.is_unloading do
                        task.wait(0.2)
                    end
                end)
                -- go through the menu first (same as End Path) before actually hopping -
                -- a cleaner leave than jumping straight from mid-gameplay into a teleport.
                -- The server can silently reject/ignore the menu invoke if the character is
                -- airborne (jumping, falling, knocked back) at the moment it fires - wait
                -- for a grounded Humanoid state first, capped at 3s so a genuinely stuck
                -- character (endless fall, etc.) doesn't block hopping forever.
                pcall(function()
                    local char = plr.Character
                    local hum = char and FindFirstChildOfClass(char, "Humanoid")
                    if hum then
                        local gt0 = os.clock()
                        while hum.Parent and (os.clock() - gt0) < 3
                            and hum:GetState() ~= Enum.HumanoidStateType.Running do
                            task.wait(0.1)
                        end
                    end
                end)
                pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)
                task.wait(0.5)
                -- Hop ONLY via the game's JoinPublicServer remote (a SERVER-side teleport). We do
                -- NOT call utility:Serverhop, because its give-up path does a CLIENT tps:Teleport to
                -- a restricted lobby place - that throws the 773 "restricted" modal AND suspends the
                -- whole script, so nothing (not even the popup-dismisser) can run and the bot never
                -- restarts. That was the actual freeze. JoinPublicServer can't hit that place, so it
                -- can't freeze us; a bad target just fires TeleportInitFailed and we try the next.
                pcall(xpfarm_fast_serverhop)
                xpfarm_hopping = false
            end

            -- Auto-Click on Hold (LMB): toggle + rate + keybind on the main Combat
            -- tab so it's reachable for general fighting (not buried in the farm).
            pcall(function()
                local ct = library.Tabs and library.Tabs.Combat
                if not ct then return end
                local g_hc = ct:AddLeftGroupbox("Carbine")
                local hc = g_hc:AddToggle("xpfarm_holdclick", {
                    Text = "Auto-Click on Hold (LMB)",
                    Default = false,
                    Tooltip = "While ON, holding left mouse auto-fires M1 at the rate below (turns a held click into rapid clicks)."
                })
                g_hc:AddSlider("xpfarm_holdclick_cps", {
                    Text = "Hold-Click / sec", Default = 10, Min = 1, Max = 20, Rounding = 0, Suffix = "/s"
                })
                pcall(function()
                    hc:AddKeyPicker("xpfarm_holdclick_key", {
                        Default = "None",
                        Text = "Auto-Click on Hold",
                        Mode = "Toggle",
                        SyncToggleState = true,
                    })
                end)

                -- Knock self via fall damage: teleport up by the height, drop, land
                -- knocked. PERMADEATH RISK if the height is too high - tune the height
                -- first; default-unbound keybind so it can't fire by accident.
                g_hc:AddDivider()
                g_hc:AddSlider("xpfarm_fallknock_height", {
                    Text = "Fall Knock Height", Default = 60, Min = 20, Max = 400, Rounding = 0, Suffix = " studs",
                    Tooltip = "How far up to drop from. Higher = more fall damage. TUNE CAREFULLY - too high can PERMAKILL you. Start low and raise until it just knocks."
                })
                local function do_knock_self()
                    local char = plr.Character
                    local hrp = char and FindFirstChild(char, "HumanoidRootPart")
                    if not hrp or cs:HasTag(char, "Knocked") then return false end
                    local h = (Options.xpfarm_fallknock_height and Options.xpfarm_fallknock_height.Value) or 60
                    pcall(function()
                        hrp.AssemblyLinearVelocity = Vector3.zero
                        hrp.CFrame = hrp.CFrame + Vector3.new(0, h, 0)
                    end)
                    return true
                end
                g_hc:AddButton("xpfarm_knockself", {
                    Text = "Knock Self (fall)",
                    Tooltip = "Teleports you up by the height above and drops you so fall damage knocks you down. WARNING: permadeath risk if the height is too high - test low first / on an alt.",
                    Func = function()
                        if not plr.Character then library:Notify("Character not found"); return end
                        if cs:HasTag(plr.Character, "Knocked") then library:Notify("Already knocked"); return end
                        if do_knock_self() then library:Notify("Dropping to knock...", 3) end
                    end
                })
                pcall(function()
                    g_hc:AddLabel("Knock Self Keybind"):AddKeyPicker("xpfarm_knockself_key", {
                        Default = "None",
                        Text = "Knock Self",
                        Mode = "Toggle",
                        Callback = function() do_knock_self() end
                    })
                end)

                -- Chokeout (knock): fire the same client signals the other knock script uses -
                -- CombatEffects "Chokeout2" + StopSprint (the chokeout you do while holding a grab).
                g_hc:AddDivider()
                local function do_chokeout()
                    -- always say what happened so it's never a silent no-op
                    local fs = firesignal or (getgenv and getgenv().firesignal) or firesignal
                    if not fs then library:Notify("Chokeout: your executor has no firesignal", 6); print("[Carbine] chokeout: no firesignal"); return end
                    local req = rps and FindFirstChild(rps, "Requests")
                    if not req then library:Notify("Chokeout: ReplicatedStorage.Requests not found", 6); print("[Carbine] chokeout: no Requests folder"); return end
                    local ce = FindFirstChild(req, "CombatEffects")
                    if not ce then library:Notify("Chokeout: 'CombatEffects' remote not found in Requests", 6); print("[Carbine] chokeout: no CombatEffects"); return end
                    pcall(function() fs(ce.OnClientEvent, "Chokeout2") end)
                    local ss = FindFirstChild(req, "StopSprint")
                    if ss then pcall(function() fs(ss.OnClientEvent) end) end
                    library:Notify("Chokeout fired (Chokeout2 + StopSprint)", 3)
                    print("[Carbine] chokeout fired")
                end
                g_hc:AddButton("xpfarm_chokeout", {
                    Text = "Knock (Chokeout)",
                    Tooltip = "Fires the CombatEffects 'Chokeout2' + StopSprint client signals - the chokeout you perform while holding a grab on someone.",
                    Func = function() do_chokeout() end
                })
                pcall(function()
                    g_hc:AddLabel("Chokeout Keybind"):AddKeyPicker("xpfarm_chokeout_key", {
                        Default = "None",
                        Text = "Chokeout",
                        Mode = "Toggle",
                        Callback = function() do_chokeout() end
                    })
                end)
            end)

            -- Auto-click on hold: while the toggle is on, holding left mouse fires
            -- M1 repeatedly at the chosen rate. Independent of the farm/path.
            do
                local holding_lmb = false
                cheat_client.feature_connections.xpfarm_holdclick_down = utility:Connection(uis.InputBegan, function(input, gp)
                    if gp then return end
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then holding_lmb = true end
                end)
                cheat_client.feature_connections.xpfarm_holdclick_up = utility:Connection(uis.InputEnded, function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then holding_lmb = false end
                end)
                task.spawn(function()
                    while shared and not shared.is_unloading do
                        if holding_lmb and Toggles.xpfarm_holdclick and Toggles.xpfarm_holdclick.Value and plr.Character then
                            pcall(function() utility:LeftClick() end)
                            local cps = math.clamp((Options.xpfarm_holdclick_cps and Options.xpfarm_holdclick_cps.Value) or 10, 1, 20)
                            task.wait(1 / cps)
                        else
                            task.wait(0.05)
                        end
                    end
                end)
            end

            -- Class-bot full run: do ONE full pass (repeats at full count) then call
            -- classbot_on_done to advance the stage, instead of looping forever.
            local classbot_run_once = false
            local classbot_on_done = nil

            -- first path step that isn't a leading inn - used on resume so we DON'T re-rent
            -- (BreakJoints-respawn) at the start inn every hop, which would drop a carried
            -- shrieker / reset progress "halfway in". After a hop we're already bound at that
            -- inn anyway, so we just walk on from the first real waypoint.
            local function first_after_leading_inns()
                for i = 1, #xp_path do
                    if xp_path[i] and xp_path[i].kind ~= "inn" then return i end
                end
                return 1
            end
            -- ---- path runner --------------------------------------------------
            task.spawn(function()
                -- These helpers live INSIDE this closure (its own register budget) so they don't
                -- add to the outer function's 200-local limit. find_repeat_* locate a block's
                -- matching ends; classbot_rep_key = persistent per-loop round counter; the GOAL
                -- counters make the Blademaster Evil-Eye / Shrieker loops run until a REAL goal
                -- (20 kills / 20 turn-ins), not a round count. All generation-keyed so they
                -- survive serverhops and reset each Run.
                local function find_repeat_start(end_idx)
                    local depth = 0
                    for j = end_idx - 1, 1, -1 do
                        local k = xp_path[j] and xp_path[j].kind
                        if k == "repeat_end" then depth = depth + 1
                        elseif k == "repeat_start" then
                            if depth == 0 then return j else depth = depth - 1 end
                        end
                    end
                    return nil
                end
                local function find_repeat_end(start_idx)
                    local depth = 0
                    for j = start_idx + 1, #xp_path do
                        local k = xp_path[j] and xp_path[j].kind
                        if k == "repeat_start" then depth = depth + 1
                        elseif k == "repeat_end" then
                            if depth == 0 then return j else depth = depth - 1 end
                        end
                    end
                    return nil
                end
                -- (nearest-preceding-repeat-block lookup is inlined at its one call site
                -- in the Make Potions retry logic below - kept as a top-level local
                -- function here once, but removed to stay under the 200-register cap)
                local function classbot_rep_key(start_idx)
                    if mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true" then
                        local gen = (mem:HasItem("classbot_gen") and mem:GetItem("classbot_gen")) or "0"
                        local kh = game.PlaceId == 3541987450 or game.PlaceId == 14341521240
                        return "classbot_rep_" .. gen .. "_" .. (kh and "khei" or "gaia") .. "_" .. start_idx
                    end
                    -- generic (non-classbot) paths: plain Repeat blocks now also
                    -- persist their count through serverhops, keyed by index.
                    return "xpfarm_rep_" .. start_idx
                end
                local function classbot_goal_key(kind)
                    local gen = (mem:HasItem("classbot_gen") and mem:GetItem("classbot_gen")) or "0"
                    if kind == "evil" then return "classbot_evil_" .. gen
                    elseif kind == "shrieker" then return "classbot_shrk_" .. gen end
                    return nil
                end
                local function classbot_goal_count(kind)
                    local k = classbot_goal_key(kind)
                    return (k and tonumber(mem:GetItem(k))) or 0
                end
                local function classbot_goal_add(kind)
                    local k = classbot_goal_key(kind)
                    if k then pcall(function() mem:SetItem(k, tostring((tonumber(mem:GetItem(k)) or 0) + 1)) end) end
                end
                local function classbot_goal_active(step)
                    return step and step.goal_kind and step.goal
                        and mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true"
                end
                -- true if we already hold a real weapon (character OR backpack) - same
                -- "is it actually a weapon, not a potion/spell" filter as ensure_weapon.
                -- Used by "Skip If Armed" NPC waypoints (e.g. a starter-sword vendor).
                local function has_weapon()
                    local char = plr.Character
                    if char and FindFirstChildOfClass(char, "Tool") then return true end
                    local bp = FindFirstChild(plr, "Backpack")
                    if bp then
                        for _, t in ipairs(bp:GetChildren()) do
                            if t:IsA("Tool")
                                and not FindFirstChild(t, "Quantity")
                                and not FindFirstChild(t, "SilverValue")
                                and not FindFirstChild(t, "Spell")
                                and not FindFirstChild(t, "Skill")
                                and not FindFirstChild(t, "SkillSpell")
                            then
                                return true
                            end
                        end
                    end
                    return false
                end
                -- CR Captcha waypoint: walk to the named NPC, talk through with
                -- fireclickdetector (NOT the real-mouse-click Xenyari uses -
                -- only Xenyari's captcha carries that specific ban risk, per
                -- the user), solve the captcha with the same solveCaptcha
                -- engine, and report the outcome so the caller can decide
                -- whether to keep going or reset+cooldown. Returns "success",
                -- "fail" (wrong answer - the NPC's cooldown/Bye dialogue
                -- showed up), or "error" (couldn't reach the NPC / no
                -- captcha or dialogue ever appeared).
                local function npc_talk_captcha(npc_name)
                    local hrp = local_hrp()
                    local npcs_folder = FindFirstChild(ws, "NPCs")
                    if not hrp or not npcs_folder then return "error" end

                    local want = npc_name and npc_name ~= "" and npc_name:gsub("^%s*(.-)%s*$", "%1"):lower() or nil
                    local nearest, nearest_pos, ndist
                    for _, npc in ipairs(npcs_folder:GetChildren()) do
                        local nhrp = FindFirstChild(npc, "HumanoidRootPart")
                        if nhrp and FindFirstChildWhichIsA(npc, "ClickDetector", true) then
                            if not want or npc.Name:lower():find(want, 1, true) then
                                local d = (nhrp.Position - hrp.Position).Magnitude
                                if d <= 150 and (not ndist or d < ndist) then ndist = d; nearest = npc; nearest_pos = nhrp.Position end
                            end
                        end
                    end
                    if not nearest then
                        library:Notify("CR Captcha: no NPC named '" .. tostring(npc_name) .. "' nearby", 6)
                        return "error"
                    end
                    if not ndist or ndist > 6 then bot_move_to(nearest_pos) end

                    local cd = FindFirstChildWhichIsA(nearest, "ClickDetector", true)
                    -- Both fail (Bye) AND success (I'll pay) can end in a final
                    -- "no choices" message that just exits the conversation -
                    -- so "settled without seeing Bye" is NOT proof of success.
                    -- Only treat it as success if we actually saw a "pay"
                    -- choice; anything else (including a plain no-choices
                    -- notice we never got a positive signal from) is NOT
                    -- confirmed - the caller treats unconfirmed the same as
                    -- failed, since continuing on a maybe is what risks a ban.
                    local settled, matched_fail, matched_pay = false, false, false
                    local conn
                    if dialogue_remote then
                        conn = utility:Connection(dialogue_remote.OnClientEvent, function(dialogData)
                            task.wait(1)
                            if not dialogData.choices then
                                pcall(function() dialogue_remote:FireServer({exit = true}) end)
                                settled = true
                            else
                                local pick = dialogData.choices[1]
                                for _, choice_entry in next, dialogData.choices do
                                    -- a choice can be a plain string OR a table with a
                                    -- Text/text field (same as talk_to_nearest_npc's
                                    -- pickChoice) - stringifying the table itself
                                    -- instead of reading its text silently never
                                    -- matched "bye", which is why this went undetected.
                                    local ctext = type(choice_entry) == "table" and (choice_entry.Text or choice_entry.text) or choice_entry
                                    local lc = tostring(ctext):lower()
                                    if lc:find("bye", 1, true) then
                                        pick = choice_entry
                                        matched_fail = true
                                        settled = true
                                        break
                                    elseif lc:find("pay", 1, true) then
                                        pick = choice_entry
                                        matched_pay = true
                                    end
                                end
                                pcall(function() dialogue_remote:FireServer({choice = pick}) end)
                            end
                        end)
                    end

                    local t0 = os.clock()
                    repeat
                        if cd then pcall(function() fireclickdetector(cd) end) end
                        task.wait(0.25)
                    until FindFirstChild(plr.PlayerGui, 'CaptchaLoad') or FindFirstChild(plr.PlayerGui, 'Captcha')
                       or (plr.Character and FindFirstChild(plr.Character, "InDialogue"))
                       or (os.clock() - t0) > 15

                    local result = "error"
                    if FindFirstChild(plr.PlayerGui, 'CaptchaLoad') or FindFirstChild(plr.PlayerGui, 'Captcha') then
                        repeat task.wait(0.05) until FindFirstChild(plr.PlayerGui, 'Captcha')
                        repeat
                            local captchaGUI = FindFirstChild(plr.PlayerGui, 'Captcha')
                            local choices = captchaGUI and captchaGUI.MainFrame.Options:GetChildren()
                            local union = captchaGUI and captchaGUI.MainFrame.Viewport.Union
                            utility:random_wait(true)
                            if choices and union then
                                local answer = solveCaptcha(union)
                                for _, v in next, choices do
                                    if v.Name == answer then
                                        local objVector = v.AbsolutePosition
                                        vim:SendMouseButtonEvent(objVector.X + 65, objVector.Y + 65, 0, true, game, 0)
                                        utility:random_wait(true)
                                        vim:SendMouseButtonEvent(objVector.X + 65, objVector.Y + 65, 0, false, game, 0)
                                        break
                                    end
                                end
                            end
                            task.wait(1)
                        until not FindFirstChild(plr.PlayerGui, 'Captcha')
                        local settle_t0 = os.clock()
                        repeat task.wait(0.2) until settled or (os.clock() - settle_t0) > 15
                        result = matched_pay and "success" or "fail"
                    elseif plr.Character and FindFirstChild(plr.Character, "InDialogue") then
                        local settle_t0 = os.clock()
                        repeat task.wait(0.2) until settled or (os.clock() - settle_t0) > 15
                        result = matched_pay and "success" or "fail"
                    end

                    if conn then pcall(function() conn:Disconnect() end) end
                    return result
                end

                -- INGREDIENT loop helpers (works for ANY path, not just the full bot): a
                -- Repeat (Ingredient) block loops the gather route until the Backpack holds
                -- >= goal of the ingredient (Quantity-summed like hasMaterials). On loop-back
                -- it walks the Return Points (a separate return route, only used inside that
                -- repeat) instead of a far air-jump, and a Return Serverhop can hop for a
                -- fresh server and resume mid-gather.
                local function count_ing(name)
                    local n = 0
                    local bp = FindFirstChild(plr, "Backpack")
                    if bp then
                        for _, v in ipairs(bp:GetChildren()) do
                            if v.Name == name then
                                local q = FindFirstChild(v, "Quantity")
                                n = n + (q and q.Value or 1)
                            end
                        end
                    end
                    return n
                end
                local function skip_returns_after(end_idx)
                    local j = end_idx + 1
                    while j <= #xp_path and xp_path[j] and xp_path[j].kind == "return" do j = j + 1 end
                    return j
                end
                local function walk_return_path(end_idx, start_idx)
                    local j = end_idx + 1
                    while j <= #xp_path and xp_path[j] and xp_path[j].kind == "return" do
                        if shared.is_unloading or not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) or xpfarm_hopping then return false end
                        local rs = xp_path[j]
                        if rs.serverhop then
                            library:Notify("Loop: Return Serverhop - hopping for fresh ingredients", 4)
                            do_path_serverhop(start_idx and (start_idx + 1) or (end_idx + 1))
                            return true
                        elseif rs.cf then
                            path_idx = j; update_path_label()
                            bot_move_to(rs.cf.Position)
                            task.wait(0.1)
                        end
                        j = j + 1
                    end
                    return false
                end
                while shared and not shared.is_unloading do
                    if Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value and #xp_path > 0 and plr.Character and not xpfarm_hopping then
                        local raw_resume = path_resume_from or 1
                        path_resume_from = nil
                        local was_manual_start = raw_resume < 0
                        local i = was_manual_start and -raw_resume or raw_resume
                        local rep_start_idx, rep_count, rep_done = nil, 0, 0
                        local rep_goal_kind, rep_goal, rep_iters = nil, 0, 0
                        local rep_ing = nil
                        classbot_kill_phase = nil   -- not farming Evil Eyes until we enter that loop
                        -- if we're RESUMING inside an Evil-Eye goal loop (started mid-path after a
                        -- hop), turn kill-counting on now so kills before the next repeat_end count
                        if i > 1 then
                            local open = nil
                            for j = 1, math.min(i, #xp_path) do
                                local k = xp_path[j] and xp_path[j].kind
                                if k == "repeat_start" then open = xp_path[j]
                                elseif k == "repeat_end" then open = nil end
                            end
                            if open and open.goal_kind == "evil"
                                and mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true" then
                                classbot_kill_phase = "evil"
                            end
                        end
                        -- (RESUME SAFETY 1 - auto re-arming Hitbox Offset on resume - was removed:
                        -- the "last offset_on/off before the resume point" scan kept misjudging
                        -- state whenever the resume index didn't land exactly where forward
                        -- execution would have, turning the offset on in places it wasn't wanted.
                        -- Offset is purely driven by the explicit offset_on/offset_off path steps
                        -- again now.)
                        -- RESUME SAFETY 2: if we're starting/resuming PAST the NEAREST
                        -- ingredient-gather loop (Scroom, Evil Eye, Sealed Shrieker, etc.) with
                        -- NONE of that ingredient in the bag - e.g. a "nearest waypoint" reroute
                        -- jumped straight past it - go back and redo it. Only checks the single
                        -- CLOSEST loop before i, never earlier ones: on a multi-lap path (Lava
                        -- Flower goal 21/41/61/81 etc.) every later lap legitimately starts at 0
                        -- of an EARLIER lap's ingredient once it's been used crafting potions -
                        -- scanning all the way back to lap 1 for that was wrongly rewinding a
                        -- bot on lap 3+ all the way to the start on every single serverhop.
                        -- Also skipped for a manual "Run Path From #" test start.
                        if i > 1 and not was_manual_start then
                            local nearest_j = nil
                            for j = i - 1, 1, -1 do
                                local s = xp_path[j]
                                if s and s.kind == "repeat_start" and s.goal_kind == "ingredient" and s.ingredient then
                                    nearest_j = j
                                    break
                                end
                            end
                            if nearest_j and count_ing(xp_path[nearest_j].ingredient) <= 0 then
                                library:Notify(string.format("Path: no %s in bag but already past that gather loop - going back to redo it", xp_path[nearest_j].ingredient), 6)
                                i = nearest_j
                            end
                        end
                        local skip_rep = test_once
                        while i <= #xp_path do
                            if shared.is_unloading or not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) or xpfarm_hopping then break end
                            path_idx = i
                            update_path_label()

                            local step = xp_path[i]
                            local jumped = false

                            -- SAFETY (generic/custom paths only - the Blademaster full bot has its
                            -- own dedicated AA-gun-safe catch-up walk, see below): if this step's
                            -- target is REALLY far from where we actually are right now (e.g. a
                            -- serverhop resume put us back at the inn), don't blindly make that huge
                            -- move - staying airborne that long risks the AA gun. Look for the
                            -- nearest waypoint instead, but ONLY within a forward-only window so it
                            -- can never skip a large chunk of the path (see BUILD 235 - this alone
                            -- is what actually fixed the "skipped past the Alchemist" bug).
                            --
                            -- BUILD 236 gated this behind actually being at the configured inn,
                            -- which turned out to misfire and stop the bot in normal situations that
                            -- have nothing to do with a hop - reverted per user report (BUILD 242).
                            if step.cf and not (mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true") then
                                local hrp_now = local_hrp and local_hrp()
                                if hrp_now then
                                    local d_target = (step.cf.Position - hrp_now.Position).Magnitude
                                    if d_target > 700 then
                                        local bi, bd = i, math.huge
                                        for j = i, math.min(i + 50, #xp_path) do
                                            local s = xp_path[j]
                                            if s.cf and s.kind ~= "return" then
                                                local dd = (s.cf.Position - hrp_now.Position).Magnitude
                                                if dd < bd then bd, bi = dd, j end
                                            end
                                        end
                                        if bi ~= i and bd < 700 then
                                            library:Notify(string.format("Path: #%d is %d studs away - going to the nearest waypoint instead (#%d, %d studs)", i, math.floor(d_target), bi, math.floor(bd)), 6)
                                            i = bi
                                            step = xp_path[i]
                                            path_idx = i
                                            update_path_label()
                                        end
                                    end
                                end
                            end

                            -- CATCH-UP after a rejoin: walk FORWARD through the consecutive points
                            -- (ground hops) up to our real progress point, skipping the actions we
                            -- already did. We must never jump straight to a far point (long air =
                            -- AA gun = ban), so during catch-up we move through positioned steps
                            -- only and ignore loops/actions/inns/hops.
                            if classbot_catchup_to and i >= classbot_catchup_to then
                                classbot_catchup_to = nil
                                library:Notify("Bot: caught up to where it was - resuming the work", 4)
                                -- resumed inside the Evil-Eye goal loop? turn kill-counting back on
                                local open = nil
                                for j = 1, math.min(i, #xp_path) do
                                    local k = xp_path[j] and xp_path[j].kind
                                    if k == "repeat_start" then open = xp_path[j]
                                    elseif k == "repeat_end" then open = nil end
                                end
                                if open and open.goal_kind == "evil"
                                    and mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true" then
                                    classbot_kill_phase = "evil"
                                end
                            end
                            local catchup = classbot_catchup_to ~= nil
                            if catchup then
                                -- pure consecutive walk: move through positioned steps ONLY (ground
                                -- hops), no actions/loops/inns/hops - avoids the AA-gun far jump.
                                -- (Return Points aren't part of the forward route, so skip them.)
                                if step.cf and step.kind ~= "return" then path_idx = i; update_path_label(); bot_move_to(step.cf.Position); task.wait(0.03) end
                            elseif step.kind == "repeat_start" then
                                -- begin a loop block. Two modes:
                                --  * GOAL loop (full bot Evil-Eye/Shrieker): runs until 20 real
                                --    kills / turn-ins, regardless of how many rounds that takes.
                                --  * round loop: repeat step.count times (persistent for the full bot).
                                -- Either way the progress is in mem so it survives serverhops, and a
                                -- block whose goal is already met is skipped on resume.
                                rep_start_idx = i
                                rep_count = step.count or 1
                                rep_goal_kind, rep_goal, rep_iters = nil, 0, 0
                                rep_ing = nil
                                if step.goal_kind == "ingredient" then
                                    -- INGREDIENT loop: keep gathering until we have enough. Works
                                    -- for any path. If we ALREADY have enough, don't jump to the
                                    -- exit (that's a long air-hop = AA gun) - WALK THROUGH the
                                    -- block's points (consecutive ground hops, no gathering) to
                                    -- reach the Repeat End, which then skips past the Return Points.
                                    rep_goal_kind, rep_goal, rep_ing = "ingredient", step.goal or 1, step.ingredient or ""
                                    local prog = count_ing(rep_ing)
                                    if prog >= rep_goal then
                                        local e = find_repeat_end(i)
                                        if e then
                                            classbot_catchup_to = e
                                            library:Notify(string.format("Loop: already have %d %s - walking through to the exit", prog, rep_ing), 3)
                                        else
                                            rep_start_idx = nil; rep_goal_kind = nil; rep_ing = nil
                                        end
                                    else
                                        library:Notify(string.format("Loop: %s %d/%d", rep_ing, prog, rep_goal), 3)
                                    end
                                elseif classbot_goal_active(step) then
                                    rep_goal_kind, rep_goal = step.goal_kind, step.goal
                                    if rep_goal_kind == "evil" then classbot_kill_phase = "evil" end
                                    local prog = classbot_goal_count(rep_goal_kind)
                                    if prog >= rep_goal then
                                        if rep_goal_kind == "evil" then classbot_kill_phase = nil end
                                        local e = find_repeat_end(i)
                                        if e then i = e + 1; jumped = true; rep_start_idx = nil; rep_goal_kind = nil end
                                    else
                                        library:Notify(string.format("Bot: %s %d/%d", rep_goal_kind == "evil" and "Evil Eyes killed" or "Shriekers turned in", prog, rep_goal), 3)
                                    end
                                else
                                    local rkey = classbot_rep_key(i)
                                    rep_done = (rkey and tonumber(mem:GetItem(rkey))) or 0
                                    if rkey and rep_done >= rep_count then
                                        local e = find_repeat_end(i)
                                        if e then i = e + 1; jumped = true; rep_start_idx = nil end
                                    else
                                        library:Notify(string.format("Path: repeat %d/%d", rep_done, rep_count), 3)
                                    end
                                end
                            elseif step.kind == "repeat_end" then
                                if not rep_start_idx then
                                    -- resumed in the MIDDLE of a loop: re-bind to its start so
                                    -- the count/goal keeps going (and reload the persistent progress)
                                    rep_start_idx = find_repeat_start(i)
                                    if rep_start_idx then
                                        local rs = xp_path[rep_start_idx]
                                        rep_count = (rs and rs.count) or 1
                                        if rs and rs.goal_kind == "ingredient" then
                                            rep_goal_kind, rep_goal, rep_ing = "ingredient", rs.goal or 1, rs.ingredient or ""
                                        elseif classbot_goal_active(rs) then
                                            rep_goal_kind, rep_goal = rs.goal_kind, rs.goal
                                            if rep_goal_kind == "evil" then classbot_kill_phase = "evil" end
                                        else
                                            local rkey = classbot_rep_key(rep_start_idx)
                                            rep_done = (rkey and tonumber(mem:GetItem(rkey))) or 0
                                        end
                                    end
                                end
                                if rep_goal_kind == "ingredient" then
                                    -- INGREDIENT loop end: if we still don't have enough, walk the
                                    -- Return Points back to the gather start (or Return Serverhop for
                                    -- a fresh server) and go again; once we do, skip past the returns.
                                    local prog = rep_ing and count_ing(rep_ing) or 0
                                    if (not skip_rep) and rep_start_idx and prog < rep_goal then
                                        library:Notify(string.format("Loop: %s %d/%d - going back for more", rep_ing, prog, rep_goal), 2)
                                        local hopped = walk_return_path(i, rep_start_idx)
                                        if hopped then break end
                                        i = rep_start_idx + 1
                                        jumped = true
                                    else
                                        if rep_start_idx then library:Notify(string.format("Loop: %s goal reached (%d/%d)", rep_ing, prog, rep_goal), 4) end
                                        i = skip_returns_after(i); jumped = true
                                        rep_start_idx = nil; rep_goal_kind = nil; rep_ing = nil
                                    end
                                elseif rep_goal_kind then
                                    -- GOAL loop: keep looping until the real goal is hit
                                    rep_iters = rep_iters + 1
                                    local prog = classbot_goal_count(rep_goal_kind)
                                    local label = rep_goal_kind == "evil" and "Evil Eyes" or "Shriekers"
                                    if (not skip_rep) and rep_start_idx and prog < rep_goal and rep_iters < 99 then
                                        library:Notify(string.format("Bot: %s %d/%d - keep going", label, prog, rep_goal), 2)
                                        i = rep_start_idx + 1
                                        jumped = true
                                    else
                                        library:Notify(string.format("Bot: %s goal reached (%d/%d)", label, prog, rep_goal), 4)
                                        if rep_goal_kind == "evil" then classbot_kill_phase = nil end
                                        if rep_goal_kind == "shrieker" then
                                            -- shriekers done: safer to skip illusionist servers
                                            -- for the rest of the run (turning in Uber, Khei boat, etc.)
                                            pcall(function() mem:SetItem("xpfarm_skip_illus", "true") end)
                                            if Toggles.xpfarm_skip_illus and not Toggles.xpfarm_skip_illus.Value then
                                                pcall(function() Toggles.xpfarm_skip_illus:SetValue(true) end)
                                            end
                                            library:Notify("Bot: shriekers done - Skip Illusionist Servers turned ON", 5)
                                        end
                                        rep_start_idx = nil; rep_goal_kind = nil
                                    end
                                else
                                    rep_done = rep_done + 1
                                    if rep_start_idx then
                                        local rkey = classbot_rep_key(rep_start_idx)
                                        if rkey then pcall(function() mem:SetItem(rkey, tostring(rep_done)) end) end
                                    end
                                    if (not skip_rep) and rep_start_idx and rep_done < rep_count then
                                        library:Notify(string.format("Path: repeat %d/%d - looping back", rep_done, rep_count), 2)
                                        i = rep_start_idx + 1
                                        jumped = true
                                    else
                                        if rep_start_idx then library:Notify(string.format("Path: repeat block done (%d)", rep_done), 3) end
                                        rep_start_idx = nil
                                    end
                                end
                            elseif step.kind == "return" then
                                -- Return Point / Return Serverhop: only used by the ingredient
                                -- loop-back (walk_return_path). Reached in the normal forward flow
                                -- (e.g. a stray resume landed here) it's a no-op we step past.
                            elseif step.kind == "end_path" then
                                library:Notify("Path: End Path reached - returning to menu and stopping", 4)
                                if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(false) end
                                task.wait(1)
                                pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)
                                break
                            elseif step.kind == "skill_gate" then
                                -- checks the Backpack for the named skill item(s) (case-insensitive
                                -- substring match, since we don't know the exact capitalization
                                -- the game uses) - if any are missing, physically walk back through
                                -- the recorded points to redo_from and retry that segment instead
                                -- of raw-jumping the index (a raw jump leaves the next step's
                                -- target far away, which fights the far-target reroute - same
                                -- lesson as the potion-retry fix, BUILD 224).
                                -- Accepts either step.skills (a list - ALL must be present) or the
                                -- older single step.skill string, for backward compatibility.
                                if not catchup then
                                    local wanted = {}
                                    if type(step.skills) == "table" and #step.skills > 0 then
                                        for _, s in ipairs(step.skills) do table.insert(wanted, tostring(s)) end
                                    elseif step.skill and tostring(step.skill) ~= "" then
                                        table.insert(wanted, tostring(step.skill))
                                    end
                                    local function has_item(want)
                                        want = want:lower()
                                        local bp = FindFirstChild(plr, "Backpack")
                                        if bp then
                                            for _, v in ipairs(bp:GetChildren()) do
                                                if tostring(v.Name):lower():find(want, 1, true) then return true end
                                            end
                                        end
                                        local char = plr.Character
                                        if char then
                                            for _, v in ipairs(char:GetChildren()) do
                                                if tostring(v.Name):lower():find(want, 1, true) then return true end
                                            end
                                        end
                                        return false
                                    end
                                    local missing = {}
                                    for _, w in ipairs(wanted) do
                                        if not has_item(w) then table.insert(missing, w) end
                                    end
                                    if #wanted == 0 or #missing == 0 then
                                        library:Notify("Path: skill check OK - have " .. table.concat(wanted, ", "), 3)
                                    else
                                        local redo_to = tonumber(step.redo_from)
                                        if redo_to and redo_to >= 1 and redo_to <= i then
                                            library:Notify(string.format("Path: missing %s - walking back to redo waypoint #%d", table.concat(missing, ", "), redo_to), 6)
                                            for j = i, redo_to, -1 do
                                                if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                                    and shared and not shared.is_unloading) then break end
                                                local ps = xp_path[j]
                                                if ps and ps.cf and ps.kind ~= "return" then
                                                    bot_move_to(ps.cf.Position)
                                                end
                                            end
                                            i = redo_to
                                            jumped = true
                                        else
                                            library:Notify(string.format("Path: missing %s and no valid redo point set - continuing anyway", table.concat(missing, ", ")), 6)
                                        end
                                    end
                                end
                            elseif step.kind == "smart_skill_skip" then
                                -- runs once at the very start of a multi-segment path (e.g. the
                                -- combined druid path): checks EVERY segment's skill up front, not
                                -- just the next one, so a partially-completed run (e.g. already has
                                -- Herbivore + Duplicate from before) jumps straight to the first
                                -- segment it's actually still missing instead of redoing segments
                                -- it doesn't need to. No physical walking needed - this fires before
                                -- any movement has happened yet, so a plain index jump is fine.
                                if not catchup and type(step.checks) == "table" then
                                    local function has_item(want)
                                        want = tostring(want):lower()
                                        local bp = FindFirstChild(plr, "Backpack")
                                        if bp then
                                            for _, v in ipairs(bp:GetChildren()) do
                                                if tostring(v.Name):lower():find(want, 1, true) then return true end
                                            end
                                        end
                                        local char = plr.Character
                                        if char then
                                            for _, v in ipairs(char:GetChildren()) do
                                                if tostring(v.Name):lower():find(want, 1, true) then return true end
                                            end
                                        end
                                        return false
                                    end
                                    local target = nil
                                    for _, check in ipairs(step.checks) do
                                        if check.skill and not has_item(check.skill) then
                                            target = tonumber(check.target)
                                            break
                                        end
                                    end
                                    if not target and step.all_done_goto then
                                        target = tonumber(step.all_done_goto)
                                    end
                                    if target and target > i then
                                        library:Notify(string.format("Path: already have earlier skills - skipping ahead to point #%d", target), 6)
                                        i = target
                                        jumped = true
                                    end
                                end
                            elseif step.kind == "smart_ingredient_skip" then
                                -- same idea as smart_skill_skip but for turn-in ingredients
                                -- (Cursed Tag / Evil Eye / Shrieker Heart) instead of skills: if
                                -- want_all is fully satisfied, skip straight to target_all (e.g.
                                -- already have both Cursed Tag and Evil Eye - jump all the way to
                                -- the Castle Sanctuary inn step, skipping both farm segments
                                -- entirely). Otherwise if want_any is satisfied, skip to target_any
                                -- (e.g. already have Cursed Tag - skip just the shrieker segment
                                -- and go straight to evil eyes). If neither, no jump - just start
                                -- the segment normally from here.
                                if not catchup then
                                    local function has_item(want)
                                        want = tostring(want):lower()
                                        local bp = FindFirstChild(plr, "Backpack")
                                        if bp then
                                            for _, v in ipairs(bp:GetChildren()) do
                                                if tostring(v.Name):lower():find(want, 1, true) then return true end
                                            end
                                        end
                                        local char = plr.Character
                                        if char then
                                            for _, v in ipairs(char:GetChildren()) do
                                                if tostring(v.Name):lower():find(want, 1, true) then return true end
                                            end
                                        end
                                        return false
                                    end
                                    local target = nil
                                    if type(step.want_all) == "table" and #step.want_all > 0 and step.target_all then
                                        local all_owned = true
                                        for _, w in ipairs(step.want_all) do
                                            if not has_item(w) then all_owned = false; break end
                                        end
                                        if all_owned then target = tonumber(step.target_all) end
                                    end
                                    if not target and step.want_any and step.target_any and has_item(step.want_any) then
                                        target = tonumber(step.target_any)
                                    end
                                    if target and target > i then
                                        library:Notify(string.format("Path: already have the needed ingredient(s) - skipping ahead to point #%d", target), 6)
                                        i = target
                                        jumped = true
                                    end
                                end
                            elseif step.kind == "wait_ores" then
                                -- gate: hold here until non-Tin ores exist (respawn), then continue
                                if (not catchup) and not ores_exist() then
                                    library:Notify("Path: waiting for ores to spawn (ignoring Tin)...", 4)
                                    while Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading and not ores_exist() do
                                        task.wait(1)
                                    end
                                    if Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value then
                                        library:Notify("Path: ores detected - continuing", 3)
                                    end
                                end
                            elseif step.kind == "wait_ingredient" then
                                -- gate: hold here until we have >= the required amount of an
                                -- ingredient (summing the Quantity of matching Backpack items).
                                if not catchup then
                                    local ing = step.ingredient or ""
                                    local need = tonumber(step.amount) or 1
                                    local function ing_count()
                                        local n = 0
                                        local bp = FindFirstChild(plr, "Backpack")
                                        if bp then
                                            for _, v in ipairs(bp:GetChildren()) do
                                                if v.Name == ing then
                                                    local q = FindFirstChild(v, "Quantity")
                                                    n = n + (q and q.Value or 1)
                                                end
                                            end
                                        end
                                        return n
                                    end
                                    if ing_count() < need then
                                        library:Notify(string.format("Gate: waiting for %d %s (have %d)...", need, ing, ing_count()), 4)
                                        while Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading and ing_count() < need do
                                            task.wait(1)
                                        end
                                        if Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value then
                                            library:Notify(string.format("Gate: have %d %s - continuing", need, ing), 3)
                                        end
                                    end
                                end
                            elseif step.kind == "serverhop" then
                                -- during catch-up, walk PAST a serverhop waypoint (don't hop again)
                                if not catchup then
                                    library:Notify("Path: Serverhop point - hopping + will resume", 4)
                                    do_path_serverhop(i + 1)
                                    break
                                end
                            elseif step.kind == "npc_captcha" then
                                if not catchup then
                                    library:Notify("Path: CR Captcha - talking to " .. tostring(step.npc_name), 4)
                                    local result = npc_talk_captcha(step.npc_name)
                                    -- "error" (couldn't reach the NPC, no captcha ever showed
                                    -- up, or the outcome was never positively confirmed) is
                                    -- treated the SAME as a failed captcha, not a shrug-and-
                                    -- continue - continuing on an unconfirmed captcha is
                                    -- exactly what risks a ban here.
                                    if result == "success" then
                                        library:Notify("Path: CR captcha solved", 4)
                                    else
                                        library:Notify("Path: CR captcha " .. (result == "fail" and "FAILED" or "unconfirmed")
                                            .. " - resetting and waiting 6 min before redoing the path", 8)
                                        if plr.Character then pcall(function() plr.Character:BreakJoints() end) end
                                        local wait_t0 = os.clock()
                                        while (os.clock() - wait_t0) < 360
                                            and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading do
                                            task.wait(1)
                                        end
                                        path_resume_from = 1
                                        break
                                    end
                                end
                            elseif step.kind == "wait_timer" then
                                if not catchup then
                                    local mins = tonumber(step.minutes) or 15
                                    library:Notify(string.format("Path: waiting %d minute(s) here...", mins), 5)
                                    local wait_t0 = os.clock()
                                    while (os.clock() - wait_t0) < (mins * 60)
                                        and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading do
                                        task.wait(1)
                                    end
                                end
                            elseif step.kind == "wait_day" then
                                if not catchup then
                                    local target_day = tonumber(step.day) or 1
                                    library:Notify(string.format("Path: waiting here until Day %d...", target_day), 5)
                                    while Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading do
                                        local ok, cur = pcall(function()
                                            return rps.Requests.Get:InvokeServer(utf8.char(65532) .. "\240\159\152\131", "DaysSurvived")["DaysSurvived"]
                                        end)
                                        if ok and type(cur) == "number" and cur >= target_day then
                                            break
                                        end
                                        task.wait(5)
                                    end
                                end
                            elseif step.kind == "orderly_n" then
                              -- Wrapped in a genuine nested function (not just do...end) so its
                              -- locals get their own fresh register scope instead of adding to
                              -- this already-near-the-limit closure's peak concurrent count
                              -- (see BUILD 219/229/230/231's compile-failure history above).
                              pcall(function()
                                if not catchup then
                                    local target_n = math.max(1, math.floor(tonumber(step.count) or 1))
                                    library:Notify(string.format("Path: Loop Orderly x%d starting...", target_n), 4)
                                    print(string.format("[ORDERLY] starting, target=%d", target_n))
                                    local done = 0
                                    local equip_fail_streak = 0
                                    while done < target_n
                                        and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading do
                                        print(string.format("[ORDERLY] rep %d/%d: checking Danger tag", done, target_n))
                                        -- wait out of Danger before each cycle, same gate the
                                        -- always-on "Loop Gain Orderly" toggle uses
                                        local wait_t0 = os.clock()
                                        while plr.Character and cs:HasTag(plr.Character, "Danger")
                                            and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading
                                            and (os.clock() - wait_t0) < 60 do
                                            task.wait(0.5)
                                        end
                                        if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) or (shared and shared.is_unloading) then
                                            print("[ORDERLY] path stopped/unloading, exiting")
                                            break
                                        end

                                        local elixir = plr.Backpack and FindFirstChild(plr.Backpack, "Tespian Elixir")
                                        print(string.format("[ORDERLY] rep %d/%d: elixir in backpack = %s", done, target_n, tostring(elixir ~= nil)))
                                        if not elixir then
                                            library:Notify(string.format("Path: Loop Orderly out of Tespian Elixirs (%d/%d done) - continuing path", done, target_n), 6)
                                            break
                                        end

                                        pcall(function() plr.Character.Humanoid:EquipTool(elixir) end)
                                        task.wait(0.3)

                                        local equippedElixir = plr.Character and FindFirstChild(plr.Character, "Tespian Elixir")
                                        local hasRemote = equippedElixir and FindFirstChild(equippedElixir, "RemoteEvent")
                                        print(string.format("[ORDERLY] rep %d/%d: equipped=%s hasRemote=%s", done, target_n, tostring(equippedElixir ~= nil), tostring(hasRemote ~= nil)))
                                        if hasRemote then
                                            equip_fail_streak = 0
                                            equippedElixir.RemoteEvent:FireServer(plr.Character.HumanoidRootPart.CFrame, "Part", "Self")
                                            print("[ORDERLY] fired drink remote")

                                            -- Deliberately reset BEFORE the server finishes consuming
                                            -- the elixir - that's the whole point (get the drink's
                                            -- effect, keep the item so the same elixir survives the
                                            -- respawn and can be reused next rep). Don't wait for
                                            -- consumption here, just the tunable delay - same as the
                                            -- always-on "Loop Gain Orderly" toggle uses.
                                            local old_character = plr.Character
                                            task.wait((Options and Options.loop_orderly_delay and Options.loop_orderly_delay.Value) or 2)
                                            pcall(function() plr.Character:BreakJoints() end)
                                            print("[ORDERLY] BreakJoints called")

                                            -- Wait for the character reference to actually change
                                            -- before checking Immortal at all - right after
                                            -- BreakJoints, plr.Character can still be the OLD (dying)
                                            -- character for a moment, and if IT already had a leftover
                                            -- Immortal child from earlier, the check below would read
                                            -- that stale one and think the new respawn already
                                            -- finished before it even started.
                                            local newchar_t0 = os.clock()
                                            repeat task.wait(0.2)
                                            until (plr.Character and plr.Character ~= old_character) or (os.clock() - newchar_t0) > 20
                                            print(string.format("[ORDERLY] new character seen=%s (%.1fs)", tostring(plr.Character ~= old_character), os.clock() - newchar_t0))

                                            -- Wait for the respawn's Immortal grace period to both
                                            -- START and FULLY CLEAR before the next rep, so the new
                                            -- character/backpack are actually settled (this is the
                                            -- "wait for the loop to go through" step that was missing -
                                            -- previously the next rep started the instant Immortal
                                            -- appeared, often before the respawn had really finished).
                                            local immortal_t0 = os.clock()
                                            repeat task.wait(0.5)
                                            until FindFirstChild(plr.Character, "Immortal") or (os.clock() - immortal_t0) > 20
                                            print(string.format("[ORDERLY] immortal appeared=%s (%.1fs)", tostring(FindFirstChild(plr.Character, "Immortal") ~= nil), os.clock() - immortal_t0))

                                            local clear_t0 = os.clock()
                                            repeat task.wait(0.5)
                                            until not FindFirstChild(plr.Character, "Immortal") or (os.clock() - clear_t0) > 30
                                            print(string.format("[ORDERLY] immortal cleared (%.1fs)", os.clock() - clear_t0))

                                            task.wait(0.5) -- small settle buffer for backpack/character to finish populating

                                            done = done + 1
                                            print(string.format("[ORDERLY] rep complete, done=%d/%d", done, target_n))
                                        else
                                            equip_fail_streak = equip_fail_streak + 1
                                            print(string.format("[ORDERLY] equip failed, streak=%d", equip_fail_streak))
                                            if equip_fail_streak >= 8 then
                                                library:Notify(string.format("Path: Loop Orderly stuck re-equipping the elixir (%d/%d done) - giving up, continuing path", done, target_n), 6)
                                                print("[ORDERLY] giving up after repeated equip failures")
                                                break
                                            end
                                            task.wait(1)
                                        end
                                    end
                                    library:Notify(string.format("Path: Loop Orderly done (%d/%d)", done, target_n), 4)
                                    print(string.format("[ORDERLY] finished, done=%d/%d", done, target_n))
                                end
                              end)
                            elseif step.kind == "reset_if_safe" then
                                if not catchup then
                                    if plr.Character and not cs:HasTag(plr.Character, "Danger") then
                                        library:Notify("Path: resetting (out of danger)", 4)
                                        pcall(function() plr.Character:BreakJoints() end)
                                        local old_char = plr.Character
                                        local t0 = os.clock()
                                        repeat task.wait(0.25)
                                        until (plr.Character and plr.Character ~= old_char)
                                            or (os.clock() - t0) > 20
                                            or not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value)
                                    else
                                        library:Notify("Path: skipping reset - in Danger", 4)
                                    end
                                end
                            elseif step.kind == "inn" then
                                -- teleport + rent (BreakJoints respawns at the inn), then CONFIRM
                                -- we actually respawned before moving on. Retry the whole rent up to
                                -- 3x if the teleport to the inn didn't take - the bot must not walk
                                -- the next leg from the wrong place because an inn hop silently failed.
                                -- (skipped during catch-up: we're already bound at the inn after a hop)
                                if not catchup then
                                local inn_ok = false
                                for _ = 1, 4 do
                                    if shared and shared.is_unloading then break end
                                    local old_char = plr.Character
                                    rent_at_inn_nearby(step.inn)
                                    local t0 = os.clock()
                                    repeat task.wait(0.25)
                                    until (shared and shared.is_unloading)
                                        or (plr.Character and plr.Character ~= old_char and FindFirstChild(plr.Character, "HumanoidRootPart"))
                                        or (os.clock() - t0 > 25)
                                    local respawned = plr.Character and plr.Character ~= old_char and FindFirstChild(plr.Character, "HumanoidRootPart")
                                    if respawned then
                                        -- respawned - now CONFIRM we actually landed at the inn
                                        -- (near the keeper), not somewhere else. Give the spawn a
                                        -- moment to settle before measuring.
                                        task.wait(0.5)
                                        local pos_ok = at_inn(step.inn)   -- true / false / nil (unverifiable)
                                        if pos_ok == false then
                                            library:Notify("Inn: respawned but NOT at " .. tostring(step.inn) .. " - retrying...", 4)
                                        else
                                            inn_ok = true
                                            library:Notify(pos_ok and ("Inn: confirmed at " .. tostring(step.inn))
                                                or ("Inn: respawned at " .. tostring(step.inn) .. " (spot unverifiable)"), 3)
                                            break
                                        end
                                    else
                                        library:Notify("Inn: teleport/rent didn't take - retrying...", 4)
                                    end
                                    if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) then break end
                                end
                                if not inn_ok then library:Notify("Inn: couldn't confirm the inn teleport (4 tries) - continuing anyway", 5) end
                                task.wait(1.5)
                                last_monster_seen = os.clock()
                                end  -- not catchup (inn)
                            elseif step.kind == "offset_on" or step.kind == "offset_off" then
                                -- toggle the hitbox offset mid-path: ON before the
                                -- shrieker swarm, OFF at the turn-in NPC
                                if Toggles.xpfarm_hitbox_air then
                                    Toggles.xpfarm_hitbox_air:SetValue(step.kind == "offset_on")
                                    library:Notify(step.kind == "offset_on" and "Path: Hitbox Offset ON" or "Path: Hitbox Offset OFF", 3)
                                end
                                task.wait(0.15)
                            elseif step.kind == "autoing_on" or step.kind == "autoing_off" then
                                -- toggle the game's Auto Ingredient pickup mid-path (ON before
                                -- an ingredient-gathering loop, OFF when done)
                                if Toggles.auto_ingredient then
                                    Toggles.auto_ingredient:SetValue(step.kind == "autoing_on")
                                    library:Notify(step.kind == "autoing_on" and "Path: Auto Ingredient Pickup ON" or "Path: Auto Ingredient Pickup OFF", 3)
                                end
                                task.wait(0.15)
                            elseif step.kind == "autobag_on" or step.kind == "autobag_off" then
                                -- toggle the game's Auto Bag floor pickup mid-path (ON before a
                                -- monster-drop farm loop so kills' drops get bagged, OFF when done)
                                if Toggles.auto_bag then
                                    Toggles.auto_bag:SetValue(step.kind == "autobag_on")
                                    library:Notify(step.kind == "autobag_on" and "Path: Auto Bag Pickup ON" or "Path: Auto Bag Pickup OFF", 3)
                                end
                                task.wait(0.15)
                            elseif step.kind == "instmine_on" or step.kind == "instmine_off" then
                                -- toggle the manual-mouse-click instant mine hook mid-path
                                if Toggles.instant_mine then
                                    Toggles.instant_mine:SetValue(step.kind == "instmine_on")
                                    library:Notify(step.kind == "instmine_on" and "Path: Instant Mine ON" or "Path: Instant Mine OFF", 3)
                                end
                                task.wait(0.15)
                            elseif step.kind == "orderly_on" or step.kind == "orderly_off" then
                                -- toggle "Loop Gain Orderly" mid-path (the potion-drink -> kill
                                -- farm loop). Lets a path arm it only while standing at the
                                -- Orderly farm spot and disarm it again before moving on.
                                if Toggles.loop_orderly then
                                    Toggles.loop_orderly:SetValue(step.kind == "orderly_on")
                                    library:Notify(step.kind == "orderly_on" and "Path: Loop Orderly ON" or "Path: Loop Orderly OFF", 3)
                                end
                                task.wait(0.15)
                            elseif step.kind == "skipillus_on" or step.kind == "skipillus_off" then
                                -- toggle "Skip Illusionist Servers" mid-path (e.g. right after a
                                -- Sealed Shrieker Grip section, same idea as the existing auto-arm
                                -- that happens once a repeat-block shrieker farm finishes).
                                -- This was setting Toggles.SkipIllusionist, which is Trinket Bot's
                                -- OWN separate toggle - XP Farm's actual serverhop-time check reads
                                -- the xpfarm_skip_illus mem flag/toggle instead, so this waypoint
                                -- was silently doing nothing for XP Farm paths. Fixed to set the
                                -- right one, and also check immediately instead of only reacting to
                                -- future joins/backpack changes.
                                local turning_on = step.kind == "skipillus_on"
                                pcall(function() mem:SetItem("xpfarm_skip_illus", turning_on and "true" or "false") end)
                                if Toggles.xpfarm_skip_illus and Toggles.xpfarm_skip_illus.Value ~= turning_on then
                                    pcall(function() Toggles.xpfarm_skip_illus:SetValue(turning_on) end)
                                end
                                library:Notify(turning_on and "Path: Skip Illusionist Servers ON" or "Path: Skip Illusionist Servers OFF", 3)

                                if turning_on and server_has_illusionist() then
                                    library:Notify("Path: Illusionist already in server - hopping now", 5)
                                    pcall(function() mem:SetItem("xpfarm_resume_active", "true") end)
                                    pcall(function() mem:SetItem("xpfarm_resume_idx", tostring(i)) end)
                                    cheat_client.config.execute_on_serverhop = true
                                    pcall(xpfarm_fast_serverhop)
                                    return
                                end
                                task.wait(0.15)
                            elseif step.kind == "equip_pickaxe" then
                                local char = plr.Character
                                local hum = char and FindFirstChildOfClass(char, "Humanoid")
                                local pick = char and FindFirstChild(char, "Pickaxe")
                                if not pick then
                                    local bp = FindFirstChild(plr, "Backpack")
                                    pick = bp and FindFirstChild(bp, "Pickaxe")
                                end
                                if hum and pick then
                                    pcall(function() hum:EquipTool(pick) end)
                                    library:Notify("Path: Pickaxe equipped", 3)
                                else
                                    library:Notify("Path: no Pickaxe in your bag", 5)
                                end
                                task.wait(0.15)
                            elseif step.kind == "equip_item" then
                              pcall(function()
                                if not catchup then
                                    local item_name = step.item_name
                                    library:Notify(string.format("Path: equipping '%s'...", tostring(item_name)), 3)
                                    -- The item may have just been handed over by an NPC's dialogue
                                    -- moments earlier and not have replicated into the backpack yet,
                                    -- so retry for a bit instead of failing on the first miss.
                                    local found_tool = nil
                                    local wait_t0 = os.clock()
                                    while (os.clock() - wait_t0) < 15
                                        and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading do
                                        local char = plr.Character
                                        found_tool = (char and FindFirstChild(char, item_name))
                                            or (plr.Backpack and FindFirstChild(plr.Backpack, item_name))
                                        if found_tool then break end
                                        task.wait(0.5)
                                    end
                                    local hum = plr.Character and FindFirstChildOfClass(plr.Character, "Humanoid")
                                    if hum and found_tool then
                                        pcall(function() hum:EquipTool(found_tool) end)
                                        library:Notify(string.format("Path: '%s' equipped", tostring(item_name)), 3)
                                    else
                                        library:Notify(string.format("Path: '%s' not found in bag/character - continuing anyway", tostring(item_name)), 6)
                                    end
                                    task.wait(0.15)
                                end
                              end)
                            elseif step.kind == "tp_menu" then
                              -- Wrapped in a genuine nested function (not just do...end) so its
                              -- ~17 locals get their own fresh register scope instead of adding
                              -- to this already-near-the-limit closure's peak concurrent count
                              -- (see BUILD 219/229/230/231's compile-failure history above).
                              pcall(function()
                                if not catchup then
                                    -- x/y/z are baked into the step itself at Add Waypoint time,
                                    -- not looked up by name at run time - so this doesn't depend
                                    -- on a matching entry existing in teleport_points.json (which
                                    -- could be missing, renamed, or just not there for whoever
                                    -- else runs this path).
                                    local loc_name = step.label or "saved spot"
                                    if not (step.x and step.y and step.z) then
                                        library:Notify("Path: Teleport Menu step has no position saved", 6)
                                    else
                                        local target_pos = Vector3.new(step.x, step.y, step.z)
                                        local landed = false
                                        for attempt = 1, 3 do
                                            if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) or (shared and shared.is_unloading) then break end
                                            library:Notify(string.format("Path: Teleport Menu to '%s' (attempt %d/3)...", loc_name, attempt), 3)

                                            local root = local_hrp()
                                            if not root then break end
                                            local char = plr.Character
                                            local humanoid = char and FindFirstChildOfClass(char, "Humanoid")
                                            if humanoid then pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end) end
                                            root.CFrame = root.CFrame + Vector3.new(0, 50, 0)
                                            task.wait(0.25)

                                            root = local_hrp()
                                            if not root then break end
                                            root.CFrame = CFrame.new(target_pos)
                                            pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
                                            pcall(function() root.AssemblyAngularVelocity = Vector3.new(0, 0, 0) end)

                                            -- race the menu spam against whatever sends you back
                                            -- (anti-cheat correction/etc) - spam every frame instead
                                            -- of sleeping between fires, starting immediately.
                                            local spam_t0 = os.clock()
                                            local fired_ok = false
                                            while (os.clock() - spam_t0) < 1.5 do
                                                local ok = pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)
                                                if ok then fired_ok = true end
                                                task.wait()
                                            end
                                            if not fired_ok then
                                                library:Notify("Path: Teleport Menu - couldn't fire the menu request, retrying", 4)
                                                task.wait(1)
                                                continue
                                            end

                                            -- WaitForChild on StartMenu only guarantees the top-level
                                            -- GUI object exists, not that Choices/Play (or its own
                                            -- click-handler connection) have finished setting up
                                            -- underneath it yet - firing the instant we find them was
                                            -- clicking Play too early sometimes. Chain WaitForChild
                                            -- all the way down plus a short settle wait.
                                            local ok_menu, startMenu = pcall(function() return plr.PlayerGui:WaitForChild("StartMenu", 30) end)
                                            if ok_menu and startMenu then
                                                local ok_choices, choices = pcall(function() return startMenu:WaitForChild("Choices", 10) end)
                                                if ok_choices and choices then
                                                    local ok_play, playBtn = pcall(function() return choices:WaitForChild("Play", 10) end)
                                                    if ok_play and playBtn then
                                                        task.wait(0.5) -- let its click handler actually finish binding
                                                        pcall(function() firesignal(playBtn.MouseButton1Click) end)
                                                    end
                                                end
                                            end

                                            -- wait for the character to actually respawn back in,
                                            -- then check whether it landed near the target - if the
                                            -- position didn't take (anti-cheat corrected it, or the
                                            -- menu/rejoin dropped us at the default spawn instead),
                                            -- this is what catches it and triggers a retry
                                            local respawn_t0 = os.clock()
                                            local new_root = nil
                                            while (os.clock() - respawn_t0) < 30 do
                                                new_root = local_hrp()
                                                if new_root then break end
                                                task.wait(0.5)
                                            end
                                            task.wait(1) -- small settle after respawn

                                            new_root = local_hrp()
                                            local dist = new_root and (new_root.Position - target_pos).Magnitude
                                            if new_root and dist and dist <= 100 then
                                                library:Notify(string.format("Path: Teleport Menu landed near '%s' (%.0f studs off)", loc_name, dist), 3)
                                                landed = true
                                                break
                                            else
                                                library:Notify(string.format("Path: Teleport Menu missed '%s' (%s) - retrying", loc_name, dist and (string.format("%.0f studs off", dist)) or "no character"), 4)
                                            end
                                        end
                                        if not landed then
                                            library:Notify("Path: Teleport Menu gave up after 3 attempts - continuing path", 6)
                                        end
                                    end
                                    task.wait(0.3)
                                end
                              end)
                            elseif step.cf then
                                bot_move_to(step.cf.Position)
                                -- "Skip If Already Armed" NPC (e.g. a starter-sword vendor): still
                                -- walk the point (keeps the path in order), just don't talk to /
                                -- buy from them if we already have a weapon. Also honors a
                                -- persistent "already bought this generation" mem flag - each bot
                                -- is only funded enough silver to reach Ultra, so a re-buy (e.g.
                                -- from the path restarting at point 1) would starve it of silver
                                -- it needs later, regardless of whether has_weapon() happens to
                                -- detect the purchased sword correctly.
                                local sword_bought_key = "classbot_sword_bought_" .. (mem:GetItem("classbot_gen") or "0")
                                local already_bought_sword = mem:HasItem(sword_bought_key) and mem:GetItem(sword_bought_key) == "true"
                                local skip_npc_armed = (step.kind == "npc" and step.skip_if_armed and (has_weapon() or already_bought_sword))
                                local wait_s = step.wait_time or (Options.xpfarm_path_wait and Options.xpfarm_path_wait.Value) or 4
                                if skip_npc_armed then
                                    library:Notify("Path: already armed - not buying from " .. ((step.npc_name and step.npc_name ~= "") and step.npc_name or "NPC"), 3)
                                elseif catchup then
                                    -- fast catch-up: walk through this waypoint, skip its action
                                    task.wait(0.03)
                                elseif step.kind == "npc" then
                                    local was_carrying = step.turnin and is_carrying_shrieker()
                                    -- talk_to_nearest_npc can fail to even OPEN the dialogue on the
                                    -- first try (character not quite settled after walking in, NPC
                                    -- not fully loaded yet, etc.) - retry a few times instead of
                                    -- silently skipping the interaction for this pass.
                                    local talked = false
                                    for attempt = 1, 3 do
                                        if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading) then break end
                                        talked = talk_to_nearest_npc(wait_s > 0 and wait_s or 6, step.npc_name, step.choice_sequence)
                                        if talked then break end
                                        library:Notify(("Path: talk to %s didn't fully go through - retrying (%d/3)"):format(
                                            (step.npc_name and step.npc_name ~= "") and step.npc_name or "NPC", attempt), 4)
                                        task.wait(1)
                                    end
                                    if step.skip_if_armed then
                                        pcall(function() mem:SetItem(sword_bought_key, "true") end)
                                    end
                                    if step.turnin then
                                        -- Monster Hunter turn-in: re-talk until the shrieker leaves
                                        -- our hands, then count it as a turn-in ONLY if it was a fresh
                                        -- grab (a carry-over from before a serverhop is cleared here
                                        -- but NOT counted, per the bot's no-double-count rule).
                                        local tt0 = os.clock()
                                        while is_carrying_shrieker() and (os.clock() - tt0) < 8
                                            and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading do
                                            talk_to_nearest_npc(3, step.npc_name)
                                            task.wait(0.2)
                                        end
                                        if was_carrying and not is_carrying_shrieker() then
                                            if shrk_countable then
                                                classbot_goal_add("shrieker")
                                                library:Notify(string.format("Bot: shrieker turned in (%d/20)", classbot_goal_count("shrieker")), 3)
                                            else
                                                library:Notify("Bot: cleared a carry-over shrieker (not counted)", 3)
                                            end
                                        end
                                        shrk_countable = false
                                    end
                                    -- then hold here for the point's wait time before moving on -
                                    -- some turn-ins (the Uber Sigil NPCs) respawn/cool down on a
                                    -- delay, and leaving early breaks the next interaction.
                                    local nd = 0
                                    while nd < wait_s and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading do
                                        nd = nd + task.wait(0.2)
                                    end
                                elseif step.kind == "shrieker" then
                                    -- knock down + pick up a shrieker; do NOT advance until grabbed.
                                    -- A shrieker still held from BEFORE a serverhop must NOT be counted
                                    -- (it can't be turned in for credit) - we still carry it to the
                                    -- Monster Hunter + back to clear it. Fresh grabs DO count.
                                    library:Notify("Path: grabbing a shrieker...", 3)
                                    equip_sword()   -- draw the blade so we can knock the shrieker down
                                    local already = is_carrying_shrieker()
                                    local crosshop = mem:HasItem("classbot_crosshop_shrk") and mem:GetItem("classbot_crosshop_shrk") == "1"
                                    pcall(function() mem:SetItem("classbot_crosshop_shrk", "") end)
                                    shrk_countable = not (already and crosshop)
                                    if grab_one_shrieker(step.wait_time, step.cf2, step.cf) then
                                        shrieker_done = shrieker_done + 1
                                        library:Notify(string.format("Path: shrieker picked up (#%d)%s", shrieker_done, shrk_countable and "" or " (carry-over)"), 3)
                                    else
                                        shrk_countable = false
                                        library:Notify("Path: no shrieker grabbed (timeout) - moving on", 4)
                                    end
                                elseif step.kind == "sealed" then
                                    -- knock down + GRIP (B) a Sealed Shrieker. Advance once one is
                                    -- gripped (or on timeout). Put this inside a Repeat (Monster Drop)
                                    -- to grip until you have enough of its drop.
                                    library:Notify("Path: gripping a Sealed Shrieker...", 3)
                                    equip_sword()
                                    if grip_one_sealed(step.wait_time, step.cf2, step.cf) then
                                        library:Notify("Path: Sealed Shrieker gripped", 3)
                                    else
                                        library:Notify("Path: no Sealed Shrieker gripped (timeout) - moving on", 4)
                                    end
                                elseif step.kind == "mana" then
                                    local dur = (step.wait_time and step.wait_time > 0) and step.wait_time or 30
                                    library:Notify(string.format("Path: training mana %ds", dur), 3)
                                    local mt0 = os.clock()
                                    while (os.clock() - mt0) < dur
                                        and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading do
                                        pcall(function() utility:charge_mana_until(98) end)
                                        task.wait(0.1)
                                    end
                                elseif step.kind == "potion" then
                                    -- craft the chosen potion at the cauldron. utility:craft loops
                                    -- (while auto_pot_active) until out of materials; we count the
                                    -- potion in the bag and stop at the chosen count (0 = make all).
                                    local pot = step.potion or "Health Potion"
                                    local want = tonumber(step.count) or 0
                                    -- if a serverhop interrupted this exact waypoint last time, resume
                                    -- toward what's left instead of re-crafting the full count from 0.
                                    local progress_key = "xpfarm_potion_progress_" .. tostring(i)
                                    local already = tonumber(mem:GetItem(progress_key)) or 0
                                    local want_remaining = (want > 0) and math.max(0, want - already) or want
                                    library:Notify(("Path: crafting %s%s ..."):format(pot, want > 0 and (" x" .. want_remaining .. (already > 0 and (" (" .. already .. " already done before a hop)") or "")) or " (until out of mats)"), 3)
                                    local function count_pot()
                                        local n = 0
                                        local bp = FindFirstChild(plr, "Backpack")
                                        if bp then
                                            for _, it in ipairs(bp:GetChildren()) do
                                                if it.Name == pot then
                                                    local q = FindFirstChild(it, "Quantity")
                                                    n = n + (q and q.Value or 1)
                                                end
                                            end
                                        end
                                        return n
                                    end
                                    local base = count_pot()
                                    local prev = auto_pot_active
                                    local craft_done = false
                                    -- slow the craft cadence to this waypoint's delay so it doesn't
                                    -- fire faster than the game registers (utility:craft waits
                                    -- cheat_client.config.auto_craft_delay between each pot); restore after.
                                    local prev_delay = cheat_client and cheat_client.config and cheat_client.config.auto_craft_delay
                                    local want_delay = tonumber(step.delay) or 1   -- default 1s (old paths had none -> was too fast)
                                    if cheat_client and cheat_client.config then cheat_client.config.auto_craft_delay = want_delay end
                                    auto_pot_active = true
                                    task.spawn(function() pcall(function() utility:craft("Alchemy", pot) end); craft_done = true end)
                                    -- time safety cap: an explicit wait_time (>=5) is the cap; else a
                                    -- generous default that SCALES with the count so a big batch (21+)
                                    -- can't get cut off (8s/potion headroom).
                                    local per = math.max(8, (want_delay or 1) * 4 + 4)
                                    local cap = (wait_s and wait_s >= 5) and wait_s or math.max(180, (want_remaining > 0) and (want_remaining * per) or 0)
                                    local pt0 = os.clock()
                                    local pt_last_save = 0
                                    local hit_target = false
                                    local moved_away_count = 0
                                    while Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading and (os.clock() - pt0) < cap do
                                        if craft_done then break end   -- out of materials / not at a cauldron
                                        if want_remaining > 0 and (count_pot() - base) >= want_remaining then hit_target = true; break end
                                        -- a mid-brew add is what actually causes the cauldron to
                                        -- explode (see addItemsToStation above) - if we somehow got
                                        -- moved away from it mid-craft (knockback, another system's
                                        -- move call, etc.), STOP crafting immediately rather than let
                                        -- an ingredient get added from the wrong spot, walk back, then
                                        -- resume toward the same target.
                                        if step.cf then
                                            local hrp_now = local_hrp and local_hrp()
                                            if hrp_now and (hrp_now.Position - step.cf.Position).Magnitude > 10 then
                                                auto_pot_active = false
                                                moved_away_count = moved_away_count + 1
                                                -- getting yanked away mid-brew IS the explosion signal -
                                                -- the brew that was in progress is assumed lost, so
                                                -- discount one from this session's count (never below
                                                -- what's actually still in the bag) rather than
                                                -- crediting a potion that didn't really survive.
                                                base = math.min(count_pot(), base + 1)
                                                pcall(function() mem:SetItem(progress_key, tostring(already + math.max(0, count_pot() - base))) end)
                                                library:Notify(("Path: moved away from the cauldron mid-brew (explosion) - discarding the last one, walking back (%d)"):format(moved_away_count), 6)
                                                bot_move_to(step.cf.Position)
                                                task.wait(0.3)
                                                if moved_away_count <= 8 and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                                    and shared and not shared.is_unloading then
                                                    auto_pot_active = true
                                                    task.spawn(function() pcall(function() utility:craft("Alchemy", pot) end); craft_done = true end)
                                                else
                                                    break
                                                end
                                            end
                                        end
                                        -- persist progress periodically so a mid-craft serverhop (a
                                        -- Return Serverhop, illusionist hop, etc.) doesn't lose it - a
                                        -- resume landing back on this same waypoint would otherwise
                                        -- re-craft the full original count from scratch.
                                        if (os.clock() - pt_last_save) > 1 then
                                            pt_last_save = os.clock()
                                            pcall(function() mem:SetItem(progress_key, tostring(already + math.max(0, count_pot() - base))) end)
                                        end
                                        task.wait(0.3)
                                    end
                                    auto_pot_active = prev   -- stops utility:craft's loop
                                    if cheat_client and cheat_client.config then cheat_client.config.auto_craft_delay = prev_delay end
                                    local made_this_run = math.max(0, count_pot() - base)
                                    local total_progress = already + made_this_run
                                    library:Notify(("Path: crafted %d %s"):format(made_this_run, pot), 4)
                                    if want > 0 and not hit_target and total_progress < want then
                                        -- ran out of materials (or timed out) before reaching the
                                        -- target - go back and gather more instead of moving past
                                        -- this waypoint with a short batch. Capped at 5 attempts:
                                        -- an uncapped version of this (nothing stopping it) got
                                        -- stuck ping-ponging against the far-target reroute forever
                                        -- (10000+ attempts, never actually gathering anything) - a
                                        -- true runaway loop is worse than the thing this was meant
                                        -- to prevent, so past the cap it STOPS the bot entirely
                                        -- (never silently skips ahead) so you can check what's wrong.
                                        local retry_key = "xpfarm_potion_retries_" .. tostring(i)
                                        local retries = (tonumber(mem:GetItem(retry_key)) or 0) + 1
                                        pcall(function() mem:SetItem(progress_key, tostring(total_progress)) end)
                                        -- a potion can need MULTIPLE ingredients from SEPARATE gather
                                        -- loops WITHIN THE SAME LAP (e.g. Health Potion needs both
                                        -- Lava Flower and Scroom) - the nearest preceding loop alone
                                        -- isn't enough if an EARLIER one in this lap is what's
                                        -- actually empty. But don't scan past a PREVIOUS lap's own
                                        -- Make Potions step - that's where an earlier lap's already-
                                        -- used-up materials live, and this was wrongly rewinding a
                                        -- bot on lap 3 (61 potions) all the way back to lap 1's (21
                                        -- potions) gather loop because that one always reads empty
                                        -- too. Only search inside the current lap's own cluster.
                                        local lap_start = 1
                                        for j = i - 1, 1, -1 do
                                            if xp_path[j] and xp_path[j].kind == "potion" then
                                                lap_start = j + 1
                                                break
                                            end
                                        end
                                        local back_to = nil
                                        for j = lap_start, i - 1 do
                                            local s = xp_path[j]
                                            if s and s.kind == "repeat_start" and s.goal_kind == "ingredient" and s.ingredient
                                                and count_ing(s.ingredient) <= 0 then
                                                back_to = j
                                                break
                                            end
                                        end
                                        if not back_to then
                                            for j = i - 1, 1, -1 do
                                                if xp_path[j] and xp_path[j].kind == "repeat_end" then
                                                    back_to = find_repeat_start(j)
                                                    break
                                                end
                                            end
                                        end
                                        if back_to and retries <= 5 then
                                            pcall(function() mem:SetItem(retry_key, tostring(retries)) end)
                                            library:Notify(("Path: only %d/%d %s made - not enough materials, walking back to gather more (attempt %d/5)"):format(total_progress, want, pot, retries), 6)
                                            -- physically retrace the recorded points back to the
                                            -- gather loop instead of jumping the array index straight
                                            -- there - a raw jump leaves the NEXT step's target far
                                            -- away, which fights the far-target reroute (BUILD 209)
                                            -- and can loop forever without ever actually walking back.
                                            for j = i - 1, back_to, -1 do
                                                if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                                    and shared and not shared.is_unloading) then break end
                                                local ps = xp_path[j]
                                                if ps and ps.cf and ps.kind ~= "return" then
                                                    bot_move_to(ps.cf.Position)
                                                end
                                            end
                                            i = back_to
                                            jumped = true
                                        elseif back_to then
                                            -- exceeded 30 retries without ever reaching the target -
                                            -- something is stuck (likely fighting the far-target
                                            -- reroute) and retrying here again clearly isn't going to
                                            -- fix itself. Stopping the bot dead used to be the response,
                                            -- but that just strands it at the exact spot it's already
                                            -- failing at instead of letting it reach the inn a little
                                            -- further ahead where it can actually recover - so give up
                                            -- on this batch and continue forward instead.
                                            library:Notify(("Path: gave up on %s after %d attempts (stuck at %d/%d) - continuing on to the next point instead of stopping"):format(pot, retries, total_progress, want), 10)
                                            pcall(function() mem:RemoveItem(progress_key) end)
                                            pcall(function() mem:RemoveItem(retry_key) end)
                                        else
                                            -- no ingredient loop exists before this waypoint at all
                                            -- (a structural path issue, not a materials shortage) -
                                            -- nothing to go back to, so this is the only case that
                                            -- actually continues past a short batch.
                                            library:Notify(("Path: short on %s (%d/%d) but no ingredient loop found before this waypoint - continuing anyway"):format(pot, total_progress, want), 8)
                                            pcall(function() mem:RemoveItem(progress_key) end)
                                            pcall(function() mem:RemoveItem(retry_key) end)
                                        end
                                    else
                                        -- reached the target (or ran until out of mats with no target) -
                                        -- clear saved progress so this waypoint starts fresh next time.
                                        pcall(function() mem:RemoveItem(progress_key) end)
                                        pcall(function() mem:RemoveItem("xpfarm_potion_retries_" .. tostring(i)) end)
                                    end
                                elseif step.kind == "mine" then
                                    -- hit the ore at this spot ONCE, then move on to the next
                                    -- waypoint (chain several Mine Here points along a path
                                    -- instead of camping one spot until every nearby ore is gone)
                                    if not mine_swing() then library:Notify("Path: no Pickaxe in your bag", 5) end
                                    task.wait(0.25)
                                elseif step.kind == "smelt" then
                                    -- Smelting is NOT a click. Confirmed live: equipping a raw
                                    -- ore Tool (Iron/Mythril/Copper - NOT "X Bar") while standing
                                    -- right up against the furnace auto-converts it into a bar
                                    -- within about a second, no ClickDetector/remote involved -
                                    -- the ore just vanishes from the character and bars appear
                                    -- in the backpack. RIGHT-clicking "Remote Smithing" summons
                                    -- workspace.PortableFurnace (a top-level model with a part
                                    -- literally named "Furnace" and NO ClickDetector at all -
                                    -- confirmed via live capture) - a completely different object
                                    -- from workspace.Stations.SmithingStation, which is actually
                                    -- the ANVIL used by "Craft Weapon" (left-click/Activate).
                                    local char = plr.Character
                                    local hum = char and FindFirstChildOfClass(char, "Humanoid")
                                    local function get_station()
                                        local hrp = local_hrp()
                                        if not hrp then return nil, nil end
                                        local best, bestpart, bestd
                                        for _, v in ipairs(ws:GetChildren()) do
                                            if v.Name == "PortableFurnace" then
                                                local part = v:FindFirstChild("Furnace") or v.PrimaryPart
                                                if part then
                                                    local d = (part.Position - hrp.Position).Magnitude
                                                    if d <= 60 and (not bestd or d < bestd) then bestd = d; best = v; bestpart = part end
                                                end
                                            end
                                        end
                                        return best, bestpart
                                    end
                                    if not (get_station()) and hum then
                                        local rsm = FindFirstChild(char, "Remote Smithing")
                                        if not rsm then
                                            local bp = FindFirstChild(plr, "Backpack")
                                            rsm = bp and FindFirstChild(bp, "Remote Smithing")
                                        end
                                        if rsm then pcall(function() hum:EquipTool(rsm); task.wait(0.2); utility:RightClick() end) end
                                    end
                                    local sw0 = os.clock()
                                    while os.clock() - sw0 < 6 and not (get_station()) do task.wait(0.2) end
                                    local station, mat = get_station()
                                    if not station or not mat then
                                        library:Notify("Smelt: no PortableFurnace nearby - couldn't summon the furnace", 5)
                                    else
                                        local hrp = local_hrp()
                                        if hrp then
                                            -- Bring just the red "Furnace" part to our hand - the
                                            -- character never walks to it. Just a brief 1s burst
                                            -- to get it in place, not a continuous hold for the
                                            -- whole smelt duration.
                                            local hand = FindFirstChild(char, "RightHand") or FindFirstChild(char, "Right Arm") or hrp
                                            local rp0 = os.clock()
                                            while os.clock() - rp0 < 1 do
                                                pcall(function()
                                                    mat.CFrame = hand.CFrame * CFrame.new(0, 0, -1.5)
                                                end)
                                                task.wait(0.15)
                                            end
                                            if (mat.Position - hrp.Position).Magnitude > 6 then
                                                bot_move_to(mat.Position)
                                                task.wait(0.3)
                                            end
                                        end

                                        -- Equipping is NOT Humanoid:EquipTool - confirmed live via a
                                        -- remote/GUI capture while manually equipping: the real
                                        -- inventory hotbar has a TextButton per item (e.g.
                                        -- "4Mythril", Text="Mythril") and clicking IT is what
                                        -- actually equips. EquipTool never reliably worked here.
                                        local function ore_tool(name)
                                            local bp = FindFirstChild(plr, "Backpack")
                                            return bp and FindFirstChild(bp, name)
                                        end
                                        local function bar_count(name)
                                            local n = 0
                                            local bp = FindFirstChild(plr, "Backpack")
                                            if bp then
                                                for _, it in ipairs(bp:GetChildren()) do
                                                    if it.Name == name then n = n + 1 end
                                                end
                                            end
                                            return n
                                        end
                                        local function click_hotbar(name)
                                            -- The macro system elsewhere in this file has its OWN
                                            -- proven-reliable "equip" action (find_tool + plain
                                            -- Humanoid:EquipTool, no UnequipTools first) - match that
                                            -- exactly instead of GUI clicks or raw key presses.
                                            local lower = name:lower()
                                            local tool
                                            local bp = FindFirstChild(plr, "Backpack")
                                            if bp then
                                                for _, t in ipairs(bp:GetChildren()) do
                                                    if t:IsA("Tool") and t.Name:lower() == lower then tool = t; break end
                                                end
                                            end
                                            if not tool and char then
                                                for _, t in ipairs(char:GetChildren()) do
                                                    if t:IsA("Tool") and t.Name:lower() == lower then tool = t; break end
                                                end
                                            end
                                            if not tool then return false end
                                            if hum then pcall(function() hum:EquipTool(tool) end) end
                                            return true
                                        end

                                        local dur = (wait_s and wait_s > 0) and wait_s or 60
                                        local totals = {}
                                        for _, ore in ipairs({ "Iron", "Mythril", "Copper" }) do
                                            local sm0 = os.clock()   -- each ore type gets its OWN time budget -
                                                                     -- sharing one clock meant Iron alone could burn
                                                                     -- through the whole cap, leaving Mythril/Copper
                                                                     -- with zero time and skipping them entirely
                                            local bar_name = ore .. " Bar"
                                            if not ore_tool(ore) then
                                                library:Notify("Path: no " .. ore .. " ore in your bag - skipping", 3)
                                            end
                                            local fails = 0
                                            while (os.clock() - sm0) < dur
                                                and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                                and shared and not shared.is_unloading do
                                                if not ore_tool(ore) then break end
                                                local base = bar_count(bar_name)
                                                if not click_hotbar(ore) then
                                                    library:Notify("Path: no hotbar slot found for " .. ore .. " - stopping this ore type", 4)
                                                    break
                                                end
                                                local w0 = os.clock()
                                                while (os.clock() - w0) < 2 and bar_count(bar_name) <= base do task.wait(0.1) end
                                                if bar_count(bar_name) <= base then
                                                    -- didn't convert this click - could be a flake, or
                                                    -- (per the user) some games mix a non-smeltable
                                                    -- "skill unlock" item in with the same name. Allow
                                                    -- a few misses before giving up on this ore type.
                                                    fails = fails + 1
                                                    if fails >= 5 then
                                                        library:Notify("Path: " .. ore .. " keeps failing to convert - stopping this ore type", 5)
                                                        break
                                                    end
                                                else
                                                    fails = 0
                                                    totals[ore] = (totals[ore] or 0) + 1
                                                    task.wait(0.1)
                                                end
                                            end
                                        end
                                        local parts = {}
                                        for _, ore in ipairs({ "Iron", "Mythril", "Copper" }) do
                                            if totals[ore] then parts[#parts + 1] = totals[ore] .. " " .. ore end
                                        end
                                        library:Notify(#parts > 0 and ("Path: smelted " .. table.concat(parts, ", "))
                                            or "Path: nothing to smelt (no ore in bag)", 5)
                                    end
                                elseif step.kind == "craft" then
                                    -- forge a weapon: equip "Remote Smithing" and LEFT-click
                                    -- (Activate) to summon the ANVIL (right-click summons the
                                    -- furnace, used by "Smelt Here" - same tool, the two mouse
                                    -- buttons summon two different stations), then run the game's own
                                    -- recipe-based utility:craft loop (already knows every
                                    -- Bronze/Steel/Mythril recipe) until out of materials or the
                                    -- chosen count is reached.
                                    local char = plr.Character
                                    local hum = char and FindFirstChildOfClass(char, "Humanoid")
                                    local function craft_station_here()
                                        local st = FindFirstChild(ws, "Stations")
                                        local hrp = local_hrp()
                                        if not st or not hrp then return nil end
                                        for _, v in ipairs(st:GetChildren()) do
                                            local timer = v:FindFirstChild("Timer")
                                            if timer and v.Name:lower():find("smith")
                                                and (timer.Position - hrp.Position).Magnitude <= 15 then
                                                return v
                                            end
                                        end
                                        return nil
                                    end
                                    if not craft_station_here() and hum then
                                        local rsm = FindFirstChild(char, "Remote Smithing")
                                        if not rsm then
                                            local bp = FindFirstChild(plr, "Backpack")
                                            rsm = bp and FindFirstChild(bp, "Remote Smithing")
                                        end
                                        if rsm then
                                            pcall(function()
                                                hum:EquipTool(rsm)
                                                task.wait(0.2)
                                                -- Neither Tool:Activate() nor firing the LeftClick
                                                -- remote directly actually summons the anvil -
                                                -- confirmed live it needs a REAL simulated mouse
                                                -- click. Move the mouse to the viewport center and
                                                -- send a genuine press+release via VirtualInputManager
                                                -- (same technique already used elsewhere in this file
                                                -- for dismissing the "Teleport Failed" popup).
                                                local cam = workspace.CurrentCamera
                                                local vp = cam and cam.ViewportSize
                                                local cx, cy = (vp and vp.X / 2) or 640, (vp and vp.Y / 2) or 360
                                                vim:SendMouseMoveEvent(cx, cy, game)
                                                task.wait(0.05)
                                                vim:SendMouseButtonEvent(cx, cy, 0, true, game, 1)
                                                task.wait(0.05)
                                                vim:SendMouseButtonEvent(cx, cy, 0, false, game, 1)
                                            end)
                                        end
                                    end
                                    local cw0 = os.clock()
                                    while os.clock() - cw0 < 6 and not craft_station_here() do task.wait(0.2) end
                                    if not craft_station_here() then
                                        library:Notify("Craft: no smithing station nearby - couldn't summon the anvil", 5)
                                    else
                                        local function bag_count(name)
                                            local n = 0
                                            local bp = FindFirstChild(plr, "Backpack")
                                            if bp then
                                                for _, it in ipairs(bp:GetChildren()) do
                                                    if it.Name == name then
                                                        local q = FindFirstChild(it, "Quantity")
                                                        n = n + (q and q.Value or 1)
                                                    end
                                                end
                                            end
                                            return n
                                        end

                                        -- utility:craft's GrabStation/addItemsToStation flow was
                                        -- never actually feeding materials in - confirmed live the
                                        -- character just stood there holding Remote Smithing doing
                                        -- nothing. The original addItemsToStation grabbed the bar by
                                        -- raw-reparenting it (k.Parent = plr.Character) instead of
                                        -- genuinely equipping it - fix: EQUIP it properly first (the
                                        -- proven-reliable Humanoid:EquipTool pattern the macro
                                        -- system already uses), THEN fire its own RemoteEvent onto
                                        -- station.Material to actually add it to the station (that
                                        -- part of the original mechanic was fine, just never reached
                                        -- because the item was never really "held").
                                        local WEAPON_RECIPES = {
                                            ["Bronze Sword"] = { ["Copper Bar"] = 1, ["Tin Bar"] = 2 },
                                            ["Bronze Dagger"] = { ["Copper Bar"] = 1, ["Tin Bar"] = 1 },
                                            ["Bronze Spear"] = { ["Tin Bar"] = 1, ["Copper Bar"] = 2 },
                                            ["Steel Sword"] = { ["Iron Bar"] = 2, ["Copper Bar"] = 1 },
                                            ["Steel Dagger"] = { ["Iron Bar"] = 1, ["Copper Bar"] = 1 },
                                            ["Steel Spear"] = { ["Iron Bar"] = 1, ["Copper Bar"] = 2 },
                                            ["Mythril Sword"] = { ["Copper Bar"] = 1, ["Iron Bar"] = 2, ["Mythril Bar"] = 1 },
                                            ["Mythril Dagger"] = { ["Copper Bar"] = 1, ["Iron Bar"] = 1, ["Mythril Bar"] = 1 },
                                            ["Mythril Spear"] = { ["Copper Bar"] = 2, ["Iron Bar"] = 1, ["Mythril Bar"] = 1 },
                                        }
                                        local function equip_and_add(matName, station)
                                            -- Live capture showed the bar bouncing back to the
                                            -- backpack almost instantly - the window to click after
                                            -- equipping is very short. Aim the mouse at Material
                                            -- FIRST, then equip, then click IMMEDIATELY (no delay in
                                            -- between) instead of equip -> wait -> aim -> click.
                                            local bp = FindFirstChild(plr, "Backpack")
                                            local tool = bp and FindFirstChild(bp, matName)
                                            if not tool then return false end

                                            -- station.Material isn't always a direct child on every
                                            -- anvil - resolve it safely (recursive search as a
                                            -- fallback) instead of indexing it directly, which threw
                                            -- "Material is not a valid member of Model SmithingStation"
                                            -- and killed the whole craft attempt.
                                            local material_part = station:FindFirstChild("Material") or station:FindFirstChild("Material", true)
                                            if not material_part then
                                                library:Notify("Path: couldn't find the anvil's Material part - stopping", 4)
                                                return false
                                            end

                                            local hrp = local_hrp()
                                            if hrp and (material_part.Position - hrp.Position).Magnitude > 6 then
                                                -- stand a few studs BACK from Material, not on top of
                                                -- it - moving to the exact position put the character
                                                -- inside the anvil, which also blocks the camera from
                                                -- ever seeing Material to click it
                                                local away = (hrp.Position - material_part.Position)
                                                if away.Magnitude < 0.01 then away = Vector3.new(0, 0, 1) end
                                                local standPos = material_part.Position + away.Unit * 4
                                                bot_move_to(standPos)
                                                task.wait(0.3)
                                            end

                                            local function aim_at_material()
                                                -- recompute fresh every attempt (not once up front) -
                                                -- Material and Hammer sit close together on the
                                                -- anvil, so if the character drifts even slightly
                                                -- between attempts a stale aim can land on Hammer
                                                -- instead of Material
                                                local cam = workspace.CurrentCamera
                                                local sp = cam and cam:WorldToViewportPoint(material_part.Position)
                                                if not (cam and sp) then return nil end
                                                local cx = math.clamp(sp.X, 1, cam.ViewportSize.X - 1)
                                                local cy = math.clamp(sp.Y, 1, cam.ViewportSize.Y - 1)
                                                pcall(function()
                                                    -- VirtualInputManager only (not mousemoveabs) -
                                                    -- WorldToViewportPoint gives coordinates in the
                                                    -- GAME's own viewport space, but mousemoveabs
                                                    -- expects raw OS screen pixels, which only match
                                                    -- if the window happens to sit at the screen's
                                                    -- top-left corner. VIM correctly interprets these
                                                    -- as game-relative when passed `game`.
                                                    vim:SendMouseMoveEvent(cx, cy, game)
                                                end)
                                                return cx, cy
                                            end

                                            -- Success signal: EITHER the station's own Contents
                                            -- string changes (what the original addItemsToStation
                                            -- checked for) OR bag_count drops - don't rely on just
                                            -- one, since it's unconfirmed whether Contents actually
                                            -- updates for this click-based feed mechanism, and
                                            -- bag_count alone proved unreliable (reported FAILED on
                                            -- an attempt that actually worked).
                                            local startContents = station.Contents.Value
                                            local before = bag_count(matName)
                                            local function fed()
                                                return station.Contents.Value ~= startContents or bag_count(matName) < before
                                            end
                                            for attempt = 1, 8 do
                                                if fed() then break end
                                                local curTool = FindFirstChild(plr.Backpack, matName)
                                                if not curTool then break end
                                                local cx, cy = aim_at_material()
                                                -- Equip by Tool instance directly (not a hotbar
                                                -- number keypress) - the hotbar slot for matName
                                                -- shifts as bars get created/consumed during
                                                -- smelting, and a stale slot number can end up
                                                -- pointing at Gate instead once it reflows into
                                                -- that slot, which was equipping Gate mid-craft.
                                                pcall(function() hum:EquipTool(curTool) end)
                                                -- click RIGHT away, no wait - the item can bounce
                                                -- back within a fraction of a second
                                                if cx then
                                                    pcall(function()
                                                        -- VIM only here too - mouse1click has no
                                                        -- coordinate argument, it clicks wherever the
                                                        -- REAL OS cursor currently is, which may not
                                                        -- match where we just told VIM to move it to
                                                        vim:SendMouseButtonEvent(cx, cy, 0, true, game, 1)
                                                        vim:SendMouseButtonEvent(cx, cy, 0, false, game, 1)
                                                    end)
                                                end
                                                local settle0 = os.clock()
                                                while (os.clock() - settle0) < 0.5 and not fed() do
                                                    task.wait(0.1)
                                                end
                                                if fed() then break end
                                            end
                                            return fed()
                                        end
                                        local function hover_and_click(part, cd)
                                            local cam = workspace.CurrentCamera
                                            if cam and part then
                                                local sp, onScreen = cam:WorldToViewportPoint(part.Position)
                                                if onScreen then pcall(function() vim:SendMouseMoveEvent(sp.X, sp.Y, game) end) end
                                            end
                                            task.wait(0.05)
                                            pcall(function() fireclickdetector(cd) end)
                                        end
                                        -- craft ONE recipe until out of an ingredient for it (or the
                                        -- optional count is hit); returns how many were made.
                                        local function craft_one(weapon, want)
                                            local recipe = WEAPON_RECIPES[weapon]
                                            if not recipe then return 0 end
                                            local base = bag_count(weapon)
                                            local made = 0
                                            while Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                                and shared and not shared.is_unloading
                                                and (want <= 0 or made < want) do
                                                local have_all = true
                                                for mat, need in pairs(recipe) do
                                                    local have = bag_count(mat)
                                                    if have < need then
                                                        if made == 0 then
                                                            library:Notify(string.format("Path: %s needs %d %s, you have %d - stopping",
                                                                weapon, need, mat, have), 5)
                                                        end
                                                        have_all = false
                                                        break
                                                    end
                                                end
                                                if not have_all then break end

                                                local station = craft_station_here()
                                                if not station then
                                                    library:Notify("Path: lost the anvil mid-craft - stopping", 4)
                                                    break
                                                end

                                                local fed_ok = true
                                                for mat, need in pairs(recipe) do
                                                    for i = 1, need do
                                                        local okAdd = equip_and_add(mat, station)
                                                        library:Notify(string.format("Path: feed %s (%d/%d) -> %s", mat, i, need, okAdd and "OK" or "FAILED"), 3)
                                                        if not okAdd then
                                                            fed_ok = false
                                                            break
                                                        end
                                                    end
                                                    if not fed_ok then break end
                                                end
                                                if not fed_ok then
                                                    library:Notify("Path: couldn't feed " .. weapon .. "'s materials into the anvil - stopping", 4)
                                                    break
                                                end

                                                local hammer = station:FindFirstChild("Hammer")
                                                local cd = hammer and hammer:FindFirstChild("ClickConcoct")
                                                if not cd then
                                                    library:Notify("Path: no ClickConcoct on the anvil - stopping", 4)
                                                    break
                                                end
                                                local hc0 = os.clock()
                                                while (os.clock() - hc0) < 6 and (bag_count(weapon) - base) <= made do
                                                    hover_and_click(hammer, cd)
                                                    task.wait(0.3)
                                                end
                                                if (bag_count(weapon) - base) <= made then
                                                    library:Notify("Path: hammering didn't produce a " .. weapon .. " - stopping", 4)
                                                    break
                                                end
                                                made = bag_count(weapon) - base
                                                task.wait(0.2)
                                            end
                                            return made
                                        end

                                        local weapon = step.weapon or "Mythril Dagger"
                                        if weapon == "Auto (Best Fit)" then
                                            -- cascades Mythril -> Steel -> Bronze. Within each tier,
                                            -- picks whichever weapon's ingot ratio best matches what's
                                            -- left in the bag, so the two shared ingots (Iron/Copper)
                                            -- get used up evenly instead of stranding a pile of one
                                            -- ingot because every recipe kept picking the other one.
                                            local function pick_mythril()
                                                local iron, myth = bag_count("Iron Bar"), bag_count("Mythril Bar")
                                                if myth <= 0 or iron <= 0 then return nil end
                                                if iron / myth >= 2 then return "Mythril Sword" end
                                                return "Mythril Dagger"   -- iron ~= mythril (or less) -> 1:1 recipe
                                            end
                                            local function pick_steel()
                                                local iron, copper = bag_count("Iron Bar"), bag_count("Copper Bar")
                                                if iron <= 0 or copper <= 0 then return nil end
                                                local ratio = iron / copper
                                                if ratio >= 2 then return "Steel Sword"
                                                elseif ratio <= 0.5 then return "Steel Spear"
                                                else return "Steel Dagger" end
                                            end
                                            local function pick_bronze()
                                                local tin, copper = bag_count("Tin Bar"), bag_count("Copper Bar")
                                                if tin <= 0 or copper <= 0 then return nil end
                                                local ratio = tin / copper
                                                if ratio >= 2 then return "Bronze Sword"
                                                elseif ratio <= 0.5 then return "Bronze Spear"
                                                else return "Bronze Dagger" end
                                            end

                                            library:Notify(string.format("Path: Auto-crafting - have %d Iron Bar, %d Copper Bar, %d Mythril Bar, %d Tin Bar",
                                                bag_count("Iron Bar"), bag_count("Copper Bar"), bag_count("Mythril Bar"), bag_count("Tin Bar")), 6)
                                            local made, breakdown = 0, {}
                                            for _, picker in ipairs({ pick_mythril, pick_steel, pick_bronze }) do
                                                local recipe = picker()
                                                if recipe then
                                                    local n = craft_one(recipe, 0)
                                                    if n > 0 then
                                                        made = made + n
                                                        breakdown[#breakdown + 1] = n .. " " .. recipe
                                                    end
                                                end
                                                if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) then break end
                                            end
                                            library:Notify(made > 0
                                                and ("Path: Auto-crafted " .. made .. " weapons - " .. table.concat(breakdown, ", "))
                                                or "Path: Auto-craft - nothing craftable (missing ingots)", 6)
                                        else
                                            local want = tonumber(step.count) or 0
                                            library:Notify(("Path: crafting %s%s ..."):format(weapon, want > 0 and (" x" .. want) or " (until out of mats)"), 3)
                                            local n = craft_one(weapon, want)
                                            library:Notify(("Path: crafted %d %s"):format(n, weapon), 4)
                                        end
                                    end
                                elseif step.kind == "sell_weapons" then
                                    -- "Can I sell in bulk?" -> "Weapons" -> "It's a deal."
                                    -- repeatedly -> "Bye."
                                    local nm = step.npc_name
                                    local sold = xpfarm_sell_categories(nm, { "Weapons" })
                                    library:Notify(sold and "Path: weapons sold" or "Path: nothing to sell", 5)
                                elseif step.kind == "hold" then
                                    -- plant the bot at this spot (re-assert position) while it
                                    -- smelts, so it can't drift / get knocked off the furnace.
                                    -- Holds for the Point Wait Time (default 60s if left at 0).
                                    local hold_secs = (wait_s and wait_s > 0) and wait_s or 60
                                    library:Notify(string.format("Path: holding spot %ds (smelting)", math.floor(hold_secs)), 3)
                                    local ht0 = os.clock()
                                    while Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading and (os.clock() - ht0) < hold_secs do
                                        local hp = local_hrp()
                                        if hp then
                                            pcall(function()
                                                hp.CFrame = step.cf
                                                hp.AssemblyLinearVelocity = Vector3.zero
                                            end)
                                        end
                                        task.wait(0.1)
                                    end
                                elseif step.kind == "attack" then
                                    -- attack until the area is CLEARED (monsters die/vanish,
                                    -- e.g. Evil Eyes, instead of getting knocked) - not a
                                    -- fixed timer. The point's wait time is a safety cap; a
                                    -- tiny value (<5) means "no cap" -> 120s default. If a Lure
                                    -- Spot (cf2) is set, every 15s dart to it and back to the
                                    -- attack spot to drag the Evil Eyes into position (still
                                    -- swinging the whole time).
                                    local range = (Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value) or 60
                                    equip_sword()   -- draw the blade before fighting the Evil Eyes
                                    -- throw one bare-handed punch before switching to the sword -
                                    -- unequip, swing until the LightAttack accessory confirms it
                                    -- actually landed (same detection the macro system's Punch
                                    -- action uses), then re-equip and fight as normal.
                                    pcall(function()
                                        local char = plr.Character
                                        local hum = char and FindFirstChildOfClass(char, "Humanoid")
                                        if not (char and hum) then return end
                                        local punched = false
                                        local conn
                                        conn = utility:Connection(char.ChildAdded, function(obj)
                                            if obj:IsA("Accessory") and obj.Name == "LightAttack" then
                                                punched = true
                                            end
                                        end)
                                        hum:UnequipTools()
                                        task.wait(0.05)
                                        local pt0 = os.clock()
                                        while not punched and (os.clock() - pt0) < 2
                                            and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading do
                                            pcall(function() utility:LeftClick() end)
                                            task.wait(0.1)
                                        end
                                        if conn then conn:Disconnect() end
                                    end)
                                    equip_sword()
                                    if step.cf2 then
                                        -- lure attack: bounce between the attack spot and the
                                        -- lure spot every 15s, 5 times (attacking the whole
                                        -- time), then move on.
                                        for _ = 1, 5 do
                                            if shared.is_unloading or not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) then break end
                                            local t = 0
                                            while t < 15 and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                                and shared and not shared.is_unloading do
                                                burst_until = os.clock() + 2   -- keep swinging at the attack spot
                                                t = t + task.wait(0.3)
                                            end
                                            if shared.is_unloading or not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value) then break end
                                            burst_until = os.clock() + 12   -- keep swinging while moving
                                            bot_move_to(step.cf2.Position)   -- out to the lure spot
                                            bot_move_to(step.cf.Position)    -- back to the attack spot
                                        end
                                        burst_until = 0
                                    else
                                        -- no lure spot: attack until the area is CLEARED, holding
                                        -- the character right at the recorded spot the whole time -
                                        -- monster knockback can otherwise drag it away mid-fight.
                                        local cap = (wait_s and wait_s >= 5) and wait_s or 120
                                        local at0, clear_since = os.clock(), nil
                                        while Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading
                                            and (os.clock() - at0) < cap do
                                            burst_until = os.clock() + 3
                                            if step.cf then
                                                local hrp_now = local_hrp and local_hrp()
                                                if hrp_now then
                                                    hrp_now.AssemblyLinearVelocity = Vector3.zero
                                                    if (hrp_now.Position - step.cf.Position).Magnitude > 4 then
                                                        pcall(function()
                                                            hrp_now.CFrame = CFrame.new(step.cf.Position, hrp_now.Position + hrp_now.CFrame.LookVector)
                                                        end)
                                                    end
                                                end
                                            end
                                            if scan_monsters(range) > 0 then
                                                clear_since = nil
                                            else
                                                clear_since = clear_since or os.clock()
                                                if os.clock() - clear_since >= 1.5 then break end
                                            end
                                            task.wait(0.2)
                                        end
                                        burst_until = 0
                                    end
                                elseif step.kind == "mana_attack" then
                                    -- cycles CHARGE -> PUNCH -> CHARGE -> PUNCH, repeating until
                                    -- the area is cleared or the overall cap runs out - not a
                                    -- one-time top-up followed by a normal fight, since mana
                                    -- depletes while fighting and needs periodic re-charging
                                    -- throughout. Stays bare-handed the entire time (never
                                    -- equips a sword) - the burst-attack loop just calls
                                    -- LeftClick regardless of what's equipped, so staying
                                    -- unarmed makes every swing a punch.
                                    local range = (Options.xpfarm_monster_range and Options.xpfarm_monster_range.Value) or 60
                                    pcall(function()
                                        local hum = plr.Character and FindFirstChildOfClass(plr.Character, "Humanoid")
                                        if hum then hum:UnequipTools() end
                                    end)
                                    local cap = (wait_s and wait_s >= 5) and wait_s or 120
                                    local mt0 = os.clock()
                                    local cleared = false

                                    -- No mana yet at the very start, so charging first is wasted
                                    -- time - attack bare-fisted for up to 1 minute BEFORE ever
                                    -- trying to charge, then fall into the normal charge/punch
                                    -- cycle below once there's actually a fight going.
                                    library:Notify("Path: attacking (fists, no mana yet)...", 3)
                                    local initial_t0 = os.clock()
                                    while (os.clock() - initial_t0) < 60
                                        and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading and not cleared do
                                        if step.cf then
                                            local hrp_now = local_hrp and local_hrp()
                                            if hrp_now then
                                                hrp_now.AssemblyLinearVelocity = Vector3.zero
                                                if (hrp_now.Position - step.cf.Position).Magnitude > 4 then
                                                    pcall(function()
                                                        hrp_now.CFrame = CFrame.new(step.cf.Position, hrp_now.Position + hrp_now.CFrame.LookVector)
                                                    end)
                                                end
                                            end
                                        end
                                        pcall(function() utility:LeftClick() end)
                                        if scan_monsters(range) == 0 then cleared = true; break end
                                        task.wait(0.3)
                                    end

                                    -- still enemies after a full minute of unmanaed fists - this
                                    -- spot isn't clearing on its own. Walk back to point 449
                                    -- instead of grinding here forever; the path naturally walks
                                    -- forward again afterward, so it comes right back to this same
                                    -- Charge Mana + Attack waypoint and retries.
                                    local retreated = false
                                    if not cleared and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading then
                                        library:Notify("Path: still enemies here after 1 min - walking back to point 449", 6)
                                        for j = i, 449, -1 do
                                            if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                                and shared and not shared.is_unloading) then break end
                                            local ps = xp_path[j]
                                            if ps and ps.cf and ps.kind ~= "return" then
                                                bot_move_to(ps.cf.Position)
                                            end
                                        end
                                        i = 449
                                        jumped = true
                                        retreated = true
                                    end

                                    while not retreated and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading
                                        and (os.clock() - mt0) < cap and not cleared do
                                        -- CHARGE PHASE: exactly 4s, or until mana's actually topped up
                                        library:Notify("Path: charging mana...", 3)
                                        local ct0 = os.clock()
                                        while (os.clock() - ct0) < 4
                                            and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading do
                                            pcall(function() utility:charge_mana_until(98) end)
                                            local mana_now = nil
                                            pcall(function()
                                                local mv = FindFirstChild(plr.Character, "Mana")
                                                if mv then mana_now = mv.Value end
                                            end)
                                            if mana_now and mana_now >= 95 then break end
                                            task.wait(0.1)
                                        end
                                        if not (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading) then break end

                                        -- PUNCH PHASE: exactly 6s of M1 swings, holding position,
                                        -- bare-handed, then back to charging
                                        library:Notify("Path: attacking (fists)...", 3)
                                        local pt0 = os.clock()
                                        while (os.clock() - pt0) < 6
                                            and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                            and shared and not shared.is_unloading do
                                            if step.cf then
                                                local hrp_now = local_hrp and local_hrp()
                                                if hrp_now then
                                                    hrp_now.AssemblyLinearVelocity = Vector3.zero
                                                    if (hrp_now.Position - step.cf.Position).Magnitude > 4 then
                                                        pcall(function()
                                                            hrp_now.CFrame = CFrame.new(step.cf.Position, hrp_now.Position + hrp_now.CFrame.LookVector)
                                                        end)
                                                    end
                                                end
                                            end
                                            pcall(function() utility:LeftClick() end)
                                            if scan_monsters(range) == 0 then cleared = true; break end
                                            task.wait(0.3)
                                        end
                                    end
                                else
                                    local dwell = 0
                                    while dwell < wait_s
                                        and Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value
                                        and shared and not shared.is_unloading do
                                        dwell = dwell + task.wait(0.2)
                                    end
                                end
                            end
                            task.wait(0.1)
                            if not jumped then i = i + 1 end
                        end
                        path_idx = 0
                        update_path_label()
                        if test_once then
                            test_once = false
                            if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(false) end
                            library:Notify("Test run complete (one pass, repeats skipped)", 5)
                        elseif classbot_run_once then
                            -- one full pass done (repeats ran fully): stop and advance the stage
                            classbot_run_once = false
                            if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(false) end
                            local done_cb = classbot_on_done
                            classbot_on_done = nil
                            if done_cb then task.spawn(done_cb) end
                        end
                    else
                        task.wait(0.3)
                    end
                end
            end)

            -- ---- resume the path after a Serverhop point / hop-near ----------
            task.spawn(function()
                -- After a serverhop, a fresh script load resets EVERY toggle to its UI
                -- default - so Hitbox Offset / Auto Ingredient / Auto Bag all go back OFF,
                -- even if an On waypoint earlier in the path had turned them on. If the
                -- resume point (snapped to the enclosing repeat_start) lands INSIDE a loop,
                -- that earlier On step never gets replayed, silently breaking mid-loop
                -- pickup - this restores the correct state directly instead. (Defined here,
                -- inside this closure, so it doesn't add to the outer function's 200-local cap.)
                local function reapply_toggle_state(idx)
                    if not idx or idx < 1 then return end
                    local offset_on, ing_on, bag_on = nil, nil, nil
                    for i = 1, math.min(idx, #xp_path) do
                        local k = xp_path[i] and xp_path[i].kind
                        if k == "offset_on" then offset_on = true
                        elseif k == "offset_off" then offset_on = false
                        elseif k == "autoing_on" then ing_on = true
                        elseif k == "autoing_off" then ing_on = false
                        elseif k == "autobag_on" then bag_on = true
                        elseif k == "autobag_off" then bag_on = false end
                    end
                    if offset_on ~= nil and Toggles.xpfarm_hitbox_air and Toggles.xpfarm_hitbox_air.Value ~= offset_on then
                        pcall(function() Toggles.xpfarm_hitbox_air:SetValue(offset_on) end)
                    end
                    if ing_on ~= nil and Toggles.auto_ingredient and Toggles.auto_ingredient.Value ~= ing_on then
                        pcall(function() Toggles.auto_ingredient:SetValue(ing_on) end)
                    end
                    if bag_on ~= nil and Toggles.auto_bag and Toggles.auto_bag.Value ~= bag_on then
                        pcall(function() Toggles.auto_bag:SetValue(bag_on) end)
                    end
                end
                if not (mem:HasItem("xpfarm_resume_active") and mem:GetItem("xpfarm_resume_active") == "true") then return end
                if mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true" then return end
                pcall(function() mem:SetItem("xpfarm_resume_active", "false") end)
                local idx = tonumber(mem:GetItem("xpfarm_resume_idx")) or 1
                pcall(function() plr.PlayerGui:WaitForChild("StartMenu", 30) end)
                if plr.PlayerGui:FindFirstChild("StartMenu") then
                    task.wait(1)
                    pcall(function()
                        if plr.PlayerGui.StartMenu:FindFirstChild("Choices") and
                           plr.PlayerGui.StartMenu.Choices:FindFirstChild("Play") then
                            firesignal(plr.PlayerGui.StartMenu.Choices.Play.MouseButton1Click)
                        end
                    end)
                end
                local deadline = os.clock() + 60
                while (not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart")) and os.clock() < deadline do
                    task.wait(0.25)
                end
                if not plr.Character then return end
                -- skip illusionist/moderator servers: re-arm resume + hop again (keep the
                -- saved path file intact - don't re-save the not-yet-loaded path). Polls
                -- for up to 10s instead of a single check after a flat 2s wait - other
                -- players' Backpack/Character contents (what these checks read) can take
                -- longer than that to replicate in a busy server, and checking too early
                -- was missing Illusionists who really were there.
                -- (Defined here, inside this closure, so it doesn't add a local to the
                -- outer function's 200-local cap - see reapply_toggle_state above.)
                local function wait_and_check_bad_server(window)
                    window = window or 10
                    local t0 = os.clock()
                    repeat
                        local illus = server_has_illusionist()
                        if illus then return "illusionist", illus end
                        local mod = server_has_moderator()
                        if mod then return "moderator", mod end
                        task.wait(1)
                    until (os.clock() - t0) >= window
                    return nil
                end
                local skip_illus_wanted = mem:HasItem("xpfarm_skip_illus") and mem:GetItem("xpfarm_skip_illus") == "true"
                local skip_mod_wanted = mem:HasItem("xpfarm_skip_mod") and mem:GetItem("xpfarm_skip_mod") == "true"
                if skip_illus_wanted or skip_mod_wanted then
                    local kind = wait_and_check_bad_server(10)
                    if (kind == "illusionist" and skip_illus_wanted) or (kind == "moderator" and skip_mod_wanted) then
                        library:Notify((kind == "illusionist" and "Illusionist" or "Moderator") .. " in server - hopping again", 5)
                        pcall(function() mem:SetItem("xpfarm_resume_active", "true") end)
                        pcall(function() mem:SetItem("xpfarm_resume_idx", tostring(idx)) end)
                        cheat_client.config.execute_on_serverhop = true
                        pcall(xpfarm_fast_serverhop)   -- JoinPublicServer (never the freezing utility:Serverhop)
                        return
                    end
                else
                    task.wait(2)
                end
                if load_xpfarm_path("__carbine_resume") then
                    -- resume from the saved waypoint (not nearest-to-spawn, which is unreliable
                    -- right after a hop) so we continue where the path left off
                    path_resume_from = idx or 1
                    reapply_toggle_state(idx or 1)
                    update_path_label()
                    if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(true) end
                    library:Notify(string.format("Path resumed from waypoint %d", idx), 6)
                else
                    library:Notify("Path resume: couldn't load the saved path", 6)
                end
            end)

            -- ---- Class Bots: Blademaster full bot (Gaia Ultra -> Khei Uber -> join) ----
            -- Sequential cross-server bot. Stage is driven by the world we load into
            -- (Gaia vs Khei) plus a mem flag, so it survives the boat teleport between
            -- the two worlds and any serverhop in between.
            do
                local FEED = "Carbine/feed_server.txt"
                local function in_khei()
                    return game.PlaceId == 3541987450 or game.PlaceId == 14341521240
                end
                local function set_status(t)
                    if classbot_full_status_label then pcall(function() classbot_full_status_label:SetText(t) end) end
                end

                local function do_join()
                    pcall(function() mem:SetItem("classbot_full", "false") end)
                    pcall(function() mem:SetItem("classbot_stage", "join") end)
                    -- finish behaviour: kick the account out, or join the broadcasting one
                    if mem:HasItem("classbot_kick_done") and mem:GetItem("classbot_kick_done") == "true" then
                        set_status("Done - Uber Sigil made, kicking the account")
                        library:Notify("Blademaster done (Uber Sigil) - kicking the account", 10)
                        task.wait(1)
                        pcall(function() rps.Requests.ReturnToMenu:InvokeServer() end)
                        pcall(function() plr:Kick("Carbine: Blademaster finished - Uber Sigil made") end)
                        return
                    end
                    set_status("Done - joining your account to be killed")
                    if not (readfile and isfile and isfile(FEED)) then
                        library:Notify("Full bot done, but no broadcast - turn on 'Broadcast My Server' on your main account (Multi-Account tab)", 14)
                        return
                    end
                    local ok, data = pcall(function() return readfile(FEED) end)
                    if not ok or not data or data == "" then library:Notify("Full bot done - broadcast file empty", 10); return end
                    local pid, jid = data:match("^(%d+),(.+)$")
                    pid = tonumber(pid)
                    if not pid or not jid or jid == "" then library:Notify("Full bot done - broadcast invalid", 10); return end
                    library:Notify("Uber Sigil done - joining your account's server to be killed", 10)
                    task.wait(1)
                    pcall(function()
                        local jr = rps.Requests and rps.Requests:FindFirstChild("JoinPublicServer")
                        if jr then jr:FireServer(jid) else Services.TeleportService:TeleportToPlaceInstance(pid, jid, plr) end
                    end)
                end

                local function run_stage()
                    -- resume from the waypoint we hopped at (if it was for THIS stage), so a
                    -- serverhop continues the farm instead of restarting from the inn.
                    local stage = in_khei() and "khei" or "gaia"
                    local resume_idx
                    if mem:HasItem("classbot_resume_idx") and mem:HasItem("classbot_resume_stage")
                        and mem:GetItem("classbot_resume_stage") == stage then
                        resume_idx = tonumber(mem:GetItem("classbot_resume_idx"))
                    end
                    pcall(function() mem:SetItem("classbot_resume_idx", "") end)
                    pcall(function() mem:SetItem("classbot_resume_stage", "") end)

                    -- If we hopped while the hitbox offset was ON (i.e. mid shrieker attack), the
                    -- offset is gone after the hop. Snap the resume back to that offset_on step so
                    -- the offset is re-applied and the shrieker attack is REDONE from there -
                    -- otherwise we'd resume standing in the swarm with no offset and never knock
                    -- one down. (No offset_on before the resume point -> keep the exact spot.)
                    local function snap_off(idx)
                        if not idx then return idx end
                        local on_at = nil
                        for i = 1, math.min(idx, #xp_path) do
                            local k = xp_path[i] and xp_path[i].kind
                            if k == "offset_on" then on_at = i
                            elseif k == "offset_off" then on_at = nil end
                        end
                        return on_at or idx
                    end

                    -- Plan the resume so we NEVER jump straight to a far waypoint (long air time =
                    -- AA-gun = ban). Find the point we're physically closest to; if that's BEHIND
                    -- our saved progress (e.g. we got sent back to the inn), walk FORWARD through
                    -- the consecutive points (ground hops, actions skipped) up to the progress
                    -- point, THEN resume. If we're already at/near it, resume there directly.
                    --
                    -- IMPORTANT: only search waypoints AT OR BEFORE the target index. A repeat
                    -- loop's turn-in NPC (e.g. the shrieker Monster Officer) is often physically
                    -- close to the inn but sits LATER in the array than the outbound leg - an
                    -- unrestricted nearest-by-distance search could pick that as "closest" even
                    -- though its index is AFTER target, which broke the "closest < target" check
                    -- below and skipped the catch-up walk entirely, sending the bot straight at
                    -- the real target in one long jump (exactly the "refuses to move 3000 studs"
                    -- bug - bot_move_to's own sanity cap just no-ops a move that far).
                    local function nearest_idx(upto)
                        local hrp = local_hrp and local_hrp()
                        if not hrp then return 1 end
                        local bi, bd = 1, math.huge
                        for i = 1, math.min(upto or #xp_path, #xp_path) do
                            local step = xp_path[i]
                            if step and step.cf and step.kind ~= "return" then
                                local d = (step.cf.Position - hrp.Position).Magnitude
                                if d < bd then bd, bi = d, i end
                            end
                        end
                        return bi
                    end
                    local function plan_resume(idx)
                        local target = snap_off(idx)
                        local closest = nearest_idx(target)
                        if closest < target then
                            path_resume_from = closest
                            classbot_catchup_to = target
                            library:Notify(string.format("Bot: at point %d, catching up to %d (walking, not jumping)", closest, target), 6)
                        else
                            path_resume_from = target
                            classbot_catchup_to = nil
                        end
                    end

                    if in_khei() then
                        pcall(function() mem:SetItem("classbot_stage", "khei") end)
                        if not load_xpfarm_path("Uber Sigil (Khei)") then library:Notify("Class bot: missing 'Uber Sigil (Khei)' preset", 8); return end
                        classbot_on_done = function()
                            library:Notify("Khei (Uber Sigil) stage complete", 6)
                            task.wait(1); do_join()
                        end
                        classbot_run_once = true
                        -- resume from wherever we ACTUALLY are: if we're back near the inn but our
                        -- progress is deep in the path, walk forward to it instead of jumping (AA gun).
                        if resume_idx then plan_resume(resume_idx) end
                        set_status(resume_idx and "Khei: resuming the Uber Sigil run (skipping finished loops)" or ("Khei: making Uber Sigil (" .. #xp_path .. " steps)"))
                        if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(true) end
                        library:Notify(resume_idx and "Class bot: Khei - resuming the run (skipping finished loops)" or "Class bot: Khei stage - making Uber Sigil", 8)
                    else
                        pcall(function() mem:SetItem("classbot_stage", "gaia") end)
                        if not load_xpfarm_path("Ultra Sigil (Gaia)") then library:Notify("Class bot: missing 'Ultra Sigil (Gaia)' preset", 8); return end
                        classbot_on_done = function()
                            if in_khei() then return end
                            -- finished a Gaia pass but Ya Alda didn't send us (Ultra not ready,
                            -- or the pass was a mid-route resume) - farm another full lap.
                            library:Notify("Ya Alda not ready - re-running the Gaia farm", 8)
                            task.wait(2)
                            run_stage()
                        end
                        classbot_run_once = true
                        -- resume from wherever we ACTUALLY are: if we're back near the inn but our
                        -- progress is deep in the path, walk forward to it instead of jumping (AA gun).
                        if resume_idx then plan_resume(resume_idx) end
                        set_status(resume_idx and "Gaia: resuming the Ultra Sigil farm (skipping finished loops)" or ("Gaia: farming Ultra Sigil (" .. #xp_path .. " steps)"))
                        if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(true) end
                        library:Notify(resume_idx and "Class bot: Gaia - resuming the farm (skipping finished loops)" or "Class bot: Gaia stage - farming Ultra Sigil", 8)
                    end
                end

                classbot_start_full = function()
                    local pt = (Options.xpfarm_ping_threshold and Options.xpfarm_ping_threshold.Value) or 1000
                    if utility and utility.CheckPingAndHop and utility:CheckPingAndHop("the Blademaster bot", pt) then return end
                    pcall(function() mem:SetItem("classbot_full", "true") end)
                    -- new run generation -> all persistent counters (rounds, Evil-Eye kills,
                    -- shrieker turn-ins) start fresh at 0 because they're keyed by this gen
                    pcall(function() mem:SetItem("classbot_gen", tostring(((tonumber(mem:GetItem("classbot_gen")) or 0) + 1))) end)
                    pcall(function() mem:SetItem("classbot_crosshop_shrk", "") end)  -- no carry-over yet
                    shrk_countable = false
                    classbot_kill_phase = nil
                    classbot_catchup_to = nil   -- fresh run, not catching up to a hop spot
                    -- seed the goal counts from the "already done" inputs so a fresh Run can start
                    -- partway (e.g. you killed some Evil Eyes / did some shriekers by hand)
                    pcall(function()
                        local g = mem:GetItem("classbot_gen") or "0"
                        local ev = math.max(0, math.floor(tonumber(Options.classbot_seed_evil and Options.classbot_seed_evil.Value) or 0))
                        local sh = math.max(0, math.floor(tonumber(Options.classbot_seed_shrk and Options.classbot_seed_shrk.Value) or 0))
                        mem:SetItem("classbot_evil_" .. g, tostring(ev))
                        mem:SetItem("classbot_shrk_" .. g, tostring(sh))
                        if ev > 0 or sh > 0 then
                            library:Notify(string.format("Blademaster starting at %d/20 Evil Eyes, %d/20 shriekers", ev, sh), 6)
                        end
                    end)
                    cheat_client.config.execute_on_serverhop = true
                    if Toggles.execute_on_serverhop and not Toggles.execute_on_serverhop.Value then
                        pcall(function() Toggles.execute_on_serverhop:SetValue(true) end)
                    end
                    run_stage()
                end

                classbot_stop_full = function()
                    pcall(function() mem:SetItem("classbot_full", "false") end)
                    classbot_run_once = false
                    classbot_on_done = nil
                    if Toggles.xpfarm_path_run then Toggles.xpfarm_path_run:SetValue(false) end
                    set_status("Stopped")
                end

                -- resume after the Gaia->Khei boat teleport (or any reload mid-run)
                task.spawn(function()
                    if not (mem:HasItem("classbot_full") and mem:GetItem("classbot_full") == "true") then return end
                    if mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true" then return end
                    pcall(function() plr.PlayerGui:WaitForChild("StartMenu", 30) end)
                    if plr.PlayerGui:FindFirstChild("StartMenu") then
                        task.wait(1)
                        pcall(function()
                            if plr.PlayerGui.StartMenu:FindFirstChild("Choices") and plr.PlayerGui.StartMenu.Choices:FindFirstChild("Play") then
                                firesignal(plr.PlayerGui.StartMenu.Choices.Play.MouseButton1Click)
                            end
                        end)
                    end
                    local deadline = os.clock() + 60
                    while (not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart")) and os.clock() < deadline do
                        task.wait(0.25)
                    end
                    if not plr.Character then return end
                    -- (Defined here, inside this closure, so it doesn't add a local to the
                    -- outer function's 200-local cap.)
                    local function wait_and_check_bad_server2(window)
                        window = window or 10
                        local t0 = os.clock()
                        repeat
                            local illus = server_has_illusionist()
                            if illus then return "illusionist", illus end
                            local mod = server_has_moderator()
                            if mod then return "moderator", mod end
                            task.wait(1)
                        until (os.clock() - t0) >= window
                        return nil
                    end
                    local skip_illus_wanted2 = mem:HasItem("xpfarm_skip_illus") and mem:GetItem("xpfarm_skip_illus") == "true"
                    local skip_mod_wanted2 = mem:HasItem("xpfarm_skip_mod") and mem:GetItem("xpfarm_skip_mod") == "true"
                    if skip_illus_wanted2 or skip_mod_wanted2 then
                        local kind2 = wait_and_check_bad_server2(10)
                        if (kind2 == "illusionist" and skip_illus_wanted2) or (kind2 == "moderator" and skip_mod_wanted2) then
                            library:Notify((kind2 == "illusionist" and "Illusionist" or "Moderator") .. " in server - hopping again", 5)
                            cheat_client.config.execute_on_serverhop = true
                            pcall(xpfarm_fast_serverhop)   -- JoinPublicServer (never the freezing utility:Serverhop)
                            return
                        end
                    else
                        task.wait(2)
                    end
                    run_stage()
                end)
            end

            -- ---- maintenance: auto-inn (low HP) + idle serverhop -------------
            local last_inn_time = 0
            local hop_started = false
            task.spawn(function()
                local illusdebug_last_print = 0
                while shared and not shared.is_unloading do
                    task.wait(0.5)
                    local char = plr.Character
                    if char then
                        -- [ILLUSDEBUG] throttled heartbeat so we can see, from real
                        -- console output, whether this loop is actually alive and what
                        -- it thinks bot_running/skip_illus/server_has_illusionist() are
                        -- at the moment someone joins mid-session - printed every 5s so
                        -- it doesn't spam, plus immediately whenever server_has_illusionist()
                        -- returns non-nil regardless of the other gates.
                        do
                            local dbg_illus = server_has_illusionist()
                            local dbg_bot_running = (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value)
                                or (Toggles.xpfarm_master and Toggles.xpfarm_master.Value)
                            local dbg_skip_wanted = mem:HasItem("xpfarm_skip_illus") and mem:GetItem("xpfarm_skip_illus") == "true"
                            if dbg_illus then
                                print(string.format("[ILLUSDEBUG] server_has_illusionist()=%s bot_running=%s skip_illus_wanted=%s",
                                    tostring(dbg_illus.Name), tostring(dbg_bot_running), tostring(dbg_skip_wanted)))
                            elseif os.clock() - illusdebug_last_print > 5 then
                                illusdebug_last_print = os.clock()
                                print(string.format("[ILLUSDEBUG] heartbeat: no illusionist found, bot_running=%s skip_illus_wanted=%s, players=%d",
                                    tostring(dbg_bot_running), tostring(dbg_skip_wanted), #plrs:GetPlayers()))
                            end
                        end
                        if Toggles.xpfarm_kick_near and Toggles.xpfarm_kick_near.Value then
                            local hrp = FindFirstChild(char, "HumanoidRootPart")
                            if hrp then
                                local kd = (Options.xpfarm_kick_dist and Options.xpfarm_kick_dist.Value) or 50
                                for _, other in ipairs(plrs:GetPlayers()) do
                                    if other ~= plr and other.Character then
                                        local ohrp = FindFirstChild(other.Character, "HumanoidRootPart")
                                        if ohrp and (ohrp.Position - hrp.Position).Magnitude <= kd then
                                            farm_kick(string.format("Player %s came within %d studs", other.Name, kd))
                                            break
                                        end
                                    end
                                end
                            end
                        end

                        -- hop even while carrying a shrieker (escaping > the shrieker); the
                        -- snap-to-repeat-start resume re-grabs it in the new server
                        local bot_running = (Toggles.xpfarm_path_run and Toggles.xpfarm_path_run.Value)
                            or (Toggles.xpfarm_master and Toggles.xpfarm_master.Value)
                        if bot_running and Toggles.xpfarm_hop_near and Toggles.xpfarm_hop_near.Value then
                            local hrp = FindFirstChild(char, "HumanoidRootPart")
                            if hrp then
                                local hd = (Options.xpfarm_hop_near_dist and Options.xpfarm_hop_near_dist.Value) or 150
                                for _, other in ipairs(plrs:GetPlayers()) do
                                    if other ~= plr and other.Character then
                                        local ohrp = FindFirstChild(other.Character, "HumanoidRootPart")
                                        if ohrp and (ohrp.Position - hrp.Position).Magnitude <= hd then
                                            library:Notify(string.format("Player %s within %d studs - serverhopping", other.Name, hd), 5)
                                            do_path_serverhop(path_idx > 0 and path_idx or 1)
                                            break
                                        end
                                    end
                                end
                            end
                        end

                        -- emergency serverhop: another player is HOLDING a flagged item
                        local em = Options.xpfarm_emergency_items and Options.xpfarm_emergency_items.Value
                        if bot_running and em and next(em) then
                            for _, other in ipairs(plrs:GetPlayers()) do
                                if other ~= plr and other.Character then
                                    local hit
                                    for _, tool in ipairs(other.Character:GetChildren()) do
                                        if tool:IsA("Tool") and em[tool.Name] then hit = tool.Name; break end
                                    end
                                    if hit then
                                        library:Notify(string.format("%s is holding %s - emergency serverhop", other.Name, hit), 5)
                                        do_path_serverhop(path_idx > 0 and path_idx or 1)
                                        break
                                    end
                                end
                            end
                        end

                        -- live skip illusionist / moderator: leave if one is in the server now.
                        -- Illusionist check mirrors the emergency-serverhop pattern directly
                        -- above (inline scan of other.Character:GetChildren() for a held
                        -- Tool) instead of going through server_has_illusionist(), since that
                        -- pattern is the one proven to reliably catch someone who joins/draws
                        -- their tool mid-session.
                        if bot_running and mem:HasItem("xpfarm_skip_illus") and mem:GetItem("xpfarm_skip_illus") == "true" then
                            for _, other in ipairs(plrs:GetPlayers()) do
                                if other ~= plr and other.Character then
                                    local has_observe
                                    for _, tool in ipairs(other.Character:GetChildren()) do
                                        if tool:IsA("Tool") and tool.Name == "Observe" then has_observe = true; break end
                                    end
                                    if not has_observe then
                                        local bp = other:FindFirstChildOfClass("Backpack")
                                        if bp then
                                            for _, tool in ipairs(bp:GetChildren()) do
                                                if tool:IsA("Tool") and tool.Name == "Observe" then has_observe = true; break end
                                            end
                                        end
                                    end
                                    if has_observe then
                                        library:Notify(string.format("%s is an Illusionist - serverhopping", other.Name), 5)
                                        do_path_serverhop(path_idx > 0 and path_idx or 1)
                                        break
                                    end
                                end
                            end
                        end
                        if bot_running then
                            if (mem:HasItem("xpfarm_skip_mod") and mem:GetItem("xpfarm_skip_mod") == "true") and server_has_moderator() then
                                library:Notify("Moderator in server - serverhopping", 5)
                                do_path_serverhop(path_idx > 0 and path_idx or 1)
                            end
                        end

                        if Toggles.xpfarm_auto_inn and Toggles.xpfarm_auto_inn.Value then
                            local hum = FindFirstChildOfClass(char, "Humanoid")
                            if hum and hum.MaxHealth > 0 then
                                local pct = hum.Health / hum.MaxHealth * 100
                                local thr = (Options.xpfarm_inn_hp and Options.xpfarm_inn_hp.Value) or 35
                                if resting then
                                    if pct >= math.min(thr + 40, 95) then
                                        resting = false
                                        last_monster_seen = os.clock()
                                        library:Notify("Recovered - resuming attacks")
                                    end
                                elseif pct <= thr and (os.clock() - last_inn_time) > 5 then
                                    last_inn_time = os.clock()
                                    resting = true
                                    library:Notify(string.format("Low HP (%.0f%%) - resting, attacks paused", pct))
                                end
                            end
                        elseif resting then
                            resting = false
                        end

                        if Toggles.xpfarm_auto_hop and Toggles.xpfarm_auto_hop.Value and not hop_started and not resting then
                            local idle_for = os.clock() - last_monster_seen
                            local timeout = (Options.xpfarm_hop_after and Options.xpfarm_hop_after.Value) or 90
                            if idle_for >= timeout then
                                hop_started = true
                                if Toggles.xpfarm_master and Toggles.xpfarm_master.Value then save_farm_state() end
                                if cs:HasTag(char, "Danger") then
                                    repeat task.wait(0.2)
                                    until not plr.Character or not cs:HasTag(plr.Character, "Danger") or (shared and shared.is_unloading)
                                end
                                library:Notify(string.format("No monsters for %ds - serverhopping", math.floor(idle_for)))
                                -- use the safe path-hop (JoinPublicServer + saves resume) not the
                                -- freezing utility:Serverhop
                                task.spawn(function() pcall(function() do_path_serverhop(path_idx > 0 and path_idx or 1) end) end)
                            end
                        else
                            if (not (Toggles.xpfarm_auto_hop and Toggles.xpfarm_auto_hop.Value)) or (os.clock() - last_monster_seen) < 5 then
                                hop_started = false
                            end
                        end
                    end
                end
            end)

            -- ---- death watch: no recovery on death, kick out of the game ------
            do
                local died_handled = false

                local function watch_character(char)
                    local hum = char and FindFirstChildOfClass(char, "Humanoid")
                    local t0 = os.clock()
                    while char and char.Parent and not hum and os.clock() - t0 < 10 do
                        task.wait(0.25)
                        hum = FindFirstChildOfClass(char, "Humanoid")
                    end
                    if not hum then return end

                    utility:Connection(hum.Died, function()
                        if died_handled then return end
                        if not (Toggles.xpfarm_master and Toggles.xpfarm_master.Value) then return end
                        if hop_started or (shared and shared.is_unloading) then return end
                        died_handled = true
                        task.spawn(farm_kick, "Died while farming")
                    end)
                end

                if plr.Character then task.spawn(watch_character, plr.Character) end
                utility:Connection(plr.CharacterAdded, function(char)
                    died_handled = false
                    task.spawn(watch_character, char)
                end)
            end

            -- ---- Full Auto: resume after serverhop ----------------------------
            -- The script reloads itself after teleports (the global OnTeleport
            -- handler queues the loader when execute_on_serverhop is enabled), so
            -- on load we press Play, restore the saved state, walk back to the
            -- hold spot and flip the master back on. Skipped while the Trinket
            -- Bot is mid-run so the two never fight over the character.
            task.spawn(function()
                if not (mem:HasItem("xpfarm_running") and mem:GetItem("xpfarm_running") == "true") then return end
                if mem:HasItem("botstarted") and mem:GetItem("botstarted") == "true" then return end

                local state
                if mem:HasItem("xpfarm_state") then
                    local ok, decoded = pcall(function()
                        return Services.HttpService:JSONDecode(mem:GetItem("xpfarm_state"))
                    end)
                    if ok and type(decoded) == "table" then state = decoded end
                end
                if state then
                    if state.hold then hold_cf = cf_from_string(state.hold) end
                    pcall(function()
                        if state.inn and Options.xpfarm_inn then Options.xpfarm_inn:SetValue(state.inn) end
                        if state.cps and Options.xpfarm_cps then Options.xpfarm_cps:SetValue(state.cps) end
                        if state.weapon then
                            selected_weapon = state.weapon
                            if Options.xpfarm_weapon then
                                Options.xpfarm_weapon:SetValues(get_backpack_tools())
                                pcall(function() Options.xpfarm_weapon:SetValue(state.weapon) end)
                            end
                        end
                        if state.speed and Options.xpfarm_speed then Options.xpfarm_speed:SetValue(state.speed) end
                        if state.range and Options.xpfarm_monster_range then Options.xpfarm_monster_range:SetValue(state.range) end
                        if state.silver_range and Options.xpfarm_silver_range then Options.xpfarm_silver_range:SetValue(state.silver_range) end
                        if state.inn_hp and Options.xpfarm_inn_hp then Options.xpfarm_inn_hp:SetValue(state.inn_hp) end
                        if state.hop_after and Options.xpfarm_hop_after then Options.xpfarm_hop_after:SetValue(state.hop_after) end
                        if state.per_class and Options.xpfarm_per_class then Options.xpfarm_per_class:SetValue(state.per_class) end
                        if state.class and Options.xpfarm_target_class then Options.xpfarm_target_class:SetValue(state.class) end
                        if Toggles.xpfarm_stop_done then Toggles.xpfarm_stop_done:SetValue(state.stop_done ~= false) end
                    end)
                    if type(state.path) == "string" and state.path ~= "" then
                        xp_path = {}
                        for token in string.gmatch(state.path, "[^|]+") do
                            local kind, rest = string.match(token, "^(%a):(.+)$")
                            if kind == "i" then
                                table.insert(xp_path, { kind = "inn", inn = rest })
                            elseif kind == "p" then
                                local x, y, z = string.match(rest, "([^,]+),([^,]+),([^,]+)")
                                x, y, z = tonumber(x), tonumber(y), tonumber(z)
                                if x and y and z then
                                    table.insert(xp_path, { kind = "point", cf = CFrame.new(x, y, z) })
                                end
                            end
                        end
                        update_path_label()
                    end
                end

                task.wait(2)

                -- skip illusionist servers? hop again before spawning in
                if (mem:HasItem("xpfarm_skip_illus") and mem:GetItem("xpfarm_skip_illus") == "true") and server_has_illusionist() then
                    library:Notify("Illusionist in server - hopping again")
                    task.wait(0.5)
                    pcall(xpfarm_fast_serverhop)   -- JoinPublicServer (never the freezing utility:Serverhop)
                    return
                end

                -- skip moderator servers? hop again before spawning in
                if (mem:HasItem("xpfarm_skip_mod") and mem:GetItem("xpfarm_skip_mod") == "true") and server_has_moderator() then
                    library:Notify("Moderator in server - hopping before spawn")
                    task.wait(0.5)
                    pcall(xpfarm_fast_serverhop)   -- JoinPublicServer (never the freezing utility:Serverhop)
                    return
                end

                -- press Play if the start menu is up (same flow the game expects)
                pcall(function() plr.PlayerGui:WaitForChild("StartMenu", 30) end)
                if plr.PlayerGui:FindFirstChild("StartMenu") then
                    task.wait(1)
                    pcall(function()
                        if plr.PlayerGui.StartMenu:FindFirstChild("Choices") and
                           plr.PlayerGui.StartMenu.Choices:FindFirstChild("Play") then
                            firesignal(plr.PlayerGui.StartMenu.Choices.Play.MouseButton1Click)
                        end
                    end)
                end

                local deadline = os.clock() + 60
                while (not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart")) and os.clock() < deadline do
                    task.wait(0.25)
                end
                if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then
                    library:Notify("XP Farm resume: character never spawned")
                    pcall(function() utility:plain_webhook("XP Farm resume failed: character never spawned") end)
                    return
                end
                task.wait(2)

                -- Get back to the hold spot using the bot's movement. RL keeps
                -- your position across servers, so usually we spawn right at the
                -- ledge; the recorded path covers spawning further away.
                if hold_cf then
                    local hrp = local_hrp()
                    local dist = hrp and (hrp.Position - hold_cf.Position).Magnitude or math.huge

                    if dist > 30 and #xp_path > 0 then
                        traverse_path_from_nearest()
                        hrp = local_hrp()
                        dist = hrp and (hrp.Position - hold_cf.Position).Magnitude or math.huge
                    end

                    if dist > 4 then
                        bot_move_to(hold_cf.Position)
                    end

                    hrp = local_hrp()
                    if hrp and (hrp.Position - hold_cf.Position).Magnitude > 30 then
                        farm_kick("Resume failed - couldn't get back to the hold spot")
                        return
                    end
                end

                last_monster_seen = os.clock()
                if Toggles.xpfarm_master then Toggles.xpfarm_master:SetValue(true) end
                library:Notify("Full Auto Farm resumed", 6)
            end)
        end

        do
            if game.PlaceId ~= 3541987450 then
                if ingredient_folder then
                    local ingredients = {}
                    local last_check_time = 0
                    local check_interval = 0.2
                    local active_ingredients = {}
                    local player_position = nil
                    local max_distance = 0
                    
                    local function update_active_ingredients()
                        if not plr.Character then return end
                        player_position = plr.Character.HumanoidRootPart.Position
                        active_ingredients = {}
                        
                        for _, object in next, ingredients do
                            if object and object.Parent then
                                local click_detector = FindFirstChild(object, "ClickDetector")
                                if click_detector then
                                    max_distance = click_detector.MaxActivationDistance - 2
                                    local distance = (object.Position - player_position).Magnitude
                                    
                                    if distance > 0 and distance < max_distance then
                                        active_ingredients[#active_ingredients + 1] = {
                                            object = object,
                                            detector = click_detector
                                        }
                                    end
                                end
                            end
                        end
                    end
        
                    for _, object in next, ingredient_folder:GetChildren() do
                        if not cheat_client.blacklisted_ingredients[object.Position] then
                            ingredients[#ingredients + 1] = object
                        end
                    end
                    
                    utility:Connection(ingredient_folder.ChildAdded, function(object)
                        if not cheat_client.blacklisted_ingredients[object.Position] then
                            ingredients[#ingredients + 1] = object
                            if plr.Character and FindFirstChild(plr.Character, "HumanoidRootPart") and cheat_client.feature_connections.auto_ingredient then
                                local click_detector = FindFirstChild(object, "ClickDetector")
                                if click_detector then
                                    local distance = (object.Position - plr.Character.HumanoidRootPart.Position).Magnitude
                                    if distance > 0 and distance < click_detector.MaxActivationDistance - 2 then
                                        active_ingredients[#active_ingredients + 1] = {
                                            object = object,
                                            detector = click_detector
                                        }
                                    end
                                end
                            end
                        end
                    end)
                    
                    utility:Connection(ingredient_folder.ChildRemoved, function(object)
                        for i, ingredient in ipairs(ingredients) do
                            if ingredient == object then
                                table.remove(ingredients, i)
                                break
                            end
                        end
                    end)
                    
                    local last_position = nil

                    local function start_auto_ingredient_rendering()
                        if cheat_client.feature_connections.auto_ingredient then return end

                        cheat_client.feature_connections.auto_ingredient = utility:Connection(rs.Heartbeat, LPH_NO_VIRTUALIZE(function(delta_time)
                            if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then return end

                            local current_time = tick()
                            local current_position = plr.Character.HumanoidRootPart.Position

                            if last_position == nil or
                               current_time - last_check_time > check_interval or
                               (current_time - last_check_time > 0.1 and (current_position - last_position).Magnitude > 2) then

                                last_check_time = current_time
                                last_position = current_position
                                update_active_ingredients()
                            end

                            for _, data in ipairs(active_ingredients) do
                                fireclickdetector(data.detector)
                            end
                        end))
                    end

                    local function stop_auto_ingredient_rendering()
                        if cheat_client.feature_connections.auto_ingredient then
                            cheat_client.feature_connections.auto_ingredient:Disconnect()
                            cheat_client.feature_connections.auto_ingredient = nil
                        end
                    end

                    cheat_client.start_auto_ingredient_rendering = start_auto_ingredient_rendering
                    cheat_client.stop_auto_ingredient_rendering = stop_auto_ingredient_rendering

                    if Toggles and Toggles.auto_ingredient and Toggles.auto_ingredient.Value then
                        start_auto_ingredient_rendering()
                    end
                end
            end
        end

        do
            local holdingF = false
            local last_block_time = 0

            local function start_hold_block()
                if cheat_client.feature_connections.hold_block then return end

                cheat_client.feature_connections.hold_block_input_began = utility:Connection(uis.InputBegan, function(input, processed)
                    if not processed and input.KeyCode == Enum.KeyCode.F then
                        holdingF = true
                    end
                end)

                cheat_client.feature_connections.hold_block_input_ended = utility:Connection(uis.InputEnded, function(input, processed)
                    if input.KeyCode == Enum.KeyCode.F then
                        holdingF = false
                    end
                end)

                cheat_client.feature_connections.hold_block = utility:Connection(rs.RenderStepped, LPH_NO_VIRTUALIZE(function()
                    if holdingF and plr.Character then
                        local delay = ((Options and Options.HoldBlockDelay and Options.HoldBlockDelay.Value) or 0) / 1000
                        local now = tick()

                        if now - last_block_time >= delay then
                            local remote = plr.Character:FindFirstChild("CharacterHandler")
                                and plr.Character.CharacterHandler:FindFirstChild("Remotes")
                                and plr.Character.CharacterHandler.Remotes:FindFirstChild("Block")

                            if remote then
                                pcall(function()
                                    remote:FireServer(false)
                                end)
                                last_block_time = now
                            end
                        end
                    end
                end))
            end

            local function stop_hold_block()
                holdingF = false

                if cheat_client.feature_connections.hold_block then
                    cheat_client.feature_connections.hold_block:Disconnect()
                    cheat_client.feature_connections.hold_block = nil
                end

                if cheat_client.feature_connections.hold_block_input_began then
                    cheat_client.feature_connections.hold_block_input_began:Disconnect()
                    cheat_client.feature_connections.hold_block_input_began = nil
                end

                if cheat_client.feature_connections.hold_block_input_ended then
                    cheat_client.feature_connections.hold_block_input_ended:Disconnect()
                    cheat_client.feature_connections.hold_block_input_ended = nil
                end
            end

            cheat_client.start_hold_block = start_hold_block
            cheat_client.stop_hold_block = stop_hold_block

                if Toggles and Toggles.HoldBlock and Toggles.HoldBlock.Value then
                    start_hold_block()
                end
        end

        do
            local bags = {}

            local function isValidBag(object)
                return object:IsA("BasePart") and object.Name:find("Bag")
            end

            local function start_auto_bag()
                if cheat_client.feature_connections.auto_bag then return end

                bags = {}
                for _, object in ipairs(ws.Thrown:GetChildren()) do
                    if isValidBag(object) then
                        bags[#bags + 1] = object
                    end
                end

                cheat_client.feature_connections.auto_bag_child_added = utility:Connection(ws.Thrown.ChildAdded, function(object)
                    if isValidBag(object) then
                        bags[#bags + 1] = object
                    end
                end)

                cheat_client.feature_connections.auto_bag_child_removed = utility:Connection(ws.Thrown.ChildRemoved, function(object)
                    for i = #bags, 1, -1 do
                        if bags[i] == object then
                            table.remove(bags, i)
                            break
                        end
                    end
                end)

                cheat_client.feature_connections.auto_bag = utility:Connection(rs.Heartbeat, LPH_NO_VIRTUALIZE(function()
                    local character = plr.Character
                    local rootPart = character and FindFirstChild(character, "HumanoidRootPart")
                    if not rootPart then return end

                    local range = (Options and Options.bag_range and Options.bag_range.Value) or 20
                    for i = #bags, 1, -1 do
                        local object = bags[i]
                        if not object:IsDescendantOf(ws) then
                            table.remove(bags, i)
                        elseif (object.Position - rootPart.Position).Magnitude <= range then
                            firetouchinterest(object, rootPart, 0)
                            firetouchinterest(object, rootPart, 1)
                        end
                    end
                end))
            end

            local function stop_auto_bag()
                if cheat_client.feature_connections.auto_bag then
                    cheat_client.feature_connections.auto_bag:Disconnect()
                    cheat_client.feature_connections.auto_bag = nil
                end

                if cheat_client.feature_connections.auto_bag_child_added then
                    cheat_client.feature_connections.auto_bag_child_added:Disconnect()
                    cheat_client.feature_connections.auto_bag_child_added = nil
                end

                if cheat_client.feature_connections.auto_bag_child_removed then
                    cheat_client.feature_connections.auto_bag_child_removed:Disconnect()
                    cheat_client.feature_connections.auto_bag_child_removed = nil
                end

                bags = {}
            end

            cheat_client.start_auto_bag = start_auto_bag
            cheat_client.stop_auto_bag = stop_auto_bag

            if Toggles and Toggles.auto_bag and Toggles.auto_bag.Value then
                start_auto_bag()
            end
        end
        
        
    
        do
            local function IsTargetValid(Target)
                if (plr.Character and Target ~= nil and Target.Name == 'Humanoid' and FindFirstChild(Target.Parent, 'HumanoidRootPart') and Target.Parent ~= plr.Character) then
                    return true
                end
                return false
            end

            local function IsValidProjectile(Projectile)
                for i,v in pairs(cheat_client.valid_projectiles) do
                    if (string.match(v, Projectile)) then return true; end
                end
                return false
            end

            local active_projectiles = {}

            local function start_perflora_teleport()
                if cheat_client.feature_connections.perflora_teleport then return end

                active_projectiles = {}
                for _, child in ipairs(ws.Thrown:GetChildren()) do
                    if typeof(child) == 'Instance' and IsValidProjectile(child.Name) then
                        active_projectiles[child] = true
                    end
                end

                cheat_client.feature_connections.perflora_child_added = utility:Connection(ws.Thrown.ChildAdded, function(Child)
                    if typeof(Child) == 'Instance' and IsValidProjectile(Child.Name) then
                        active_projectiles[Child] = true
                    end
                end)

                cheat_client.feature_connections.perflora_child_removed = utility:Connection(ws.Thrown.ChildRemoved, function(Child)
                    active_projectiles[Child] = nil
                end)

                cheat_client.feature_connections.perflora_teleport = utility:Connection(rs.Heartbeat, LPH_NO_VIRTUALIZE(function()
                    if not IsTargetValid(workspace.CurrentCamera.CameraSubject) then
                        return
                    end

                    local target_pos = workspace.CurrentCamera.CameraSubject.Parent.HumanoidRootPart.Position

                    for projectile in pairs(active_projectiles) do
                        if projectile and projectile.Parent then
                            projectile.Position = target_pos
                        else
                            active_projectiles[projectile] = nil
                        end
                    end
                end))
            end

            local function stop_perflora_teleport()
                if cheat_client.feature_connections.perflora_teleport then
                    cheat_client.feature_connections.perflora_teleport:Disconnect()
                    cheat_client.feature_connections.perflora_teleport = nil
                end

                if cheat_client.feature_connections.perflora_child_added then
                    cheat_client.feature_connections.perflora_child_added:Disconnect()
                    cheat_client.feature_connections.perflora_child_added = nil
                end

                if cheat_client.feature_connections.perflora_child_removed then
                    cheat_client.feature_connections.perflora_child_removed:Disconnect()
                    cheat_client.feature_connections.perflora_child_removed = nil
                end

                active_projectiles = {}
            end

            cheat_client.start_perflora_teleport = start_perflora_teleport
            cheat_client.stop_perflora_teleport = stop_perflora_teleport

            if Toggles and Toggles.PerfloraTeleport and Toggles.PerfloraTeleport.Value then
                start_perflora_teleport()
            end

            local attach_victim = nil
            local attach_connection = nil
            local attach_notified = false
            local camera = utility:GetCamera()

            local function get_nearby_player()
                if not plr.Character then return nil end
                local plr_hrp = FindFirstChild(plr.Character, "HumanoidRootPart")
                if not plr_hrp then return nil end

                local closest_plr = nil
                local min_dist = 350

                for _, target_player in ipairs(plrs:GetPlayers()) do
                    if target_player ~= plr and target_player.Character then
                        local target_hrp = FindFirstChild(target_player.Character, "HumanoidRootPart")
                        local target_humanoid = FindFirstChild(target_player.Character, "Humanoid")

                        if target_hrp and target_humanoid and target_humanoid.Health > 0 then
                            local screen_pos, on_screen = camera:WorldToViewportPoint(target_hrp.Position)
                            if on_screen then
                                local screen_distance = (Vector2.new(screen_pos.X, screen_pos.Y) - Vector2.new(mouse.X, mouse.Y)).Magnitude
                                local world_distance = (plr_hrp.Position - target_hrp.Position).Magnitude

                                if screen_distance < min_dist and world_distance < 130 then
                                    min_dist = screen_distance
                                    closest_plr = target_player
                                end
                            end
                        end
                    end
                end

                return closest_plr
            end

            local function start_attach()
                if attach_connection then return end

                attach_connection = utility:Connection(rs.Stepped, function()
                    if not (Toggles and Toggles.blatant_mode and Toggles.blatant_mode.Value) then
                        attach_victim = nil
                        return
                    end

                    if not attach_victim then
                        attach_victim = get_nearby_player()
                        if not attach_victim then return end
                    end

                    if not attach_victim.Character or not plr.Character then
                        attach_victim = nil
                        return
                    end

                    local victim_hrp = FindFirstChild(attach_victim.Character, "HumanoidRootPart")
                    local victim_humanoid = FindFirstChild(attach_victim.Character, "Humanoid")
                    local plr_hrp = FindFirstChild(plr.Character, "HumanoidRootPart")

                    if not victim_hrp or not plr_hrp then
                        attach_victim = nil
                        return
                    end

                    if not victim_humanoid or victim_humanoid.Health <= 0 then
                        attach_victim = nil
                        return
                    end

                    local distance_check = (plr_hrp.Position - victim_hrp.Position).Magnitude
                    if distance_check > 130 then
                        attach_victim = nil
                        return
                    end

                    plr_hrp.Velocity = Vector3.new(0, 0, 0)

                    local torso = FindFirstChild(plr.Character, "Torso")
                    local head = FindFirstChild(plr.Character, "Head")
                    if torso then torso.CanCollide = false end
                    if head then head.CanCollide = false end

                    local is_flinging = Toggles and Toggles.fling and Toggles.fling.Value
                    if is_flinging then
                        plr_hrp.CFrame = victim_hrp.CFrame * CFrame.new(0, -2, 0)
                    else
                        local offset = 2
                        if uis:IsKeyDown(Enum.KeyCode.W) then
                            offset = -1
                        elseif uis:IsKeyDown(Enum.KeyCode.S) then
                            offset = 6.5
                        end

                        if uis:IsKeyDown(Enum.KeyCode.A) then
                            plr_hrp.CFrame = victim_hrp.CFrame + victim_hrp.CFrame:vectorToWorldSpace(Vector3.new(1, 0, 0) * -3) + (victim_hrp.CFrame.lookVector * -offset)
                        elseif uis:IsKeyDown(Enum.KeyCode.D) then
                            plr_hrp.CFrame = victim_hrp.CFrame + victim_hrp.CFrame:vectorToWorldSpace(Vector3.new(-1, 0, 0) * -3) + (victim_hrp.CFrame.lookVector * -offset)
                        else
                            plr_hrp.CFrame = victim_hrp.CFrame + (victim_hrp.CFrame.lookVector * -offset)
                        end
                    end
                end)
            end

            local function stop_attach()
                if attach_connection then
                    attach_connection:Disconnect()
                    attach_connection = nil
                end
                attach_victim = nil
            end

            utility:Connection(uis.InputBegan, function(input, chat)
                if chat or not Options.AttachToBackKeybind then return end
                if Options.AttachToBackKeybind.Value == "None" then return end
                if input.KeyCode == Enum.KeyCode[Options.AttachToBackKeybind.Value] then
                    if not (Toggles and Toggles.blatant_mode and Toggles.blatant_mode.Value) then
                        library:Notify("Attach to Back requires Blatant Mode enabled!", 3)
                        return
                    end

                    if attach_victim ~= nil then
                        stop_attach()
                    else
                        local nearby = get_nearby_player()
                        if nearby ~= nil then
                            if nearby ~= attach_victim then
                                attach_victim = nearby
                                start_attach()
                            else
                                stop_attach()
                            end
                        else
                            stop_attach()
                        end
                    end
                end
            end)
        end

        do
            local misogi_connections = {}

            local function handleAutoMisogi(obj)
                if not (Toggles and Toggles.AutoMisogi and Toggles.AutoMisogi.Value) then return end

                if obj.Name == "LandedShoryuExcept" then
                    task.wait(0.02)
                    if not plr.Backpack then return end
                    local tool = FindFirstChild(plr.Backpack, "Rising Dragon")
                    if tool then
                        plr.Character.Humanoid:EquipTool(tool)

                        task.spawn(function()
                            while shared and not shared.is_unloading and obj.Parent == plr.Character and not FindFirstChild(plr.Character, "TPSafe") do
                                if not FindFirstChild(plr.Character, "Rising Dragon") and plr.Backpack then
                                    local backpackTool = FindFirstChild(plr.Backpack, "Rising Dragon")
                                    if backpackTool then
                                        plr.Character.Humanoid:EquipTool(backpackTool)
                                    end
                                end

                                utility:RightClick()
                                task.wait(0.1)
                            end
                        end)
                    end
                end
            end

            local function setupMisogi(character)
                for _, conn in pairs(misogi_connections) do
                    conn:Disconnect()
                end
                misogi_connections = {}
                misogi_connections[#misogi_connections + 1] = utility:Connection(character.ChildAdded, handleAutoMisogi)
            end

            if plr.Character then
                setupMisogi(plr.Character)
            end

            utility:Connection(plr.CharacterAdded, setupMisogi)
        end

        do
            local DETECTION_RANGE = 30
            local AUTO_PARRY_COOLDOWN = 0.1
            local LAST_PARRY = 0
            local EARTH_PILLAR_PARRY_DISTANCE = 10
            local EARTH_PILLAR_BLOCK_DURATION = 0.45
            local INPUT_BLOCKED = false
            local BLOCKED_KEYS = {Enum.KeyCode.F, Enum.KeyCode.G}

            local function getPing()
                local success, ping = pcall(function()
                    return Services.Stats:WaitForChild('PerformanceStats'):WaitForChild('Ping'):GetValue()
                end)
                return success and ping or 0
            end

            local AUTO_PARRY_SOUNDS = {
                ["OwlSlash"] = {delay = 0.1, blockDuration = 0.7, requiresVisibility = false},
                ["Shadowrush"] = {delay = 0.05, blockDuration = 0.3, requiresVisibility = true},
                ["ShadowrushCharge"] = {delay = 0.05, blockDuration = 0.3, requiresVisibility = true},
                ["PerfectCast"] = {delay = 0, blockDuration = 0.25, requiresVisibility = true}
            }
            
            local function blockInputs()
                INPUT_BLOCKED = true

                cas:BindAction("BlockAutoParryInputs", function()
                    return Enum.ContextActionResult.Sink
                end, false, unpack(BLOCKED_KEYS))

                cas:BindAction("BlockAutoParryMouse", function()
                    if INPUT_BLOCKED then
                        return Enum.ContextActionResult.Sink
                    end
                end, false, Enum.UserInputType.MouseButton1, Enum.UserInputType.MouseButton2)
            end

            local function unblockInputs()
                INPUT_BLOCKED = false
                cas:UnbindAction("BlockAutoParryInputs")
                cas:UnbindAction("BlockAutoParryMouse")
            end

            local function is_on_screen_visible(characterHRP)
                local vector, on_screen = ws.CurrentCamera:WorldToScreenPoint(characterHRP.Position)

                if not on_screen then
                    return false
                end

                if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then
                    return false
                end

                local playerHRP = plr.Character.HumanoidRootPart
                local directionToCharacter = (characterHRP.Position - playerHRP.Position).Unit

                local rayParams = RaycastParams.new()
                rayParams.FilterDescendantsInstances = {plr.Character}
                rayParams.FilterType = Enum.RaycastFilterType.Blacklist

                local rayResult = workspace:Raycast(
                    playerHRP.Position,
                    directionToCharacter * (playerHRP.Position - characterHRP.Position).Magnitude,
                    rayParams
                )

                return not rayResult or rayResult.Instance:IsDescendantOf(characterHRP.Parent)
            end

            local function is_visible(characterHRP)
                local vector, on_screen = ws.CurrentCamera:WorldToScreenPoint(characterHRP.Position)

                if not on_screen then
                    return false
                end

                if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then
                    return false
                end

                local playerHRP = plr.Character.HumanoidRootPart
                local playerLookVector = playerHRP.CFrame.LookVector
                local directionToCharacter = (characterHRP.Position - playerHRP.Position).Unit

                local dotProduct = playerLookVector:Dot(directionToCharacter)
                local fovAngle = Options.ParryFovAngle.Value
                local angleThreshold = math.cos(math.rad(fovAngle / 2))

                if dotProduct > angleThreshold then
                    local rayParams = RaycastParams.new()
                    rayParams.FilterDescendantsInstances = {plr.Character}
                    rayParams.FilterType = Enum.RaycastFilterType.Blacklist

                    local rayResult = workspace:Raycast(
                        playerHRP.Position,
                        directionToCharacter * (playerHRP.Position - characterHRP.Position).Magnitude,
                        rayParams
                    )

                    if rayResult and rayResult.Instance:IsDescendantOf(characterHRP.Parent) then
                        return true
                    end
                end

                return false
            end

            local function on_cooldown()
                if not plr.Character then return true end
                
                if FindFirstChild(plr.Character, "ParryCool") then
                    return true
                end
                
                return false
            end

            local function performAutoParry(delay, blockDuration, useVim, attackingPlayer)
                if attackingPlayer and cheat_client:is_friendly(attackingPlayer) then
                    return
                end

                local disableWhenUnfocused = Toggles.ParryDisableWhenUnfocused.Value
                if disableWhenUnfocused then
                    if not cheat_client.window_active or uis:GetFocusedTextBox() then
                        return
                    end
                end
                
                local currentTime = tick()
                if currentTime - LAST_PARRY < AUTO_PARRY_COOLDOWN then return end

                local semiBlatantBlock = Toggles.ParrySemiBlatantBlock and Toggles.ParrySemiBlatantBlock.Value
                if not semiBlatantBlock and FindFirstChild(plr.Character, "NoDash") then return end

                if FindFirstChildOfClass(plr.Character, "ForceField") then return end
                if on_cooldown() then return end

                LAST_PARRY = currentTime
                blockDuration = blockDuration or 0.3
                
                local adjustedDelay = delay or 0
                if Toggles and Toggles.ParryCustomDelay and Toggles.ParryCustomDelay.Value then
                    local customDelayMs = Options.ParryCustomDelayMs.Value
                    adjustedDelay = adjustedDelay + (customDelayMs / 1000)
                elseif Toggles.ParryPingAdjust.Value then
                    local ping = getPing()
                    local pingCompensation = ping / 2000
                    adjustedDelay = adjustedDelay - pingCompensation
                end
                
                adjustedDelay = math.max(0, adjustedDelay)

                if not useVim then
                    blockInputs()
                end

                if adjustedDelay > 0 then
                    task.wait(adjustedDelay)
                    if on_cooldown() then
                        if not useVim then
                            unblockInputs()
                        end
                        return
                    end
                end

                local humanoid = FindFirstChildOfClass(plr.Character, "Humanoid")
                local mana = FindFirstChild(plr.Character, "Mana")
                if humanoid and mana and mana.Value > 0 then
                    humanoid:UnequipTools()
                end

                local blockRemote, unblockRemote
                if plr.Character then
                    local remotes = FindFirstChild(plr.Character, "CharacterHandler", true) and
                                FindFirstChild(plr.Character.CharacterHandler, "Remotes")

                    if remotes then
                        blockRemote = FindFirstChild(remotes, "Block")
                        unblockRemote = FindFirstChild(remotes, "Unblock")
                    end
                end

                local semiBlatantBlock = Toggles.ParrySemiBlatantBlock and Toggles.ParrySemiBlatantBlock.Value
                if semiBlatantBlock and blockRemote and unblockRemote then
                    task.spawn(function()
                        local endTime = tick() + blockDuration
                        while tick() < endTime do
                            blockRemote:FireServer(false)
                            task.wait()
                        end

                        local inputObject = {}
                        unblockRemote:FireServer(inputObject)
                        unblockInputs()
                    end)
                elseif useVim or not (blockRemote and unblockRemote) then
                    task.spawn(function()
                        vim:SendKeyEvent(true, Enum.KeyCode.F, false, game)
                        task.wait(blockDuration)
                        vim:SendKeyEvent(false, Enum.KeyCode.F, false, game)
                    end)
                else
                    blockRemote:FireServer(false)

                    task.delay(blockDuration, function()
                        local inputObject = {}
                        unblockRemote:FireServer(inputObject)
                        unblockInputs()
                    end)
                end
            end

            local connectedSounds = {}
            local characterConnections = {}
            
            local function disconnect_character_sounds(player)
                if characterConnections[player] then
                    for _, connection in pairs(characterConnections[player]) do
                        if connection and connection.Connected then
                            connection:Disconnect();
                        end
                    end
                    characterConnections[player] = nil
                end
                connectedSounds[player] = nil
            end
            
            local function connect_sounds(character)
                local player = plrs:GetPlayerFromCharacter(character)
                if not player or player == plr then
                    return
                end

                disconnect_character_sounds(player)
                characterConnections[player] = {}
                connectedSounds[player] = true

                local characterHRP = WaitForChild(character, "HumanoidRootPart", 3)
                if not characterHRP then
                    return
                end
                
                local function handleSound(sound)
                    if not utility then return end
                    return utility:Connection(sound.Played, function()
                        if not shared or not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then
                            return
                        end
                        local playerHRP = plr.Character.HumanoidRootPart
                        local distance = (playerHRP.Position - characterHRP.Position).Magnitude
                        if distance <= DETECTION_RANGE then
                            if sound.Name == "OwlSlash" and shared and Toggles and Toggles.AutoPerfectBlock and Toggles.AutoPerfectBlock.Value and Options.ParryAbilities.Value["Owlslash"] then
                                if plr.Character and FindFirstChild(plr.Character, "AIRSLASH") then
                                    local soundInfo = AUTO_PARRY_SOUNDS[sound.Name]
                                    local ignoreVisibility = shared and Toggles.ParryIgnoreVisibility and Toggles.ParryIgnoreVisibility.Value
                                    local should_parry = ignoreVisibility or not soundInfo.requiresVisibility or is_visible(characterHRP)
                                    if should_parry then
                                        task.spawn(function()
                                            if shared then
                                                performAutoParry(soundInfo.delay, soundInfo.blockDuration, false, player)
                                            end
                                        end)
                                    end
                                end
                            elseif (sound.Name == "Shadowrush" or sound.Name == "ShadowrushCharge") and shared and Toggles and Toggles.AutoPerfectBlock and Toggles.AutoPerfectBlock.Value and Options.ParryAbilities.Value["Shadowrush"] then
                                local attackerLookDirection = characterHRP.CFrame.LookVector
                                local directionToPlayer = (playerHRP.Position - characterHRP.Position).Unit
                                local facingDotProduct = attackerLookDirection:Dot(directionToPlayer)

                                if facingDotProduct > -0.17 then
                                    local soundInfo = AUTO_PARRY_SOUNDS[sound.Name]
                                    local ignoreVisibility = shared and Toggles.ParryIgnoreVisibility and Toggles.ParryIgnoreVisibility.Value
                                    local should_parry = ignoreVisibility or not soundInfo.requiresVisibility or is_visible(characterHRP)
                                    if should_parry then
                                        local actualDelay = soundInfo.delay
                                        if (sound.Name == "Shadowrush" or sound.Name == "ShadowrushCharge") and distance <= 9 then
                                            actualDelay = 0
                                        end
                                        task.defer(function()
                                            if shared then
                                                performAutoParry(actualDelay, soundInfo.blockDuration, false, player)
                                            end
                                        end)
                                    end
                                end
                            elseif sound.Name == "PerfectCast" and shared and Toggles and Toggles.AutoPerfectBlock and Toggles.AutoPerfectBlock.Value and Options.ParryAbilities.Value["Verdien"] then
                                local soundInfo = AUTO_PARRY_SOUNDS[sound.Name]
                                local hasVerdien = FindFirstChild(character, "Verdien") or FindFirstChild(character, "New Verdien")

                                if hasVerdien then
                                    local ignoreVisibility = shared and Toggles.ParryIgnoreVisibility and Toggles.ParryIgnoreVisibility.Value
                                    local should_parry = ignoreVisibility or not soundInfo.requiresVisibility or is_visible(characterHRP)
                                    if should_parry then
                                        task.spawn(function()
                                            if shared then
                                                performAutoParry(soundInfo.delay, soundInfo.blockDuration, true, player)
                                            end
                                        end)
                                    end
                                end
                            end
                        end
                    end)
                end

                for _, sound in ipairs(characterHRP:GetChildren()) do
                    if sound:IsA("Sound") then
                        local soundConnection = handleSound(sound)
                        if soundConnection then
                            table.insert(characterConnections[player], soundConnection)
                        end
                    end
                end

                if utility and utility.Connection then
                    local childAddedConnection = utility:Connection(characterHRP.ChildAdded, function(child)
                        if child:IsA("Sound") then
                            task.wait(0.1)
                            local soundConnection = handleSound(child)
                            if soundConnection then
                                characterConnections[player] = characterConnections[player] or {}
                                table.insert(characterConnections[player], soundConnection)
                            end
                        end
                    end)
                    table.insert(characterConnections[player], childAddedConnection)
                end
            end

            local playerConnections = {}
            local function connect_player(player)
                if player == plr or playerConnections[player] then
                    return
                end

                playerConnections[player] = {}

                if player.Character then
                    connect_sounds(player.Character)
                end

                playerConnections[player].characterAdded = utility:Connection(player.CharacterAdded, function(character)
                    task.wait(0.5)
                    connect_sounds(character)
                end)

                playerConnections[player].characterRemoving = utility:Connection(player.CharacterRemoving, function()
                    disconnect_character_sounds(player)
                end)
            end

            local function disconnect_player(player)
                if playerConnections[player] then
                    for _, connection in pairs(playerConnections[player]) do
                        if connection and connection.Connected then
                            connection:Disconnect()
                        end
                    end
                    playerConnections[player] = nil
                end
                disconnect_character_sounds(player)
            end

            local function connect_players()
                for _, player in ipairs(plrs:GetPlayers()) do
                    if player ~= plr then
                        connect_player(player)
                    end
                end

                utility:Connection(plrs.PlayerAdded, function(player)
                    if player ~= plr then
                        connect_player(player)
                    end
                end)

                utility:Connection(plrs.PlayerRemoving, function(player)
                    disconnect_player(player)
                end)
            end


            utility:Connection(workspace.Thrown.ChildAdded, function(model)
                if not (Toggles and Toggles.AutoPerfectBlock and Toggles.AutoPerfectBlock.Value and Options.ParryAbilities.Value["Viribus"]) then return end
                if not model:IsA("Model") then return end

                local crater = WaitForChild(model, "Crater", 1)
                if not crater then return end

                if crater:IsA("Model") then
                    crater = crater.PrimaryPart or FindFirstChildWhichIsA(crater, "BasePart")
                    if not crater then return end
                end

                if not crater:IsA("BasePart") then return end
                if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then return end

                local playerHRP = plr.Character.HumanoidRootPart
                if FindFirstChild(model, "EarthSpear" .. plr.Name) then return end

                local distance = (crater.Position - playerHRP.Position).Magnitude
                if distance > EARTH_PILLAR_PARRY_DISTANCE then return end

                local closestCaster, closestDistance = nil, math.huge

                for _, player in ipairs(plrs:GetPlayers()) do
                    if player ~= plr and player.Character then
                        local casterHRP = FindFirstChild(player.Character, "HumanoidRootPart")
                        if casterHRP then
                            local casterToEarthPillar = (casterHRP.Position - crater.Position).Magnitude
                            if casterToEarthPillar < 50 and casterToEarthPillar < closestDistance then
                                closestCaster, closestDistance = player.Character, casterToEarthPillar
                            end
                        end
                    end
                end

                local function isInFov(direction)
                    local playerLookVector = playerHRP.CFrame.LookVector
                    local dotProduct = playerLookVector:Dot(direction)
                    local fovAngle = Options.ParryFovAngle.Value
                    local angleThreshold = math.cos(math.rad(fovAngle / 2))
                    return dotProduct > angleThreshold
                end

                if closestCaster then
                    local casterHRP = FindFirstChild(closestCaster, "HumanoidRootPart")
                    if casterHRP and isInFov((casterHRP.Position - playerHRP.Position).Unit) then
                        local attackingPlayer = plrs:GetPlayerFromCharacter(closestCaster)
                        performAutoParry(0, EARTH_PILLAR_BLOCK_DURATION, false, attackingPlayer)
                    end
                else
                    if isInFov((crater.Position - playerHRP.Position).Unit) then
                        performAutoParry(0, EARTH_PILLAR_BLOCK_DURATION, false, nil)
                    end
                end
            end)


            local function setup_grapple_parry()
                if not plr.Character then return end

                utility:Connection(plr.Character.DescendantAdded, function(child)
                    if not (Toggles and Toggles.AutoPerfectBlock and Toggles.AutoPerfectBlock.Value and Options.ParryAbilities.Value["Grapple"]) then return end
                    if not (child:IsA("Attachment") and child.Name == "Attachment2") then return end

                    local enemyPlayer = nil
                    local should_parry = true

                    task.wait(0.05)

                    for _, player in ipairs(plrs:GetPlayers()) do
                        if player == plr or not player.Character then continue end

                        local leftArm = FindFirstChild(player.Character, "Left Arm")
                        if not leftArm then continue end

                        local cord = FindFirstChild(leftArm, "Cord")
                        if not cord or not cord:IsA("Beam") or cord.Attachment1 ~= child then continue end
                        enemyPlayer = player

                        local ignoreVisibility = Toggles.ParryIgnoreVisibility and Toggles.ParryIgnoreVisibility.Value
                        if not ignoreVisibility then
                            local enemyHRP = FindFirstChild(player.Character, "HumanoidRootPart")
                            if enemyHRP then
                                should_parry = is_on_screen_visible(enemyHRP)
                            end
                        end
                        break
                    end

                    if not enemyPlayer then return end
                    if plr.Character and FindFirstChild(plr.Character, "HumanoidRootPart") and enemyPlayer.Character then
                        local playerHRP = plr.Character.HumanoidRootPart
                        local enemyHRP = FindFirstChild(enemyPlayer.Character, "HumanoidRootPart")

                        if enemyHRP then
                            local distance = (playerHRP.Position - enemyHRP.Position).Magnitude
                            local semiBlatantBlock = Toggles.ParrySemiBlatantBlock and Toggles.ParrySemiBlatantBlock.Value
                            if not semiBlatantBlock and distance > 60 then
                                return
                            end
                        end
                    end

                    if should_parry then
                        performAutoParry(0, 0.25, true, enemyPlayer)
                    end
                end)
            end

            if plr.Character then
                setup_grapple_parry()
            end

            utility:Connection(plr.CharacterAdded, function()
                task.wait(0.5)
                setup_grapple_parry()
            end)

            connect_players()
        end

        do
            local valid_tools = { Celeritas = true, Armis = true, Vulnere = true, ["Dagger Throw"] = true, Arguere = true, Grapple = true, ["Autumn Rain"] = true, Ignis = true, Percutiens = true }

            local get_nearest_player = LPH_NO_VIRTUALIZE(function()
                local players_list = plrs:GetPlayers()
                local camera = ws.CurrentCamera
                local smallest_distance = math.huge
                local nearest
            
                local plr_humanoid_root_part = plr.Character and FindFirstChild(plr.Character, "HumanoidRootPart")
                local mouse_position = Vector2.new(mouse.X, mouse.Y)
            
                if not plr_humanoid_root_part then
                    return nil
                end
            
                local fov_radius = (Options and Options.SilentAimFov and Options.SilentAimFov.Value) or 100
                local hitparts = {
                    ["Head"] = true
                }
            
                local function is_visible_from_camera(part, target_character)
                    local camera_position = camera.CFrame.Position
                    local direction = (part.Position - camera_position).Unit
                    local distance = (part.Position - camera_position).Magnitude

                    local raycast_params = RaycastParams.new()
                    raycast_params.FilterDescendantsInstances = {plr.Character, target_character}
                    raycast_params.FilterType = Enum.RaycastFilterType.Blacklist

                    local result = workspace:Raycast(camera_position, direction * distance, raycast_params)

                    if not result then
                        return true
                    end

                    if result.Instance == part then
                        return true
                    end

                    if result.Instance.Transparency > 0.9 and not result.Instance.CanCollide then
                        return true
                    end

                    local hit_distance = (result.Position - camera_position).Magnitude
                    local target_distance = (part.Position - camera_position).Magnitude

                    return math.abs(hit_distance - target_distance) < 1
                end
            
                for _, target_player in ipairs(players_list) do
                    if target_player ~= plr and not cheat_client:is_friendly(target_player) then
                        local target_character = target_player.Character
                        if target_character then
                            if FindFirstChild(target_character, "Carried") then
                                continue
                            end

                            local ignore_blocking = Toggles and Toggles.IgnoreBlocking and Toggles.IgnoreBlocking.Value
                            if ignore_blocking and FindFirstChild(target_character, "Blocking") then
                                continue
                            end

                            local closest_part = nil
                            local closest_part_distance = math.huge
                            
                            for part_name, _ in next, hitparts do
                                local part = FindFirstChild(target_character, part_name)
                                if part then
                                    local screen_position, on_screen = camera:WorldToScreenPoint(part.Position)
                                    
                                    if on_screen then
                                        local target_screen_position = Vector2.new(screen_position.X, screen_position.Y)
                                        local distance_to_mouse = (mouse_position - target_screen_position).Magnitude
                                        
                                        if distance_to_mouse <= fov_radius and distance_to_mouse < closest_part_distance then
                                            if not cheat_client.config.visible_check or is_visible_from_camera(part, target_character) then
                                                closest_part = part
                                                closest_part_distance = distance_to_mouse
                                            end
                                        end
                                    end
                                end
                            end
                            
                            if closest_part and closest_part_distance <= fov_radius and closest_part_distance < smallest_distance then
                                smallest_distance = closest_part_distance
                                nearest = target_player
                                cheat_client.aimbot.silent_vector = closest_part.Position
                                cheat_client.aimbot.current_target_part = closest_part
                            end
                        end
                    end
                end
                return nearest
            end)
            
            function is_valid_tool_equipped()
                local equipped_tool = plr.Character and FindFirstChildOfClass(plr.Character, "Tool")
                return equipped_tool and valid_tools[equipped_tool.Name]
            end

            local function start_silent_aim_rendering()
                if cheat_client.feature_connections.silent_aim then return end

                cheat_client.feature_connections.silent_aim = utility:Connection(rs.Heartbeat, LPH_NO_VIRTUALIZE(function()
                    local isHideFovCircleEnabled = Toggles and Toggles.HideFovCircle and Toggles.HideFovCircle.Value or false
                    local mouse_pos = Vector2.new(uis:GetMouseLocation().X, uis:GetMouseLocation().Y)
                    aimbot_fov_circle.Position = mouse_pos
                    aimbot_fov_circle.Radius = (Options and Options.SilentAimFov and Options.SilentAimFov.Value) or 100
                    aimbot_fov_circle.Visible = cheat_client.window_active and not isHideFovCircleEnabled

                    local nearest_player = get_nearest_player()
                    if cheat_client and cheat_client.aimbot then
                        cheat_client.aimbot.current_target = nearest_player
                    end

                    if game.PlaceId ~= 14341521240 and get_mouse_remote then
                        get_mouse_remote.OnClientInvoke = function()
                            if not is_valid_tool_equipped() then
                                return {
                                    Hit = mouse.Hit,
                                    Target = mouse.Target,
                                    UnitRay = mouse.UnitRay,
                                    X = mouse.X,
                                    Y = mouse.Y
                                }
                            end

                            if cheat_client and cheat_client.aimbot and cheat_client.aimbot.current_target and cheat_client.aimbot.silent_vector and cheat_client.aimbot.current_target_part then
                                local camera = ws.CurrentCamera
                                local target_screen_point = camera:WorldToScreenPoint(cheat_client.aimbot.silent_vector)
                                local target_cframe = CFrame.new(cheat_client.aimbot.silent_vector)

                                return {
                                    Hit = target_cframe,
                                    Target = cheat_client.aimbot.current_target_part,
                                    X = target_screen_point.X,
                                    Y = target_screen_point.Y,
                                    UnitRay = Ray.new(camera.CFrame.Position, (cheat_client.aimbot.silent_vector - camera.CFrame.Position).Unit)
                                }
                            end

                            return {
                                Hit = mouse.Hit,
                                Target = mouse.Target,
                                UnitRay = mouse.UnitRay,
                                X = mouse.X,
                                Y = mouse.Y
                            }
                        end
                    end
                end))
            end

            local function stop_silent_aim_rendering()
                if cheat_client.feature_connections.silent_aim then
                    cheat_client.feature_connections.silent_aim:Disconnect()
                    cheat_client.feature_connections.silent_aim = nil

                    cheat_client.aimbot.silent_vector = nil
                    cheat_client.aimbot.current_target = nil
                    cheat_client.aimbot.current_target_part = nil
                    aimbot_fov_circle.Visible = false
                    silent_circle.Visible = false
                end
            end

            cheat_client.start_silent_aim_rendering = start_silent_aim_rendering
            cheat_client.stop_silent_aim_rendering = stop_silent_aim_rendering

            if Toggles and Toggles.SilentAim and Toggles.SilentAim.Value then
                start_silent_aim_rendering()
            end
        end

        do
            local direction = Vector3.new()
            local interpolated_dir = direction
            local tilt = 0
            local interpolated_tilt = tilt
            local sprinting = false
            local camera_pos = ws.CurrentCamera.CFrame.Position
            local cached_parts = {}
            local last_character = nil
            local death_connection

            local function lerp(a, b, t)
                return a + (b - a) * t
            end

            local function cache_character_parts(character)
                cached_parts = {}
                for _, v in pairs(character:GetDescendants()) do
                    if v:IsA("BasePart") then
                        table.insert(cached_parts, v)
                    end
                end
            end

            local function start_better_flight()
                if cheat_client.feature_connections.better_flight then return end

                local character = plr.Character
                if character then
                    local humanoid = character:FindFirstChildOfClass("Humanoid")
                    if humanoid then
                        death_connection = utility:Connection(humanoid.Died, function()
                            if Toggles.better_flight then
                                Toggles.better_flight:SetValue(false)
                            end
                        end)
                    end
                end

                cheat_client.feature_connections.better_flight_input_began = utility:Connection(uis.InputBegan, function(input, processed)
                    if processed then return end
                    if input.KeyCode == nil then return end

                    local key = tostring(input.KeyCode):gsub("Enum.KeyCode.", "")

                    if key == "LeftControl" then
                        sprinting = true
                    elseif key == "W" then
                        tilt = -20
                        direction = Vector3.new(direction.X, direction.Y, -1)
                    elseif key == "A" then
                        direction = Vector3.new(-1, direction.Y, direction.Z)
                    elseif key == "S" then
                        tilt = 20
                        direction = Vector3.new(direction.X, direction.Y, 1)
                    elseif key == "D" then
                        direction = Vector3.new(1, direction.Y, direction.Z)
                    end
                end)

                cheat_client.feature_connections.better_flight_input_ended = utility:Connection(uis.InputEnded, function(input, processed)
                    if processed then return end
                    if input.KeyCode == nil then return end

                    local key = tostring(input.KeyCode):gsub("Enum.KeyCode.", "")

                    if key == "LeftControl" then
                        sprinting = false
                    elseif key == "W" then
                        tilt = 0
                        direction = Vector3.new(direction.X, direction.Y, 0)
                    elseif key == "A" then
                        direction = Vector3.new(0, direction.Y, direction.Z)
                    elseif key == "S" then
                        tilt = 0
                        direction = Vector3.new(direction.X, direction.Y, 0)
                    elseif key == "D" then
                        direction = Vector3.new(0, direction.Y, direction.Z)
                    end
                end)

                cheat_client.feature_connections.better_flight = utility:Connection(rs.Stepped, LPH_NO_VIRTUALIZE(function()
                    if not plr.Character or not FindFirstChild(plr.Character, "HumanoidRootPart") then return end

                    if last_character ~= plr.Character then
                        last_character = plr.Character
                        cache_character_parts(plr.Character)
                    end

                    for _, v in ipairs(cached_parts) do
                        if v and v.Parent then
                            v.Velocity = Vector3.new()
                            v.CanCollide = false
                        end
                    end

                    local root_part = plr.Character.HumanoidRootPart

                    interpolated_dir = interpolated_dir:Lerp((direction * (sprinting and 15 or 5)), 0.2)
                    interpolated_tilt = lerp(interpolated_tilt, tilt * (sprinting and 2 or 1), tilt == 0 and 0.2 or 0.1)

                    root_part.CFrame = root_part.CFrame:Lerp(
                        CFrame.new(root_part.Position, root_part.Position + mouse.UnitRay.Direction) *
                        CFrame.Angles(0, math.rad(0), 0) *
                        CFrame.new(interpolated_dir) *
                        CFrame.Angles(math.rad(interpolated_tilt), 0, 0),
                        0.2
                    )
                end))
            end

            local function stop_better_flight()
                direction = Vector3.new()
                interpolated_dir = direction
                tilt = 0
                interpolated_tilt = tilt
                sprinting = false

                if cheat_client.feature_connections.better_flight then
                    cheat_client.feature_connections.better_flight:Disconnect()
                    cheat_client.feature_connections.better_flight = nil
                end

                if cheat_client.feature_connections.better_flight_input_began then
                    cheat_client.feature_connections.better_flight_input_began:Disconnect()
                    cheat_client.feature_connections.better_flight_input_began = nil
                end

                if cheat_client.feature_connections.better_flight_input_ended then
                    cheat_client.feature_connections.better_flight_input_ended:Disconnect()
                    cheat_client.feature_connections.better_flight_input_ended = nil
                end

                if death_connection then
                    death_connection:Disconnect()
                    death_connection = nil
                end
            end

            cheat_client.start_better_flight = start_better_flight
            cheat_client.stop_better_flight = stop_better_flight
        end

        do
            local flingEnabled = false
            local Y_VELOCITY = 9e9
            local death_connection
            local FLING_FLIGHT_SPEED = 50
            local was_noclip_enabled_fling = false

            local function start_fling()
                if cheat_client.feature_connections.fling then return end

                flingEnabled = true

                local character = plr.Character
                if character then
                    local humanoid = character:FindFirstChildOfClass("Humanoid")
                    if humanoid then
                        death_connection = utility:Connection(humanoid.Died, function()
                            if Toggles.fling then
                                Toggles.fling:SetValue(false)
                            end
                        end)
                    end
                end

                cheat_client.feature_connections.fling = utility:Connection(rs.RenderStepped, LPH_NO_VIRTUALIZE(function()
                    local character = plr.Character
                    if not character or not flingEnabled then return end

                    local rootPart = FindFirstChild(character, "HumanoidRootPart")
                    if not rootPart then return end

                    local camCFrame = workspace.CurrentCamera.CFrame
                    local huma = FindFirstChildOfClass(character, "Humanoid")

                    for i, v in next, character:GetDescendants() do
                        if v:IsA("BasePart") then
                            v.Velocity = Vector3.new()
                            v.CanCollide = false
                            if v ~= rootPart then
                                v.RotVelocity = Vector3.new(0, 0, 0)
                            end
                        end
                    end

                    if not was_noclip_enabled_fling and huma then
                        huma:SetStateEnabled(5, false)
                        huma:ChangeState(3)
                    end

                    if rootPart then
                        local lookVector = camCFrame.LookVector
                        local flatLook = Vector3.new(lookVector.X, 0, lookVector.Z).Unit
                        if flatLook.Magnitude > 0.01 then
                            rootPart.CFrame = CFrame.new(rootPart.Position, rootPart.Position + flatLook)
                        end
                    end

                    was_noclip_enabled_fling = true

                    if not cheat_client.custom_flight_functions["GetFocusedTextBox"](uis) then
                        local eVector = Vector3.new()
                        local rVector, lVector, uVector = camCFrame.RightVector, camCFrame.LookVector, camCFrame.UpVector

                        if cheat_client.custom_flight_functions["IsKeyDown"](uis, "W") then eVector += lVector end
                        if cheat_client.custom_flight_functions["IsKeyDown"](uis, "S") then eVector -= lVector end
                        if cheat_client.custom_flight_functions["IsKeyDown"](uis, "D") then eVector += rVector end
                        if cheat_client.custom_flight_functions["IsKeyDown"](uis, "A") then eVector -= rVector end

                        local isHoldingSpace = cheat_client.custom_flight_functions["IsKeyDown"](uis, "Space")
                        if isHoldingSpace then eVector += uVector end
                        if cheat_client.custom_flight_functions["IsKeyDown"](uis, "LeftShift") then eVector -= uVector end

                        local isMovingDown = cheat_client.custom_flight_functions["IsKeyDown"](uis, "LeftShift")
                        if not isMovingDown and rootPart.AssemblyLinearVelocity.Y < 0 then
                            local currentVelocity = rootPart.AssemblyLinearVelocity
                            rootPart.AssemblyLinearVelocity = Vector3.new(currentVelocity.X, 0, currentVelocity.Z)
                        end

                        if eVector.Unit.X == eVector.Unit.X then
                            local flight_speed = Options.fling_flight_speed and Options.fling_flight_speed.Value or 50
                            rootPart.AssemblyLinearVelocity = eVector.Unit * flight_speed
                        else
                            local currentVel = rootPart.AssemblyLinearVelocity
                            rootPart.AssemblyLinearVelocity = currentVel * 0.85
                        end

                        local shouldAnchor = eVector == Vector3.new() or rootPart.AssemblyLinearVelocity.Magnitude < 1
                        rootPart.Anchored = shouldAnchor
                    end
                end))

                cheat_client.feature_connections.fling_heartbeat = utility:Connection(rs.Heartbeat, function()
                    if not flingEnabled then return end

                    local character = plr.Character
                    if not character then return end

                    local originalVelocities = {}
                    for _, part in ipairs(character:GetDescendants()) do
                        if part:IsA("BasePart") then
                            originalVelocities[part] = part.AssemblyLinearVelocity
                            part.AssemblyLinearVelocity = Vector3.new(0, Y_VELOCITY, 0)
                        end
                    end

                    rs.RenderStepped:Wait()

                    if not flingEnabled then
                        for part, _ in pairs(originalVelocities) do
                            if part and part.Parent then
                                part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                            end
                        end
                        return
                    end

                    for part, velocity in pairs(originalVelocities) do
                        if part and part.Parent then
                            part.AssemblyLinearVelocity = velocity
                        end
                    end
                end)
            end

            local function stop_fling()
                flingEnabled = false

                rs.Heartbeat:Wait()
                rs.RenderStepped:Wait()

                if cheat_client.feature_connections.fling then
                    cheat_client.feature_connections.fling:Disconnect()
                    cheat_client.feature_connections.fling = nil
                end

                if cheat_client.feature_connections.fling_heartbeat then
                    cheat_client.feature_connections.fling_heartbeat:Disconnect()
                    cheat_client.feature_connections.fling_heartbeat = nil
                end

                if death_connection then
                    death_connection:Disconnect()
                    death_connection = nil
                end

                if plr and plr.Character then
                    local character = plr.Character
                    local huma = FindFirstChildOfClass(character, "Humanoid")
                    local rootPart = FindFirstChild(character, "HumanoidRootPart")

                    if rootPart then
                        rootPart.Anchored = false
                    end

                    for _, part in ipairs(character:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                            part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                            part.Velocity = Vector3.new(0, 0, 0)

                            if part.Name ~= "HumanoidRootPart" then
                                if part.Name == "Head" or part.Name == "Torso" then
                                    part.CanCollide = true
                                else
                                    part.CanCollide = false
                                end
                            end
                        end
                    end

                    if huma then
                        huma:SetStateEnabled(5, true)
                        huma:ChangeState(Enum.HumanoidStateType.Physics)
                        task.wait()
                        huma:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end
                end

                was_noclip_enabled_fling = false
            end

            cheat_client.start_fling = start_fling
            cheat_client.stop_fling = stop_fling
        end

        do
            local empty_vector = Vector3.new(0, 0, 0)
    
            local move_position = Vector2.new(0, 0)
            local move_direction = empty_vector
    
            local last_right_button_down = Vector2.new(0, 0)
            local right_mouse_button_down = false
    
            local keys_down = {}
            
            local enum_keycode = Enum.KeyCode
            local zoom_keycode = enum_keycode.Z
    
            local mouse_movement = Enum.UserInputType.MouseMovement
            local mouse_button_2 = Enum.UserInputType.MouseButton2
            
            local begin_state = Enum.UserInputState.Begin
            local end_state = Enum.UserInputState.End
    
            local lock_current_position = Enum.MouseBehavior.LockCurrentPosition
            local default_mouse = Enum.MouseBehavior.Default
    
            local camera = utility:GetCamera()
            local camera_scriptable = Enum.CameraType.Scriptable
            local camera_custom = Enum.CameraType.Custom
    
            local move_keys = {
                [enum_keycode.D] = Vector3.new(1, 0, 0),
                [enum_keycode.A] = Vector3.new(-1, 0, 0),
                [enum_keycode.S] = Vector3.new(0, 0, 1),
                [enum_keycode.W] = Vector3.new(0, 0, -1),
                [enum_keycode.E] = Vector3.new(0, 1, 0),
                [enum_keycode.Q] = Vector3.new(0, -1, 0)
            }
    
            utility:Connection(uis.InputChanged, LPH_NO_VIRTUALIZE(function(input)
                if input.UserInputType == mouse_movement then
                    move_position = move_position + Vector2.new(input.Delta.X, input.Delta.Y)
                end
            end))
    
            local keyboard = {
        		W = 0,
        		A = 0,
        		S = 0,
        		D = 0,
        		E = 0,
        		Q = 0,
        		U = 0,
        		H = 0,
        		J = 0,
        		K = 0,
        		I = 0,
        		Y = 0,
        		Up = 0,
        		Down = 0,
        		LeftShift = 0,
        		RightShift = 0,
    	   }
            
            local function Keypress(action, state, input)
                local freecam_keybind_string = Options.FreecamKeybind and Options.FreecamKeybind.Value
                local freecam_keybind_enum = freecam_keybind_string and Enum.KeyCode[freecam_keybind_string]

                if freecam_keybind_enum and input.KeyCode == freecam_keybind_enum then
                    return Enum.ContextActionResult.Pass
                end

                keyboard[input.KeyCode.Name] = state == Enum.UserInputState.Begin and 1 or 0
                return Enum.ContextActionResult.Sink
            end
    
            function StartCapture()
    		    cas:BindActionAtPriority("FreecamKeyboard", Keypress, false, Enum.ContextActionPriority.High.Value,
        			Enum.KeyCode.W, Enum.KeyCode.U,
        			Enum.KeyCode.A, Enum.KeyCode.H,
        			Enum.KeyCode.S, Enum.KeyCode.J,
        			Enum.KeyCode.D, Enum.KeyCode.K,
        			Enum.KeyCode.E, Enum.KeyCode.I,
        			Enum.KeyCode.Q, Enum.KeyCode.Y,
        			Enum.KeyCode.Up, Enum.KeyCode.Down
        		)
    	    end
    
            local function Zero(t)
    			for k, v in pairs(t) do
    				t[k] = v*0
    			end
            end
    	
    		function StopCapture()
    			navSpeed = 1
    			Zero(keyboard)
    			cas:UnbindAction("FreecamKeyboard")
    		end
    
            local calculate_movement = LPH_NO_VIRTUALIZE(function()
                local new_movement = empty_vector
                
                for index, value in next, keys_down do
                    new_movement = new_movement + (move_keys[index] or empty_vector)
                end
                
                return new_movement
            end)
    
            local function input_register(input)
                local key_code = input.KeyCode
    
                if move_keys[key_code] then
                    if input.UserInputState == begin_state then
                        keys_down[key_code] = true
                    elseif input.UserInputState == end_state then
                        keys_down[key_code] = nil
                    end
                else
                    if input.UserInputState == begin_state and shared and Toggles and Toggles.freecam and Toggles.freecam.Value then
                        if input.UserInputType == mouse_button_2 then
                            right_mouse_button_down = true
                            last_right_button_down = Vector2.new(mouse.X, mouse.Y)
                            uis.MouseBehavior = lock_current_position
                        end
                    else
                        if input.UserInputType == mouse_button_2 and shared and Toggles and Toggles.freecam and Toggles.freecam.Value then
                            right_mouse_button_down = false
                            uis.MouseBehavior = default_mouse
                        end
                    end
                end
            end
    
            utility:Connection(mouse.WheelForward, function()
                camera.CoordinateFrame = camera.CoordinateFrame * CFrame.new(0, 0, -5)
            end)
    
            utility:Connection(mouse.WheelBackward, function()
                camera.CoordinateFrame = camera.CoordinateFrame * CFrame.new(0, 0, 5)
            end)
    
            utility:Connection(uis.InputBegan, input_register)
            utility:Connection(uis.InputEnded, input_register)
    
            local function start_freecam_rendering()
                if cheat_client.feature_connections.freecam then return end

                cheat_client.feature_connections.freecam = utility:Connection(rs.RenderStepped, LPH_NO_VIRTUALIZE(function()
                    local freecamSpeed = (Options and Options.freecam_speed and Options.freecam_speed.Value) or 16
                    camera.CoordinateFrame = CFrame.new(camera.CoordinateFrame.Position) * CFrame.fromEulerAnglesYXZ(-move_position.Y / 300, -move_position.X / 300, 0) * CFrame.new(calculate_movement() * freecamSpeed)

                    if right_mouse_button_down then
                        local mouse_position = Vector2.new(mouse.X, mouse.Y)

                        uis.MouseBehavior = lock_current_position
                        move_position = move_position - (last_right_button_down - mouse_position)
                        last_right_button_down = mouse_position
                    end
                end))
            end

            local function stop_freecam_rendering()
                if cheat_client.feature_connections.freecam then
                    cheat_client.feature_connections.freecam:Disconnect()
                    cheat_client.feature_connections.freecam = nil
                end
            end

            cheat_client.start_freecam_rendering = start_freecam_rendering
            cheat_client.stop_freecam_rendering = stop_freecam_rendering
        end


        do
            local teleport_debounce = false

            utility:Connection(plr.OnTeleport, function(State)
                if teleport_debounce then
                    return
                end
                teleport_debounce = true

                if cheat_client.config.execute_on_serverhop then
                    local queue_func = queueteleport or queue_on_teleport
                    if queue_func then
                        local success, err = pcall(function()
                            local loader_script
                            if readfile and isfile and isfile("bazaar_loader.lua") then
                                loader_script = [[local code=readfile("bazaar_loader.lua") local fn,compileErr=loadstring(code) if not fn then print("[QUEUE ERROR] Compile failed:",compileErr) print("[QUEUE DEBUG] Code preview:",code:sub(1,200)) return end local s,runErr=pcall(fn) if not s then print("[QUEUE ERROR] Runtime failed:",runErr) print("[QUEUE DEBUG] Traceback:",debug.traceback()) end]]
                            else
                                loader_script = [[if not game:IsLoaded() then game.Loaded:Wait() end task.wait(1) local s,code=pcall(function() return game:HttpGet("https://raw.githubusercontent.com/tallyka/Carbine/refs/heads/main/loader.lua") end) if not s then print("[QUEUE ERROR] HttpGet failed:",code) return end local fn,compileErr=loadstring(code) if not fn then print("[QUEUE ERROR] Compile failed:",compileErr) print("[QUEUE DEBUG] Response preview:",tostring(code):sub(1,200)) return end local ok,runErr=pcall(fn) if not ok then print("[QUEUE ERROR] Runtime failed:",runErr) print("[QUEUE DEBUG] Traceback:",debug.traceback()) end]]
                            end
                            queue_func(loader_script)
                        end)
                    end
                end
            end)
        end
    
        do
            local stats = Services.Stats
            local pingStat = WaitForChild(stats, "PerformanceStats"):WaitForChild("Ping")
            local smoothed_ping = 0

            task.spawn(function()
                while shared and not shared.is_unloading do
                    local raw = pingStat and pingStat:GetValue() or 0
                    smoothed_ping = math.clamp((smoothed_ping * 0.3) + (raw * 0.7), 0, 300)
                    task.wait(0.25)
                end
            end)

            local function adjusted_wait(base, mult)
                mult = mult or 1
                task.wait(base + (math.min(smoothed_ping, 150) / 2000) * mult)
            end

            local function apply_auto_charge(character)
                local mana = WaitForChild(character, "Mana")
                local cached_tool = nil

                task.spawn(function()
                    while shared and not shared.is_unloading do
                        if Toggles.SnapTrain and Toggles.SnapTrain.Value then
                            task.wait(0.01)
                        else
                            if not utility then break end
                            task.wait(utility:random_wait(true))
                        end

                        if not plr.Character or plr.Character ~= character or not utility or not Toggles or not Options then
                            break
                        end

                        local char = plr.Character
                        local mana_val = mana.Value

                        if Toggles.SnapTrain and Toggles.SnapTrain.Value and utility then
                            if Toggles.AutoCharge and Toggles.AutoCharge.Value then
                                Toggles.AutoCharge:SetValue(false)
                            end

                            local tool = FindFirstChildOfClass(char, "Tool")
                            if tool and FindFirstChild(tool, "Spell") and not cached_tool then
                                cached_tool = tool
                            end

                            if cached_tool and cheat_client.spell_cost[cached_tool.Name] then
                                local spell_data = cheat_client.spell_cost[cached_tool.Name][1]
                                local min_cost, max_cost = spell_data[1], spell_data[2]
                                local mid_cost = (min_cost + max_cost) / 2
                                local range = max_cost - min_cost
                                
                                local buffer = math.min(3, math.floor(range / 3))
                                if buffer < 1 then buffer = 0 end

                                if mana_val < (mid_cost - 1) then
                                    utility:charge_mana_until(mid_cost)
                                end

                                if mana_val >= (min_cost + buffer)
                                    and mana_val <= (max_cost - buffer)
                                    and not cs:HasTag(char, "Casting")
                                then
                                    if FindFirstChildOfClass(char, "Tool") ~= cached_tool then
                                        if cached_tool.Parent == plr.Backpack then
                                            char.Humanoid:EquipTool(cached_tool)
                                            adjusted_wait(0.01)
                                        end
                                    end

                                    if utility then
                                        utility:LeftClick()
                                    end

                                    -- unconditional unequip/reequip after every click - not
                                    -- gated behind detecting the "Casting" tag (that race was
                                    -- too brittle: a short detection window could miss the tag
                                    -- entirely and skip the unequip/reequip cycle for that
                                    -- click). Charge -> click -> unequip -> reequip -> repeat.
                                    adjusted_wait(0.05)

                                    char.Humanoid:UnequipTools()
                                    adjusted_wait(0.05)

                                    if not utility then return end
                                    if cached_tool.Parent == plr.Backpack then
                                        char.Humanoid:EquipTool(cached_tool)
                                    end
                                end
                            end
                        else
                            cached_tool = nil
                        end

                        if Toggles.AutoCharge and Toggles.AutoCharge.Value
                            and mana_remote
                            and mana_val <= Options.AutoChargeThreshold.Value
                            and not cs:HasTag(char, "Casting")
                        then
                            if Toggles.train_climb and Toggles.train_climb.Value then
                                Toggles.train_climb:SetValue(false)
                            end

                            utility:charge_mana_until(Options.AutoChargeThreshold.Value)
                        end

                        if Toggles.train_climb and Toggles.train_climb.Value then
                            if Toggles.AutoCharge and Toggles.AutoCharge.Value then
                                Toggles.AutoCharge:SetValue(false)
                            end

                            utility:charge_mana_until(100)
                            repeat
                                vim:SendKeyEvent(true, "Space", false, game)
                                adjusted_wait(0.05)
                                vim:SendKeyEvent(false, "Space", false, game)
                                adjusted_wait(0.05)
                            until mana.Value == 0 or not Toggles.train_climb.Value
                        end
                    end
                end)
            end

            local character = plr.Character or plr.CharacterAdded:Wait()
            apply_auto_charge(character)
            utility:Connection(plr.CharacterAdded, apply_auto_charge)
        end


        do
            while shared and not shared.is_unloading and task.wait(0.6) do
                if plr.Backpack and plr.Character and not cs:HasTag(plr.Character, "Danger") and shared and Toggles and Toggles.loop_orderly and Toggles.loop_orderly.Value then
                    local elixir = FindFirstChild(plr.Backpack, "Tespian Elixir")
                    if elixir then
                        -- Match the macro system's own proven-reliable "equip" action
                        -- exactly (find_tool + plain Humanoid:EquipTool, no UnequipTools
                        -- first) instead of a GUI click or raw key press.
                        pcall(function() plr.Character.Humanoid:EquipTool(elixir) end)
                        task.wait(0.3)

                        local equippedElixir = FindFirstChild(plr.Character, "Tespian Elixir")
                        if equippedElixir and FindFirstChild(equippedElixir, "RemoteEvent") then
                            equippedElixir.RemoteEvent:FireServer(plr.Character.HumanoidRootPart.CFrame, "Part", "Self")
                            -- delay between drinking and BreakJoints - tunable via the
                            -- "Loop Gain Orderly Delay" slider (was a hardcoded 1.5s)
                            task.wait((Options and Options.loop_orderly_delay and Options.loop_orderly_delay.Value) or 2)
                            plr.Character:BreakJoints()

                            repeat task.wait(0.5)
                            until FindFirstChild(plr.Character, "Immortal")
                        end
                    end
                end
            end
        end
    end
    end, function(err)
        return debug.traceback(err, 2)
    end)

    if not success then
        if key then
            getgenv()[key] = nil
        end
        warn("[hydroxide.sol] Script error:", err)
    end
end
